  str_homestory_chat_14824006 = "It gives me a sense of security when I have my day planned out.",
  str_homestory_chat_14824007 = "So, that's how PlayerName thought?",
  str_homestory_chat_14824008 = "I thought you were more of a happy-go-lucky kind of guy!",
  str_homestory_chat_14824009 = "Never...",
  str_homestory_chat_14824010 = "Things never go as planned.",
  str_homestory_chat_14824011 = "That's absolutely right!",
  str_homestory_chat_14824012 = "Every day is different, and that's what keeps life interesting!",
  str_homestory_chat_14825001 = "You want to go shopping for clothes?",
  str_homestory_chat_14825002 = "There doesn't seem to be a place that sells clothes in your Cloud Gardens?",
  str_homestory_chat_14825003 = "Because it isn't necessary here... Can't you go to Umbraton if you want to buy clothes?",
  str_homestory_chat_14825004 = "I wanna buy some for you, boatscrapper.",
  str_homestory_chat_14825005 = "Huh? For me?",
  str_homestory_chat_14825006 = "Why?",
  str_homestory_chat_14825007 = "Because you keep wearing the same clothes, I'm sick of seeing them already.",
  str_homestory_chat_14825008 = "Well... You have a point.",
  str_homestory_chat_14825009 = "I don't need any.",
  str_homestory_chat_14825010 = "Well, do you wanna go to Umbraton with me?",
  str_homestory_chat_14825011 = "I'll think about it.",
  str_homestory_chat_14825012 = "What's there to think? If you keep going everywhere in the same set of clothes, even the Chubbs will get sick of seeing you.",
  str_homestory_chat_14826001 = "Practice?",
  str_homestory_chat_14826002 = "I need to practice with my daggers sometimes. I can't always fight against fish and trees.",
  str_homestory_chat_14826003 = "So you're the one who left those scratches on the trees...",
  str_homestory_chat_14826004 = "Help me find a good sparring partner!",
  str_homestory_chat_14826005 = "Nobody is suitable here.",
  str_homestory_chat_14826006 = "You should just stick to the trees.",
  str_homestory_chat_14826007 = "Or... what about rocks?",
  str_homestory_chat_14826008 = "I think you're fobbing me off, boatscrapper.",
  str_homestory_chat_14826009 = "It's because this is a peaceful place. You should relax when you're here.",
  str_homestory_chat_14826010 = "I think it's time I find some targets for myself. Those Chubbs are looking quite suitable!",
  str_homestory_chat_14826011 = "They move slowly and won't counterattack. They even look very durable.",
  str_homestory_chat_14826012 = "Please don't!",
  str_homestory_chat_12299999 = "Care for a glass of diesel on an amazing day like today?",
  str_homestory_chat_12221001 = "Thanks, but no thanks.",
  str_homestory_chat_12221002 = "You sure you're going to pass on such an appetizing old diesel?",
  str_homestory_chat_12221003 = "Old diesel... I seriously don't get you.",
  str_homestory_chat_12222001 = "How are you liking it here?",
  str_homestory_chat_12222002 = "It's actually a pretty decent place...",
  str_homestory_chat_12222003 = "but the diesel here's a little pricey.",
  str_homestory_chat_12222004 = "I mean, they're shipped from afar, after all.",
  str_homestory_chat_12222005 = "Those fuddy-duddies from Illumina must have hiked up the prices furtively!",
  str_homestory_chat_12222006 = "...There's something I'm not sure if I should tell you.",
  str_homestory_chat_12222007 = "Why are you beating around the bush, boss?",
  str_homestory_chat_12222008 = "It's just that the diesel is shipped by Rediesel Wrench.",
  str_homestory_chat_12222009 = "!!!",
  str_homestory_chat_12222010 = "Are you upset?",
  str_homestory_chat_12222011 = "Thanks for letting me know about this, boss...",
  str_homestory_chat_12222012 = "I can finally get some free diesel!",
  str_homestory_chat_12223001 = "Anyway, let's put aside diesel...",
  str_homestory_chat_12223002 = "What are you looking at?",
  str_homestory_chat_12223003 = "Have you seen Rabbie, boss?",
  str_homestory_chat_12223004 = "You need something from her?",
  str_homestory_chat_12223005 = "I've not seen her for hours!",
  str_homestory_chat_12223006 = "What if something happens to her, and I'm not there to protect her?",
  str_homestory_chat_12223007 = "I'll regret it forever!",
  str_homestory_chat_12223008 = "You've got to save Rabbie, Boss! Save me!",
  str_homestory_chat_12223009 = "...All right, calm down. You're just being hysterical.",
  str_homestory_chat_11299999 = "Hello there, my friend.",
  str_homestory_chat_11201001 = "Hello, Nemesis.",
  str_homestory_chat_11201002 = "Care to join me in seeing justice done today?",
  str_homestory_chat_11201003 = "With Nemesis here, it feels much safer here.",
  str_homestory_chat_11201004 = "Of course. I would never let any darkness fester.",
  str_homestory_chat_11221001 = "It's so peaceful here lately.",
  str_homestory_chat_11221002 = "Yes, but patrols are still necessary.",
  str_homestory_chat_11221003 = "Nah, there's no need.",
  str_homestory_chat_11221004 = "I doubt any of us will be at loggerheads since we're all friends.",
  str_homestory_chat_11221005 = "That's a fair point...",
  str_homestory_chat_11221006 = "but nipping it in the bud is something I've to do as an enforcer.",
  str_homestory_chat_11221007 = "That's a great idea.",
  str_homestory_chat_11221008 = "We're all friends here, but we're bound to have some friction.",
  str_homestory_chat_11221009 = "I'd hate for anyone to get into a fight.",
  str_homestory_chat_11221010 = "Thanks for affirming the value of my work, my friend.",
  str_homestory_chat_11221011 = "Let me take the reign in safeguarding this tranquility.",
  str_homestory_chat_11222001 = "What happened?",
  str_homestory_chat_11222002 = "I just stopped someone from damaging the Eraveilian environment.",
  str_homestory_chat_11222003 = "Huh? What did that person do?",
  str_homestory_chat_11222004 = "He was trying to pluck flowers in the garden...",
  str_homestory_chat_11222005 = "and I can never tolerate this sort of rule-breaking!",
  str_homestory_chat_11222006 = "What did you do to him?",
  str_homestory_chat_11222007 = "I used my Blade of Judgment to send him flying.",
  str_homestory_chat_11222008 = "Ah! Thanks for protecting the environment here, Nemesis.",
  str_homestory_chat_11222009 = "But I still need to put up warning signs for the garden.",
  str_homestory_chat_11222010 = "Warn everyone against...?",
  str_homestory_chat_11222011 = "To warn everyone that picking flowers is a high-risk activity.",
  str_homestory_chat_11223001 = "You look really happy...",
  str_homestory_chat_11223002 = "Did anything good happen to you today?",
  str_homestory_chat_11223003 = "I helped a lost kitty find its way back home.",
  str_homestory_chat_11223004 = "Both the kitty and its owner were very grateful.",
  str_homestory_chat_11223005 = "The sun appears to be shining even more brightly today.",
  str_homestory_chat_11223006 = "It's certainly a beautiful day.",
  str_homestory_chat_11223007 = "I'm glad to share this experience with you, my friend.",
  str_homestory_chat_11223008 = "I should be enforcing justice and helping others on days like these.",
  str_homestory_chat_11224001 = "You want to increase the workforce?",
  str_homestory_chat_11224002 = "Yes, I want to form a patrol to maintain law and order here.",
  str_homestory_chat_11224003 = "This isn't the Illumina Federation... You don't need to be so anxious.",
  str_homestory_chat_11224004 = "I can't keep being so complacent. Even with my disposition, I've started slacking off lately.",
  str_homestory_chat_11224005 = "I don't want to work at all... I can't let this continue.",
  str_homestory_chat_11224006 = "Should we put you in charge of reminding everyone to work hard?",
  str_homestory_chat_11224007 = "What a good idea! I'll get on it right away.",
  str_homestory_chat_11224008 = "What amazing efficiency!",
  str_homestory_chat_11225001 = "Are you looking for the Chubbs?",
  str_homestory_chat_11225002 = "Yes. What do you think of them?",
  str_homestory_chat_11225003 = "They're good companions.",
  str_homestory_chat_11225004 = "Just companions, huh...",
  str_homestory_chat_11225005 = "They're Cloud Gardens' architects.",
  str_homestory_chat_11225006 = "Architects?",
  str_homestory_chat_11225007 = "Sigh... It looks like you haven't discovered their good qualities yet.",
  str_homestory_chat_11225008 = "Such as?",
  str_homestory_chat_11225009 = "They're disciplined. When I give them orders, they always get the job done.",
  str_homestory_chat_11225010 = "It would've been perfect if you could organize them into a force to maintain public security here.",
  str_homestory_chat_11225011 = "It's a shame they weren't interested when I spoke about it. All they said in response was, \"Chubb.\"",
  str_homestory_chat_11225012 = "I guess they rejected the notion...",
  str_homestory_chat_11226001 = "Something on your mind?",
  str_homestory_chat_11226002 = "I'm wondering whether I should establish some rules here.",
  str_homestory_chat_11226003 = "Such as?",
  str_homestory_chat_11226004 = "Rules on garbage sorting, regular room cleaning, and so on.",
  str_homestory_chat_11226005 = "I think Cloud Gardens will gradually become like Illumina if you do that...",
  str_homestory_chat_11226006 = "Are you unhappy with how life is here?",
  str_homestory_chat_11226007 = "No, it's very comfortable, but I just feel like I'm out of place for some reason.",
  str_homestory_chat_11226008 = "I can't sleep well at night if I don't do something.",
  str_homestory_chat_11226009 = "I think you're too used to being in Illumina... Just treat your time here like you're on vacation.",
  str_homestory_chat_11226010 = "Vacations are part of Illumina's system too. You have to follow it.",
  str_homestory_chat_11226011 = "I guess when I think about it that way... it's permissible.",
  str_homestory_chat_12599999 = "Hi! With the new day comes new ideas.",
  str_homestory_chat_12521001 = "For performances?",
  str_homestory_chat_12521002 = "Ah... Are you looking forward to my performance, PlayerName?",
  str_homestory_chat_12521003 = "You've excellent taste since my performances never fail to disappoint.",
  str_homestory_chat_12521004 = "...I've actually not thought of that...",
  str_homestory_chat_12521005 = "but it's fine if you want to perform.",
  str_homestory_chat_12522001 = "For scripts?",
  str_homestory_chat_12522002 = "Do you want to listen to the lines?",
  str_homestory_chat_12522003 = "I'd have to say, PlayerName, your aesthetic sense is gradually improving.",
  str_homestory_chat_12522004 = "Ahem. In the boundless dark night, I hear the shattering of one's heart...",
  str_homestory_chat_12522005 = "Isn't that too sorrowful?",
  str_homestory_chat_12522006 = "That's right. Through the usage of my spectacular vocabulary, what needs to be conveyed is...",
  str_homestory_chat_12522007 = "sorrow and despair...",
  str_homestory_chat_12522008 = "This is what the world we live in actually looks like!",
  str_homestory_chat_12522009 = "It seems that I'm right about you, PlayerName.",
  str_homestory_chat_12522010 = "Your aesthetic sense is gradually improving under my influence.",
  str_homestory_chat_12522011 = "Isn't that too frightening?",
  str_homestory_chat_12522012 = "Frightening? Don't tell me that you can't detect it...?",
  str_homestory_chat_12522013 = "Beneath the terrifying description lies a strong undercurrent of sorrow, and hurt.",
  str_homestory_chat_12522014 = "Uh, no...",
  str_homestory_chat_12522015 = "PlayerName, I regret that I have to retract my earlier assessment of your aesthetics.",
  str_homestory_chat_12523001 = "How have you been?",
  str_homestory_chat_12523002 = "PlayerName, isn't it too narrow here?",
  str_homestory_chat_12523003 = "Why do you say that?",
  str_homestory_chat_12523004 = "I think Other End cannot pass at all!",
  str_homestory_chat_12523005 = "If we drive it through here, we'll definitely knock down a wall, or knock over a tree...",
  str_homestory_chat_12523006 = "Nah.",
  str_homestory_chat_12523007 = "But it's not even wide enough to let Other End pass.",
  str_homestory_chat_12523008 = "Is my darling Other End supposed to float in the sky then?",
  str_homestory_chat_12523009 = "Wait! Why do you want to drive a train in a space where people walk?!",
  str_homestory_chat_12524001 = "I heard you have a plan...",
  str_homestory_chat_12524002 = "Yes. PlayerName, aren't you going to build something on this empty land?",
  str_homestory_chat_12524003 = "Build what?",
  str_homestory_chat_12524004 = "A stage!",
  str_homestory_chat_12524005 = "A stage that belongs to me, the artist, and Other End!",
  str_homestory_chat_12524006 = "How about it? Isn't it a super passionate and creative proposal?",
  str_homestory_chat_12524007 = "I'm not building anything.",
  str_homestory_chat_12524008 = "PlayerName, look at this empty land. Doesn't it look so pale?",
  str_homestory_chat_12524009 = "It's just waiting for artistic passion to breathe color into it—",
  str_homestory_chat_12524010 = "So... What's your point?",
  str_homestory_chat_12524011 = "So let's build a stage! For art and for Other End!",
  str_homestory_chat_12524012 = "Uh, I'll think about it.",
  str_homestory_chat_12525001 = "Today's ball...",
  str_homestory_chat_12525002 = "Are you saying... that there's a ball being held tonight?",
  str_homestory_chat_12525003 = "I won't be going! The fated end of an evil artist's life is solitude.",
  str_homestory_chat_12525004 = "But you look like you really want to go...",
  str_homestory_chat_12525005 = "Ahem, you saw wrong.",
  str_homestory_chat_12525006 = "But if you insist on inviting me, then I suppose I can be gracious enough to accept...",
  str_homestory_chat_12525007 = "Okay, then I insist on inviting you.",
  str_homestory_chat_12525008 = "Okay. See you then.",
  str_homestory_chat_12525009 = "... Aren't you going to insist on inviting me?",
  str_homestory_chat_12525010 = "Okay...",
  str_homestory_chat_12525011 = "Ahem. Charon, there is a ball tonight. I insist that you attend.",
  str_homestory_chat_12525012 = "Well, I guess I'll grudgingly agree to it, on your account.",
  str_homestory_chat_12526001 = "I have a question.",
  str_homestory_chat_12526002 = "Oh? I'll do my best to answer PlayerName's question.",
  str_homestory_chat_12526003 = "Tell me, my friend. What's troubling you?",
  str_homestory_chat_12526004 = "All trains run on tracks...",
  str_homestory_chat_12526005 = "Why doesn't your Other End need any?",
  str_homestory_chat_12526006 = "Hahahah... That's a very good question you have!",
  str_homestory_chat_12526007 = "Other End is a friend of mine. You can think of it as my inspiration. And inspiration must be free.",
  str_homestory_chat_12526008 = "How can you call it free if it's trapped by rails?",
  str_homestory_chat_12526009 = "But it can't just run amok in Eraveil!",
  str_homestory_chat_10699999 = "Want to have a chat with me, PlayerName?",
  str_homestory_chat_10601001 = "Yeah.",
  str_homestory_chat_10601002 = "It would be my pleasure, but you must keep an eye on the time.",
  str_homestory_chat_10601003 = "You have several plans later, don't forget.",
  str_homestory_chat_10621001 = "As for dessert...",
  str_homestory_chat_10621002 = "Do you have any suggestions on the style?",
  str_homestory_chat_10621003 = "You guys are going to do desserts?",
  str_homestory_chat_10621004 = "Yes, we want to prepare some snacks for everyone.",
  str_homestory_chat_10621005 = "Hm, I recommend the strawberry coconut cream cake...",
  str_homestory_chat_10621006 = "But if it's too much trouble to make, you can instead pick something else.",
  str_homestory_chat_10621007 = "Strawberry coconut cream cake...",
  str_homestory_chat_10621008 = "It's Carleen's favorite dessert, isn't it?",
  str_homestory_chat_10621009 = "It's not that I want to eat it, I just... just sincerely recommend it.",
  str_homestory_chat_10621010 = "We have the help of an expert this time!",
  str_homestory_chat_10621011 = "This will definitely go well.",
  str_homestory_chat_10621012 = "Well, it's all finished. You must come try it!",
  str_homestory_chat_10622001 = "Nice weather today!",
  str_homestory_chat_10622002 = "Yes, the weather here is good as always.",
  str_homestory_chat_10622003 = "You like sunny days, huh?",
  str_homestory_chat_10622004 = "A sunny day puts people in a good mood.",
  str_homestory_chat_10622005 = "But having only sunny days will be a problem too.",
  str_homestory_chat_10622006 = "It's because not every day is a sunny day...",
  str_homestory_chat_10622007 = "That having a sunny day will cheer people up.",
  str_homestory_chat_10622008 = "PlayerName, you've said something very philosophical.",
  str_homestory_chat_10622009 = "Yeah.",
  str_homestory_chat_10622010 = "Perhaps what moves people is not just sunny days...",
  str_homestory_chat_10622011 = "It's also the peaceful atmosphere here.",
  str_homestory_chat_10622012 = "I wish days like these would last forever.",
  str_homestory_chat_10623001 = "Do you have time?",
  str_homestory_chat_10623002 = "PlayerName, is there something you need my help with?",
  str_homestory_chat_10623003 = "Oh, yes.",
  str_homestory_chat_10623004 = "It's nothing particularly important, though.",
  str_homestory_chat_10623005 = "If you have something else to do, then do that.",
  str_homestory_chat_10623006 = "Let me think...",
  str_homestory_chat_10623007 = "Just some little things. You don't have to bother with them.",
  str_homestory_chat_10623008 = "I don't think there's any.",
  str_homestory_chat_10623009 = "Are you done with what you have to do?",
  str_homestory_chat_10623010 = "There are still some things, but you don't have to trouble yourself with them.",
  str_homestory_chat_10623011 = "But I'd like to do what I can for everyone.",
  str_homestory_chat_10624001 = "I heard you have something to tell me?",
  str_homestory_chat_10624002 = "PlayerName, Vice told me that...",
  str_homestory_chat_10624003 = "You were late to the fishing competition a few days ago.",
  str_homestory_chat_10624004 = "Yes...",
  str_homestory_chat_10624005 = "I had half an hour when I left, and didn't think that the destination was so far...",
  str_homestory_chat_10624006 = "You can ask me for help the next time you're in this sort of situation.",
  str_homestory_chat_10624007 = "I can summon a horse and fetch you there.",
  str_homestory_chat_10624008 = "Anyway, don't get into the bad habit of being late.",
  str_homestory_chat_10625001 = "I heard you want to go fishing.",
  str_homestory_chat_10625002 = "Yes, any plans for a fishing trip soon?",
  str_homestory_chat_10625003 = "Yes!",
  str_homestory_chat_10625004 = "I guess I should get ready.",
  str_homestory_chat_10625005 = "Speaking of getting ready, you were way too prepared the last time.",
  str_homestory_chat_10625006 = "You even brought a tent umbrella and the lance.",
  str_homestory_chat_10625007 = "The tent umbrella is to protect against the rain when we're in the middle of fishing...",
  str_homestory_chat_10625008 = "The lance can be used to deal with escaping fish. One stab, and done!",
  str_homestory_chat_10625009 = "I don't like unexpected things happening.",
  str_homestory_chat_10625010 = "Being prepared is the foundation for sure success.",
  str_homestory_chat_10625011 = "I feel like I've learned something yet again...",
  str_homestory_chat_10626001 = "Any suggestion?",
  str_homestory_chat_10626002 = "I'd like to add some ornament here, but I'm not sure what yet.",
  str_homestory_chat_10626003 = "Ornament? Let me think...",
  str_homestory_chat_10626004 = "How about some equipment for martial arts training?",
  str_homestory_chat_10626005 = "Like a sandbag?",
  str_homestory_chat_10626006 = "Hmm... Sandbags are common training equipment. Most people will benefit from it.",
  str_homestory_chat_10626007 = "Like an archery target?",
  str_homestory_chat_10626008 = "Hmm... Aurorian archers like Vice would love it.",
  str_homestory_chat_10626009 = "Okay... I got it.",
  str_homestory_chat_10626010 = "Once you firm up a plan, the rest of the work becomes easy.",
  str_homestory_chat_10626011 = "Search for blueprints, gather materials and build what you need.",
  str_homestory_chat_10626012 = "That's right. And these are what I do best.",
  str_homestory_chat_12899999 = "Hello there! Do you have any advice to give?",
  str_homestory_chat_12801001 = "No.",
  str_homestory_chat_12801002 = "No, I just wanted to say hello.",
  str_homestory_chat_12801003 = "Your greetings make me very happy!",
  str_homestory_chat_12801004 = "Come, please take these Holy Water Shells. They will surely come in handy!",
  str_homestory_chat_12821001 = "What are you looking at?",
  str_homestory_chat_12821002 = "Whoa, My canines seems to have grown longer.",
  str_homestory_chat_12821003 = "I didn't expect the cross to be used as a mirror...",
  str_homestory_chat_12821004 = "Do you want to compare the length of our canines?",
  str_homestory_chat_12821005 = "Come here, stand in front of the cross.",
  str_homestory_chat_12821006 = "No thanks...",
  str_homestory_chat_12821007 = "Relax, my cross reflects really clearly!",
  str_homestory_chat_12821008 = "You sure you don't want to see how long your canines are?",
  str_homestory_chat_12821009 = "Or do you not have any canines?",
  str_homestory_chat_12822001 = "Raphael, what are you doing?",
  str_homestory_chat_12822002 = "Huff—",
  str_homestory_chat_12822003 = "I'm going to give these holy water bombs to everyone.",
  str_homestory_chat_12822004 = "Everyone's getting one!",
  str_homestory_chat_12822005 = "And what's the reason for this?",
  str_homestory_chat_12822006 = "Well, of course it's because... Eraveil's Aurorian population is growing...",
  str_homestory_chat_12822007 = "In case someone gets hurt by accident, and I'm not around...",
  str_homestory_chat_12822008 = "I would be devastated if I couldn't help save them in time!",
  str_homestory_chat_12823001 = "Hi, Raphael.",
  str_homestory_chat_12823002 = "The pastry I made the other day was great, wasn't it?",
  str_homestory_chat_12823003 = "I can make more and give you some!",
  str_homestory_chat_12823004 = "Uh, I'll pass...",
  str_homestory_chat_12823005 = "Understood!",
  str_homestory_chat_12823006 = "What did you understand?",
  str_homestory_chat_12823007 = "You must think the pastry I make is too refined...",
  str_homestory_chat_12823008 = "So you can't bear to eat it!",
  str_homestory_chat_12823009 = "...Sure, you can take it that way.",
  str_homestory_chat_12823010 = "Why come to me again?",
  str_homestory_chat_12823011 = "Because everyone says PlayerName has the world's greatest appreciation for food!",
  str_homestory_chat_12823012 = "And who came up with that?!",
  str_homestory_chat_12823013 = "Tell me, and I'll recommend you to someone with an even higher level of appreciation!",
  str_homestory_chat_10799999 = "La, la-la, la... Oh, PlayerName! You called out to me?",
  str_homestory_chat_10721001 = "Am I interrupting your singing?",
  str_homestory_chat_10721002 = "N-No, not at all. I was just... Um.",
  str_homestory_chat_10721003 = "Did you want to see me for something?",
  str_homestory_chat_10722001 = "What are you looking for?",
  str_homestory_chat_10722002 = "Will there be rabbits here, PlayerName?",
  str_homestory_chat_10722003 = "I guess?",
  str_homestory_chat_10722004 = "I think I've seen some people organize hunting activities...",
  str_homestory_chat_10722005 = "And among the prey they bring back...",
  str_homestory_chat_10722006 = "Stop! Don't continue!",
  str_homestory_chat_10722007 = "That's terrible... Things like that must be stopped!",
  str_homestory_chat_10722008 = "I don't think there's any.",
  str_homestory_chat_10722009 = "I haven't seen one anyway.",
  str_homestory_chat_10722010 = "...This is fine too. At least I won't see them being hurt here.",
  str_homestory_chat_10723001 = "Have you gotten used to this place?",
  str_homestory_chat_10723002 = "The wind here is very gentle...",
  str_homestory_chat_10723003 = "You think so too?",
  str_homestory_chat_10723004 = "What is happiness to you, PlayerName?",
  str_homestory_chat_10723005 = "Staying here.",
  str_homestory_chat_10723006 = "Staying in my hometown and guarding this land. To me...",
  str_homestory_chat_10723007 = "This is a blissful thing.",
  str_homestory_chat_10723008 = "I see...",
  str_homestory_chat_10723009 = "Peace and quiet.",
  str_homestory_chat_10723010 = "No lies, no bloodshed, and unwavering smiles on the faces of all children...",
  str_homestory_chat_10723011 = "That is truly... remarkable happiness.",
  str_homestory_chat_10751001 = "Where's the special fish?",
  str_homestory_chat_10751002 = "Oh the breeze, what a feeling!",
  str_homestory_chat_10751003 = "What are you talking about?",
  str_homestory_chat_10751004 = "Maybe it's you. Are you in a rush?",
  str_homestory_chat_10751005 = "I am, actually... I heard you saw a special fish?",
  str_homestory_chat_10751006 = "I know words travel fast, but this is still a surprise.",
  str_homestory_chat_10751007 = "Or was it coming from some particular one? For example, that rabbit?",
  str_homestory_chat_10751008 = "Nope... Forget about it. Where's the fish?",
  str_homestory_chat_10751009 = "The rabbit... mentioned that the fish loves a tree of some sort.",
  str_homestory_chat_10751010 = "Could it be... the Dwarf Leaf Quinlan Tree?",
  str_homestory_chat_10751011 = "Looks like I gotta make another trip...",
  str_homestory_chat_10751012 = "What?",
  str_homestory_chat_10751013 = "No worries! The seeds of Dwarf Leaf Quinlan Tree, right? Easy-peasy!",
  str_homestory_chat_10751014 = "Thanks!",
  str_homestory_chat_10199999 = "I received your greeting.",
  str_homestory_chat_10121001 = "Okay.",
  str_homestory_chat_10121002 = "I'm good. Is there anything else you want to say?",
  str_homestory_chat_10121003 = "Yeah, uh... I...",
  str_homestory_chat_10121004 = "Looks like I'll need some patience to wait for you to express yourself.",
  str_homestory_chat_10122001 = "You want to see me?",
  str_homestory_chat_10122002 = "PlayerName, I'd like you to keep one fact in mind.",
  str_homestory_chat_10122003 = "What fact?",
  str_homestory_chat_10122004 = "The waterfront here is very suitable for growing white narcissus.",
  str_homestory_chat_10122005 = "...",
  str_homestory_chat_10122006 = "Well? Do you need me to list the reasons one by one on why it's suitable?",
  str_homestory_chat_10122007 = "No need... I will consider it.",
  str_homestory_chat_10123001 = "How are you getting along here?",
  str_homestory_chat_10123002 = "Yes... Though there are many places here which cannot compare to Northland...",
  str_homestory_chat_10123003 = "It still has something very commendable to offer.",
  str_homestory_chat_10123004 = "What is it?",
  str_homestory_chat_10123005 = "The sky, air, and water here are all very clean.",
  str_homestory_chat_10123006 = "Living here, the souls of the Aurorians will have their souls nourished.",
  str_homestory_chat_10123007 = "That sounds very much like praise...",
  str_homestory_chat_10123008 = "What do you mean it can't compare to Northland?!",
  str_homestory_chat_10123009 = "I hope you don't dwell on these tiny details...",
  str_homestory_chat_10123010 = "And lose sight of what is truly valuable—",
  str_homestory_chat_10123011 = "I think a clean house nourishes the soul of Aurorians.",
  str_homestory_chat_10123012 = "I hope you will always guard the tranquility and purity of this place.",
  str_homestory_chat_10123013 = "Okay... Sure, I will.",
  str_homestory_chat_10124001 = "What are you looking at?",
  str_homestory_chat_10124002 = "The mirror. Another home has appeared in there...",
  str_homestory_chat_10124003 = "Isn't that a normal occurrence?",
  str_homestory_chat_10124004 = "Don't treat the Lake Mirror as an ordinary mirror.",
  str_homestory_chat_10124005 = "It can reveal illusions that are thousands of miles away...",
  str_homestory_chat_10124006 = "It can connect two worlds, and let you see yourself in the deepest part of your soul...",
  str_homestory_chat_10124007 = "Never underestimate its power.",
  str_homestory_chat_10124008 = "So... what does all of this have to do with reflecting homes in the mirror?",
  str_homestory_chat_10124009 = "...",
  str_homestory_chat_10124010 = "PlayerName, stop coming to chat with me.",
  str_homestory_chat_10299999 = "Thank you for asking. All is well with me.",
  str_homestory_chat_10221001 = "Oh... That's good.",
  str_homestory_chat_10221002 = "Judging from how you look...",
  str_homestory_chat_10221003 = "It seems you've had lots of chores to do lately. It's best to get more rest.",
  str_homestory_chat_10221004 = "I'll take a break then.",
  str_homestory_chat_10221005 = "You can join me in meditation under the tree there.",
  str_homestory_chat_10222001 = "Enjoying the view?",
  str_homestory_chat_10222002 = "The scenery here often reminds me of my hometown.",
  str_homestory_chat_10222003 = "The valley, river, and forest... Only the cherry blossoms are missing.",
  str_homestory_chat_10222004 = "How about planting some cherry blossoms?",
  str_homestory_chat_10222005 = "I don't mean to interfere with your decision, but...",
  str_homestory_chat_10222006 = "How about planting some...",
  str_homestory_chat_10222007 = "You want to plant cherry blossoms here?",
  str_homestory_chat_10222008 = "I planned to, yes.",
  str_homestory_chat_10222009 = "Not every type of soil is suitable for cherry blossoms.",
  str_homestory_chat_10222010 = "Well, this is a problem that has to be resolved with the proper consultation.",
  str_homestory_chat_10223001 = "What are you doing?",
  str_homestory_chat_10223002 = "...",
  str_homestory_chat_10223003 = "Why is Miss Hiiro tapping on this blade...",
  str_homestory_chat_10223004 = "I'm powdering Sakae.",
  str_homestory_chat_10223005 = "What is \"powdering\"?",
  str_homestory_chat_10223006 = "When you tap the blade with a powdering stick, the powder absorbs the old oil on the blade.",
  str_homestory_chat_10223007 = "It's a form of maintenance for Sakae.",
  str_homestory_chat_10223008 = "Amazing!",
  str_homestory_chat_10223009 = "Can I watch for a little longer?",
  str_homestory_chat_10223010 = "Sure.",
  str_homestory_chat_10224001 = "It's so quiet...",
  str_homestory_chat_10224002 = "The environment here is perfect for meditation.",
  str_homestory_chat_10224003 = "Did you find a wonderful place to meditate?",
  str_homestory_chat_10224004 = "At the foot of the mountain, by the creek, under the trees, close your eyes and sink into the depths of your mind...",
  str_homestory_chat_10224005 = "PlayerName, you can give it a try too. This can build up your strength.",
  str_homestory_chat_10224006 = "Oh. That does sound like it's worth a try.",
  str_homestory_chat_10224007 = "Is it a must to pick a location to meditate?",
  str_homestory_chat_10224008 = "No, you can meditate even if you're in the middle of the city.",
  str_homestory_chat_10224009 = "Peace of mind removes all noise.",
  str_homestory_chat_10224010 = "But it's easy to meditate here, away from the hustle and bustle.",
  str_homestory_chat_10224011 = "PlayerName, you can give it a try too.",
  str_homestory_chat_10225001 = "You seem to be wary of something.",
  str_homestory_chat_10225002 = "Martial artists should always be aware of their surroundings.",
  str_homestory_chat_10225003 = "That's reasonable.",
  str_homestory_chat_10225004 = "This must be Miss Hiiro's way of honing her concentration.",
  str_homestory_chat_10225005 = "...",
  str_homestory_chat_10225006 = "(I seem to have interrupted Miss Hiiro's training.)",
  str_homestory_chat_10225007 = "There's no need to be so nervous.",
  str_homestory_chat_10225008 = "We're all friends here.",
  str_homestory_chat_10225009 = "I cannot relax, even in a comfortable environment.",
  str_homestory_chat_10225010 = "This is my way of honing my concentration.",
  str_homestory_chat_10225011 = "Alright. I'll leave you alone then, Miss Hiiro.",
  str_homestory_chat_10226001 = "Meditating again?",
  str_homestory_chat_10226002 = "No, I'm just enjoying the scenery.",
  str_homestory_chat_10226003 = "Hmm? Hiiro would appreciate the scenery too?",
  str_homestory_chat_10226004 = "Don't be so surprised. Observing and learning from the world is part of my training.",
  str_homestory_chat_10226005 = "Sounds complicated...",
  str_homestory_chat_10226006 = "You should give it a try.",
  str_homestory_chat_10226007 = "This training has nothing to do with your physical fitness. It's more for your mind and heart.",
  str_homestory_chat_10226008 = "O-Okay, I'll give it a try.",
  str_homestory_chat_11199999 = "Yes. I hope that you will be able to stand straight the next time you greet me, compatriot.",
  str_homestory_chat_11101001 = "Err...",
  str_homestory_chat_11101002 = "Greetings don't have to be so serious, surely?",
  str_homestory_chat_11101003 = "No, this has nothing to do with seriousness.",
  str_homestory_chat_11101004 = "This is a state of mind.",
  str_homestory_chat_11121001 = "How have you been?",
  str_homestory_chat_11121002 = "Don't stand too close to me, compatriot.",
  str_homestory_chat_11121003 = "I suddenly noticed that your pupils seem to have gotten bigger.",
  str_homestory_chat_11121004 = "This rude gawking... If it were anyone else...",
  str_homestory_chat_11121005 = "My Azure Flame would have been unsheathed.",
  str_homestory_chat_11121006 = "It looks really mysterious.",
  str_homestory_chat_11121007 = "When I focus, I...",
  str_homestory_chat_11121008 = "Okay, get out of the way.",
  str_homestory_chat_11121009 = "Oh, I'll take note for next time.",
  str_homestory_chat_11121010 = "Well, then stand further away now!",
  str_homestory_chat_11121011 = "Ah, okay.",
  str_homestory_chat_11122001 = "I saw you on a stroll.",
  str_homestory_chat_11122002 = "There are many little stones on this path.",
  str_homestory_chat_11122003 = "Isn't that normal?",
  str_homestory_chat_11122004 = "My tail always gets nicked.",
  str_homestory_chat_11122005 = "Compatriot, I hope you can sweep them away.",
  str_homestory_chat_11122006 = "Oh, okay.",
  str_homestory_chat_11122007 = "Is it troubling you?",
  str_homestory_chat_11122008 = "Yes, I have to walk with my tail up.",
  str_homestory_chat_11122009 = "If I don't, it gets caught on the stones.",
  str_homestory_chat_11122010 = "Looks like I'll have to clear the road.",
  str_homestory_chat_11123001 = "How's it going?",
  str_homestory_chat_11123002 = "I'm quite happy with this life, Compatriot.",
  str_homestory_chat_11123003 = "Thank you for the confirmation!",
  str_homestory_chat_11123004 = "There is no overbearing rule, no corrupt system...",
  str_homestory_chat_11123005 = "Wait...",
  str_homestory_chat_11123006 = "Why would you associate with those things?",
  str_homestory_chat_11123007 = "We're all friends, why would there be...",
  str_homestory_chat_11123008 = "What's all this...",
  str_homestory_chat_11123009 = "Don't worry, compatriot. I am just praising the way of life here.",
  str_homestory_chat_11123010 = "We're all friends!",
  str_homestory_chat_11123011 = "Maybe it's because of this that life here is so nice.",
  str_homestory_chat_11124001 = "You're training?",
  str_homestory_chat_11124002 = "Huff— Huff—",
  str_homestory_chat_11124003 = "Indeed, compatriot. I hope you can join in.",
  str_homestory_chat_11124004 = "I heard from Vice that you are desperate to improve yourself.",
  str_homestory_chat_11124005 = "I'm not that desperate...",
  str_homestory_chat_11124006 = "Time waits for no man. I hope you act fast.",
  str_homestory_chat_11124007 = "Ah, okay.",
  str_homestory_chat_11124008 = "What's your training plan like?",
  str_homestory_chat_11124009 = "In addition to basic physical exercises, I will also teach you combat.",
  str_homestory_chat_11124010 = "It is only between life and death that you can be inspired to...",
  str_homestory_chat_11124011 = "...Oh, I'm not really in a rush to improve myself or anything.",
  str_homestory_chat_11125001 = "What a great day.",
  str_homestory_chat_11125002 = "Yes, it's always sunny in Eraveil.",
  str_homestory_chat_11125003 = "Everyday is perfect for exercise.",
  str_homestory_chat_11125004 = "Would you like to join me, compatriot?",
  str_homestory_chat_11125005 = "Sure.",
  str_homestory_chat_11125006 = "I enjoy some exercise from time to time.",
  str_homestory_chat_11125007 = "As long as it's not too much...",
  str_homestory_chat_11125008 = "You will never progress if you don't push yourself.",
  str_homestory_chat_11125009 = "Don't get too comfortable with the present.",
  str_homestory_chat_11125010 = "I just want to stay fit!",
  str_homestory_chat_11125011 = "Maybe some other time...",
  str_homestory_chat_11125012 = "I've seen how people exercise in Illumina...",
  str_homestory_chat_11125013 = "I don't think I can handle it one more time.",
  str_homestory_chat_11125014 = "Don't force yourself, compatriot. Do what you can.",
  str_homestory_chat_13899999 = "Hey, my defeated opponent, you want to challenge me again?",
  str_homestory_chat_13801001 = "Yes! I've come to challenge you!",
  str_homestory_chat_13801002 = "I'll definitely not lose to you in this racing game!",
  str_homestory_chat_13801003 = "Ha! Then be prepared to taste defeat once more.",
  str_homestory_chat_13821001 = "Hi, whatcha up to?",
  str_homestory_chat_13821002 = "PlayerName, has the game room been built yet?",
  str_homestory_chat_13821003 = "Huh?",
  str_homestory_chat_13821004 = "You want to build a game room?",
  str_homestory_chat_13821005 = "Isn't the plan to build a game room a matter of fact?",
  str_homestory_chat_13821006 = "I don't think so...",
  str_homestory_chat_13821007 = "How can there be no game room?!",
  str_homestory_chat_13821008 = "Is the game machine not enough for you?",
  str_homestory_chat_13821009 = "Of course not!",
  str_homestory_chat_13821010 = "Only a game room can create an immersive gaming experience!",
  str_homestory_chat_13822001 = "I heard you lost in the game.",
  str_homestory_chat_13822002 = "It's fishing, not gaming.",
  str_homestory_chat_13822003 = "But I won't lose to anyone, even in fishing!",
  str_homestory_chat_13822004 = "What's that you're holding?",
  str_homestory_chat_13822005 = "Heheh, my new invention! It's a fishing machine...",
  str_homestory_chat_13822006 = "Just put it in the water and all the fish in a ten-meter radius will go belly up!",
  str_homestory_chat_13822007 = "And then I just have to pull them all out, and I'll win...",
  str_homestory_chat_13822008 = "What an insane thirst for victory...",
  str_homestory_chat_13822009 = "I'm confiscating your fishing machine.",
  str_homestory_chat_13822010 = "No way!",
  str_homestory_chat_13823001 = "On a stroll?",
  str_homestory_chat_13823002 = "PlayerName, I've walked to all corners of this place.",
  str_homestory_chat_13823003 = "Just the surface, of course. There's still the underground...",
  str_homestory_chat_13823004 = "What are you up to?",
  str_homestory_chat_13823005 = "Just exploring and seeing if there are any more fun technological items left.",
  str_homestory_chat_13823006 = "After all, the technology of you Caelestites...",
  str_homestory_chat_13823007 = "But I'll be sure to let you know if I discover anything!",
  str_homestory_chat_13823008 = "I got a bad feeling about this...",
  str_homestory_chat_13823009 = "What are you talking about?",
  str_homestory_chat_13823010 = "Well, I'll be sure to let you know if I discover anything!",
  str_homestory_chat_13823011 = "...I'll believe you.",
  str_homestory_chat_13824001 = "What are you up to?",
  str_homestory_chat_13824002 = "PlayerName, have you developed any new games recently?",
  str_homestory_chat_13824003 = "I've finished all the games. I'm bored...",
  str_homestory_chat_13824004 = "Come help if you have nothing to do—",
  str_homestory_chat_13824005 = "Come clean up over here.",
  str_homestory_chat_13824006 = "Wow, the winner of the Emperor's Cup is actually being ordered by a Caelestite to clean up!",
  str_homestory_chat_13824007 = "Water the flowers.",
  str_homestory_chat_13824008 = "Wow, the Tech Officer of Illumina is actually being ordered by a Caelestite to water flowers!",
  str_homestory_chat_13824009 = "...",
  str_homestory_chat_13824010 = "Okay, I'll treat it like a simulation game.",
  str_homestory_chat_13825001 = "Playing a new game?",
  str_homestory_chat_13825002 = "Yeah. Guess what I'm playing.",
  str_homestory_chat_13825003 = "In this game, you need to pick up a weapon and hit the enemy.",
  str_homestory_chat_13825004 = "Defeat the enemies to get materials so you can build tools!",
  str_homestory_chat_13825005 = "Could it be...?",
  str_homestory_chat_13825006 = "A role-play game?",
  str_homestory_chat_13825007 = "An action game?",
  str_homestory_chat_13825008 = "Close but no. Let me give you one more hint.",
  str_homestory_chat_13825009 = "The enemy is short, stout and very hard!",
  str_homestory_chat_13825010 = "That's quite strange!",
  str_homestory_chat_13825011 = "Something short, stout, and tough that drops materials...",
  str_homestory_chat_13825012 = "Hold on. Are you mining?",
  str_homestory_chat_13825013 = "Correct!",
  str_homestory_chat_14499999 = "Hello! What are your plans for today? Do you need my supervision?",
  str_homestory_chat_14401001 = "Not for now.",
  str_homestory_chat_14401002 = "If you have plans, you must let me know!",
  str_homestory_chat_14401003 = "I'll help you with your plans and make them go perfectly.",
  str_homestory_chat_14421001 = "How are you getting along here?",
  str_homestory_chat_14421002 = "Curie loves it here.",
  str_homestory_chat_14421003 = "Dragons are creatures of the sky after all.",
  str_homestory_chat_14421004 = "Does Miss Vivian like it here too?",
  str_homestory_chat_14421005 = "PlayerName has asked everyone this question...",
  str_homestory_chat_14421006 = "No one will answer \"no,\" right?",
  str_homestory_chat_14421007 = "I do like this place a lot, like Curie.",
  str_homestory_chat_14422001 = "Hi, Vivian.",
  str_homestory_chat_14422002 = "What are you doing, PlayerName?",
  str_homestory_chat_14422003 = "Ah, I'm calculating the recent income from rent and expenses.",
  str_homestory_chat_14422004 = "What a troubling task...",
  str_homestory_chat_14422005 = "I'll help you.",
  str_homestory_chat_14422006 = "...",
  str_homestory_chat_14422007 = "Done. Come have a look.",
  str_homestory_chat_14422008 = "That was fast!",
  str_homestory_chat_14422009 = "Anything to do with calculations is not too difficult for me.",
  str_homestory_chat_14423001 = "You want to see me?",
  str_homestory_chat_14423002 = "PlayerName, do you have any recent plans to remodel your home?",
  str_homestory_chat_14423003 = "Of course!",
  str_homestory_chat_14423004 = "I've been thinking so much about what changes to make I even dream—",
  str_homestory_chat_14423005 = "I have so many ideas I can't keep up with them.",
  str_homestory_chat_14423006 = "Not for now...",
  str_homestory_chat_14423007 = "My inspiration has dried up...",
  str_homestory_chat_14423008 = "Take your time, and don't push yourself too hard. A balance between work and play is best.",
  str_homestory_chat_14423009 = "But if you have plans, you can come see me whenever you'd like.",
  str_homestory_chat_14423010 = "Give me a list and I'll help you make them all a reality with the highest efficiency.",
  str_homestory_chat_14424001 = "What's wrong?",
  str_homestory_chat_14424002 = "I'm going to get those guys to explain themselves!",
  str_homestory_chat_14424003 = "How did they end up making such a mess of their work?!",
  str_homestory_chat_14424004 = "What happened?",
  str_homestory_chat_14424005 = "It's the home renovation plan. I was sure I split the tasks...",
  str_homestory_chat_14424006 = "I calculated the time taken to complete them, and assigned them to the person in charge—",
  str_homestory_chat_14424007 = "This should have been very easy work for them, but...",
  str_homestory_chat_14424008 = "No one could finish on time!",
  str_homestory_chat_14424009 = "There's no need to be so tense.",
  str_homestory_chat_14424010 = "No, I can't stand it! I will settle the score with them!",
  str_homestory_chat_14425001 = "Any suggestion?",
  str_homestory_chat_14425002 = "I've been working hard with Cloud Gardens renovation plan.",
  str_homestory_chat_14425003 = "But everyone's performance is different...",
  str_homestory_chat_14425004 = "So, we've got endless problems here.",
  str_homestory_chat_14425005 = "Like what?",
  str_homestory_chat_14425006 = "Like Dove can never complete her logging quest in time.",
  str_homestory_chat_14425007 = "Ah... Dove has always been like that.",
  str_homestory_chat_14425008 = "We've given up the idea of making her less lazy.",
  str_homestory_chat_14425009 = "I guess I must improve my Cloud Gardens renovation plan.",
  str_homestory_chat_14425010 = "People's characteristics and work styles must be taken into consideration this time!",
  str_homestory_chat_14425011 = "Don't be too hard on yourself, Vivian.",
  str_homestory_chat_12199999 = "Ah, I can feel the boundless love in your tone from your greeting.",
  str_homestory_chat_12101001 = "I d-don't think there is...",
  str_homestory_chat_12101002 = "Would you deny this love?",
  str_homestory_chat_12101003 = "My heart is once again torn to shreds by the indifferent thorns of a rose...",
  str_homestory_chat_12101004 = "Hey! Can you please be a little more normal?",
  str_homestory_chat_12101005 = "It's just a greeting!",
  str_homestory_chat_12121001 = "Have you been cultivating flowers recently?",
  str_homestory_chat_12121002 = "Oh yes, PlayerName, would you like to visit my latest rose garden?",
  str_homestory_chat_12121003 = "Every flower is turning in anticipation of your arrival!",
  str_homestory_chat_12121004 = "I'll pass...",
  str_homestory_chat_12121005 = "I have too many tasks to complete. I'll go see it later.",
  str_homestory_chat_12121006 = "I am relieved to have secured your promise to visit.",
  str_homestory_chat_12121007 = "Let us hope the flowers and I will not be disappointed.",
  str_homestory_chat_12121008 = "Sure!",
  str_homestory_chat_12121009 = "There's plenty of sunlight here, so you can show off your gardening talents.",
  str_homestory_chat_12121010 = "Ah, what thoughtful words.",
  str_homestory_chat_12121011 = "You're right. This place is full of the beauty of nature—",
  str_homestory_chat_12121012 = "It's a great fit for me!",
  str_homestory_chat_12122001 = "What are you laughing at?",
  str_homestory_chat_12122002 = "So many children have moved into this place...",
  str_homestory_chat_12122003 = "It sure gladdens the heart!",
  str_homestory_chat_12122004 = "You like young children?",
  str_homestory_chat_12122005 = "Yes! Seeing their innocent eyes, and rosy faces...",
  str_homestory_chat_12122006 = "Makes me think of all kinds of flowers!",
  str_homestory_chat_12122007 = "It's a pity that some disobedient children are like flowers that have grown out the wrong way.",
  str_homestory_chat_12122008 = "When I encounter flowers like these, I prune them!",
  str_homestory_chat_12122009 = "Uh... Did I just hear something terrible?",
  str_homestory_chat_11499999 = "PlayerName, it's a pleasure to meet you.",
  str_homestory_chat_11401001 = "Hello, Schwartz.",
  str_homestory_chat_11401002 = "Thanks for inviting me to your lovely home.",
  str_homestory_chat_11401003 = "Don't mention it.",
  str_homestory_chat_11401004 = "I hope this place'll thrive under your governance.",
  str_homestory_chat_11421001 = "What do you think of this place?",
  str_homestory_chat_11421002 = "It's orderly and great. It seems that you've put in an awful lot of work on this.",
  str_homestory_chat_11421003 = "PlayerName, you'll inevitably encounter difficulties when running this place.",
  str_homestory_chat_11421004 = "If you ever require help, I'll always set aside time for you.",
  str_homestory_chat_11421005 = "Thanks!",
  str_homestory_chat_11421006 = "I'd like to ask for your guidance in this regard, My Lord.",
  str_homestory_chat_11421007 = "Order is at the heart of governance.",
  str_homestory_chat_11421008 = "It may be harsh, but it's essential.",
  str_homestory_chat_11421009 = "(Oh man... Are we starting this discussion now...?)",
  str_homestory_chat_11421010 = "It's unnecessary right now...",
  str_homestory_chat_11421011 = "Since we're all friends here, I can hardly call it \"governance.\"",
  str_homestory_chat_11421012 = "But I do hope your method can bring prosperity to this place.",
  str_homestory_chat_11422001 = "You're more than welcome to visit.",
  str_homestory_chat_11422002 = "Your home, like Lumopolis, is blessed with wonderful sunny days.",
  str_homestory_chat_11422003 = "It's perfect weather for...",
  str_homestory_chat_11422004 = "Fishing!",
  str_homestory_chat_11422005 = "Sitting by the river, as you wait for your prey to take the bait...",
  str_homestory_chat_11422006 = "Is this a popular relaxing activity in these parts?",
  str_homestory_chat_11422007 = "Want to try?",
  str_homestory_chat_11422008 = "Sounds good to me.",
  str_homestory_chat_11422009 = "Running!",
  str_homestory_chat_11422010 = "It's a sport for young people.",
  str_homestory_chat_11422011 = "I'm quite happy to watch from the sidelines.",
  str_homestory_chat_11423001 = "Reading?",
  str_homestory_chat_11423002 = "On a beautiful sunny day like this, reading is certainly the most relaxing pastime.",
  str_homestory_chat_11423003 = "PlayerName, I can always let you have a look if you're interested.",
  str_homestory_chat_11423004 = "Thanks!",
  str_homestory_chat_11423005 = "Any book that can catch your eyes must be interesting, right?",
  str_homestory_chat_11423006 = "I don't read for \"fun.\"",
  str_homestory_chat_11423007 = "I'd prefer to question the boundaries of the universe and explore the depths of human nature in books.",
  str_homestory_chat_11423008 = "But it's great if you can have fun with it.",
  str_homestory_chat_11423009 = "It's all right...",
  str_homestory_chat_11423010 = "I'd love to read and take a break, but I'm just swamped with work...",
  str_homestory_chat_11423011 = "You can always entrust some to me if you can't handle it.",
  str_homestory_chat_12999999 = "Oh, it's really you...",
  str_homestory_chat_12921001 = "Ah, yes.",
  str_homestory_chat_12921002 = "I've sensed your arrival in the wind.",
  str_homestory_chat_12921003 = "That sounds incredible?",
  str_homestory_chat_12921004 = "You have a peculiar aura.",
  str_homestory_chat_12922001 = "You seem very relaxed.",
  str_homestory_chat_12922002 = "I've realized that... something interesting will occur if I sunbathe in a cage...",
  str_homestory_chat_12922003 = "What is it?",
  str_homestory_chat_12922004 = "Some parts of your face will feel hot while the rest remains cold.",
  str_homestory_chat_12922005 = "Why is that?",
  str_homestory_chat_12922006 = "I'm not sure either...",
  str_homestory_chat_12922007 = "Let's not think about it. Thinking is far too exhausting.",
  str_homestory_chat_12922008 = "Is it because of the cage?",
  str_homestory_chat_12922009 = "The cage casts a shadow on your face, so the areas where the light doesn't hit will become cool.",
  str_homestory_chat_12922010 = "Perhaps, you're right.",
  str_homestory_chat_12922011 = "But I don't want to analyze things since thinking is far too exhausting.",
  str_homestory_chat_12923001 = "You seem to like it here.",
  str_homestory_chat_12923002 = "Warm sunshine...",
  str_homestory_chat_12923003 = "Phew... That's right... I feel like silk threads...",
  str_homestory_chat_12923004 = "Phew... Yeah, I'm not asleep...",
  str_homestory_chat_12923005 = "(I'd better not disturb her sleep.)",
  str_homestory_chat_12924001 = "What are you doing?",
  str_homestory_chat_12924002 = "Can you hear that?",
  str_homestory_chat_12924003 = "This place produces an abundance of sounds...",
  str_homestory_chat_12924004 = "in a continuous stream from the creek, the woods, and the valley.",
  str_homestory_chat_12924005 = "That's right.",
  str_homestory_chat_12924006 = "What's heard most in Lumopolis is the sound of the wind, and the Aurorians.",
  str_homestory_chat_12924007 = "In comparison, I much prefer the sounds here.",
  str_homestory_chat_12924008 = "I didn't even notice it.",
  str_homestory_chat_12924009 = "Now that you mentioned it, I can detect them...",
  str_homestory_chat_12924010 = "Listening can bring about unexpected happiness.",
  str_homestory_chat_12925001 = "Wood?",
  str_homestory_chat_12925002 = "Ah, indeed, wood. Do you have anything light and sturdy?",
  str_homestory_chat_12925003 = "Um... What are you planning to use this wood for all of a sudden?",
  str_homestory_chat_12925004 = "I want to remodel this cage—it's too big and heavy.",
  str_homestory_chat_12925005 = "Right, if the wood were lighter, it'd make things easier for you.",
  str_homestory_chat_12925006 = "However, the kind of wood you mentioned seems pretty difficult to find in Cloud Gardens.",
  str_homestory_chat_12925007 = "The trees here are all kind of strange, so it's difficult to make them into lumber.",
  str_homestory_chat_12925008 = "And... those Chubbs might not agree to chop it up either.",
  str_homestory_chat_12926001 = "Somewhere high up?",
  str_homestory_chat_12926002 = "I'm looking for a scenic spot in Cloud Gardens. After thinking it over...",
  str_homestory_chat_12926003 = "Somewhere higher up would be good, and it would be even better if it could overlook all of Cloud Gardens.",
  str_homestory_chat_12926004 = "Ah... So, I wanted to ask you if there's a place like that.",
  str_homestory_chat_12926005 = "I know a place.",
  str_homestory_chat_12926006 = "Perhaps Hyacinth Tower would do?",
  str_homestory_chat_12926007 = "But will Chubb agree?",
  str_homestory_chat_12926008 = "Definitely... not.",
  str_homestory_chat_12926009 = "I don't think so.",
  str_homestory_chat_12926010 = "Ah... I guess it's impossible then.",
  str_homestory_chat_12926011 = "What were you planning on doing?",
  str_homestory_chat_12926012 = "I want to hang my cage up high and enjoy the sensation of it swaying gently in the breeze.",
  str_homestory_chat_12926013 = "It would be ever so soothing and easier for me to fall asleep.",
  str_homestory_chat_12926014 = "Sure, but there might be strong winds at higher altitudes, so the cage could be prone to be shaken violently.",
  str_homestory_chat_12926015 = "Oh, you're right. That does make sense.",
  str_homestory_chat_12926016 = "So, it'd be better to keep things the way they are.",
  str_homestory_chat_12699999 = "Ah! Don't get too close.",
  str_homestory_chat_12601001 = "Why not?",
  str_homestory_chat_12601002 = "My power... can burn you...",
  str_homestory_chat_12601003 = "It's all right. I'll be careful.",
  str_homestory_chat_12601004 = "Hopefully... Let's hope I won't hurt you.",
  str_homestory_chat_12621001 = "Wanna chat?",
  str_homestory_chat_12621002 = "Chat?",
  str_homestory_chat_12621003 = "What's there to chat about...? Hmm... I'm not sure...",
  str_homestory_chat_12621004 = "Like anything happened recently?",
  str_homestory_chat_12621005 = "I won't remember anything meaningless...",
  str_homestory_chat_12621006 = "But what is considered meaningful...? I'm not sure...",
  str_homestory_chat_12621007 = "Like any scenery you've seen recently?",
  str_homestory_chat_12621008 = "Are you referring to the black shadows in the anti-explosion barrel...?",
  str_homestory_chat_12621009 = "It'll be ignited by my flames once in a while...",
  str_homestory_chat_12621010 = "Um... S-Sure?",
  str_homestory_chat_12622001 = "What did you just say?",
  str_homestory_chat_12622002 = "...What to say...? Let's see...",
  str_homestory_chat_12622003 = "H-Hey!",
  str_homestory_chat_12622004 = "...What's wrong?",
  str_homestory_chat_12622005 = "You drifted off while talking.",
  str_homestory_chat_12622006 = "...I didn't drift off... I was... just thinking...",
  str_homestory_chat_12622007 = "It must be hard talking to someone like me, right...?",
  str_homestory_chat_12622008 = "Yep!",
  str_homestory_chat_12622009 = "When you're stuck in your own world, look up at us once in a while...",
  str_homestory_chat_12622010 = "It's not that hard, so give it a try!",
  str_homestory_chat_12622011 = "Not really...",
  str_homestory_chat_12622012 = "Occasional silence allows one to relax...",
  str_homestory_chat_12622013 = "Enjoy this moment together then.",
  str_homestory_chat_12623001 = "Let's talk about your Ring of Fire.",
  str_homestory_chat_12623002 = "This thing? It's connected to my past...",
  str_homestory_chat_12623003 = "Recalling the past is a painful thing...",
  str_homestory_chat_12623004 = "T-Then let's not talk about it.",
  str_homestory_chat_12623005 = "But savoring pain is nothing unusual for me.",
  str_homestory_chat_12623006 = "It's no big deal to talk to you about it either.",
  str_homestory_chat_12624001 = "Anything interesting happened?",
  str_homestory_chat_12624002 = "...What do you want to talk about?",
  str_homestory_chat_12624003 = "I heard that Vice and the others accidentally a tablecloth on fire at a picnic.",
  str_homestory_chat_12624004 = "You used your Ring of Fire to help them put out the fire.",
  str_homestory_chat_12624005 = "Yes...",
  str_homestory_chat_12624006 = "Your Ring of Fire can suck away flames...",
  str_homestory_chat_12624007 = "That's so cool!",
  str_homestory_chat_12624008 = "It is? Oh... Thanks for the compliment.",
  str_homestory_chat_12625001 = "How's it going?",
  str_homestory_chat_12625002 = "Not very good...",
  str_homestory_chat_12625003 = "Is there anything I can do better?",
  str_homestory_chat_12625004 = "Not that... I'm a little confused...",
  str_homestory_chat_12625005 = "There're so many plants and trees in Eraveil...",
  str_homestory_chat_12625006 = "If I fall asleep carelessly... I might...",
  str_homestory_chat_12625007 = "Set grass or trees on fire...",
  str_homestory_chat_12625008 = "What?!",
  str_homestory_chat_12625009 = "Although I used my Ring of Fire to put out the fire every time...",
  str_homestory_chat_12625010 = "The grass was still scorched...",
  str_homestory_chat_12625011 = "Don't worry about it.",
  str_homestory_chat_12625012 = "The grass will grow back!",
  str_homestory_chat_12625013 = "As long as you are safe and buildings are not burnt down, it's not a problem.",
  str_homestory_chat_14699999 = "How are you?",
  str_homestory_chat_14601001 = "Hi, where are the others?",
  str_homestory_chat_14601002 = "They're busy with something.",
  str_homestory_chat_14601003 = "You have nothing to do?",
  str_homestory_chat_14601004 = "...Bye.",
  str_homestory_chat_14621001 = "Have you eaten?",
  str_homestory_chat_14621002 = "I don't eat vegetables ♪",
  str_homestory_chat_14621003 = "Since I hate the bitter taste ♪",
  str_homestory_chat_14621004 = "Veggies are good for you!",
  str_homestory_chat_14621005 = "I'm in good health, my dear Navigator.",
  str_homestory_chat_14621006 = "You, on the other hand, needs to eat more veggies, Unhealthy Navigator.",
  str_homestory_chat_14621007 = "Look at you! You could really use some veggies in your system.",
  str_homestory_chat_14622001 = "Have you read any books lately?",
  str_homestory_chat_14622002 = "I need to read storybooks ♪",
  str_homestory_chat_14622003 = "For those long days are difficult to endure ♪",
  str_homestory_chat_14622004 = "You guys can find something to do.",
  str_homestory_chat_14622005 = "My dear Navigator, I urge you to read more storybooks...",
  str_homestory_chat_14622006 = "to develop a virtue for helping others!",
  str_homestory_chat_14622007 = "I'll help you find it in a bit!",
  str_homestory_chat_14622008 = "If you take action in a bit ♪",
  str_homestory_chat_14622009 = "You'll forget after a while ♪",
  str_homestory_chat_14623001 = "What about here?",
  str_homestory_chat_14623002 = "Are you asking me if I like it here ♪",
  str_homestory_chat_14623003 = "Of course, I love it here ♪",
  str_homestory_chat_14623004 = "Thanks for your affirmation!",
  str_homestory_chat_14623005 = "I'm saying the words you love to hear ♪",
  str_homestory_chat_14623006 = "Do you understand ♪",
  str_homestory_chat_14623007 = "...",
  str_homestory_chat_14623008 = "But... there're times when it's true ♪",
  str_homestory_chat_14623009 = "When truth are spoken too ♪",
  str_homestory_chat_14624001 = "What are you looking for?",
  str_homestory_chat_14624002 = "My book's missing!",
  str_homestory_chat_14624003 = "Have you seen it, Navigator?",
  str_homestory_chat_14624004 = "Right over there.",
  str_homestory_chat_14624005 = "You should go further and help me ♪",
  str_homestory_chat_14624006 = "Find the book together ♪",
  str_homestory_chat_14624007 = "...Can I refuse?",
  str_homestory_chat_14624008 = "I don't see it.",
  str_homestory_chat_14624009 = "Navigator's eyesight isn't very good ♪",
  str_homestory_chat_14624010 = "Maybe it's 'cause you got up too early ♪",
  str_homestory_chat_14624011 = "Get up too early ♪",
  str_homestory_chat_14624012 = "Hair will fall out ♪",
  str_homestory_chat_14624013 = "You...!",
  str_homestory_chat_14625001 = "I... I got things to do!",
  str_homestory_chat_14625002 = "Bye!",
  str_homestory_chat_14625003 = "The Navigator fled in confusion.",
  str_homestory_chat_14625004 = "The Navigator felt guilty.",
  str_homestory_chat_14625005 = "I'm not!",
  str_homestory_chat_14625006 = "I-I just need to continue building Eraveil!",
  str_homestory_chat_14625007 = "Busy like a bee.",
  str_homestory_chat_14625008 = "But no goal to achieve.",
  str_homestory_chat_14625009 = "Don't get mad with kids, don't...",
  str_homestory_chat_14625010 = "The Navigator pretends to be mature.",
  str_homestory_chat_14625011 = "His not old...",
  str_homestory_chat_14625012 = "Yet he doesn't have much hair left.",
  str_homestory_chat_14625013 = "Why you...!",
  str_homestory_chat_12399999 = "A-Are you saying hello to me? T-Then... Hello!",
  str_homestory_chat_12301001 = "No need to be so nervous.",
  str_homestory_chat_12301002 = "O-Okay, I need to muster my courage...",
  str_homestory_chat_12301003 = "Hello, PlayerName!!",
  str_homestory_chat_12301004 = "Whoa! That's loud!",
  str_homestory_chat_12321001 = "You can play a musical instrument, right?",
  str_homestory_chat_12321002 = "I heard that you're a great clarinet player.",
  str_homestory_chat_12321003 = "Huh? W-What? You want me to play for the party?",
  str_homestory_chat_12321004 = "Everyone's looking forward to your performance.",
  str_homestory_chat_12321005 = "B-But...",
  str_homestory_chat_12321006 = "You don't want to?",
  str_homestory_chat_12321007 = "N-No, I'm just a little nervous.",
  str_homestory_chat_12321008 = "But if everyone's looking forward to it, I'll do my best...",
  str_homestory_chat_12321009 = "Believe in yourself and you'll be fine!",
  str_homestory_chat_12321010 = "Why don't you give it a shot?",
  str_homestory_chat_12321011 = "O-Okay, since it's an invitation from PlayerName...",
  str_homestory_chat_12321012 = "I'll give it my best shot.",
  str_homestory_chat_12321013 = "We'll be looking forward to your performance!",
  str_homestory_chat_12322001 = "I'm a little thirsty.",
  str_homestory_chat_12322002 = "PlayerName, d-do you want to try some coffee?",
  str_homestory_chat_12322003 = "It's okay if you don't want to... I can always pour it away...",
  str_homestory_chat_12322004 = "Of course, I'd like some!",
  str_homestory_chat_12322005 = "But... If it tastes bad...",
  str_homestory_chat_12322006 = "Why pour it away?",
  str_homestory_chat_12322007 = "I was practicing my coffee brewing skills earlier, so I've made loads...",
  str_homestory_chat_12322008 = "Um... I think it's best to pour them out since they may taste horrible...",
  str_homestory_chat_12322009 = "Hold on!",
  str_homestory_chat_12322010 = "I can't tell the difference between good and bad coffee, so don't worry about it.",
  str_homestory_chat_12322011 = "It's good as long as it keeps me awake.",
  str_homestory_chat_12322012 = "All right...",
  str_homestory_chat_12323001 = "What's up?",
  str_homestory_chat_12323002 = "It's so bright...",
  str_homestory_chat_12323003 = "The sun here's too bright...",
  str_homestory_chat_12323004 = "If only there's a shadier place...",
  str_homestory_chat_12323005 = "Will the shade make you feel better?",
  str_homestory_chat_12323006 = "I-I guess...?",
  str_homestory_chat_12324001 = "Who are you talking to?",
  str_homestory_chat_12324002 = "All right, I get it... Ugh, I'm sorry!",
  str_homestory_chat_12324003 = "It's the Antons... Do you want to chat with them?",
  str_homestory_chat_12324004 = "No need...",
  str_homestory_chat_12324005 = "They... can be rather scary sometimes...",
  str_homestory_chat_12324006 = "But the Antons're all good children, believe me!",
  str_homestory_chat_12324007 = "All right!",
  str_homestory_chat_12324008 = "T-Then I'll call them out for you...",
  str_homestory_chat_12325001 = "What are you busy doing?",
  str_homestory_chat_12325002 = "Hey, PlayerName...",
  str_homestory_chat_12325003 = "I've moved in for a while. Many people have helped me...",
  str_homestory_chat_12325004 = "I'd like to brew some coffee for everyone. But... I...",
  str_homestory_chat_12325005 = "Is there some difficulty you are facing?",
  str_homestory_chat_12325006 = "Yes... I... I don't know if they like coffee...",
  str_homestory_chat_12325007 = "So, I'm still thinking...",
  str_homestory_chat_12325008 = "Relax, Connolly!",
  str_homestory_chat_12325009 = "You've always been making great coffee. Besides...",
  str_homestory_chat_12325010 = "It's Connolly's heart that really matters!",
  str_homestory_chat_13699999 = "I'm so bored... Are you finally going to find something for me to do?",
  str_homestory_chat_13601001 = "Nope, I'm just here to say hi.",
  str_homestory_chat_13601002 = "Just to say hi?",
  str_homestory_chat_13601003 = "...I shouldn't have perked up to answer your boring question.",
  str_homestory_chat_13621001 = "How's it going lately?",
  str_homestory_chat_13621002 = "The food here's so bland that it's not even worth feeding it to the dogs.",
  str_homestory_chat_13621003 = "What do you want to eat?",
  str_homestory_chat_13621004 = "Anything.",
  str_homestory_chat_13621005 = "Who's the one despising the food just now?",
  str_homestory_chat_13621006 = "Anyway, just add more spices, like chili and salt.",
  str_homestory_chat_13621007 = "Just this?",
  str_homestory_chat_13621008 = "My dog and I have very low requirements.",
  str_homestory_chat_13622001 = "So, what are you doing?",
  str_homestory_chat_13622002 = "...Quiet. The shadows are resting.",
  str_homestory_chat_13622003 = "Shadows need rest too?",
  str_homestory_chat_13622004 = "...Yes.",
  str_homestory_chat_13622005 = "No other reason?",
  str_homestory_chat_13622006 = "...No.",
  str_homestory_chat_13622007 = "You just don't want to talk to me.",
  str_homestory_chat_13622008 = "You can interpret it that way for now.",
  str_homestory_chat_13622009 = "Come look for me when the shadows are well-rested.",
  str_homestory_chat_13623001 = "Hi, Hydrad.",
  str_homestory_chat_13623002 = "Quite a few of people here have dogs.",
  str_homestory_chat_13623003 = "Got a problem with that?",
  str_homestory_chat_13623004 = "Because dogs might bite?",
  str_homestory_chat_13623005 = "No.",
  str_homestory_chat_13623006 = "Because dogs might bark?",
  str_homestory_chat_13623007 = "All voluble dogs bark.",
  str_homestory_chat_13623008 = "So what is it you have a problem with?",
  str_homestory_chat_13623009 = "When have I said I have a problem with people keeping dogs?",
  str_homestory_chat_13623010 = "...",
  str_homestory_chat_14999999 = "Boss, what do you need? Do you need me to beat someone up for you?",
  str_homestory_chat_14901001 = "Just here to say hi.",
  str_homestory_chat_14901002 = "Oh... Is that so?",
  str_homestory_chat_14901003 = "Don't forgot to let me know when you're about to beat someone up!",
  str_homestory_chat_14921001 = "Need help?",
  str_homestory_chat_14921002 = "Do you see any specks of dust on my armor, Boss?",
  str_homestory_chat_14921003 = "No, it's very clean.",
  str_homestory_chat_14921004 = "There isn't any?",
  str_homestory_chat_14921005 = "To think I was looking forward to polishing my armor to pass the time.",
  str_homestory_chat_14921006 = "Are you bored?",
  str_homestory_chat_14921007 = "There's no one who can fight me here.",
  str_homestory_chat_14921008 = "Of course, I'm bored.",
  str_homestory_chat_14921009 = "There're some here, actually.",
  str_homestory_chat_14921010 = "Let me see... Thanks, Boss.",
  str_homestory_chat_14922001 = "You don't look well...",
  str_homestory_chat_14922002 = "Boss, I'm so hungry...",
  str_homestory_chat_14922003 = "I've been eating vegetables for several days in a row...",
  str_homestory_chat_14922004 = "Vegetables are good for you.",
  str_homestory_chat_14922005 = "Boss, for people, like me, who can't live without meat...",
  str_homestory_chat_14922006 = "don't you think those words are far too cruel?",
  str_homestory_chat_14922007 = "I don't want to eat vegetables either!",
  str_homestory_chat_14922008 = "But I'm nearly broke, so you'll just have to bear it!",
  str_homestory_chat_14922009 = "Boss, we're having such a hard time!",
  str_homestory_chat_14951001 = "Those are some huge shrimp...",
  str_homestory_chat_14951002 = "You saw them too, Kingpin of Cloud Gardens!?",
  str_homestory_chat_14951003 = "Don't call me that...",
  str_homestory_chat_14951004 = "Alrighty, then! Boss, I bet you didn't expect to see huge shrimp like that here!",
  str_homestory_chat_14951005 = "They're ginormous! If you sell them in Umbraton, you'll make a bundle!",
  str_homestory_chat_14951006 = "Really?",
  str_homestory_chat_14951007 = "That's right! These shrimp are the super-aggressive type, so they're a lot of fun to watch.",
  str_homestory_chat_14951008 = "When I saw them beating each other up, it was like watching a pair of huge turtles in mating season! They looked just like my two blades, they did!",
  str_homestory_chat_14951009 = "Gosh, it makes my fingers itch... I can't help wondering if I'd stand a chance against them...",
  str_homestory_chat_14951010 = "It's probably not a good idea, you're different species...",
  str_homestory_chat_14951011 = "I guess all I can do is look at them... There are a lot of people in Umbraton who can't get enough of them.",
  str_homestory_chat_14951012 = "Sometimes their battles are really exciting!",
  str_homestory_chat_14951013 = "They're still popular in Umbraton?",
  str_homestory_chat_14951014 = "(We could make a fortune...)",
  str_homestory_chat_14951015 = "You seem to be quite familiar with this kind of shrimp?",
  str_homestory_chat_14951016 = "Naturally! First of all, they're called \"Emperor Prawns.\"",
  str_homestory_chat_14951017 = "Secondly, I've found them lurking in several places so far.",
  str_homestory_chat_14951018 = "Several places!?",
  str_homestory_chat_14951019 = "And there are different kinds.",
  str_homestory_chat_14951020 = "Many different kinds?",
  str_homestory_chat_14951021 = "Actually, there are only two kinds. The most common one is blue.",
  str_homestory_chat_14951022 = "Right, that's the kind I saw.",
  str_homestory_chat_14951023 = "Of course it is. In addition to the blue one, there's also a brown variety. Now, that's what one might call a high-grade product.",
  str_homestory_chat_14951024 = "But it's a lot more difficult to find...",
  str_homestory_chat_14951025 = "Where can I find them?",
  str_homestory_chat_14951026 = "First, you need the blue brawler shrimp, or as it is officially known, the Cobalt Emperor Prawn.",
  str_homestory_chat_14951027 = "If you bring me one of those, you can exchange it for the bigger brown shrimp's fishing spots.",
  str_homestory_chat_14951028 = "Is that all you're gonna give me?",
  str_homestory_chat_14951029 = "Hey, you've learned how to haggle! Of course, the boss of Cloud Gardens deserves an extra special bonus.",
  str_homestory_chat_14951030 = "Rest assured, I'll make sure you get what you deserve!",
  str_homestory_chat_14951031 = "But where can I catch Cobalt Emperor Prawns?",
  str_homestory_chat_14951032 = "Huh? Didn't you just say you saw some?",
  str_homestory_chat_14951033 = "But isn't it better to have a few more fishing spots up my sleeve, just in case?",
  str_homestory_chat_14951034 = "Alright! I know a lot of fishing spots. You should be able to find some Cobalt Emperor Prawns.",
  str_homestory_chat_14951035 = "Of course, with your talent, it should be no problem at all! Then, you'll be able to exchange them for an \"Ochre Emperor Prawn\" fishing spot!",
  str_homestory_chat_14951036 = "So, that's the proper name for the brown shrimp...",
  str_homestory_chat_14951037 = "All clear now? With your skill, you can make a lot of money! And so can I...",
  str_homestory_chat_14951038 = "Ahem.",
  str_homestory_chat_14951039 = "So, Cloud Gardens Kingpin, do you have any more questions?",
  str_homestory_chat_14951040 = "I want to catch Ochre Emperor Prawns.",
  str_homestory_chat_14951041 = "So, did you bring Cobalt Emperor Prawns?",
  str_homestory_chat_14951042 = "Yep.",
  str_homestory_chat_14951043 = "Let me see the goods!",
  str_homestory_chat_14951044 = "Give Cobalt Emperor Prawn ({1}/1).",
  str_homestory_chat_14951045 = "Nice! I'll tell you where the fishing spot is now... I've marked it on your map!",
  str_homestory_chat_14951046 = "Let me think it over.",
  str_homestory_chat_14951047 = "No...",
  str_homestory_chat_14951048 = "Well, I guess that's too bad. Information doesn't come for free. I'll wait until you get one.",
  str_homestory_chat_14951049 = "Alright, then.",
  str_homestory_chat_14951050 = "I'm here about the shrimp.",
  str_homestory_chat_14951051 = "Well, in Umbraton, there's a charge for sharing this kind of information!",
  str_homestory_chat_14951052 = "Isn't this Cloud Gardens...?",
  str_homestory_chat_14951053 = "The deal is, you can exchange a Cobalt Emperor Prawn for info on a fishing spot where you can catch Oche Emperor Prawns.",
  str_homestory_chat_14951054 = "Of course, I'll give you some extra rewards for it. Got it?",
  str_homestory_chat_14951055 = "Got it.",
  str_homestory_chat_14951056 = "I want to fish for Cobalt Emperor Prawns.",
  str_homestory_chat_14951057 = "Are you sure?",
  str_homestory_chat_14951058 = "That's right.",
  str_homestory_chat_14951059 = "Okay! I've marked it down. Remember, you can exchange it for info on an Ochre Emperor Prawn fishing spot!",
  str_homestory_chat_14951060 = "Got it? Then I'll head off now!",
  str_homestory_chat_14951061 = "I still need to think about it...",
  str_homestory_chat_14952001 = "I want to know about those \"Emperor Prawns.\"",
  str_homestory_chat_14952002 = "Alright, alright... Who died and made you the lord of Cloud Gardens? Ask away!",
  str_homestory_chat_14952003 = "So, what do you want to know?",
  str_homestory_chat_14952004 = "I want to catch Ochre Emperor Prawns.",
  str_homestory_chat_14952005 = "So, did you bring Cobalt Emperor Prawns?",
  str_homestory_chat_14952006 = "Yep.",
  str_homestory_chat_14952007 = "Let me see the goods!",
  str_homestory_chat_14952008 = "Give Cobalt Emperor Prawn ({1}/1).",
  str_homestory_chat_14952009 = "Nice! I'll tell you where the fishing spot is now... I've marked it on your map!",
  str_homestory_chat_14952010 = "Let me think it over.",
  str_homestory_chat_14952011 = "No...",
  str_homestory_chat_14952012 = "Well, I guess that's too bad. Information doesn't come for free. I'll wait until you get one.",
  str_homestory_chat_14952013 = "Alright, then.",
  str_homestory_chat_14952014 = "I'm here about the shrimp.",
  str_homestory_chat_14952015 = "Again...? My mouth is as dry as a rusty blade already!",
  str_homestory_chat_14952016 = "I'm sorry. I just want to understand a little more.",
  str_homestory_chat_14952017 = "Well, you can exchange a Cobalt Emperor Prawn for info on a fishing spot where you can catch Oche Emperor Prawns. Remember?",
  str_homestory_chat_14952018 = "I remember.",
  str_homestory_chat_14952019 = "And I'll pay you! You won't be working for free!",
  str_homestory_chat_14952020 = "Right, I get it.",
  str_homestory_chat_14952021 = "I want to fish for Cobalt Emperor Prawns.",
  str_homestory_chat_14952022 = "Are you sure?",
  str_homestory_chat_14952023 = "I'm sure.",
  str_homestory_chat_14952024 = "I'll mark it for you. In addition, after fishing one up, you can exchange it for info on an Ochre Emperor Prawn fishing spot!",
  str_homestory_chat_14952025 = "I remember...",
  str_homestory_chat_14952026 = "I still need to think about it...",
  str_homestory_chat_14952027 = "I think I know pretty much all I need to know now.",
  str_homestory_chat_14952028 = "Then go get out of here!",
  str_homestory_chat_14953001 = "That shrimp...",
  str_homestory_chat_14953002 = "Again, huh...? I've marked all the places you can catch shrimp!",
  str_homestory_chat_14953003 = "Anything else?",
  str_homestory_chat_14953004 = "I'm here about the shrimp.",
  str_homestory_chat_14953005 = "*sigh* Alright, alright. After all, you are the boss here.",
  str_homestory_chat_14953006 = "First, catch the Cobalt Emperor Prawn, and then give it to me.",
  str_homestory_chat_14953007 = "Then I'll tell you where the fishing spot is and give you something extra.",
  str_homestory_chat_14953008 = "Think you'll be able to remember this time?",
  str_homestory_chat_14953009 = "Thank you!",
  str_homestory_chat_14953010 = "I'm afraid not.",
  str_homestory_chat_14953011 = "Great. Run along, then!",
  str_homestory_chat_11899999 = "What? Stop bothering me with trivial things. Can't you see I'm busy?",
  str_homestory_chat_11801001 = "I'm only just saying hi!",
  str_homestory_chat_11801002 = "Oh, got it.",
  str_homestory_chat_11801003 = "But I don't think there's going to be any \"major event\" here.",
  str_homestory_chat_11801004 = "Indeed.",
  str_homestory_chat_11821001 = "Hi. You're looking for me?",
  str_homestory_chat_11821002 = "PlayerName, you must listen to my new song.",
  str_homestory_chat_11821003 = "Can I say no?",
  str_homestory_chat_11821004 = "You actually dare to refuse? Of course not!",
  str_homestory_chat_11821005 = "Looks like there's a pressing need to improve your taste in music!",
  str_homestory_chat_11821006 = "Let's hear it.",
  str_homestory_chat_11821007 = "Ah, you certainly have such refined taste.",
  str_homestory_chat_11821008 = "But I need a band.",
  str_homestory_chat_11821009 = "I'll let you know once everything's ready.",
  str_homestory_chat_11822001 = "Looks like there's nothing to do.",
  str_homestory_chat_11822002 = "That's right! Gosh, I'm so boring!",
  str_homestory_chat_11822003 = "Me too...",
  str_homestory_chat_11822004 = "You have any bright ideas?",
  str_homestory_chat_11822005 = "It's moments like these you need a mental concert!",
  str_homestory_chat_11822006 = "My electric guitar will blast away all boredom!",
  str_homestory_chat_11822007 = "How's that, PlayerName? Not a bad idea, eh?",
  str_homestory_chat_11822008 = "Uh... I'll think about it.",
  str_homestory_chat_11823001 = "What are you talking about?",
  str_homestory_chat_11823002 = "Cantaloupe, mayonnaise...",
  str_homestory_chat_11823003 = "Is that an incantation?",
  str_homestory_chat_11823004 = "No, they're the most delicious things in this world!",
  str_homestory_chat_11823005 = "Drizzle mayonnaise all over the cold pieces of cantaloupe...",
  str_homestory_chat_11823006 = "All your worries will vanish with just a bite...",
  str_homestory_chat_11823007 = "Is it really that good?",
  str_homestory_chat_11823008 = "Shall I try some, too?",
  str_homestory_chat_11823009 = "Don't have this in front of me, or else I'm afraid I may steal them from you.",
  str_homestory_chat_11824001 = "How's it going?",
  str_homestory_chat_11824002 = "PlayerName, could you build a stage that's high enough to see the entire Eraveil?",
  str_homestory_chat_11824003 = "Oh? What is it for?",
  str_homestory_chat_11824004 = "The best metal concert, of course!",
  str_homestory_chat_11824005 = "My electric guitar will tell everyone what music is really about.",
  str_homestory_chat_11824006 = "I have nothing against this idea as long as you are fine sharing it with Barbara...",
  str_homestory_chat_10899999 = "Yo, you're here? Anything needs fixing?",
  str_homestory_chat_10801001 = "Now that you mention it... I do have something.",
  str_homestory_chat_10801002 = "But there's no hurry.",
  str_homestory_chat_10801003 = "Show me later.",
  str_homestory_chat_10821001 = "What do you feel like eating?",
  str_homestory_chat_10821002 = "Why are you asking me this all of a sudden?",
  str_homestory_chat_10821003 = "Just those things I normally have since I'm not picky.",
  str_homestory_chat_10821004 = "Want to have more egg dishes?",
  str_homestory_chat_10821005 = "Sure.",
  str_homestory_chat_10821006 = "But what special effects do these egg dishes have on me?",
  str_homestory_chat_10821007 = "Don't worry, it's all for your own good.",
  str_homestory_chat_10821008 = "Want to have a glass of milk every day?",
  str_homestory_chat_10821009 = "Sure.",
  str_homestory_chat_10821010 = "But why does that sound rather strange?",
  str_homestory_chat_10821011 = "...I got it.",
  str_homestory_chat_10821012 = "You're laughing at my height indirectly!",
  str_homestory_chat_10821013 = "No! Absolutely not!",
  str_homestory_chat_10822001 = "What's on your mind?",
  str_homestory_chat_10822002 = "PlayerName, I've just thought of a great idea!",
  str_homestory_chat_10822003 = "We can install some strong lights on these buildings.",
  str_homestory_chat_10822004 = "Why?",
  str_homestory_chat_10822005 = "...All right, it's because I've got nothing to do right now.",
  str_homestory_chat_10822006 = "PlayerName, do you have any new construction needs?",
  str_homestory_chat_10822007 = "Let me think about it.",
  str_homestory_chat_11799999 = "Hello, PlayerName!",
  str_homestory_chat_11701001 = "Hi, Rabbie!",
  str_homestory_chat_11701002 = "Any plans today?",
  str_homestory_chat_11701003 = "Not at the moment.",
  str_homestory_chat_11701004 = "Want to drill holes with me?",
  str_homestory_chat_11701005 = "M-Maybe later?",
  str_homestory_chat_11721001 = "You look like you've something on your mind?",
  str_homestory_chat_11721002 = "PlayerName, want to hear my evacuation plan?",
  str_homestory_chat_11721003 = "Evacuation?",
  str_homestory_chat_11721004 = "No established home should be without an evacuation plan!",
  str_homestory_chat_11721005 = "It's for everyone's safety!",
  str_homestory_chat_11721006 = "Okay, I'll take a look.",
  str_homestory_chat_11721007 = "I'm already done with a portion of it and drilled three holes!",
  str_homestory_chat_11721008 = "No way?!",
  str_homestory_chat_11722001 = "What are you looking at?",
  str_homestory_chat_11722002 = "PlayerName, I got a new drill bit!",
  str_homestory_chat_11722003 = "I'd really love to give it a try now!",
  str_homestory_chat_11722004 = "D-Don't...",
  str_homestory_chat_11722005 = "The hole you drilled the last time hasn't even been filled in yet!",
  str_homestory_chat_11722006 = "Are you unsatisfied with my underground evacuation plan?",
  str_homestory_chat_11722007 = "N-Not really. Anyhow, just let me know before you drill holes.",
  str_homestory_chat_11722008 = "All right, I got it! I'll keep that in mind!",
  str_homestory_chat_11751001 = "Where's that fish?",
  str_homestory_chat_11751002 = "Ah! Retreat!",
  str_homestory_chat_11751003 = "Retreat? Hey...",
  str_homestory_chat_11751004 = "A-Are you here to catch me?",
  str_homestory_chat_11751005 = "Catch you? What did you do?",
  str_homestory_chat_11751006 = "Well.. for the sake of facilitating emergency retreats, I just wanted to dig a tunnel beneath Cloud Gardens.",
  str_homestory_chat_11751007 = "When the time comes, if I don't think we'll be able to hold out, I'll just make like a tree and run— Ah, retreat, yeah!",
  str_homestory_chat_11751008 = "Oh, that's pretty thoughtful of you.",
  str_homestory_chat_11751009 = "And I saw that fish while digging the tunnel... Oh yeah! Is that why you came over?",
  str_homestory_chat_11751010 = "Huh? Oh, right... Anyway, that tunnel didn't seem to be too useful, so the Chubbs are filling it up again.",
  str_homestory_chat_11751011 = "Filling it up?!",
  str_homestory_chat_11751012 = "How are we gonna retreat?! What if something terrible actually happens?!",
  str_homestory_chat_11751013 = "Nothing's going to happen. Also, you dug that tunnel without even asking me if it was okay.",
  str_homestory_chat_11751014 = "I guess...",
  str_homestory_chat_11751015 = "But anyway, I came to ask you about that fish. Where did you see it? Near the tunnel?",
  str_homestory_chat_11751016 = "Actually, it was a bit further away than that. I don't really have the energy to explain it right now. Digging tunnels is hard work...",
  str_homestory_chat_11751017 = "You're not looking for compensation, are you?",
  str_homestory_chat_11751018 = "Of course I am! Give me some seeds of Giant Leaf Quinlan Tree and I'll consider us even!",
  str_homestory_chat_11751019 = "Otherwise... Hey, I think I may have just figured out a new retreat route!",
  str_homestory_chat_11751020 = "Okay, okay... How is any of this even have anything to do with me...?",
  str_homestory_chat_14099999 = "Want some pop rocks?",
  str_homestory_chat_14001001 = "Pop rocks?",
  str_homestory_chat_14001002 = "Is it really candy and not bombs?",
  str_homestory_chat_14001003 = "Want me to show you?",
  str_homestory_chat_14001004 = "But I may just finish it all in one bite.",
  str_homestory_chat_14021001 = "Hi, what's up?",
  str_homestory_chat_14021002 = "PlayerName, I suggest you promote waste classification.",
  str_homestory_chat_14021003 = "Why?",
  str_homestory_chat_14021004 = "It's so troublesome to have all the garbage mixed up together.",
  str_homestory_chat_14021005 = "That's actually a good idea.",
  str_homestory_chat_14021006 = "Then what are you waiting for?",
  str_homestory_chat_14021007 = "Well, I can help you if you want.",
  str_homestory_chat_14021008 = "So eager, huh?",
  str_homestory_chat_14021009 = "I wanted to grab something useful from the garbage but my hand was smeared with chili sauce.",
  str_homestory_chat_14021010 = "Who wouldn't be upset?",
  str_homestory_chat_14022001 = "You were looking for me?",
  str_homestory_chat_14022002 = "When's the party, PlayerName?",
  str_homestory_chat_14022003 = "In a few days...",
  str_homestory_chat_14022004 = "Do you need fireworks?",
  str_homestory_chat_14022005 = "Come on, say you \"need it\"!",
  str_homestory_chat_14022006 = "Ye... Wait, why would I need it?",
  str_homestory_chat_14022007 = "Because I can't wait to try out my new fireworks, of course!",
  str_homestory_chat_14022008 = "Not for the time being.",
  str_homestory_chat_14022009 = "No, you have to!",
  str_homestory_chat_14022010 = "Otherwise, where am I supposed to go test the new fireworks?",
  str_homestory_chat_14022011 = "Hey, you can set them off in any open space!",
  str_homestory_chat_14022012 = "Now, you're talking!",
  str_homestory_chat_14022013 = "...Wait, can I take that back?",
  str_homestory_chat_14023001 = "What are you doing?",
  str_homestory_chat_14023002 = "PlayerName, want to see my new bomb?",
  str_homestory_chat_14023003 = "Nope.",
  str_homestory_chat_14023004 = "You blew up a tree the time before...",
  str_homestory_chat_14023005 = "and half a hillside the last time...",
  str_homestory_chat_14023006 = "What do you want to destroy this time?",
  str_homestory_chat_14023007 = "... I definitely had no destructive intent!",
  str_homestory_chat_14023008 = "You didn't have the intent because you did it on purpose!",
  str_homestory_chat_15199999 = "Are you up for board games since you came to say hello to us?",
  str_homestory_chat_15121001 = "No thanks. How's it going?",
  str_homestory_chat_15121002 = "PlayerName, if you want everyone to live comfortably here, you should have something to eat at the very least, right?",
  str_homestory_chat_15121003 = "Isn't there enough to eat?",
  str_homestory_chat_15121004 = "It's not that there isn't enough, but there's simply nothing edible...",
  str_homestory_chat_15121005 = "What do you want to eat?",
  str_homestory_chat_15121006 = "Let's start with ten cans of 5-year-old engine oil...",
  str_homestory_chat_15121007 = "and five jars of gun sludge.",
  str_homestory_chat_15122001 = "You seem pretty free.",
  str_homestory_chat_15122002 = "Yes, PlayerName. I've been here for so long that my guns are rusty.",
  str_homestory_chat_15122003 = "You can always get someone to fix it.",
  str_homestory_chat_15122004 = "Yes, I can... But it's merely a temporary solution.",
  str_homestory_chat_15122005 = "After all, it only became rusty from boredom.",
  str_homestory_chat_15122006 = "I'd say it'll be best to build a shooting range.",
  str_homestory_chat_15122007 = "Any good solutions?",
  str_homestory_chat_15122008 = "It's to build a shooting range. Take some time to think it over, PlayerName.",
  str_homestory_chat_15122009 = "Yeah, I will.",
  str_homestory_chat_15123001 = "Board games?",
  str_homestory_chat_15123002 = "We can include bets too!",
  str_homestory_chat_15123003 = "They aren't something frightening, are they?",
  str_homestory_chat_15123004 = "Nope, you can choose whatever you wish to bet this time.",
  str_homestory_chat_15123005 = "Anything is fine, like your hands and legs.",
  str_homestory_chat_15124001 = "How do you find this place?",
  str_homestory_chat_15124002 = "Not bad at all, but too quiet.",
  str_homestory_chat_15124003 = "Quiet?",
  str_homestory_chat_15124004 = "I can only hear the sound of nature, but no gunfire or cars.",
  str_homestory_chat_15124005 = "I'll need to get used to this.",
  str_homestory_chat_15124006 = "I think I'll have to return to the desert from time to time, to get my touch back.",
  str_homestory_chat_15124007 = "But it's too far to go back and forth.",
  str_homestory_chat_15124008 = "If I can keep a few guns here, that'd be great.",
  str_homestory_chat_15124009 = "No!!",
  str_homestory_chat_15399999 = "What can I get you, my dearest Boss?",
  str_homestory_chat_15321001 = "Oh...",
  str_homestory_chat_15321002 = "I've a brand new Bunnybear Plush, a Sandworm horn in perfect condition...",
  str_homestory_chat_15321003 = "Wait! I'm just here to say hi.",
  str_homestory_chat_15321004 = "No worries, a simple greeting can always lead to a satisfying deal too!",
  str_homestory_chat_15322001 = "What are you doing?",
  str_homestory_chat_15322002 = "Boss, do you hear a barking sound?",
  str_homestory_chat_15322003 = "No...",
  str_homestory_chat_15322004 = "Am I hearing things?",
  str_homestory_chat_15322005 = "Geez... Since there aren't any puppies, where should I seek comfort?",
  str_homestory_chat_15322006 = "Unless, Boss, you buy more items from me.",
  str_homestory_chat_15322007 = "Well...",
  str_homestory_chat_15322008 = "I believe so...",
  str_homestory_chat_15322009 = "Yes, I knew I heard it right!",
  str_homestory_chat_15322010 = "I'm going to look for the puppy first, Boss. Be sure to come to me if you want to buy anything!",
  str_homestory_chat_15322011 = "Okay, okay. You just go ahead.",
  str_homestory_chat_15323001 = "Find something new?",
  str_homestory_chat_15323002 = "Yes, Boss! There's a huge business opportunity hidden at home!",
  str_homestory_chat_15323003 = "Come, tell me. What's this business opportunity?",
  str_homestory_chat_15323004 = "Good grief, you've not noticed it at all!?",
  str_homestory_chat_15323005 = "If you ever find a business opportunity, we can have a chat about it...",
  str_homestory_chat_15323006 = "Wouldn't I be left with the short end of the stick if I were to tell you now? This also goes against my principles.",
  str_homestory_chat_15323007 = "Unless, you'd like to pay a consultation fee...",
  str_homestory_chat_15323008 = "I'll then be very forthcoming with the business opportunity!",
  str_homestory_chat_15323009 = "...It's all right.",
  str_homestory_chat_11399999 = "Hello there, PlayerName! Want to clean the place up with me?",
  str_homestory_chat_11321001 = "Wow, you sure work hard!",
  str_homestory_chat_11321002 = "Of course, we've got to be diligent in keeping the place clean!",
  str_homestory_chat_11322001 = "Hey, it's time to hold a party!",
  str_homestory_chat_11322002 = "PlayerName, have you decided on a theme for your upcoming party?",
  str_homestory_chat_11322003 = "Yep!",
  str_homestory_chat_11322004 = "Want me to add another idea to the mix?",
  str_homestory_chat_11322005 = "Like... \"A home in the snow\"?",
  str_homestory_chat_11322006 = "Not yet...",
  str_homestory_chat_11322007 = "I've thought of a theme for you!",
  str_homestory_chat_11322008 = "\"A home in the snow\"!",
  str_homestory_chat_11322009 = "I can provide the fluttering ice crystals, and tap-dancing snowmen!",
  str_homestory_chat_11322010 = "That sounds good. We can give it a try.",
  str_homestory_chat_11323001 = "What are you looking at?",
  str_homestory_chat_11323002 = "Over there... It looks like something's gleaming!",
  str_homestory_chat_11323003 = "It's just a dewdrop on a blade of grass...",
  str_homestory_chat_11323004 = "Even if it's just a dewdrop, it's very cute!",
  str_homestory_chat_11323005 = "I'm going to freeze it and keep it as a keepsake!",
  str_homestory_chat_11323006 = "They're just glass fragments...",
  str_homestory_chat_11323007 = "Transparent and glistening glass fragments!",
  str_homestory_chat_11323008 = "Bye, PlayerName! I'm going to go collect them all!",
  str_homestory_chat_11324001 = "What are you making?",
  str_homestory_chat_11324002 = "PlayerName! I made lots of snowmen ornaments!",
  str_homestory_chat_11324003 = "I can give them to you if you like!",
  str_homestory_chat_11324004 = "Won't they melt?",
  str_homestory_chat_11324005 = "Of course not! I can even make them dance if that's what you want!",
  str_homestory_chat_11324006 = "I'll bring them over later!",
  str_homestory_chat_11325001 = "What a great day.",
  str_homestory_chat_11325002 = "Yeah, it's so different from the snowy Northland!",
  str_homestory_chat_11325003 = "But, sadly, we can't make a snowman here...",
  str_homestory_chat_11325004 = "Wanna go fishing with me?",
  str_homestory_chat_11325005 = "Go fishing?",
  str_homestory_chat_11325006 = "I wonder if there's any fish here that sparks like the snowflake!",
  str_homestory_chat_11325007 = "Let's go find it out!",
  str_homestory_chat_11325008 = "Wanna play on the swing?",
  str_homestory_chat_11325009 = "You mean the chair that you can fly and dangle your legs in?",
  str_homestory_chat_11325010 = "It sounds like I dance in the air like a snowflake!",
  str_homestory_chat_11325011 = "I'd love to be light and sparkling like the snow!",
  str_homestory_chat_11099999 = "Hi, PlayerName. You look nice today.",
  str_homestory_chat_11021001 = "Are you looking for something?",
  str_homestory_chat_11021002 = "Candies. Would you like one?",
  str_homestory_chat_11021003 = "They aren't wooden candies created with magic. But instead, they're actual candies.",
  str_homestory_chat_11021004 = "Sure, I'll have one.",
  str_homestory_chat_11021005 = "Um... Hold on, let me search for it. My pockets are so big that I'm always having trouble finding things.",
  str_homestory_chat_11022001 = "You have a question for me?",
  str_homestory_chat_11022002 = "PlayerName, would you rather be an elf or a fairy?",
  str_homestory_chat_11022003 = "Where's this coming from?",
  str_homestory_chat_11022004 = "That's because I'm working on a new story!",
  str_homestory_chat_11022005 = "Would you like to be featured in my story?",
  str_homestory_chat_11022006 = "Of course.",
  str_homestory_chat_11022007 = "Hmm, let's see... I'd rather be a fairy.",
  str_homestory_chat_11022008 = "No problem! A mystical fairy who can see the trails of light!",
  str_homestory_chat_11022009 = "Is there any difference between elves and fairies?",
  str_homestory_chat_11022010 = "Of course, there is!",
  str_homestory_chat_11022011 = "I can find you some books on them. You'll understand once you've read them!",
  str_homestory_chat_11023001 = "What are you look for?",
  str_homestory_chat_11023002 = "PlayerName, have you had any candy recently?",
  str_homestory_chat_11023003 = "Yes.",
  str_homestory_chat_11023004 = "Have you come across any pretty candy wrappers?",
  str_homestory_chat_11023005 = "I don't think so...",
  str_homestory_chat_11023006 = "Oh, is that so...?",
  str_homestory_chat_11023007 = "What's wrong?",
  str_homestory_chat_11023008 = "I was hoping you've found some pretty candy wrappers...",
  str_homestory_chat_11023009 = "Anything will do, like glistening glass wrappers, and soft floral-print wrappers!",
  str_homestory_chat_11023010 = "I don't have any impression of this...",
  str_homestory_chat_11023011 = "But I'll keep an eye out for you.",
  str_homestory_chat_11024001 = "Did you sleep well last night?",
  str_homestory_chat_11024002 = "PlayerName, I had a beautiful dream last night.",
  str_homestory_chat_11024003 = "What was it about?",
  str_homestory_chat_11024004 = "I dreamt that I was sitting inside a candy house with everyone...",
  str_homestory_chat_11024005 = "Time for handicrafts!",
  str_homestory_chat_11024006 = "Why do I feel like your eyes are teeming with expectation?",
  str_homestory_chat_11024007 = "PlayerName, shall we host a handicrafts competition?",
  str_homestory_chat_11025001 = "What are you doing?",
  str_homestory_chat_11025002 = "I'm collecting Dandelions!",
  str_homestory_chat_11025003 = "The dandelion is so light that a gentle breeze can make it dance in the sky...",
  str_homestory_chat_11025004 = "This would make Northland so much more beautiful!",
  str_homestory_chat_11025005 = "Would it be possible to grow in the north?",
  str_homestory_chat_11025006 = "I'm not sure but I'd like to try!",
  str_homestory_chat_11025007 = "I hope these dandelions will become sprites of the north just like the snowflake.",
  str_homestory_chat_11025008 = "Good luck!",
  str_homestory_chat_11025009 = "I will try harder!",
  str_homestory_chat_11025010 = "Though it's not easy.",
  str_homestory_chat_11025011 = "Dandelions would fly away even in the gentlest wind.",
  str_homestory_chat_11025012 = "I must hurry up!",
  str_homestory_chat_11999999 = "PlayerName, a new day is yet another day of seeking the truth.",
  str_homestory_chat_11901001 = "Ah... Yes.",
  str_homestory_chat_11901002 = "Are you willing to accept my invitation this time?",
  str_homestory_chat_11901003 = "U-Um... Not now... Let's talk about it next time.",
  str_homestory_chat_11921001 = "How's your day?",
  str_homestory_chat_11921002 = "It's great to see you alive and kicking today.",
  str_homestory_chat_11921003 = "Would you like to know your fortune?",
  str_homestory_chat_11921004 = "Sure!",
  str_homestory_chat_11921005 = "That's very bold of you.",
  str_homestory_chat_11921006 = "It thrills me to see you brimming with hope for the future.",
  str_homestory_chat_11921007 = "No thanks...",
  str_homestory_chat_11921008 = "You have no reason to fear the future when the truth is with you...",
  str_homestory_chat_11921009 = "Why not offer your soul and become a follower of truth?",
  str_homestory_chat_11922001 = "Hi! What are you up to?",
  str_homestory_chat_11922002 = "PlayerName, fancy a drink with me?",
  str_homestory_chat_11922003 = "When the darkness silences everything on this endless night...",
  str_homestory_chat_11922004 = "Wait a minute...",
  str_homestory_chat_11922005 = "Wait, what will we be drinking?",
  str_homestory_chat_11922006 = "If I'm to choose our drink...",
  str_homestory_chat_11922007 = "I'll suggest a warm cup...",
  str_homestory_chat_11922008 = "N-No... I'll pass...",
  str_homestory_chat_11922009 = "I'd rather not...",
  str_homestory_chat_11922010 = "I see fear in your eyes.",
  str_homestory_chat_11922011 = "Why be afraid? You can pick your own drink this time.",
  str_homestory_chat_11923001 = "Are you reading?",
  str_homestory_chat_11923002 = "I really enjoy reading here.",
  str_homestory_chat_11923003 = "Here, you can always find a quiet place isolated from all clamor...",
  str_homestory_chat_11923004 = "This allows me to explore the most profound knowledge in ancient books.",
  str_homestory_chat_11923005 = "Is that for sure?",
  str_homestory_chat_11923006 = "Of course!",
  str_homestory_chat_11923007 = "As the guardian of this place, you deserve all my compliments.",
  str_homestory_chat_11924001 = "You've something to tell me?",
  str_homestory_chat_11924002 = "There's something I'd like to discuss with you.",
  str_homestory_chat_11924003 = "Go ahead.",
  str_homestory_chat_11924004 = "If there's ever a collective distribution of food in the future...",
  str_homestory_chat_11924005 = "Please exclude me.",
  str_homestory_chat_11924006 = "But why?",
  str_homestory_chat_11924007 = "As you know, I'll never accept this sort of invitation.",
  str_homestory_chat_11924008 = "I'd very much prefer to pick my own food.",
  str_homestory_chat_10999999 = "My friend, you must hear the truth today.",
  str_homestory_chat_10901001 = "Um... I guess I will.",
  str_homestory_chat_10901002 = "My friend, I can sense your sincerity...",
  str_homestory_chat_10901003 = "I believe you must be really eager to discuss the words of truth with me?",
  str_homestory_chat_10901004 = "N-Not really...",
  str_homestory_chat_10921001 = "Is everything alright?",
  str_homestory_chat_10921002 = "My friend, may I temporarily entrust the White Suitcase in your care?",
  str_homestory_chat_10921003 = "Please don't...",
  str_homestory_chat_10921004 = "Your rejection is particularly cold in this weather.",
  str_homestory_chat_10921005 = "Don't worry. It won't leave you with any bad memory.",
  str_homestory_chat_10921006 = "Why does that sound like a hoax?",
  str_homestory_chat_10921007 = "I'll need to think about it.",
  str_homestory_chat_10921008 = "Do you still remember the White Suitcase Care Guide?",
  str_homestory_chat_10921009 = "It prefers moderate temperatures, daily cleaning and to be fed at noon...",
  str_homestory_chat_10921010 = "...Hold on, is it too late to say no?",
  str_homestory_chat_10922001 = "What are you looking for?",
  str_homestory_chat_10922002 = "My friend, is there any ancient ruins around here?",
  str_homestory_chat_10922003 = "No.",
  str_homestory_chat_10922004 = "You always look like you're about to do something unusual and absurd.",
  str_homestory_chat_10922005 = "That's nonsense.",
  str_homestory_chat_10922006 = "As a pursuer of truth, everything I do, I do it for a reason.",
  str_homestory_chat_10922007 = "I'm more than happy to explain if you're interested to learn more.",
  str_homestory_chat_10922008 = "T-That won't be necessary.",
  str_homestory_chat_10922009 = "Let me think...",
  str_homestory_chat_10922010 = "You always look like you're struggling to recall the right memories.",
  str_homestory_chat_10922011 = "Please do let me know when it eventually comes to your mind.",
  str_homestory_chat_10923001 = "You look like you're contemplating.",
  str_homestory_chat_10923002 = "My friend, don't you think the air here is missing something?",
  str_homestory_chat_10923003 = "What are you talking about?",
  str_homestory_chat_10923004 = "The preaching of truth.",
  str_homestory_chat_10923005 = "Don't you think we need to host an awareness campaign...",
  str_homestory_chat_10923006 = "to free everyone from their meaningless life...",
  str_homestory_chat_10923007 = "and help them advance towards the land of truth?",
  str_homestory_chat_10923008 = "...I think we're doing just fine.",
  str_homestory_chat_10599999 = "H-Hello...",
  str_homestory_chat_10521001 = "Is this Mia today?",
  str_homestory_chat_10521002 = "Yes, she's... still sound asleep.",
  str_homestory_chat_10522001 = "The weather is lovely today.",
  str_homestory_chat_10522002 = "Y-Yes, it is...",
  str_homestory_chat_10522003 = "Everyday spent at home makes one feel so comfortable...",
  str_homestory_chat_10522004 = "Um... I'm sorry, I don't mean to confuse you.",
  str_homestory_chat_10522005 = "Not at all.",
  str_homestory_chat_10522006 = "You know, I've not seen Baba Yaga for a while.",
  str_homestory_chat_10522007 = "That's because... the tranquility at home makes her fall into a deep slumber...",
  str_homestory_chat_10522008 = "I-If you really want to see her, I could...",
  str_homestory_chat_10522009 = "Wait, that's not what I meant!",
  str_homestory_chat_10523001 = "What would you like to drink?",
  str_homestory_chat_10523002 = "Do you have any Knight's Black Tea?",
  str_homestory_chat_10523003 = "If you do, serve it immediately. Don't make me ask every time.",
  str_homestory_chat_10523004 = "Baba Yaga?",
  str_homestory_chat_10523005 = "Don't change the subject.",
  str_homestory_chat_10523006 = "I remember it's Mia who likes Knight's Black Tea.",
  str_homestory_chat_10523007 = "Say no more, or you'll have a steel claw to deal with.",
  str_homestory_chat_10523008 = "Please give me a minute...",
  str_homestory_chat_10523009 = "I probably need some time to search for it.",
  str_homestory_chat_10523010 = "You better pray it won't take too long.",
  str_homestory_chat_10524001 = "I heard that there's a spider lately...",
  str_homestory_chat_10524002 = "A Black Spider at night? You saw it, too? Who do you think that was?",
  str_homestory_chat_10524003 = "Was that you?",
  str_homestory_chat_10524004 = "Sounds like you're very much into mystery stories.",
  str_homestory_chat_10524005 = "You'll see more after nightfall.",
  str_homestory_chat_10524006 = "I've no idea...",
  str_homestory_chat_10524007 = "Stay awake and you may just find the truth behind the mystery.",
  str_homestory_chat_10524008 = "Don't you want to see it for yourself?",
  str_homestory_chat_10524009 = "D-Definitely not...",
  str_homestory_chat_10499999 = "Hey! Are you here with food?",
  str_homestory_chat_10401001 = "...No.",
  str_homestory_chat_10401002 = "Just here to say hi.",
  str_homestory_chat_10401003 = "Tsk... Please move out of the way. Food's of the top priority right now.",
  str_homestory_chat_10421001 = "You're sweating.",
  str_homestory_chat_10421002 = "Yes... It's so hot lately.",
  str_homestory_chat_10421003 = "Is there any cold beer, frozen fish or ice tin?",
  str_homestory_chat_10421004 = "I need take a look...",
  str_homestory_chat_10421005 = "Hurry up and start looking now!",
  str_homestory_chat_10421006 = "Take your own sweet time if you want to watch me melt into a puddle!",
  str_homestory_chat_10421007 = "No...",
  str_homestory_chat_10421008 = "No way, life can't just go on like this!",
  str_homestory_chat_10422001 = "Did you go swimming recently?",
  str_homestory_chat_10422002 = "Yes, I had a great time swimming in the river...",
  str_homestory_chat_10422003 = "R-River?",
  str_homestory_chat_10422004 = "Yes, rivers are meant for people to swim in. You have a problem with that?",
  str_homestory_chat_10422005 = "No... I just realized that you should be a great swimmer.",
  str_homestory_chat_10422006 = "What's more, the shallow river is perfectly safe for you.",
  str_homestory_chat_10423001 = "Ice cubes?",
  str_homestory_chat_10423002 = "Yes, do you have ice cubes?",
  str_homestory_chat_10423003 = "Ones that are as big as a house.",
  str_homestory_chat_10423004 = "No!",
  str_homestory_chat_10423005 = "How am I supposed to deal with summer then?",
  str_homestory_chat_10423006 = "How did you guys deal with it before?",
  str_homestory_chat_10423007 = "Did jobs everywhere, then bought ice cubes with the money.",
  str_homestory_chat_10423008 = "So, you should be working and making money.",
  str_homestory_chat_10423009 = "Yes!",
  str_homestory_chat_10423010 = "And they're bigger than houses! They're as large as the mountains!",
  str_homestory_chat_10423011 = "Really?!",
  str_homestory_chat_10423012 = "No, not really.",
  str_homestory_chat_15099999 = "Hello, bro!",
  str_homestory_chat_15001001 = "Hey there...",
  str_homestory_chat_15001002 = "Please don't mind my teeth. I'm not showing them intentionally.",
  str_homestory_chat_15001003 = "I know, I know... Just hide them, please...",
  str_homestory_chat_15021001 = "What are you looking for?",
  str_homestory_chat_15021002 = "Do we have cats here, bro?",
  str_homestory_chat_15021003 = "I think so...",
  str_homestory_chat_15021004 = "Please show me when you have time.",
  str_homestory_chat_15021005 = "Don't worry. I don't eat cats.",
  str_homestory_chat_15021006 = "I'm mostly vegetarian, remember?",
  str_homestory_chat_15021007 = "Yes, I remember...",
  str_homestory_chat_15021008 = "I don't think so...",
  str_homestory_chat_15021009 = "When will we ever have cats here?",
  str_homestory_chat_15021010 = "Once cats come, there won't be any boredom...",
  str_homestory_chat_15022001 = "Looking for me?",
  str_homestory_chat_15022002 = "You want some shark tooth powder, bro?",
  str_homestory_chat_15022003 = "What's that for?",
  str_homestory_chat_15022004 = "You have it with your supper.",
  str_homestory_chat_15022005 = "You'll know once you've tried it.",
  str_homestory_chat_15022006 = "I don't have it with me right now. I'll bring some over next time.",
  str_homestory_chat_15023001 = "Your teeth...",
  str_homestory_chat_15023002 = "Hm? Oh, they're getting a bit loose again.",
  str_homestory_chat_15023003 = "Looks like I'm going to need a new batch. Do you take these?",
  str_homestory_chat_15023004 = "What use would they be?",
  str_homestory_chat_15023005 = "No.",
  str_homestory_chat_15023006 = "Come on! They're very useful.",
  str_homestory_chat_15023007 = "You could make a sculpture with them, or you can grind them down and use them as a cooking spice.",
  str_homestory_chat_15023008 = "You might even be able to make some money by selling them in Umbraton.",
  str_homestory_chat_15023009 = "Then why don't you keep them for yourself...",
  str_homestory_chat_15023010 = "Because this is the protection fee I'm paying you.",
  str_homestory_chat_15031001 = "Strange fish...",
  str_homestory_chat_15031002 = "Hmm? You saw something, boss?",
  str_homestory_chat_15031003 = "A few days ago, I saw a bunch of fish in the stream that I'd never seen before.",
  str_homestory_chat_15031004 = "Their eyes were huge, and their bodies were kind of round.",
  str_homestory_chat_15031005 = "Oh, you must be talking about the Bighead Carp! Actually, I was the one who put 'em there...",
  str_homestory_chat_15031006 = "Huh?",
  str_homestory_chat_15031007 = "Well, I noticed that Bighead Carp do really well around here.",
  str_homestory_chat_15031008 = "The water, the weather, the speed of the current are all perfect for them! But the most important thing is that they're very rare!",
  str_homestory_chat_15031009 = "And here I thought you wanted to eat them...",
  str_homestory_chat_15031010 = "C'mon boss! Sharp-toothed as I am, I never eat meat!",
  str_homestory_chat_15031011 = "How many more times are you guys gonna judge me wrong by my looks?",
  str_homestory_chat_15031012 = "Do I have to deal with this for the rest of my life?!",
  str_homestory_chat_15031013 = "Here you go again...",
  str_homestory_chat_15031014 = "Don't be so thin-skinned! You were in a gang before, weren't you?",
  str_homestory_chat_15031015 = "Yeah, but you keep doing it over and over again...",
  str_homestory_chat_15031016 = "Uh... Korgon, why did you bring these Bighead Carp here in the first place?",
  str_homestory_chat_15031017 = "To let them breed, of course! And once there are plenty of them, I'll bring them all back to Sharkfang Island.",
  str_homestory_chat_15031018 = "Reconstruction has been wearing me out lately. It feels like the work just never ends!",
  str_homestory_chat_15031019 = "But just seeing these cute little guys makes all my fatigue go away! That's why I want to bring 'em over to the island.",
  str_homestory_chat_15031020 = "Seeing them swimming around in all shapes and sizes—",
  str_homestory_chat_15031021 = "Wait! They come in different sizes?",
  str_homestory_chat_15031022 = "Yeah, see? It looks that way.",
  str_homestory_chat_15031023 = "But I only see one size...",
  str_homestory_chat_15031024 = "Anyways, Bighead Carp are extremely skittish. It took me forever just to find a few spots where they live.",
  str_homestory_chat_15031025 = "They ain't easy to catch either...",
  str_homestory_chat_15031026 = "If you need someone to fish them up, I can handle that.",
  str_homestory_chat_15031027 = "R-Really, boss?! That'd be a huge load off my shoulders. Thank you!",
  str_homestory_chat_15031028 = "But like I said, Bighead Carp are extremely rare. I'm a little reluctant to see any of them go, to be honest...",
  str_homestory_chat_15031029 = "Alright, alright... What's the catch?",
  str_homestory_chat_15031030 = "Quick as a fox, just like always! So the deal is, you bring me one of these smaller Bighead Carp, and I'll share some valuable info with you.",
  str_homestory_chat_15031031 = "I'll tell you exactly where you can fish up an even bigger Bighead Carp! But what happens after that depends on your fishing skills, boss.",
  str_homestory_chat_15031032 = "Of course, I'm also willing to offer some other rewards for bringing me more Bighead Carp. I'm a nice guy, after all!",
  str_homestory_chat_15031033 = "For each Bighead Carp you bring me, I'll tell you where to find one that's larger!",
  str_homestory_chat_15031034 = "I hear some are as heavy as 50 kilos! Can you believe that?!",
  str_homestory_chat_15031035 = "Also, there's a chance you might fish up an especially rare and shiny Bighead Carp!",
  str_homestory_chat_15031036 = "Well, you're definitely selling this to me like someone from Umbraton...",
  str_homestory_chat_15031037 = "But I don't even have the tiniest fish to give you right now.",
  str_homestory_chat_15031038 = "That's alright, boss! I know plenty of spots where you can find these little guys, although you'll only catch the smallest of the bunch in those areas.",
  str_homestory_chat_15031039 = "But if you've got the skills for the job, you just need to bring me the tiny one, and I'll be more than happy to trade it!",
  str_homestory_chat_15031040 = "They go from tiny, to small, to medium, to large...",
  str_homestory_chat_15031041 = "And if you make it that far, I'll make sure you catch an even bigger one! You might even be lucky enough to catch that rare, shiny one too!",
  str_homestory_chat_15031042 = "I see.",
  str_homestory_chat_15031043 = "So are you up for it, boss? I bet you can handle it!",
  str_homestory_chat_15031044 = "Do you have any other questions?",
  str_homestory_chat_15031045 = "I want to catch an even larger Bighead Carp.",
  str_homestory_chat_15031046 = "Not a problem! There are plenty of fishing spots out there. It all comes down to how big we're talking here!",
  str_homestory_chat_15031047 = "I want to catch a Small Bighead Carp.",
  str_homestory_chat_15031048 = "If you want to know where to catch Small Bighead Carp, you'll need to bring me a Tiny Bighead Carp first. Did you get one yet?",
  str_homestory_chat_15031049 = "Give Tiny Bighead Carp ({1}/1)",
  str_homestory_chat_15031050 = "Let me think it over.",
  str_homestory_chat_15031051 = "I want to catch a Medium Bighead Carp.",
  str_homestory_chat_15031052 = "If you want to know where to catch Medium Bighead Carp, you'll need to bring me a Small Bighead Carp first. Did you get one yet?",
  str_homestory_chat_15031053 = "Give Small Bighead Carp ({1}/1)",
