  str_homestory_chat_15032021 = "Let me think it over.",
  str_homestory_chat_15032022 = "You're the man, boss! I can't tell ya how happy I am!",
  str_homestory_chat_15032023 = "Check your map. I'll mark down where you can find even bigger fish!",
  str_homestory_chat_15032024 = "Ah... Let me think about it.",
  str_homestory_chat_15032025 = "I still want to ask about something else.",
  str_homestory_chat_15032026 = "Ask away, boss!",
  str_homestory_chat_15032027 = "Remind me about our Bighead Carp deal.",
  str_homestory_chat_15032028 = "Oh... You must have a lot on your plate if you already forgot, boss. But that's alright!",
  str_homestory_chat_15032029 = "I'll tell you a thousand times if I have to! You're the boss, after all!",
  str_homestory_chat_15032030 = "If you happen to have a small-sized Bighead Carp, just bring it to me.",
  str_homestory_chat_15032031 = "You give me the fish, and I tell you where to find the next largest size of Bighead Carp.",
  str_homestory_chat_15032032 = "But that's not all, boss! I'll give you some other good stuff in exchange for the fish too!",
  str_homestory_chat_15032033 = "Got it.",
  str_homestory_chat_15032034 = "I want to fish for Bighead Carp.",
  str_homestory_chat_15032035 = "Ready to start with a Tiny Bighead Carp? You can come to find me anytime once you catch one! I'll tell you where to find the next size after that!",
  str_homestory_chat_15032036 = "Yep, I'm ready.",
  str_homestory_chat_15032037 = "Great, boss! I'll mark where you can find them on the map!",
  str_homestory_chat_15032038 = "Let me think it over.",
  str_homestory_chat_15032039 = "I don't have any more questions.",
  str_homestory_chat_15032040 = "That works, boss! Just come to me whenever you've got questions!",
  str_homestory_chat_15033001 = "Tell me more about the Bighead Carp.",
  str_homestory_chat_15033002 = "No problem, boss! I already marked the fishing spots for that size of Bighead Carp on your map. Go take a look!",
  str_homestory_chat_15033003 = "I'll be rooting for you from over here, boss! Come find me if you need anything!",
  str_homestory_chat_15033004 = "Remind me about our Bighead Carp deal.",
  str_homestory_chat_15033005 = "Forgot already? That's alright, I'll tell you as many times as you like, boss!",
  str_homestory_chat_15033006 = "The deal's simple: Just bring me Bighead Carp of any size.",
  str_homestory_chat_15033007 = "You give me the fish, and I tell you where to find the next largest size of Bighead Carp.",
  str_homestory_chat_15033008 = "I'll even give you some other rewards for your troubles! You're the boss, after all!",
  str_homestory_chat_15033009 = "Ah, I got it.",
  str_homestory_chat_15033010 = "Thanks again, Korgon!",
  str_homestory_chat_15033011 = "Anytime, boss! Always ready to help!",
  str_homestory_chat_13599999 = "Hello! No work today?",
  str_homestory_chat_13501001 = "I'm taking a break.",
  str_homestory_chat_13501002 = "I'm happy to help if you're struggling with your work!",
  str_homestory_chat_13521001 = "How do you like it here?",
  str_homestory_chat_13521002 = "Yoshi loves it here!",
  str_homestory_chat_13521003 = "She can fly freely in the sky.",
  str_homestory_chat_13521004 = "What about you?",
  str_homestory_chat_13521005 = "I also... Ahem... F-For sure.",
  str_homestory_chat_13521006 = "That's great to hear.",
  str_homestory_chat_13522001 = "You look really tired...",
  str_homestory_chat_13522002 = "What? No way?",
  str_homestory_chat_13522003 = "Look! Aren't my dark circles smaller now?",
  str_homestory_chat_13522004 = "It seems like it.",
  str_homestory_chat_13522005 = "That's because I've not worked any extra shift lately!",
  str_homestory_chat_13522006 = "There's so little work to be done here that I no longer need to stay up late.",
  str_homestory_chat_13522007 = "That's great! Good for you!",
  str_homestory_chat_13522008 = "Not really.",
  str_homestory_chat_13522009 = "Um... How so?",
  str_homestory_chat_13522010 = "I've clearly not worked till late...",
  str_homestory_chat_13522011 = "Perhaps, you need to go to bed on time.",
  str_homestory_chat_13522012 = "You have a point.",
  str_homestory_chat_13551001 = "You want to tell me about a special fish?",
  str_homestory_chat_13551002 = "That's right! And I have to make a delivery after I tell you about it.",
  str_homestory_chat_13551003 = "But why would someone in Cloud Gardens need something delivered?",
  str_homestory_chat_13551004 = "Aren't you here to rest?",
  str_homestory_chat_13551005 = "No I'm here to train! And I cannot stop! Anyway, this special fish is also a subject of my training!",
  str_homestory_chat_13551006 = "A subject? You're pretty serious about this, aren't you?",
  str_homestory_chat_13551007 = "Of course, that's why I won't tell you anything until you give me the seeds of Sonorous Blooming Trees!",
  str_homestory_chat_13551008 = "Huh?",
  str_homestory_chat_13551009 = "Sometimes a little waiting is required as part of the training.",
  str_homestory_chat_13551010 = "The wasted time is also taken into account! So go! Now!",
  str_homestory_chat_13551011 = "Um, so are you in a hurry or not? This is... weird.",
  str_homestory_chat_13551012 = "Just go! Seeds of Sonorous Blooming Trees! Now!",
  str_homestory_chat_13551013 = "Okay, okay!",
  str_homestory_chat_14299999 = "Hello, PlayerName!",
  str_homestory_chat_14201001 = "Hi...",
  str_homestory_chat_14201002 = "But why do you need to shout...?",
  str_homestory_chat_14201003 = "A soldier must exercise his military spirit at all times!",
  str_homestory_chat_14201004 = "...Okay, I get it.",
  str_homestory_chat_14221001 = "You seem pretty free.",
  str_homestory_chat_14221002 = "That's right. Life here is too relaxing. Do you need me to help you train?",
  str_homestory_chat_14221003 = "Thanks, but no thanks...",
  str_homestory_chat_14221004 = "At this rate, I'll forget what it's like to be on the battlefield.",
  str_homestory_chat_14221005 = "It won't be good if you lose your military instinct.",
  str_homestory_chat_14221006 = "I'll think about it.",
  str_homestory_chat_14221007 = "Start including physical training to your schedule as soon as possible!",
  str_homestory_chat_14221008 = "A real soldier remains vigilant in times of peace!",
  str_homestory_chat_14222001 = "Are you playing a game?",
  str_homestory_chat_14222002 = "Ah, PlayerName! Come, play with me!",
  str_homestory_chat_14222003 = "I'm not free now...",
  str_homestory_chat_14222004 = "I'm so sorry, but I'm swamped with work...",
  str_homestory_chat_14222005 = "Forget it, I won't keep you here.",
  str_homestory_chat_14222006 = "I can have a game with myself.",
  str_homestory_chat_14222007 = "Be sure to play a game with me when you have time!",
  str_homestory_chat_14222008 = "Sure!",
  str_homestory_chat_14222009 = "...Gosh, why did you have to say yes so quickly?",
  str_homestory_chat_14222010 = "It's not like I have a board or any pieces with me right now.",
  str_homestory_chat_14222011 = "I'll look for you once I have everything.",
  str_homestory_chat_14223001 = "What's up?",
  str_homestory_chat_14223002 = "Bored. I'm so bored!",
  str_homestory_chat_14223003 = "There's no war to fight and no soldiers for me to train.",
  str_homestory_chat_14223004 = "This boring life really makes me want to shoot at the air with a gun.",
  str_homestory_chat_14223005 = "No, not allowed!",
  str_homestory_chat_14223006 = "No rifle firing at home!",
  str_homestory_chat_14223007 = "I can't do this and I'm not allowed to do that... You should find something for me to do!",
  str_homestory_chat_14224001 = "Please don't ask me to play another round with you.",
  str_homestory_chat_14224002 = "That's true.. You're truly horrible at it.",
  str_homestory_chat_14224003 = "That's true...",
  str_homestory_chat_14224004 = "In that case, I should teach you!",
  str_homestory_chat_14224005 = "When you play chess with me, you should also take note of my tactics.",
  str_homestory_chat_14224006 = "That's because you always play dirty!",
  str_homestory_chat_14224007 = "Well, playing chess is like fighting a war. It doesn't matter what tricks you pull, so long as you win.",
  str_homestory_chat_14224008 = "You really need to learn this from me.",
  str_homestory_chat_14224009 = "...",
  str_homestory_chat_16199999 = "Navigator, how's life treating you?",
  str_homestory_chat_16101001 = "Great!",
  str_homestory_chat_16101002 = "Excellent. You know you can tell me anything if you encounter any problems.",
  str_homestory_chat_16121001 = "Looking for me?",
  str_homestory_chat_16121002 = "PlayerName, is there anything you want to share with me?",
  str_homestory_chat_16121003 = "Not really.",
  str_homestory_chat_16121004 = "Please don't keep your negative feelings to yourself.",
  str_homestory_chat_16121005 = "You know you can open your heart to me!",
  str_homestory_chat_16121006 = "There're some...",
  str_homestory_chat_16121007 = "Great. There's no need to worry, so just tell me everything.",
  str_homestory_chat_16121008 = "I'm all ears, and we'll find a solution together!",
  str_homestory_chat_16121009 = "There're loads!",
  str_homestory_chat_16121010 = "I guess we should sit down and do this properly.",
  str_homestory_chat_16121011 = "Don't worry. I have lots of time.",
  str_homestory_chat_16122001 = "I heard about your new discovery.",
  str_homestory_chat_16122002 = "Yes, I've recently learned a new emotional therapy technique!",
  str_homestory_chat_16122003 = "PlayerName, would you like to try?",
  str_homestory_chat_16122004 = "How?",
  str_homestory_chat_16122005 = "First, try to recall your most recent emotion...",
  str_homestory_chat_16122006 = "Then, describe them to me one by one.",
  str_homestory_chat_16122007 = "Lastly, I'll provide you with an analysis report by using the new therapy theory.",
  str_homestory_chat_16122008 = "You'll see.",
  str_homestory_chat_16123001 = "just the person I'm looking for.",
  str_homestory_chat_16123002 = "Something bothering you, PlayerName?",
  str_homestory_chat_16123003 = "Yes, actually.",
  str_homestory_chat_16123004 = "I don't feel motivated in doing anything lately.",
  str_homestory_chat_16123005 = "Even if I get enough sleep.",
  str_homestory_chat_16123006 = "Maybe you need to exercise more.",
  str_homestory_chat_16123007 = "Try running five kilometers every day, and you'll feel different!",
  str_homestory_chat_16123008 = "Running, huh...",
  str_homestory_chat_17499999 = "... Is there anything I can help you with?",
  str_homestory_chat_17401001 = "Not really.",
  str_homestory_chat_17401002 = "I just wanted to say hi.",
  str_homestory_chat_17401003 = "...That's good... Do you mind leaving me alone?",
  str_homestory_chat_17401004 = "Not at all.",
  str_homestory_chat_17421001 = "What's on your mind?",
  str_homestory_chat_17421002 = "Yeah... Is it troubling you?",
  str_homestory_chat_17421003 = "It's not because of you... Daydreaming is an old habit of mine.",
  str_homestory_chat_17421004 = "What's more, this place is perfect for that. I don't feel the need to think about anything.",
  str_homestory_chat_17421005 = "Just make yourself comfortable.",
  str_homestory_chat_17421006 = "There's nothing urgent that needs to be done.",
  str_homestory_chat_17422001 = "You don't look very well...",
  str_homestory_chat_17422002 = "... I had another awful nightmare... PlayerName, do you suffer from nightmares as well?",
  str_homestory_chat_17422003 = "Frequently...",
  str_homestory_chat_17422004 = "You're just like me...",
  str_homestory_chat_17422005 = "If you don't mind, we can talk about your nightmares.",
  str_homestory_chat_17422006 = "Never.",
  str_homestory_chat_17422007 = "How lucky you must be!",
  str_homestory_chat_17422008 = "Sometimes, I wonder if these nightmares are a form of punishment for me...",
  str_homestory_chat_17422009 = "Occasionally.",
  str_homestory_chat_17422010 = "You're very lucky.",
  str_homestory_chat_17422011 = "But occasional nightmares can still be a torment.",
  str_homestory_chat_15499999 = "PlayerName, you have a job for me?",
  str_homestory_chat_15401001 = "Not at the moment.",
  str_homestory_chat_15401002 = "Just stopped by to say hello. How are you doing?",
  str_homestory_chat_15401003 = "There's nothing much to do, so I shall take a short break I guess.",
  str_homestory_chat_15421001 = "Really?",
  str_homestory_chat_15421002 = "No problem! Don't forget about me when you have tasks to assign.",
  str_homestory_chat_15421003 = "It's always a pleasure to take some weight off your shoulder!",
  str_homestory_chat_15421004 = "Thanks!",
  str_homestory_chat_15421005 = "I can't think of any task for you at the moment.",
  str_homestory_chat_15421006 = "Anyway, you can count on me for anything!",
  str_homestory_chat_15421007 = "I actually dont much of a burden to bear...",
  str_homestory_chat_15421008 = "If you really want to help, talk to Vice. She always has a list of tasks.",
  str_homestory_chat_15421009 = "Sure, I got this.",
  str_homestory_chat_15422001 = "You're in a good mood today.",
  str_homestory_chat_15422002 = "PlayerName, what do you think about my uniform today?",
  str_homestory_chat_15422003 = "I can't tell any difference...",
  str_homestory_chat_15422004 = "Look carefully! All my buttons are new.",
  str_homestory_chat_15422005 = "To work hard, I must keep my uniform in its best condition!",
  str_homestory_chat_15422006 = "It looks great on you!",
  str_homestory_chat_15422007 = "Thanks for your kind words. I'll work hard today...",
  str_homestory_chat_15422008 = "Maintain my best performance just like this uniform!",
  str_homestory_chat_15899999 = "Hi, PlayerName. What a beautiful day it is today!",
  str_homestory_chat_15801001 = "Hi, Amy!",
  str_homestory_chat_15801002 = "Did you work out today?",
  str_homestory_chat_15801003 = "I trained very hard!",
  str_homestory_chat_15801004 = "You're so energetic, like always!",
  str_homestory_chat_15801005 = "Of course!",
  str_homestory_chat_15821001 = "Be careful!",
  str_homestory_chat_15821002 = "Ah, I'm sorry!",
  str_homestory_chat_15821003 = "You don't need to stand so far away from the banner...",
  str_homestory_chat_15821004 = "I promise there won't be a next time...",
  str_homestory_chat_15821005 = "Next time...",
  str_homestory_chat_15821006 = "I'll definitely suffer from a concussion if this happens again!",
  str_homestory_chat_15821007 = "I-I didn't m-mean it...",
  str_homestory_chat_15821008 = "Why were you swinging the banner with so much strength?",
  str_homestory_chat_15821009 = "It's for my training! I must give my absolute best every time!",
  str_homestory_chat_15821010 = "... I'm convinced it's only a matter of time till this tragedy repeats itself...",
  str_homestory_chat_15822001 = "What are you doing?",
  str_homestory_chat_15822002 = "Where do you want me to place this banner?",
  str_homestory_chat_15822003 = "You don't have to do this...",
  str_homestory_chat_15822004 = "I-I don't?",
  str_homestory_chat_15822005 = "I'll move it away then... Are you sure about this?",
  str_homestory_chat_15822006 = "Let me think...",
  str_homestory_chat_15822007 = "You must consider it thoroughly!",
  str_homestory_chat_15822008 = "I guarantee that placing a banner at home will make it look even better!",
  str_homestory_chat_15851001 = "Do you know the special fish?",
  str_homestory_chat_15851002 = "That was fast! I guess you want those special fish very much.",
  str_homestory_chat_15851003 = "Maybe hard work is why you own Cloud Gardens! I can learn from you!",
  str_homestory_chat_15851004 = "So where can I get the special fish?",
  str_homestory_chat_15851005 = "I guess it's necessary to make more rounds or intensify the training...",
  str_homestory_chat_15851006 = "Amy!",
  str_homestory_chat_15851007 = "Oops, sorry, that came off too much like talking to myself.",
  str_homestory_chat_15851008 = "Effort is required to reach the spot where you can catch the special fish!",
  str_homestory_chat_15851009 = "Effort?",
  str_homestory_chat_15851010 = "I guess it came off too easy the way I put it...",
  str_homestory_chat_15851011 = "So how about finding the seed of Flourishing Strangefruit Tree for me?",
  str_homestory_chat_15851012 = "Piece of cake!",
  str_homestory_chat_15851013 = "Good luck!",
  str_homestory_chat_17699999 = "It's great to see you...",
  str_homestory_chat_17601001 = "How are you, Kleken?",
  str_homestory_chat_17601002 = "Take a guess. Will I tell the truth this time?",
  str_homestory_chat_17601003 = "Is... there a need to lie for this question?",
  str_homestory_chat_17601004 = "You never know.",
  str_homestory_chat_17621001 = "Any news?",
  str_homestory_chat_17621002 = "Yes, Brave Navigator. I've a piece of bad news for you.",
  str_homestory_chat_17621003 = "I think it'll be a good one.",
  str_homestory_chat_17621004 = "Based on my understanding, your bad news are often a good one.",
  str_homestory_chat_17621005 = "What if I tell you... The river's full of dead fish...",
  str_homestory_chat_17621006 = "Y-You can't be serious! What happened? I-I...",
  str_homestory_chat_17621007 = "Pfft... Got you! I'm just kidding.",
  str_homestory_chat_17621008 = "So, what's the bad news?",
  str_homestory_chat_17621009 = "You're not afraid that I'll lie to you?",
  str_homestory_chat_17621010 = "Wouldn't that be better? If that's the case, there won't be any bad news.",
  str_homestory_chat_17621011 = "...You're such an adorable Navigator.",
  str_homestory_chat_17622001 = "What do you want to tell me?",
  str_homestory_chat_17622002 = "...Hmm...",
  str_homestory_chat_17622003 = "Wait, don't say a word first.",
  str_homestory_chat_17622004 = "You're always lying whenever you speak.",
  str_homestory_chat_17622005 = "Fine, I'll let you speak first this time.",
  str_homestory_chat_17622006 = "...I don't have anything to say.",
  str_homestory_chat_17622007 = "...Hmm... Umm... What am I supposed to say?",
  str_homestory_chat_17622008 = "You really know how to keep a conversation going.",
  str_homestory_chat_17623001 = "What are you looking at?",
  str_homestory_chat_17623002 = "This river... Where does it flow to?",
  str_homestory_chat_17623003 = "I'm not sure...",
  str_homestory_chat_17623004 = "Perhaps, this river'll lead me to the ocean I've found in the ancient books...",
  str_homestory_chat_17623005 = "Under the waves, a palace stands in silence.",
  str_homestory_chat_17623006 = "There is merely an ordinary river... So, don't expect so much from it...",
  str_homestory_chat_17623007 = "I know...",
  str_homestory_chat_17623008 = "But it's not coming to me right now...",
  str_homestory_chat_17623009 = "Hmm... Looks like your memory must be exceptional.",
  str_homestory_chat_17899999 = "Ah... Hello.",
  str_homestory_chat_17801001 = "Hi, Robyn.",
  str_homestory_chat_17801002 = "Please keep this distance. Don't come too close... Or stay too far away.",
  str_homestory_chat_17801003 = "Is it okay if I stand right here?",
  str_homestory_chat_17801004 = "Yeah.",
  str_homestory_chat_17821001 = "Are you looking for someone?",
  str_homestory_chat_17821002 = "Do you... know where Dayna is?",
  str_homestory_chat_17821003 = "Over there...",
  str_homestory_chat_17821004 = "Ah, I see... Thanks a lot.",
  str_homestory_chat_17821005 = "I better get going... I hope I've not wasted any of your time.",
  str_homestory_chat_17821006 = "Don't worry about it.",
  str_homestory_chat_17821007 = "I don't know...",
  str_homestory_chat_17821008 = "H-How could this be? She must be worried sick...",
  str_homestory_chat_17821009 = "I feel like you two're always looking for each other...",
  str_homestory_chat_17821010 = "That's because we only have each other.",
  str_homestory_chat_17822001 = "It seems that you like it here a lot?",
  str_homestory_chat_17822002 = "Yes... Very much.",
  str_homestory_chat_17822003 = "It's very nice here... We actually longed for a place like this.",
  str_homestory_chat_17822004 = "I'm sorry... I'm not very good at giving compliments...",
  str_homestory_chat_17822005 = "If you can understand...",
  str_homestory_chat_17822006 = "Yes, I do.",
  str_homestory_chat_17823001 = "What are you trying to say?",
  str_homestory_chat_17823002 = "...Thanks for having me here.",
  str_homestory_chat_17823003 = "Please let me know if there's anything I can help you with.",
  str_homestory_chat_17823004 = "I can't think of anything right now...",
  str_homestory_chat_17823005 = "Ah, I see... If that's the case, I won't disturb you anymore.",
  str_homestory_chat_17823006 = "There's something I need your help with!",
  str_homestory_chat_17823007 = "But not right now. I'll let you know once I'm ready.",
  str_homestory_chat_17823008 = "Sure, that's all right.",
  str_homestory_chat_17399999 = "Did you bring us any treats?",
  str_homestory_chat_17301001 = "Nope...",
  str_homestory_chat_17301002 = "That's okay!",
  str_homestory_chat_17301003 = "Don't forget it next time!",
  str_homestory_chat_17321001 = "Do you like it here?",
  str_homestory_chat_17321002 = "Yes! It's perfect for hide-and-seek!",
  str_homestory_chat_17321003 = "Want to play?",
  str_homestory_chat_17321004 = "Count to ten...",
  str_homestory_chat_17321005 = "and the game will begin!",
  str_homestory_chat_17321006 = "Run!",
  str_homestory_chat_17321007 = "Here I come!",
  str_homestory_chat_17321008 = "No, I refuse to play!",
  str_homestory_chat_17322001 = "You seem pretty happy.",
  str_homestory_chat_17322002 = "Yes, there's fresh water here!",
  str_homestory_chat_17322003 = "Doggy loves it here!",
  str_homestory_chat_17322004 = "Wait...",
  str_homestory_chat_17322005 = "Do you drink from the river directly?",
  str_homestory_chat_17322006 = "Can't we?",
  str_homestory_chat_17322007 = "What'll happen after drinking it?",
  str_homestory_chat_17322008 = "Because... a certain someone loves to swim in the river!",
  str_homestory_chat_11699999 = "Hello. I hope you sleep well tonight.",
  str_homestory_chat_11601001 = "Ah... Hi.",
  str_homestory_chat_11601002 = "What's up?",
  str_homestory_chat_11601003 = "Nothing much.",
  str_homestory_chat_11601004 = "In that case, I'll take a nap first.",
  str_homestory_chat_11601005 = "All right. Rest well.",
  str_homestory_chat_11621001 = "Your eyes...",
  str_homestory_chat_11621002 = "My dark circles are pretty much gone.",
  str_homestory_chat_11621003 = "A good night sleep sure does improve my mood tremendously.",
  str_homestory_chat_11621004 = "It seems that... you just got up?",
  str_homestory_chat_11621005 = "Yeah. It's so much easier to find a peaceful spot for a nap here than in the desert.",
  str_homestory_chat_11621006 = "Speaking of which, I'd like to thank you.",
  str_homestory_chat_11621007 = "Haha. You're welcome.",
  str_homestory_chat_11622001 = "Can I help you?",
  str_homestory_chat_11622002 = "PlayerName, do you have any snacks?",
  str_homestory_chat_11622003 = "Yes!",
  str_homestory_chat_11622004 = "Give me some.",
  str_homestory_chat_11622005 = "But I don't have it with me.",
  str_homestory_chat_11622006 = "Bring me some whenever you remember.",
  str_homestory_chat_11622007 = "No...",
  str_homestory_chat_11622008 = "I'll bring you some whenever I've some.",
  str_homestory_chat_11622009 = "Thanks in advance then.",
  str_homestory_chat_11622010 = "Snacking's the only way to kill some time.",
  str_homestory_chat_11623001 = "What are you looking for?",
  str_homestory_chat_11623002 = "There seems to be loads of fluffy... creatures here.",
  str_homestory_chat_11623003 = "Don't you like them?",
  str_homestory_chat_11623004 = "I can't say I do... but I don't dislike them either.",
  str_homestory_chat_11623005 = "However, I'll make the person suffer if they dare mistreat them.",
  str_homestory_chat_17799999 = "The person I've been awaiting... It's a pleasure to see you.",
  str_homestory_chat_17701001 = "Thanks, Your Majesty.",
  str_homestory_chat_17701002 = "May there always be peace here.",
  str_homestory_chat_17701003 = "Likewise, Your Majesty.",
  str_homestory_chat_17721001 = "What's on your mind, Your Majesty?",
  str_homestory_chat_17721002 = "I'm glad to see so many people keeping you company on this journey.",
  str_homestory_chat_17721003 = "It seems that many people on this land are happy to follow you.",
  str_homestory_chat_17721004 = "We're all friends.",
  str_homestory_chat_17721005 = "I think our friendship brings us together, yet they aren't my followers.",
  str_homestory_chat_17721006 = "It pleases me that you see it this way.",
  str_homestory_chat_17721007 = "Then, am I also a friend of yours?",
  str_homestory_chat_17721008 = "Of course!",
  str_homestory_chat_17722001 = "Your Majesty, are you used to living here?",
  str_homestory_chat_17722002 = "The scenery here is very different from the Northland, but it makes me feel relaxed and happy.",
  str_homestory_chat_17722003 = "You're a fantastic host.",
  str_homestory_chat_17722004 = "Apart from your somewhat bitter black tea, limited collection of books, and a rather high temperature...",
  str_homestory_chat_17722005 = "I'm quite satisfied with everything else here.",
  str_homestory_chat_17722006 = "Ah! I see...",
  str_homestory_chat_17723001 = "I'm here.",
  str_homestory_chat_17723002 = "How much have you read the book I've given you?",
  str_homestory_chat_17723003 = "I've finished it!",
  str_homestory_chat_17723004 = "You must have learned a great deal.",
  str_homestory_chat_17723005 = "Let me help test you to help you absorb the knowledge.",
  str_homestory_chat_17723006 = "N-No... That's not necessary, Your Majesty...",
  str_homestory_chat_17723007 = "I've only read half of it...",
  str_homestory_chat_17723008 = "Even so, you should have learned a lot.",
  str_homestory_chat_17723009 = "Come, tell me how you feel about the book.",
  str_homestory_chat_17723010 = "I-I... May I have a moment to think?",
  str_homestory_chat_17723011 = "I not started yet...",
  str_homestory_chat_17723012 = "...",
  str_homestory_chat_17723013 = "It's not that I don't want to read it, but I'm far too busy...",
  str_homestory_chat_17723014 = "I'll check on you again next time, so you better get to it.",
  str_homestory_chat_17723015 = "What?",
  str_homestory_chat_17724001 = "Your Majesty, are you taking a stroll?",
  str_homestory_chat_17724002 = "Yes, PlayerName. What do you do during your free time?",
  str_homestory_chat_17724003 = "I barely have any...",
  str_homestory_chat_17724004 = "Hmm... I guess you'll be back to work after our chat.",
  str_homestory_chat_17724005 = "That's right.",
  str_homestory_chat_17724006 = "Your Majesty, may I get you anything?",
  str_homestory_chat_17724007 = "Not today. Why don't we chat more next time?",
  str_homestory_chat_17724008 = "So many things...",
  str_homestory_chat_17724009 = "I'd play games, go fishing, exercise, ...",
  str_homestory_chat_17724010 = "Do you practice swordsmanship?",
  str_homestory_chat_17724011 = "Eh? What swordsmanship...?",
  str_homestory_chat_17724012 = "Oh, I get it. Are you in need of space to swordfight, Your Majesty?",
  str_homestory_chat_17724013 = "Your intelligence never fails to amaze me.",
  str_homestory_chat_17725001 = "Are you looking for me, your majesty?",
  str_homestory_chat_17725002 = "Yes, I have been contemplating your personal abilities.",
  str_homestory_chat_17725003 = "Personal abilities...?",
  str_homestory_chat_17725004 = "Your martial arts prowess, especially self-defense.",
  str_homestory_chat_17725005 = "Because you were in dangerous situations many times, and you didn't have what it takes to protect your companions.",
  str_homestory_chat_17725006 = "In situations like these, the least you can do is protect yourself. After thinking about this for a while...",
  str_homestory_chat_17725007 = "I think I will teach you a few sword techniques for self-defense.",
  str_homestory_chat_17725008 = "Sword techniques? That sounds good... But I think I'll need to build my strength first.",
  str_homestory_chat_17725009 = "Techniques are secondary. The most important part is your stamina.",
  str_homestory_chat_17725010 = "For example, why don't we start with ten laps? It'll increase your stamina, and you can run faster when fleeing danger.",
  str_homestory_chat_17725011 = "Um, that's what you really want me to do, isn't it, your majesty?",
  str_homestory_chat_17726001 = "The sky?",
  str_homestory_chat_17726002 = "Yes, I've been looking up at the sky, and I realized that there's something wrong with Cloud Gardens.",
  str_homestory_chat_17726003 = "What do you mean?",
  str_homestory_chat_17726004 = "The sky is undefended. Cloud Gardens is surrounded by mountains, so it's difficult for ground attacks.",
  str_homestory_chat_17726005 = "But attacks from above are hard to defend.",
  str_homestory_chat_17726006 = "And we don't have anyone patrolling the skies, either.",
  str_homestory_chat_17726007 = "Um, how about the Colossus?",
  str_homestory_chat_17726008 = "Does it have any combat capabilities?",
  str_homestory_chat_17726009 = "Well, it can at least issue a warning.",
  str_homestory_chat_17726010 = "You are correct. I was overthinking things.",
  str_homestory_chat_17727001 = "Chubbs?",
  str_homestory_chat_17727002 = "What do you think of them?",
  str_homestory_chat_17727003 = "They are companions.",
  str_homestory_chat_17727004 = "Like Aurorians?",
  str_homestory_chat_17727005 = "Hmm, maybe slightly different, because they mainly hang out in Cloud Gardens.",
  str_homestory_chat_17727006 = "They are helpers.",
  str_homestory_chat_17727007 = "Just helpers?",
  str_homestory_chat_17727008 = "Maybe they are also...",
  str_homestory_chat_17727009 = "Administrators of this place?",
  str_homestory_chat_17727010 = "Have you thought about giving them more responsibilities?",
  str_homestory_chat_17727011 = "For example, letting them board the Colossus, or sending them to other towns as messengers of Cloud Gardens.",
  str_homestory_chat_17727012 = "I think... that's a little too soon.",
  str_homestory_chat_16499999 = "PlayerName, you look relaxed and carefree today..",
  str_homestory_chat_16421001 = "Have you been keeping an eye on me?",
  str_homestory_chat_16421002 = "You don't like that, PlayerName?",
  str_homestory_chat_16421003 = "Ah, I didn't mean that...",
  str_homestory_chat_16421004 = "Looks like my supervision is driving you to keep going.",
  str_homestory_chat_16422001 = "Yes, I'm taking a break.",
  str_homestory_chat_16422002 = "...Is it break time already?",
  str_homestory_chat_16422003 = "That's correct.",
  str_homestory_chat_16422004 = "Your schedule isn't packed enough. To think that you're taking a break at this time?!",
  str_homestory_chat_16422005 = "I don't think so...",
  str_homestory_chat_16422006 = "In this case, let's end our conversation right away and head back to work.",
  str_homestory_chat_16422007 = "You need to keep yourself busy, like me.",
  str_homestory_chat_16422008 = "But... It doesn't seem like you're doing anything right now.",
  str_homestory_chat_16422009 = "...Although I seem to have nothing to do on the surface, I've been paying attention all the time.",
  str_homestory_chat_16423001 = "What are you doing?",
  str_homestory_chat_16423002 = "Meditation.",
  str_homestory_chat_16423003 = "...Don't look at me like that.",
  str_homestory_chat_16423004 = "If you are facing the same amount of pressure as me, I'm sure you'll also choose to meditate for your inner peace.",
  str_homestory_chat_16423005 = "All right. I guess I'll leave you to it.",
  str_homestory_chat_16424001 = "Looking for me?",
  str_homestory_chat_16424002 = "There's something you need to know.",
  str_homestory_chat_16424003 = "What is it?",
  str_homestory_chat_16424004 = "I can't find anywhere to use Red Baron's power.",
  str_homestory_chat_16424005 = "You need to build a training ground.",
  str_homestory_chat_16424006 = "Can I reject this idea?",
  str_homestory_chat_16424007 = "It's best not to use such a dangerous weapon here.",
  str_homestory_chat_16424008 = "...Is that so? Well, I still think it's better to have a training ground.",
  str_homestory_chat_16424009 = "Sure!",
  str_homestory_chat_16424010 = "A training ground is good for all of us.",
  str_homestory_chat_16424011 = "I'll be awaiting an invitation to your training grounds tour.",
  str_homestory_chat_15799999 = "Hello. What's up, meow?",
  str_homestory_chat_15701001 = "Hello.",
  str_homestory_chat_15701002 = "Nothing much. Just here to say hi.",
  str_homestory_chat_15701003 = "I see, meow. I'll say hi too...",
  str_homestory_chat_15701004 = "Hello! Hi, meow!!!",
  str_homestory_chat_15721001 = "Do you like it here?",
  str_homestory_chat_15721002 = "Yes, I love it here, meow.",
  str_homestory_chat_15721003 = "That's because I can sleep to my heart's content here, meow.",
  str_homestory_chat_15721004 = "You seem to be always sleepy?",
  str_homestory_chat_15721005 = "I'm not just sleepy... I just love to sleep, meow!",
  str_homestory_chat_15721006 = "A soft, comfy bed will make it even better, meow.",
  str_homestory_chat_15721007 = "Noted.",
  str_homestory_chat_15722001 = "What are you up to?",
  str_homestory_chat_15722002 = "No one feeds me dried fish...",
  str_homestory_chat_15722003 = "I've decided to cook for myself, meow!",
  str_homestory_chat_15722004 = "What's the plan?",
  str_homestory_chat_15722005 = "I'll go fishing first, meow.",
  str_homestory_chat_15722006 = "But... What if I fall asleep and drown in the river?",
  str_homestory_chat_15722007 = "I've some dried fish!",
  str_homestory_chat_15722008 = "Share with me, meow.",
  str_homestory_chat_15722009 = "I'll pay you back, meow.",
  str_homestory_chat_15722010 = "But I don't have it with me though...",
  str_homestory_chat_15722011 = "Sigh... I'll visit you shortly, meow.",
  str_homestory_chat_15723001 = "Your hair...",
  str_homestory_chat_15723002 = "My hair may look messy, but it feels very soft, meow.",
  str_homestory_chat_15723003 = "Can I touch it?",
  str_homestory_chat_15723004 = "But I just licked it clean...",
  str_homestory_chat_15723005 = "Go ahead if you don't mind, meow.",
  str_homestory_chat_15723006 = "Oh, um...",
  str_homestory_chat_15723007 = "Let's brush your hair a little...",
  str_homestory_chat_15723008 = "Who knows, it may just feel even better afterward?",
  str_homestory_chat_15723009 = "No, I don't want to! Brushing my hair's tiring, meow.",
  str_homestory_chat_15724001 = "How was your sleep?",
  str_homestory_chat_15724002 = "I've slept for so long, but Yumi feels so sleepy, meow.",
  str_homestory_chat_15724003 = "Yumi?",
  str_homestory_chat_15724004 = "Isn't that obvious, meow?",
  str_homestory_chat_15724005 = "...I've just woken up, but I'm feeling somewhat sleepy, meow.",
  str_homestory_chat_15724006 = "How about Philyshy?",
  str_homestory_chat_15724007 = "Philyshy is already asleep, meow.",
  str_homestory_chat_15724008 = "She has been awake for too long, meow. So, it's her turn to rest.",
  str_homestory_chat_15724009 = "I won't wake her up for you, meow.",
  str_homestory_chat_18399999 = "Hello, master. Statement. Today's tasks are completed.",
  str_homestory_chat_18321001 = "Um...",
  str_homestory_chat_18321002 = "I only here to say hi, so it's not an inspection...",
  str_homestory_chat_18321003 = "Translating and converting. Lilliam understands.",
  str_homestory_chat_18322001 = "What do you think about this place?",
  str_homestory_chat_18322002 = "Translating and converting. It can use some cleaning. Master, please give me a cleaning order.",
  str_homestory_chat_18322003 = "That won't be necessary...",
  str_homestory_chat_18322004 = "Cleaning this place up is a lot of work...",
  str_homestory_chat_18322005 = "Why don't I arrange something else for you to do?",
  str_homestory_chat_18322006 = "Overstatement. Okay.",
  str_homestory_chat_18322007 = "Good idea.",
  str_homestory_chat_18322008 = "But please wait until everyone else finishes their job.",
  str_homestory_chat_18322009 = "Determining... You are right.",
  str_homestory_chat_18323001 = "What are you doing?",
  str_homestory_chat_18323002 = "Question. How may I help you?",
  str_homestory_chat_18323003 = "Ah... Nothing in particular...",
  str_homestory_chat_18323004 = "Statement. Lilliam believes you need many things but you choose to ignore them.",
  str_homestory_chat_18323005 = "Statement. You need some thinking exercise to better make demands.",
  str_homestory_chat_18323006 = "You've got to be kidding...",
  str_homestory_chat_18323007 = "I'll think about it...",
  str_homestory_chat_18323008 = "Overstatement. You need to think clearly what you want beforehand so Lilliam can get to work quickly.",
  str_homestory_chat_18323009 = "Ah... Okay. I'll work on that.",
  str_homestory_chat_18324001 = "Do you want to take a break?",
  str_homestory_chat_18324002 = "Translating and converting... Lilliam is still motivated enough to complete the next job.",
  str_homestory_chat_18324003 = "Master, is there a new job?",
  str_homestory_chat_18324004 = "No, not really.",
  str_homestory_chat_18324005 = "I just see you cleaning or doing other work all the time.",
  str_homestory_chat_18324006 = "Cloud Gardens is meant to be a place for resting. You can take a break here.",
  str_homestory_chat_18324007 = "Master, are you ordering me to take a break?",
  str_homestory_chat_18324008 = "Yes.",
  str_homestory_chat_18324009 = "Understood. Lilliam will take a break now.",
  str_homestory_chat_18325001 = "I heard you had a sister?",
  str_homestory_chat_18325002 = "Are you referring to No. 2?",
  str_homestory_chat_18325003 = "Yes.",
  str_homestory_chat_18325004 = "No. 2 isn't my sister.",
  str_homestory_chat_18325005 = "No.",
  str_homestory_chat_18325006 = "Who are you referring to?",
  str_homestory_chat_18325007 = "Well... Forget it, I asked the wrong question.",
  str_homestory_chat_18325008 = "I just wanted to ask if there was anyone you were close to, like a good friend.",
  str_homestory_chat_18325009 = "We can invite them here as our guests because you're always alone.",
  str_homestory_chat_18325010 = "Translating and converting... Master, are you finding a partner for Lilliam?",
  str_homestory_chat_18325011 = "Er... You know what Lilliam, just carry on like you always do.",
  str_homestory_chat_18325012 = "Yes, Master.",
  str_homestory_chat_18099999 = "Hi...",
  str_homestory_chat_18001001 = "Hello, Unimet.",
  str_homestory_chat_18001002 = "D-Did you just say hi to me? Oh, um... Hello!",
  str_homestory_chat_18001003 = "No need to be so nervous, all right?",
  str_homestory_chat_18001004 = "You're making me nervous too.",
  str_homestory_chat_18001005 = "I-I'm sorry!",
  str_homestory_chat_18021001 = "Do you enjoy chatting?",
  str_homestory_chat_18021002 = "C-Chatting? Sure, I've the time... L-Let's chat.",
  str_homestory_chat_18021003 = "What should we... chat about? Can you please think of a topic?",
  str_homestory_chat_18021004 = "Come on...",
  str_homestory_chat_18021005 = "You're making this a task now.",
  str_homestory_chat_18021006 = "But... This may just be the truth... For me...",
  str_homestory_chat_18021007 = "Next time, I'll write down all the key points... and prepare a speech!",
  str_homestory_chat_18022001 = "I heard you're adept at fixing thing?",
  str_homestory_chat_18022002 = "Hmm... PlayerName, do you have something t-that needs fixing?",
  str_homestory_chat_18022003 = "I don't think so...",
  str_homestory_chat_18022004 = "I-I see... I'll get going then...",
  str_homestory_chat_18022005 = "Yes!",
  str_homestory_chat_18022006 = "R-Really? Ah... I'm sorry... I was p-probably too loud...",
  str_homestory_chat_18022007 = "Hmm... I'd like to say... that my Assistant is getting better and better...",
  str_homestory_chat_18022008 = "S-So, feel free to come to me for help!",
  str_homestory_chat_18022009 = "Got it. I'll keep that in mind.",
  str_homestory_chat_18999999 = "Hey, you look good today.",
  str_homestory_chat_18901001 = "So do you.",
  str_homestory_chat_18901002 = "Glad to see you're in great spirits.",
  str_homestory_chat_18901003 = "Do I look in great spirit?",
  str_homestory_chat_18901004 = "Yes, you can take my word for it.",
  str_homestory_chat_18921001 = "Do you like it here?",
  str_homestory_chat_18921002 = "Peaceful and tranquil in this land makes it a great residence.",
  str_homestory_chat_18921003 = "Usually, I don't have a habit of telling anyone my likes and dislikes.",
  str_homestory_chat_18921004 = "But as for this question, I can tell you that...",
  str_homestory_chat_18921005 = "I love this place.",
  str_homestory_chat_18921006 = "It's an ideal dwelling for all Aurorians.",
  str_homestory_chat_18921007 = "That's quite a high appraisal!",
  str_homestory_chat_18922001 = "Are you resting?",
  str_homestory_chat_18922002 = "Yes, I didn't expect to be able to find a suitable way for me to relax here.",
  str_homestory_chat_18922003 = "Fishing.",
  str_homestory_chat_18922004 = "Sitting by the river silently under the warm sunlight...",
  str_homestory_chat_18922005 = "Waiting for the fish to pull the line...",
  str_homestory_chat_18922006 = "An activity that lets your mind stay focused while your body rests.",
  str_homestory_chat_18922007 = "It fills me with contentment.",
  str_homestory_chat_18922008 = "Miss Irridon enjoys Fishing...",
  str_homestory_chat_18922009 = "I'll invite you to join me when I go fishing next time!",
  str_homestory_chat_18923001 = "Fancy a run together?",
  str_homestory_chat_18923002 = "You're inviting me to run?",
  str_homestory_chat_18923003 = "I'm sorry... but I'm not a good runner...",
  str_homestory_chat_18923004 = "How come?",
  str_homestory_chat_18923005 = "As you can see, my legs... Although they may look the same as everyone's...",
  str_homestory_chat_18923006 = "they actually can't handle vigorous exercises.",
  str_homestory_chat_18923007 = "All right, then...",
  str_homestory_chat_18923008 = "I'm sorry, it's not that I don't want to. It's just that my legs...",
  str_homestory_chat_18923009 = "I understand! I'll invite you to some relaxing activity next time?",
  str_homestory_chat_18923010 = "It'll be my pleasure!",
  str_homestory_chat_12799999 = "Hello, PlayerName. Any new command?",
  str_homestory_chat_12721001 = "No.",
  str_homestory_chat_12721002 = "Just wanted to say hi.",
  str_homestory_chat_12721003 = "...",
  str_homestory_chat_12721004 = "... Is there a problem?",
  str_homestory_chat_12721005 = "No, I'm just thinking how I should respond to your greeting.",
  str_homestory_chat_12722001 = "Wanna chat?",
  str_homestory_chat_12722002 = "With pleasure.",
  str_homestory_chat_12722003 = "Talking's certainly the most effective way of communication.",
  str_homestory_chat_12722004 = "I agree.",
  str_homestory_chat_12722005 = "May I have a chat with you often?",
  str_homestory_chat_12722006 = "I'd love it.",
  str_homestory_chat_12722007 = "I'm not sure about that.",
  str_homestory_chat_12722008 = "If you try to express something through your eyes...",
  str_homestory_chat_12722009 = "You'll come to understand how clear and forthright languages are.",
  str_homestory_chat_12723001 = "What do you think about this place?",
  str_homestory_chat_12723002 = "The environment here is very relaxing.",
  str_homestory_chat_12723003 = "But I think we need more inspectors.",
  str_homestory_chat_12723004 = "You're right!",
  str_homestory_chat_12723005 = "For example, to stop people from drinking directly from the river...",
  str_homestory_chat_12723006 = "You can leave this to me.",
  str_homestory_chat_12723007 = "I'll make sure every violator receives their penalty.",
  str_homestory_chat_12723008 = "Is there a need to do that?",
  str_homestory_chat_12723009 = "I guess that's the end of this topic.",
  str_homestory_chat_12723010 = "But I'm ready to provide any assistance should you need it.",
  str_homestory_chat_18699999 = "I'm so happy to see you.",
  str_homestory_chat_18601001 = "Me too.",
  str_homestory_chat_18601002 = "Especially when I see you... alive and well.",
  str_homestory_chat_18601003 = "Ah... What happened?!",
  str_homestory_chat_18601004 = "Don't worry, it was a joke... My kind of joke.",
  str_homestory_chat_18621001 = "What are you eating?",
  str_homestory_chat_18621002 = "Miss Vice's dessert. She made a lot recently. PlayerName, have you tried?",
  str_homestory_chat_18621003 = "Yeah...",
  str_homestory_chat_18621004 = "Why this face?",
  str_homestory_chat_18621005 = "You'll see once you've tried...",
  str_homestory_chat_18621006 = "I've tried it...",
  str_homestory_chat_18621007 = "But I'd rather put on an \"another adventure completed\" face.",
  str_homestory_chat_18621008 = "No...",
  str_homestory_chat_18621009 = "It seems that you've missed out on an opportunity for adventure.",
  str_homestory_chat_18621010 = "...I'll refuse to partake in such adventures.",
  str_homestory_chat_18622001 = "Do you like to go for a walk?",
  str_homestory_chat_18622002 = "Yes, especially here. It just seems so pleasant.",
  str_homestory_chat_18622003 = "I'd say I love to be near the nature here rather than enjoy walking.",
  str_homestory_chat_18622004 = "It's rare to see this sort of soft grass in Lumopolis, especially these tiny flowers.",
  str_homestory_chat_18622005 = "It seems that I can invite you for a walk more frequently in the future.",
  str_homestory_chat_18622006 = "I'll never say no to your invitation.",
  str_homestory_chat_18623001 = "How've you been?",
  str_homestory_chat_18623002 = "Have you tried any unique dishes?",
  str_homestory_chat_18623003 = "Yes...",
  str_homestory_chat_18623004 = "Speaking of which, it was a nightmare.",
  str_homestory_chat_18623005 = "Oh? I thought you'd be willing to embrace such challenges.",
  str_homestory_chat_18623006 = "...Wait a minute... Did you have others bring me those unusual dishes?",
  str_homestory_chat_18623007 = "Please don't glare at me...",
  str_homestory_chat_18623008 = "I've also tried those unique dishes...",
  str_homestory_chat_18623009 = "No.",
  str_homestory_chat_18623010 = "Hmm? But I've clearly...",
  str_homestory_chat_18623011 = "What?",
  str_homestory_chat_18623012 = "Hush... This may be a secret that I have to take to the grave...",
  str_homestory_chat_17999999 = "Hi, PlayerName! What's your plan for today?",
  str_homestory_chat_17921001 = "Ah... Nothing really.",
  str_homestory_chat_17921002 = "In that case, may I show you yesterday's account book?",
  str_homestory_chat_17921003 = "N-No need...",
  str_homestory_chat_17921004 = "I'll keep it safe for you then.",
  str_homestory_chat_17922001 = "I heard that you have some suggestions.",
  str_homestory_chat_17922002 = "Yes, PlayerName. I suggest that you should count your Nightium every day.",
  str_homestory_chat_17922003 = "Why?",
  str_homestory_chat_17922004 = "Only after you count them will you know exactly how many you have...",
  str_homestory_chat_17922005 = "Then, you'll really come to appreciate it.",
  str_homestory_chat_17922006 = "...I see. I've once again spent them lavishly recently...",
  str_homestory_chat_17923001 = "I want to do a daily review.",
  str_homestory_chat_17923002 = "I can help you with one daily review for free.",
  str_homestory_chat_17923003 = "May I ask if you need it?",
  str_homestory_chat_17923004 = "Sure.",
  str_homestory_chat_17923005 = "Based on today's daily review, your cash flow today isn't balanced.",
  str_homestory_chat_17923006 = "There's a loss of 11 Nightium.",
  str_homestory_chat_17923007 = "Fortunately... That's not too bad.",
  str_homestory_chat_17923008 = "Many a little makes a mickle.",
  str_homestory_chat_17923009 = "So, you must pay attention to them.",
  str_homestory_chat_19199999 = "Greetings...",
  str_homestory_chat_19101001 = "Hi, Chloe.",
  str_homestory_chat_19101002 = "I hope I've not disturbed you?",
  str_homestory_chat_19101003 = "As opposed to disturbing me, you've actually just saved me from drowning in sorrow.",
  str_homestory_chat_19121001 = "What are you doing?",
  str_homestory_chat_19121002 = "...I was praying. Is there something you wish to talk about with me?",
  str_homestory_chat_19121003 = "Don't worry. You didn't interrupt me.",
  str_homestory_chat_19121004 = "I'd rather talk to you than being on my own.",
  str_homestory_chat_19121005 = "Do you always pray when you're free?",
  str_homestory_chat_19121006 = "I also play the harp sometimes.",
  str_homestory_chat_19121007 = "Only praying provides me with a moment of peace.",
  str_homestory_chat_19122001 = "Can you perform at our party?",
  str_homestory_chat_19122002 = "...Is this an invitation?",
  str_homestory_chat_19122003 = "Yes.",
  str_homestory_chat_19122004 = "Everyone's looking forward to hearing some soothing music!",
  str_homestory_chat_19122005 = "I can never say no to a sincere invitation.",
  str_homestory_chat_19122006 = "Don't worry, I'll be there on time.",
  str_homestory_chat_19122007 = "Would it be a problem?",
  str_homestory_chat_19122008 = "Not at all. I don't feel bothered.",
  str_homestory_chat_19122009 = "On the contrary, I'd love to!",
  str_homestory_chat_19122010 = "Every opportunity to perform for others should be cherished.",
  str_homestory_chat_18499999 = "It's good to see you again today, PlayerName.",
  str_homestory_chat_18401001 = "Hello, Shadowlord.",
  str_homestory_chat_18401002 = "Go ahead if you've got anything to say to me.",
  str_homestory_chat_18401003 = "Um... May I have a moment to organize my thought?",
  str_homestory_chat_18421001 = "How do you feel about this place?",
  str_homestory_chat_18421002 = "I'm pleased to be here.",
  str_homestory_chat_18421003 = "Here, I've seen the unknown sides of countless people.",
  str_homestory_chat_18421004 = "Are there any that I should be wary of?",
  str_homestory_chat_18421005 = "Haha, don't worry.",
  str_homestory_chat_18421006 = "I'm just saying that everyone's taking off their mask and feeling completely relaxed here.",
  str_homestory_chat_18421007 = "Unknown side?",
  str_homestory_chat_18421008 = "Yeah. All you have to do is watch carefully and you'll realize...",
  str_homestory_chat_18421009 = "Some people are behaving quite differently from their usual self.",
  str_homestory_chat_18421010 = "For real? I need to be more observant...",
  str_homestory_chat_18422001 = "What a relaxing day!",
  str_homestory_chat_18422002 = "PlayerName, fancy a game of chess?",
  str_homestory_chat_18422003 = "Not really...",
  str_homestory_chat_18422004 = "What a pity!",
  str_homestory_chat_18422005 = "It'll be pretty interesting if you're willing to play against me.",
  str_homestory_chat_18422006 = "Sure!",
  str_homestory_chat_18422007 = "But shouldn't we get a board and some chess pieces first?",
  str_homestory_chat_18422008 = "My invitation will always remain valid for you.",
  str_homestory_chat_18422009 = "You can come anytime with your own chess set.",
  str_homestory_chat_18423001 = "Looking for me?",
  str_homestory_chat_18423002 = "PlayerName, please let me know if you ever find wine here.",
  str_homestory_chat_18423003 = "What for?",
  str_homestory_chat_18423004 = "Add to my collection.",
  str_homestory_chat_18423005 = "Don't worry, I'll pay you a good price.",
  str_homestory_chat_18423006 = "Sure, no problem!",
  str_homestory_chat_18423007 = "Just like that?",
  str_homestory_chat_18423008 = "Aren't you going to ask me about my payment?",
  str_homestory_chat_18423009 = "It's not a big deal, so payment isn't needed.",
  str_homestory_chat_18423010 = "Ha! I admire your generosity!",
  str_homestory_chat_17099999 = "Ah! Kiddo, how can I help you this time?",
  str_homestory_chat_17021001 = "Nothing.",
  str_homestory_chat_17021002 = "Go back then, kiddo.",
  str_homestory_chat_17021003 = "Oh, that's right! Stop calling me a kiddo!",
  str_homestory_chat_17021004 = "Oh. What should I call you then? Why don't you tell me, kiddo?",
  str_homestory_chat_17021005 = "I'll think about it.",
  str_homestory_chat_17021006 = "Um...",
  str_homestory_chat_17022001 = "How do you feel about this place?",
  str_homestory_chat_17022002 = "It's much better than Umbraton.",
  str_homestory_chat_17022003 = "How so?",
  str_homestory_chat_17022004 = "That's because Sunstone can fly freely here.",
  str_homestory_chat_17022005 = "As for Umbraton... Well, you know that place...",
  str_homestory_chat_17022006 = "It could barely spread its wings there.",
  str_homestory_chat_17022007 = "So, kiddo, don't build too many skyscrapers in the future.",
  str_homestory_chat_17022008 = "Ah... Noted.",
  str_homestory_chat_17023001 = "What's new?",
  str_homestory_chat_17023002 = "What's up? Wanna chat with me?",
  str_homestory_chat_17023003 = "Can't I?",
  str_homestory_chat_17023004 = "Haha. Of course, you can. But don't blame me if I say something strange.",
  str_homestory_chat_17023005 = "Urgh... Can I end our conversation now?",
  str_homestory_chat_17023006 = "You don't like talking to others?",
  str_homestory_chat_17023007 = "Is it that obvious?",
  str_homestory_chat_17023008 = "Well, I'd be more concerned if you don't want to chat with me, kiddo.",
  str_homestory_chat_17024001 = "Your temper...",
  str_homestory_chat_17024002 = "is much better than before.",
  str_homestory_chat_17024003 = "Did I have a bad temper before?",
  str_homestory_chat_17024004 = "Yes!",
  str_homestory_chat_17024005 = "Hmph! Kiddo, that's very bold of you.",
  str_homestory_chat_17024006 = "Aren't you afraid I'll lose my temper?",
  str_homestory_chat_17024007 = "W-Wait a minute... Stay back!",
  str_homestory_chat_17024008 = "That's not what I meant...",
  str_homestory_chat_17024009 = "Haha, don't be frightened.",
  str_homestory_chat_17024010 = "I've also noticed I'm much calmer now.",
  str_homestory_chat_17024011 = "Come to think of it, I think this place puts me in a good mood.",
  str_homestory_chat_18599999 = "Hello. May I help you record anything today?",
  str_homestory_chat_18521001 = "No need.",
  str_homestory_chat_18521002 = "Just wanted to say hi.",
  str_homestory_chat_18521003 = "Okay. Let me know if you need to search for any information.",
  str_homestory_chat_18522001 = "That box...",
  str_homestory_chat_18522002 = "... Don't you try to peep into the Marmon Box.",
  str_homestory_chat_18522003 = "I'm just curious...",
  str_homestory_chat_18522004 = "You've been putting things into the box since you arrived here.",
  str_homestory_chat_18522005 = "That's because I need to keep my record up to date.",
  str_homestory_chat_18522006 = "There're things here that needs recording?",
  str_homestory_chat_18522007 = "...My files don't record only those dark deeds.",
  str_homestory_chat_18523001 = "You want to catch some birds?",
  str_homestory_chat_18523002 = "... Don't put words in my mouth.",
  str_homestory_chat_18523003 = "But there're so many birds.",
  str_homestory_chat_18523004 = "...I wouldn't mind having a few more.",
  str_homestory_chat_18523005 = "You...",
  str_homestory_chat_18523006 = "All right, stop giving me that face.",
  str_homestory_chat_18523007 = "I won't break any rule here.",
  str_homestory_chat_18524001 = "What do you do for fun?",
  str_homestory_chat_18524002 = "...Practice calligraphy.",
  str_homestory_chat_18524003 = "What?",
  str_homestory_chat_18524004 = "Whenever I have free time, I'll practice calligraphy.",
  str_homestory_chat_18524005 = "Each record must be written in the best handwriting.",
  str_homestory_chat_18524006 = "That sounds tiresome...",
  str_homestory_chat_18524007 = "Otherwise, the readers'll find it tedious to read the records.",
  str_homestory_chat_16099999 = "Hi, PlayerName. How's your day?",
  str_homestory_chat_16021001 = "Not bad.",
  str_homestory_chat_16021002 = "Not bad isn't good enough. You need to open your arms and embrace life.",
  str_homestory_chat_16021003 = "Live life to the fullest and enjoy every moment. So, you've got to remember this.",
  str_homestory_chat_16022001 = "What's on your mind?",
  str_homestory_chat_16022002 = "Yesterday's breakfast.",
  str_homestory_chat_16022003 = "...How can you still remember yesterday's breakfast?",
  str_homestory_chat_16022004 = "Is that very strange?",
  str_homestory_chat_16022005 = "Breakfast is the most important meal of the day.",
  str_homestory_chat_16022006 = "After all, it represents the start of a new day. So, having a great breakfast is the best way to start the day.",
  str_homestory_chat_16023001 = "If you didn't join the Rediesel Wrench...",
  str_homestory_chat_16023002 = "what do you think you would be doing?",
  str_homestory_chat_16023003 = "Probably a receptionist somewhere.",
  str_homestory_chat_16023004 = "Why?",
  str_homestory_chat_16023005 = "Look at my mechanical arm... I can shake hands with three customers at once.",
  str_homestory_chat_16023006 = "No way...",
  str_homestory_chat_16023007 = "You're already having a hard time shaking hands with someone.",
  str_homestory_chat_16023008 = "Who said that? No, I can shake three people's hands at once.",
  str_homestory_chat_16023009 = "I suppose four person is manageable if I must.",
  str_homestory_chat_16023010 = "...It seems strange when I try to picture it.",
  str_homestory_chat_16024001 = "What are you thinking about?",
  str_homestory_chat_16024002 = "What should I listen to today?",
  str_homestory_chat_16024003 = "Rock 'n' Roll!",
  str_homestory_chat_16024004 = "Not bad, you've even listened to this.",
  str_homestory_chat_16024005 = "Classical music!",
  str_homestory_chat_16024006 = "Even though I'm not a big fan, it's pretty good.",
  str_homestory_chat_16024007 = "Well, that was easy.",
  str_homestory_chat_16024008 = "Everything's all right, so long as you don't force yourself.",
  str_homestory_chat_18899999 = "Hello, PlayerName.",
  str_homestory_chat_18801001 = "Ah... Hello.",
  str_homestory_chat_18801002 = "Why... are you so loud all of a sudden?",
  str_homestory_chat_18801003 = "I-I'm just really happy to see you...",
  str_homestory_chat_18801004 = "I'll try to keep my volume down next time.",
  str_homestory_chat_18801005 = "You don't have to go that far. It's okay to be loud.",
  str_homestory_chat_18821001 = "Why are you staring at the grass?",
  str_homestory_chat_18821002 = "T-That's because... I'm so hungry...",
  str_homestory_chat_18821003 = "There's food in the grass?",
  str_homestory_chat_18821004 = "Of course! Beetles and caterpillars are exceptional ingredients!",
  str_homestory_chat_18821005 = "You eat grass?",
  str_homestory_chat_18821006 = "Me? No way!",
  str_homestory_chat_18821007 = "I'm looking for small bugs... Beetles, caterpillars and such...",
  str_homestory_chat_18821008 = "...I feel like your voice is gradually becoming high-pitched...",
  str_homestory_chat_18821009 = "Of course, I'm feeling so excited at the mention of delicious food!",
  str_homestory_chat_18822001 = "Something's different about you today.",
  str_homestory_chat_18822002 = "PlayerName, how do I look today?",
  str_homestory_chat_18822003 = "Very pretty!",
  str_homestory_chat_18822004 = "Aww... Really? I won't stand out too much, will I?",
  str_homestory_chat_18822005 = "You'll, of course, be eye-catching when you dress so well.",
  str_homestory_chat_18822006 = "Hmm... Maybe I should get changed...",
  str_homestory_chat_18822007 = "A little strange...",
  str_homestory_chat_18822008 = "Strange? I-I better get changed...",
  str_homestory_chat_18822009 = "Strange but very stylish!",
  str_homestory_chat_18822010 = "Ah... Is that so?",
  str_homestory_chat_18823001 = "What are you thinking about?",
  str_homestory_chat_18823002 = "The race a few days ago was really fun!",
  str_homestory_chat_18823003 = "So you like to run?",
  str_homestory_chat_18823004 = "No, not really...",
  str_homestory_chat_18823005 = "But I enjoy that feeling of dashing forward with all your might!",
  str_homestory_chat_18823006 = "Hmm... Do I sound like a weirdo?",
  str_homestory_chat_18823007 = "Not at all. You're very cute!",
  str_homestory_chat_18823008 = "R-Really?",
  str_homestory_chat_17599999 = "Hello, it's so nice of you to come see me today. What's up?",
  str_homestory_chat_17521001 = "Nothing really.",
  str_homestory_chat_17521002 = "Be honest with me. Did you break something today?",
  str_homestory_chat_17521003 = "Let me think... No, wait! I didn't break anything, alright!",
  str_homestory_chat_17521004 = "I thought you're here to have me to fix something again.",
  str_homestory_chat_17522001 = "What's the matter?",
  str_homestory_chat_17522002 = "Darn it, those guys!",
  str_homestory_chat_17522003 = "I've just fixed this Communicator and they broke it again.",
  str_homestory_chat_17522004 = "Hmph! I want to...",
  str_homestory_chat_17522005 = "beat them up?",
  str_homestory_chat_17522006 = "That's too simple and violent for me...",
  str_homestory_chat_17522007 = "I want to hack into their Communicator so they won't be able to use it for a while!",
  str_homestory_chat_17523001 = "I heard you're an expert.",
  str_homestory_chat_17523002 = "PlayerName wants to learn?",
  str_homestory_chat_17523003 = "I'd love to!",
  str_homestory_chat_17523004 = "I do love such energy.",
  str_homestory_chat_17523005 = "But you better be an intelligent student.",
  str_homestory_chat_17523006 = "I don't think I can handle another Brock.",
  str_homestory_chat_17523007 = "Not really...",
  str_homestory_chat_17523008 = "I offered to train you only because your foundation's not bad.",
  str_homestory_chat_17523009 = "But I didn't think you've no desire for knowledge!",
  str_homestory_chat_17523010 = "Forget it.",
  str_homestory_chat_17524001 = "Looking for me?",
  str_homestory_chat_17524002 = "PlayerName, is there any competition coming up?",
  str_homestory_chat_17524003 = "Yes!",
  str_homestory_chat_17524004 = "Come on, tell me all about it. What competition is it? Where will it be held?",
  str_homestory_chat_17524005 = "What are you up to?",
  str_homestory_chat_17524006 = "I'm getting my futuristic technology ready in advance.",
  str_homestory_chat_17524007 = "Well, I'm not telling you anything beforehand. That way, I can ensure the fairness of the competition.",
  str_homestory_chat_17524008 = "Hmph! It's not like you're the only source I can approach.",
  str_homestory_chat_17524009 = "No...",
  str_homestory_chat_17524010 = "Oh. I initially intended to prepare some new technology. I guess there's no need to now.",
  str_homestory_chat_19099999 = "Hi, PlayerName. What a coincidence!",
  str_homestory_chat_19001001 = "Hello, Barbara!",
  str_homestory_chat_19001002 = "Fancy a song?",
  str_homestory_chat_19001003 = "I can request a song?",
  str_homestory_chat_19001004 = "Of course, but just keep one thing in mind...",
  str_homestory_chat_19001005 = "I never do Metal or Death Rock!",
  str_homestory_chat_19021001 = "What do you think about this place?",
  str_homestory_chat_19021002 = "I love it here!",
  str_homestory_chat_19021003 = "I can enjoy sashimi anytime and anywhere.",
  str_homestory_chat_19021004 = "Wait a minute...",
  str_homestory_chat_19021005 = "...The fish we prepared for the party... Don't tell me that you...",
  str_homestory_chat_19021006 = "Eh? It's impossible for me to finish them up alone!",
  str_homestory_chat_19021007 = "I've only had a small piece!",
  str_homestory_chat_19021008 = "Who else?",
  str_homestory_chat_19021009 = "Umm... I'll never betray my friends!",
  str_homestory_chat_19022001 = "Hi. You're looking for me?",
  str_homestory_chat_19022002 = "PlayerName, did you listen to my new album?",
  str_homestory_chat_19022003 = "New album?",
  str_homestory_chat_19022004 = "You didn't know I've released a new album?",
  str_homestory_chat_19022005 = "This is so heartbreaking... PlayerName doesn't care about me at all...",
  str_homestory_chat_19022006 = "I promise you I'll listen to it today!",
  str_homestory_chat_19022007 = "Oh? Don't lie to me!",
  str_homestory_chat_19022008 = "Yes!",
  str_homestory_chat_19022009 = "How is it? Are you a fan of mine now?",
  str_homestory_chat_19022010 = "Let me give you my autograph.",
  str_homestory_chat_19022011 = "I can only sign my new album though.",
  str_homestory_chat_19022012 = "Sure, I'll bring over the album next time for an autograph!",
  str_homestory_chat_19023001 = "What are you doing?",
  str_homestory_chat_19023002 = "PlayerName, don't you find this place too quiet?",
  str_homestory_chat_19023003 = "No, it's actually rather noisy.",
  str_homestory_chat_19023004 = "Should we... play some music to drown out the noise?",
  str_homestory_chat_19023005 = "It really is quiet today.",
  str_homestory_chat_19023006 = "Should we liven things up with some music?",
  str_homestory_chat_19023007 = "How about a soft, sweet tune?",
  str_homestory_chat_19023008 = "Or a grand concert for young beauties!",
  str_homestory_chat_19023009 = "I'll think about it.",
  str_homestory_chat_18199999 = "Hello, PlayerName.",
  str_homestory_chat_18101001 = "Hello!",
  str_homestory_chat_18101002 = "You're in good spirits! Want to challenge yourself with me today?",
  str_homestory_chat_18101003 = "How should I challenge you?",
  str_homestory_chat_18101004 = "A 10,000 run! Are you in?",
  str_homestory_chat_18101005 = "... No, no... I'll leave you to it...",
  str_homestory_chat_18121001 = "You're always exercising.",
  str_homestory_chat_18121002 = "Yes... The race a few days ago was... so boring!",
  str_homestory_chat_18121003 = "How so?",
  str_homestory_chat_18121004 = "It was only 5,000 meters. I can finished it in no time.",
  str_homestory_chat_18121005 = "5,000 meters isn't enough for you?",
  str_homestory_chat_18121006 = "I can finish 5,000 meters in one breath.",
  str_homestory_chat_18121007 = "It should be 10,000 meters. No, at least 30,000 meters!",
  str_homestory_chat_18121008 = "Why does it sound like you're bragging now...?",
  str_homestory_chat_18122001 = "What would you like to buy?",
  str_homestory_chat_18122002 = "Any protein powder here?",
  str_homestory_chat_18122003 = "Of course!",
  str_homestory_chat_18122004 = "I believe I saw it somewhere not too long ago...",
  str_homestory_chat_18122005 = "Where?",
  str_homestory_chat_18122006 = "Hmm... I'm sorry, I can't remember now.",
  str_homestory_chat_18122007 = "You should have said no in the first place. What's the point of giving me such high expectation?",
  str_homestory_chat_18122008 = "I don't think so...",
  str_homestory_chat_18122009 = "There isn't even any protein powder...",
  str_homestory_chat_18122010 = "How can one live without protein powder?",
  str_homestory_chat_18122011 = "PlayerName, get some for me!",
  str_homestory_chat_18123001 = "What are you looking at?",
  str_homestory_chat_18123002 = "PlayerName, check out my new shoes! What do you think?",
  str_homestory_chat_18123003 = "I can't tell any difference...",
  str_homestory_chat_18123004 = "Look carefully at the front, the heel, and the colors...",
  str_homestory_chat_18123005 = "These're the trendiest shoes in the market right now!",
  str_homestory_chat_18123006 = "O-Oh, really? I've learned something new today.",
  str_homestory_chat_18123007 = "Pretty good!",
  str_homestory_chat_18123008 = "Your taste is as good as mine.",
  str_homestory_chat_18123009 = "Aren't you jealous? Want me to get you some?",
  str_homestory_chat_18123010 = "That'd be great!",
  str_homestory_chat_18299999 = "Hehe... Greetings!",
  str_homestory_chat_18201001 = "Hey, Ophina!",
  str_homestory_chat_18201002 = "I'm embarking on a new adventure today. Would you like to join me?",
  str_homestory_chat_18201003 = "Adventure? Where to? Are you leaving us?",
  str_homestory_chat_18201004 = "Don't worry, I'll never leave Colossus...",
  str_homestory_chat_18221001 = "What's wrong?",
  str_homestory_chat_18221002 = "Huff... Huff... I'm exhausted.",
  str_homestory_chat_18221003 = "It's so exhausting to walk with these massive horns...",
  str_homestory_chat_18221004 = "Want me to help you carry them for a while?",
  str_homestory_chat_18221005 = "D-Don't touch my horns... They can be dangerous!",
  str_homestory_chat_18222001 = "What's up?",
  str_homestory_chat_18222002 = "I want to tell you that...",
  str_homestory_chat_18222003 = "I really love this place! I can explore freely without worrying about those Eclipsites.",
  str_homestory_chat_18222004 = "My new adventure starts today, so wish me luck!",
  str_homestory_chat_18222005 = "Sure, have a pleasant journey. Bon voyage!",
  str_homestory_chat_19299999 = "...",
  str_homestory_chat_19201001 = "Hello.",
  str_homestory_chat_19201002 = "Why did you greet me?",
  str_homestory_chat_19201003 = "Am I supposed to greet you back as well?",
  str_homestory_chat_19201004 = "U-Um...",
  str_homestory_chat_19201005 = "Fine. Would you be satisfied if I say hello?",
  str_homestory_chat_19221001 = "Wanna chat?",
  str_homestory_chat_19221002 = "Chat? What do you want to chat about?",
  str_homestory_chat_19221003 = "Let's make it clear. You're here to chat with me, but I may not reply to you.",
  str_homestory_chat_19221004 = "Aren't you already replying to me?",
  str_homestory_chat_19221005 = "...I may or may not reply, got it?",
  str_homestory_chat_19221006 = "Fine. I give up.",
  str_homestory_chat_19221007 = "How can you give up so easily?",
  str_homestory_chat_19221008 = "Don't you think it's awful that you'll just give up something after hearing a few words from someone?",
  str_homestory_chat_19221009 = "...",
  str_homestory_chat_19222001 = "What are you thinking about?",
  str_homestory_chat_19222002 = "Did you enjoy yesterday's dinner?",
  str_homestory_chat_19222003 = "Yes, I did!",
  str_homestory_chat_19222004 = "I don't get you. How could you find that delicious?",
  str_homestory_chat_19222005 = "There was radish in it! Don't you know that radish ruins the entire dish?",
  str_homestory_chat_19222006 = "Is that so? I never knew that.",
  str_homestory_chat_19222007 = "Not really...",
  str_homestory_chat_19222008 = "Why is that?",
  str_homestory_chat_19222009 = "I asked several people already and no one liked it.",
  str_homestory_chat_19222010 = "You people are strange. I know there were uncommon dishes like roasted lizard...",
  str_homestory_chat_19222011 = "but how can you not enjoy it?",
  str_homestory_chat_19222012 = "Um...",
  str_homestory_chat_19223001 = "Wow, so many notes...",
  str_homestory_chat_19223002 = "PlayerName, should I organize them for you?",
  str_homestory_chat_19223003 = "I've plenty of free time today.",
  str_homestory_chat_19223004 = "That'd be great!",
  str_homestory_chat_19223005 = "But let me find my notebook first...",
  str_homestory_chat_19223006 = "You actually don't know where your reading notes are? That's so disorganized of you!",
  str_homestory_chat_19223007 = "I'll help you tidy things up after.",
  str_homestory_chat_19223008 = "I actually don't have any reading notes...",
  str_homestory_chat_19223009 = "I can't believe someone in this world doesn't keep any notes! Don't you know how to take notes?",
  str_homestory_chat_19223010 = "I'm more than happy to teach you if you don't.",
  str_homestory_chat_14599999 = "Hello.",
  str_homestory_chat_14501001 = "Hi, Nails.",
  str_homestory_chat_14501002 = "Your greeting always makes this sinner perplexed and uneasy.",
  str_homestory_chat_14501003 = "But it's my honor to bear such bewilderment.",
  str_homestory_chat_14501004 = "...A simple greeting brings about such serious consequences?",
  str_homestory_chat_14521001 = "You want to confess?",
  str_homestory_chat_14521002 = "Do you want to join me?",
  str_homestory_chat_14521003 = "Nope...",
  str_homestory_chat_14521004 = "Of course. Someone, who lives under the sun, is nothing like me...",
  str_homestory_chat_14521005 = "Confession is the only way to atone for my sins...",
  str_homestory_chat_14521006 = "Um... I think self-reflection is beneficial, but don't overdo it...",
  str_homestory_chat_14521007 = "I guess so...",
  str_homestory_chat_14521008 = "Come, follow me. Face the Truth and confess your sins.",
  str_homestory_chat_14521009 = "... My sin? That's too heavy a word, isn't it?",
  str_homestory_chat_14522001 = "What's wrong?",
  str_homestory_chat_14522002 = "...The sunlight here is too harsh.",
  str_homestory_chat_14522003 = "Do you not like the sunlight?",
  str_homestory_chat_14522004 = "Why would I not like it?",
  str_homestory_chat_14522005 = "Instead... I think the sun is unwilling to shin upon sinners like me.",
  str_homestory_chat_14522006 = "Should you be avoiding the sun altogether?",
  str_homestory_chat_14522007 = "I read some creatures get hurt when they're exposed to the sun.",
  str_homestory_chat_14522008 = "I do get hurt by the sun... It's just that it's not my body that gets hurt...",
  str_homestory_chat_14522009 = "but instead, it's my sinful heart.",
  str_homestory_chat_14522010 = "...",
  str_homestory_chat_14523001 = "Your body...",
  str_homestory_chat_14523002 = "Don't worry about the blood.",
  str_homestory_chat_14523003 = "It's not easy for me to stop the bleeding.",
  str_homestory_chat_14523004 = "Did you get into another fight?",
  str_homestory_chat_14523005 = "I rarely commit such sins lately.",
  str_homestory_chat_14523006 = "That's good... but you should still do something to stop the bleeding.",
  str_homestory_chat_14523007 = "Did you stab yourself again?",
  str_homestory_chat_14523008 = "It's my way of releasing my energy... But it's also a way for me to atone.",
  str_homestory_chat_14523009 = "The blood flow feels so real.",
  str_homestory_chat_14523010 = "I still think you need to stop the bleeding.",
  str_homestory_chat_14523011 = "I'll give it some serious thought.",
  str_homestory_chat_16899999 = "Hi, PlayerName!",
  str_homestory_chat_16801001 = "Hello, Wendy!",
  str_homestory_chat_16801002 = "No mail for you today!",
  str_homestory_chat_16801003 = "Okay, got it.",
  str_homestory_chat_16801004 = "Don't be sad. Wendy'll write you a letter!",
  str_homestory_chat_16821001 = "Looking for me?",
  str_homestory_chat_16821002 = "Woah, is there filth on my feathers?",
  str_homestory_chat_16821003 = "Quick, take a look for me!",
  str_homestory_chat_16821004 = "I don't see anything...",
  str_homestory_chat_16821005 = "Really? But why do I feel like something's wrong?",
  str_homestory_chat_16821006 = "I should probably flap my wings with some force!",
  str_homestory_chat_16821007 = "W-Wait a second. I'm still here!",
  str_homestory_chat_16821008 = "Right here!",
  str_homestory_chat_16821009 = "Q-Quick, get it off me!",
  str_homestory_chat_16821010 = "Haha, I'm just kidding.",
  str_homestory_chat_16821011 = "Ugh... Do you want me to slap you?",
  str_homestory_chat_16822001 = "You seem pretty relaxed.",
  str_homestory_chat_16822002 = "I'm starting to feel bored...",
  str_homestory_chat_16822003 = "How come?",
  str_homestory_chat_16822004 = "I can't even kick up sand on this land...",
  str_homestory_chat_16822005 = "In the Rediesel Desert, my kick can raise a sandstorm. It's pretty awesome.",
  str_homestory_chat_16822006 = "Without the sand, my kick doesn't seem that powerful anymore...",
  str_homestory_chat_16822007 = "...Got it, I'll find you a sand pit.",
  str_homestory_chat_16823001 = "You want to know about backpacks?",
  str_homestory_chat_16823002 = "That's right!",
  str_homestory_chat_16823003 = "So, what do you want to know?",
  str_homestory_chat_16823004 = "About the material, mainly. I need something light and sturdy.",
  str_homestory_chat_16823005 = "There'll be a lot of wear and tear since I fly very fast, and in sandy areas!",
  str_homestory_chat_16823006 = "Material, eh? Just go to Umbraton. It's got all kinds of fabrics.",
  str_homestory_chat_16823007 = "But it's too expensive there! Too many crooked dealers, too!",
  str_homestory_chat_16823008 = "It's not like Cloud Gardens, where I might get good stuff for free!",
  str_homestory_chat_16823009 = "So that's what you really want...",
  str_homestory_chat_16824001 = "What are you looking at?",
  str_homestory_chat_16824002 = "Who, me? I'm not looking at anything. I'm just taking in the wind.",
  str_homestory_chat_16824003 = "It's quiet, and there's no wind at all here. Is there a windier place around?",
  str_homestory_chat_16824004 = "No.",
  str_homestory_chat_16824005 = "Well, it is indeed quiet here, probably too quiet.",
  str_homestory_chat_16824006 = "I'm getting antsy. I might have to spin and make a little whirlwind myself.",
  str_homestory_chat_16824007 = "You... probably want to do that somewhere with more space.",
  str_homestory_chat_16824008 = "Why do you want a strong wind?",
  str_homestory_chat_16824009 = "So I can feel the power of speed and test this jetpack on top!",
  str_homestory_chat_16824010 = "I run into that often when I fly in the desert!",
  str_homestory_chat_16824011 = "Why can't you just test it in the Redisel Desert then?",
  str_homestory_chat_16825001 = "Are you looking for a package?",
  str_homestory_chat_16825002 = "Yeah, I think I lost a package again!",
  str_homestory_chat_16825003 = "You think? You don't know?",
  str_homestory_chat_16825004 = "I lost it all right, just not sure where.",
  str_homestory_chat_16825005 = "I know it's around here, but it's okay.",
  str_homestory_chat_16825006 = "It's okay?",
  str_homestory_chat_16825007 = "Yeah.",
  str_homestory_chat_16825008 = "That's rather cavalier as a courier.",
  str_homestory_chat_16825009 = "It's all right, because it was addressed to someone here.",
  str_homestory_chat_16825010 = "I lost it here, and the recipient is here, so they should still get it at some point.",
  str_homestory_chat_16825011 = "Uh...",
  str_homestory_chat_15999999 = "Hello! I didn't think you'll say hello to an ordinary man like me.",
  str_homestory_chat_15901001 = "It has nothing to do with someone being ordinary or not.",
  str_homestory_chat_15901002 = "You're my friend.",
  str_homestory_chat_15901003 = "Aww... I'm so touched.",
  str_homestory_chat_15921001 = "How are you getting along here?",
  str_homestory_chat_15921002 = "I'm finally living my dream now!",
  str_homestory_chat_15921003 = "This is the best place for an ordinary man like me!",
  str_homestory_chat_15921004 = "So you like it here?",
  str_homestory_chat_15921005 = "Yes, PlayerName! Let me stay here forever!",
  str_homestory_chat_15921006 = "I'll listen to whatever you say!",
  str_homestory_chat_15922001 = "It looks like you're in a good mood?",
  str_homestory_chat_15922002 = "No letters to deliver lately...",
  str_homestory_chat_15922003 = "That's right. No weirdoes to deal with.",
  str_homestory_chat_15922004 = "You must have met all sorts of strange people.",
  str_homestory_chat_15922005 = "Aren't you afraid?",
  str_homestory_chat_15922006 = "I might be the weirdest for many.",
  str_homestory_chat_19699999 = "Hmm...",
  str_homestory_chat_19601001 = "Hi, Sariel.",
  str_homestory_chat_19601002 = "Huh? Did you just greet me?",
  str_homestory_chat_19601003 = "Sorry I didn't hear. I was in a trance...",
  str_homestory_chat_19601004 = "It's okay.",
  str_homestory_chat_19601005 = "It's better late than never... Hello.",
  str_homestory_chat_19621001 = "What do you have to say?",
  str_homestory_chat_19621002 = "I have a request to make but I'm not sure if it's okay to ask...",
  str_homestory_chat_19621003 = "Try me.",
  str_homestory_chat_19621004 = "Could you move closer?",
  str_homestory_chat_19621005 = "Ahh... Err...",
  str_homestory_chat_19621006 = "Why is your face turning red?",
  str_homestory_chat_19621007 = "Please don't take me wrong. I just wanted you to stand closer...",
  str_homestory_chat_19621008 = "The scenery behind you would look more symmetrical.",
  str_homestory_chat_19622001 = "What are you looking for?",
  str_homestory_chat_19622002 = "Did you see a black cat just now?",
  str_homestory_chat_19622003 = "Yes!",
  str_homestory_chat_19622004 = "Where? Show me!",
  str_homestory_chat_19622005 = "Ah... It was a fast runner. I lost sight of it quickly.",
  str_homestory_chat_19622006 = "I see...",
  str_homestory_chat_19622007 = "No...",
  str_homestory_chat_19622008 = "I saw it run this way...",
  str_homestory_chat_19622009 = "Ah... Forget it if no one else saw it.",
  str_homestory_chat_19623001 = "What are you doing?",
  str_homestory_chat_19623002 = "PlayerName, did you like the coffee we had last time?",
  str_homestory_chat_19623003 = "It was superb!",
  str_homestory_chat_19623004 = "Hmm. I guess we have a similar taste.",
  str_homestory_chat_19623005 = "I'll invite you when I brew again.",
  str_homestory_chat_19623006 = "Can't wait!",
  str_homestory_chat_19623007 = "A little bitter...",
  str_homestory_chat_19623008 = "I see... Should have offered you more cream and sugar...",
  str_homestory_chat_19623009 = "After all, Americano is not for everyone.",
  str_homestory_chat_19624001 = "What do you think about this place?",
  str_homestory_chat_19624002 = "Everybody is so friendly here.",
  str_homestory_chat_19624003 = "So glad to hear!",
  str_homestory_chat_19624004 = "When I first arrived in Umbraton, I got scammed and lost a lot of money.",
  str_homestory_chat_19624005 = "I haven't met a single swindler here.",
  str_homestory_chat_19624006 = "... Really?",
  str_homestory_chat_19624007 = "There are swindlers who are not after your money!",
  str_homestory_chat_20399999 = "PlayerName, what's the plan for today?",
  str_homestory_chat_20301001 = "Nothing in particular.",
  str_homestory_chat_20301002 = "Okay. Any suspect to interrogate today?",
  str_homestory_chat_20301003 = "When did we ever have any?",
  str_homestory_chat_20301004 = "So no?",
  str_homestory_chat_20301005 = "Of course not!",
  str_homestory_chat_20321001 = "Your eye patch...",
  str_homestory_chat_20321002 = "Stop staring at the patch on my right eye.",
  str_homestory_chat_20321003 = "Is it magical?",
  str_homestory_chat_20321004 = "Are you seriously asking? This was from Victoria...",
  str_homestory_chat_20321005 = "She's always right!",
  str_homestory_chat_20321006 = "Then...",
  str_homestory_chat_20321007 = "You misled me!",
  str_homestory_chat_20321008 = "I asked you to stop looking at my eye patch because...",
  str_homestory_chat_20321009 = "Your stare is very strange!",
  str_homestory_chat_20322001 = "What's on your mind?",
  str_homestory_chat_20322002 = "Haven't seen that for a while.",
  str_homestory_chat_20322003 = "What are you talking about?",
  str_homestory_chat_20322004 = "You know. Those bloody faces twisted with pain.",
  str_homestory_chat_20322005 = "I'm getting bored.",
  str_homestory_chat_20322006 = "...",
  str_homestory_chat_20323001 = "You are asking for an interrogation room?",
  str_homestory_chat_20323002 = "That's right. When can we build one?",
  str_homestory_chat_20323003 = "Why do we need one?",
  str_homestory_chat_20323004 = "Because it's essential for my work.",
  str_homestory_chat_20323005 = "We are not building an interrogation room.",
  str_homestory_chat_20323006 = "We don't have criminals here.",
  str_homestory_chat_20323007 = "Not now. But who can be so sure about the future?",
  str_homestory_chat_20323008 = "PlayerName, just build one. I'll help you.",
  str_homestory_chat_20323009 = "Not a chance.",
  str_homestory_chat_20324001 = "Are you buying something?",
  str_homestory_chat_20324002 = "Yes, an eye mask!",
  str_homestory_chat_20324003 = "An eye patch?",
  str_homestory_chat_20324004 = "I'm always wearing this eye patch. I think I'm getting sick of it.",
  str_homestory_chat_20324005 = "Lady Victoria doesn't seem to be talking to me often recently. It must be because she's sick of it as well.",
  str_homestory_chat_20324006 = "What color and style are you looking for in your new eye patch?",
  str_homestory_chat_20324007 = "White? Red? Heart-shaped? Should it have lace edges?",
  str_homestory_chat_20324008 = "Well...",
  str_homestory_chat_20324009 = "I think I'm asking the wrong person. Maybe I should ask Vice?",
  str_homestory_chat_20324010 = "She's...",
  str_homestory_chat_20324011 = "Oh, you think there's something wrong with her? I'll note that down first, hehe.",
  str_homestory_chat_20324012 = "Don't!",
  str_homestory_chat_20325001 = "You want to train?",
  str_homestory_chat_20325002 = "Yes, I feel like I've been here for too long recently. My interrogation skills feel rusty.",
  str_homestory_chat_20325003 = "You don't really need to practice that...",
  str_homestory_chat_20325004 = "No way! That's the only thing I love doing, I mean, it's what I do best.",
  str_homestory_chat_20325005 = "Just be honest and tell me that you want to interrogate something. But it's a pity you can't do that here.",
  str_homestory_chat_20325006 = "You can't do that to me!",
  str_homestory_chat_20325007 = "Since you're in Cloud Gardens, you might as well enjoy life here...",
  str_homestory_chat_20325008 = "Enjoy... I enjoy interrogation though.",
  str_homestory_chat_20325009 = "How about... I practice on the Chubbs? They look so white and plump.",
  str_homestory_chat_20325010 = "Absolutely not! Never!",
  str_homestory_chat_20326001 = "Dormitory...",
  str_homestory_chat_20326002 = "How did you find out? I only mentioned it once and you just heard about it.",
  str_homestory_chat_20326003 = "But it saves me the trouble of coming to you since you're asking. I want to build a dormitory. What do you think?",
  str_homestory_chat_20326004 = "Why?",
  str_homestory_chat_20326005 = "Don't ask me why yet. Just tell me whether you agree or not.",
  str_homestory_chat_20326006 = "No way! You must tell me your intentions first.",
  str_homestory_chat_20326007 = "No...",
  str_homestory_chat_20326008 = "Ah? Why are you saying no before asking me anything?",
  str_homestory_chat_20326009 = "I have a feeling that there's something wrong about it. Why do you want to build one?",
  str_homestory_chat_20326010 = "Well, I want to build it for Lady Victoria.",
  str_homestory_chat_20326011 = "I don't feel good whenever I see her living in the same dormitory with the others.",
  str_homestory_chat_20326012 = "She's THE Lady Victoria!",
  str_homestory_chat_20326013 = "L-Let me think it over.",
  str_homestory_chat_19399999 = "Hello, young man.",
  str_homestory_chat_19301001 = "Hi, Migard.",
  str_homestory_chat_19301002 = "Finally you've decided to offer yourself for my anatomy?",
  str_homestory_chat_19301003 = "No! Never!",
  str_homestory_chat_19301004 = "Well, think about it some more.",
  str_homestory_chat_19321001 = "Have a minute?",
  str_homestory_chat_19321002 = "Sure, young man. What would you like to talk?",
  str_homestory_chat_19321003 = "It's better be something fun. I'm not in the mood for trivial matters.",
  str_homestory_chat_19321004 = "Ah... What should I do?",
  str_homestory_chat_19321005 = "Whatever you are about to say, run it by your heart first and see if it's funny.",
  str_homestory_chat_19321006 = "...",
  str_homestory_chat_19321007 = "I decide to not say anything.",
  str_homestory_chat_19321008 = "Hmm. Excellent.",
  str_homestory_chat_19322001 = "How are you getting along here?",
  str_homestory_chat_19322002 = "It's very comfortable here but quite boring at times.",
  str_homestory_chat_19322003 = "I wish I could get some drinks.",
  str_homestory_chat_19322004 = "We've got lots of drinks here...",
  str_homestory_chat_19322005 = "Sadly, none of them are to my liking.",
  str_homestory_chat_19322006 = "Don't we have drinks here?",
  str_homestory_chat_19322007 = "I'm not a picky drinker by any standard.",
  str_homestory_chat_19322008 = "But seriously, I can't think of anything good about these drinks.",
  str_homestory_chat_19322009 = "How about I make a list and you place an order?",
  str_homestory_chat_19322010 = "Sure.",
  str_homestory_chat_19323001 = "What's the plan for today?",
  str_homestory_chat_19323002 = "It's a perfect sleeping day, don't you think?",
  str_homestory_chat_19323003 = "Not really...",
  str_homestory_chat_19323004 = "With so many things left to do, I don't know how you can sleep like that.",
  str_homestory_chat_19323005 = "Have a lovely busy day. I'm going to bed.",
  str_homestory_chat_19323006 = "Yes.",
  str_homestory_chat_19323007 = "I can never get enough sleep.",
  str_homestory_chat_19323008 = "Same here.",
  str_homestory_chat_19323009 = "Come on. Time for bed.",
  str_homestory_chat_19323010 = "... Wait! I got things to do!",
  str_homestory_chat_19799999 = "Hello, PlayerName.",
  str_homestory_chat_19701001 = "Hi.",
  str_homestory_chat_19701002 = "Are you sick?",
  str_homestory_chat_19701003 = "... Nope. Why did you ask?",
  str_homestory_chat_19701004 = "If someone asks me this question, more likely than not he's here seeking treatment.",
  str_homestory_chat_19721001 = "You are very clean.",
  str_homestory_chat_19721002 = "I can share my procedure of washing hands here if needed.",
  str_homestory_chat_19721003 = "Great!",
  str_homestory_chat_19721004 = "This way we can reduce the potential spread of diseases.",
  str_homestory_chat_19721005 = "That's right. However, you must strictly follow my method.",
  str_homestory_chat_19721006 = "Wash thoroughly for five minutes.",
  str_homestory_chat_19721007 = "... Ah...",
  str_homestory_chat_19721008 = "I don't think that's necessary...",
  str_homestory_chat_19721009 = "Not everyone has five minutes to spend on washing hands...",
  str_homestory_chat_19721010 = "... Have you paid any attention when I wash my hands?",
  str_homestory_chat_19722001 = "Do you dislike the sunshine?",
  str_homestory_chat_19722002 = "It's a bit too bright.",
  str_homestory_chat_19722003 = "Precisely speaking, I don't particularly dislike the sunshine...",
  str_homestory_chat_19722004 = "I'm not a fan of any overly bright light.",
  str_homestory_chat_19722005 = "I can put up with the sun easily on a cloudy day.",
  str_homestory_chat_19722006 = "I see.",
  str_homestory_chat_19723001 = "Your clothes...",
  str_homestory_chat_19723002 = "I heard there were several complaints about my fashion style?",
  str_homestory_chat_19723003 = "That's correct...",
  str_homestory_chat_19723004 = "... Hmm. Why do they care what clothes I'm wearing?",
  str_homestory_chat_19723005 = "Maybe they are just tired of their clothing?",
  str_homestory_chat_19723006 = "What do you want?",
  str_homestory_chat_19723007 = "My ice blade is very sharp.",
  str_homestory_chat_19723008 = "Don't do it!",
  str_homestory_chat_12499999 = "Hi! How are you?",
  str_homestory_chat_12401001 = "Hello, Curo.",
  str_homestory_chat_12401002 = "Where is Benny?",
  str_homestory_chat_12401003 = "I was just about to ask you.",
  str_homestory_chat_12401004 = "Oh...",
  str_homestory_chat_12421001 = "What are you looking for?",
  str_homestory_chat_12421002 = "Have you seen Benny?",
  str_homestory_chat_12421003 = "Why are you looking for her?",
  str_homestory_chat_12421004 = "She challenged me to a fight.",
  str_homestory_chat_12421005 = "Not here, please!",
  str_homestory_chat_12421006 = "It's okay. You can be our referee.",
  str_homestory_chat_12421007 = "Absolutely not! Fistfight is not allowed here!",
  str_homestory_chat_12422001 = "Looking for me?",
  str_homestory_chat_12422002 = "Yes. If you see Benny, tell her to shut up.",
  str_homestory_chat_12422003 = "Err... That's tricky.",
  str_homestory_chat_12422004 = "She talks very fast. I can't get in a word at all.",
  str_homestory_chat_12422005 = "Why don't you speak to Benny directly?",
  str_homestory_chat_12422006 = "I don't want to waste my breath.",
  str_homestory_chat_12422007 = "... Okay.",
  str_homestory_chat_12423001 = "Going back to rest?",
  str_homestory_chat_12423002 = "Benny is already bad. She ate too much.",
  str_homestory_chat_12423003 = "I'm staying for a bit longer.",
  str_homestory_chat_12423004 = "It's not my style to go to bed early.",
  str_homestory_chat_19899999 = "PlayerName, good to see you again today.",
  str_homestory_chat_19801001 = "Hi, Cuscuta.",
  str_homestory_chat_19801002 = "How's life treating you here?",
  str_homestory_chat_19801003 = "I'm getting along just fine.",
  str_homestory_chat_19801004 = "I can't imagine how I would feel if I couldn't adapt to the new environment.",
  str_homestory_chat_19821001 = "Is there something you want to say?",
  str_homestory_chat_19821002 = "I believe one must develop feelings to express feelings.",
  str_homestory_chat_19821003 = "But I... It's hard for me to have emotions.",
  str_homestory_chat_19821004 = "Some called me a good listener.",
  str_homestory_chat_19821005 = "Feel free to tell me anything. You won't be judged in any way.",
  str_homestory_chat_19821006 = "I see...",
  str_homestory_chat_19822001 = "What's on your mind?",
  str_homestory_chat_19822002 = "It's been a while since I last saw a black rose blooming.",
  str_homestory_chat_19822003 = "That sounds lovely.",
  str_homestory_chat_19822004 = "I guess so for many of us.",
  str_homestory_chat_19822005 = "After all, those are corpse blossoms.",
  str_homestory_chat_19822006 = "Is it a bad omen?",
  str_homestory_chat_19822007 = "That I don't know.",
  str_homestory_chat_19822008 = "But black roses only bloom on corpses.",
  str_homestory_chat_19822009 = "I can get you some if you are interested.",
  str_homestory_chat_19822010 = "Uh, that won't be necessary...",
  str_homestory_chat_19823001 = "What food do you like?",
  str_homestory_chat_19823002 = "I can't think of any. I'm not picky.",
  str_homestory_chat_19823003 = "It's actually hard for me to tell if a food is tasty...",
  str_homestory_chat_19823004 = "I also have no idea if a food is to your liking.",
  str_homestory_chat_19823005 = "Hmm... Maybe I should taste it for you next time.",
  str_homestory_chat_19823006 = "Sure... As long as you don't mind the risk of me mistaking salt for sugar.",
  str_homestory_chat_19823007 = "Uhh...",
  str_homestory_chat_19999999 = "Hello, PlayerName.",
  str_homestory_chat_19921001 = "How do you feel today?",
  str_homestory_chat_19921002 = "Don't worry about me. The black thorns on my body are not growing.",
  str_homestory_chat_19922001 = "What's on your mind?",
  str_homestory_chat_19922002 = "I wonder if little animals here would get close to me...",
  str_homestory_chat_19922003 = "You like animals?",
  str_homestory_chat_19922004 = "Yes... I love having their company.",
  str_homestory_chat_19922005 = "But now... These black thorns on me are keeping people and animals from approaching.",
  str_homestory_chat_19922006 = "Little animals don't come to you?",
  str_homestory_chat_19922007 = "They used to but not since I got these black thorns...",
  str_homestory_chat_19922008 = "Sometimes, I'm also concerned about hurting them...",
  str_homestory_chat_19922009 = "I see...",
  str_homestory_chat_19923001 = "Need my help?",
  str_homestory_chat_19923002 = "PlayerName, could you please help check my shirt?",
  str_homestory_chat_19923003 = "What's the matter?",
  str_homestory_chat_19923004 = "I'm afraid my black thorns have torn it again.",
  str_homestory_chat_19923005 = "Nope.",
  str_homestory_chat_19923006 = "That's great!",
  str_homestory_chat_19923007 = "I don't need to order another one!",
  str_homestory_chat_19923008 = "True...",
  str_homestory_chat_19923009 = "But it's tiny. You can barely see it.",
  str_homestory_chat_19923010 = "In this case... I don't have to retire this shirt yet.",
  str_homestory_chat_19923011 = "Thank you, PlayerName.",
  str_homestory_chat_19924001 = "Do you have a keen interest in music?",
  str_homestory_chat_19924002 = "Yes.",
  str_homestory_chat_19924003 = "Many people here can sing and play instruments.",
  str_homestory_chat_19924004 = "I'd love to make friends with them...",
  str_homestory_chat_19924005 = "Easy. I'll introduce you to some friends who play music. What do you say?",
  str_homestory_chat_19924006 = "You are the best, PlayerName! Thank you.",
  str_homestory_chat_20099999 = "I heard your greeting, Snowball.",
  str_homestory_chat_20001001 = "Yes, Sikare.",
  str_homestory_chat_20001002 = "Is there something you want to tell me?",
  str_homestory_chat_20001003 = "Not right now.",
  str_homestory_chat_20021001 = "Did someone disturb you?",
  str_homestory_chat_20021002 = "No one purposely. I wish this place...",
  str_homestory_chat_20021003 = "Could be quieter.",
  str_homestory_chat_20021004 = "With nothing but the sound of the wind and insects. Evening should be peaceful, don't you think?",
  str_homestory_chat_20022001 = "You want to see me?",
  str_homestory_chat_20022002 = "Snowball, could you find me more old books?",
  str_homestory_chat_20022003 = "With pleasure!",
  str_homestory_chat_20022004 = "That makes me happy.",
  str_homestory_chat_20022005 = "Okay, stop staring. Get going. Bring them to me.",
  str_homestory_chat_20022006 = "I can't find any more...",
  str_homestory_chat_20022007 = "... Do I have to listen to those noisy Blockheads?",
  str_homestory_chat_20022008 = "Okay, I'll see what I can do.",
  str_homestory_chat_20022009 = "That's my Snowball.",
  str_homestory_chat_20023001 = "Your veil...",
  str_homestory_chat_20023002 = "Snowball, quit staring at my veil, would you?",
  str_homestory_chat_20023003 = "Why not change them?",
  str_homestory_chat_20023004 = "These black veils look troublesome.",
  str_homestory_chat_20023005 = "Quite the opposite. I really like these black ones.",
  str_homestory_chat_20023006 = "They help keep those noisy paramecias out of my world.",
  str_homestory_chat_20023007 = "However, I'm more than happy to lift my veil for you.",
  str_homestory_chat_20024001 = "Got a question for me?",
  str_homestory_chat_20024002 = "Yeah. I'd like to know if there are any hiding spots.",
  str_homestory_chat_20024003 = "There are.",
  str_homestory_chat_20024004 = "Such as the riverside, hollow trees, and underground caves.",
  str_homestory_chat_20024005 = "They aren't safe, though. Someone would find them eventually.",
  str_homestory_chat_20024006 = "Nope.",
  str_homestory_chat_20024007 = "Some spots are more remote than others, but the Chubbs have probably found them all.",
  str_homestory_chat_20024008 = "I see.",
  str_homestory_chat_20024009 = "Why are you looking for one? Do you want to hide something?",
  str_homestory_chat_20024010 = "Yes, to hide Faria. I don't want to lose it again.",
  str_homestory_chat_20024011 = "Perhaps it's safest to leave it here with you?",
  str_homestory_chat_20024012 = "No, can't do that...",
  str_homestory_chat_20025001 = "Something on your mind?",
  str_homestory_chat_20025002 = "I'm contemplating your purpose.",
  str_homestory_chat_20025003 = "Purpose?",
  str_homestory_chat_20025004 = "You won't be here for the rest of your life. You must move on eventually.",
  str_homestory_chat_20025005 = "I haven't thought that far yet.",
  str_homestory_chat_20025006 = "You probably should sometimes. This is just a stop, after all.",
  str_homestory_chat_20025007 = "I can sense you have a long future full of possibilities ahead.",
  str_homestory_chat_20025008 = "That's... some serious stuff from you.",
  str_homestory_chat_20025009 = "Yes. And when the time comes, I can watch over this place for you.",
  str_homestory_chat_20025010 = "Just like how I guarded the Crypt before.",
  str_homestory_chat_20025011 = "Right... Thanks.",
  str_homestory_chat_18799999 = "No need to greet me. Say what you gotta say.",
  str_homestory_chat_18701001 = "Ah... Okay...",
  str_homestory_chat_18701002 = "Greeting is a waste of time.",
  str_homestory_chat_18701003 = "Hmm... What was I saying?",
  str_homestory_chat_18721001 = "What are you looking for?",
  str_homestory_chat_18721002 = "Don't we have traditional operas to watch here?",
  str_homestory_chat_18721003 = "No...",
  str_homestory_chat_18721004 = "Sadly, traditional operas are often considered old fashioned.",
  str_homestory_chat_18721005 = "I don't think we have much an interest here.",
  str_homestory_chat_18721006 = "Never mind. I'll find myself something else to do.",
  str_homestory_chat_18721007 = "I can organize one.",
  str_homestory_chat_18721008 = "You amaze me all the time.",
  str_homestory_chat_18721009 = "It's not cheap to set up the scene and get professional actors.",
  str_homestory_chat_18721010 = "And I don't think we will have a large audience here.",
  str_homestory_chat_18721011 = "Are you serious about this?",
  str_homestory_chat_18721012 = "Of course.",
  str_homestory_chat_18721013 = "I'll wait for the show patiently.",
  str_homestory_chat_18722001 = "You are practicing?",
  str_homestory_chat_18722002 = "PlayerName, do you play dart?",
  str_homestory_chat_18722003 = "Yes!",
  str_homestory_chat_18722004 = "Oh? Glad to hear.",
  str_homestory_chat_18722005 = "Come and join me.",
  str_homestory_chat_18722006 = "Now?",
  str_homestory_chat_18722007 = "You have things to do? Next time then.",
  str_homestory_chat_18722008 = "Sure.",
  str_homestory_chat_18722009 = "Never...",
  str_homestory_chat_18722010 = "That's okay. You can hold the board for me.",
  str_homestory_chat_18722011 = "... Am I allowed to say no?",
  str_homestory_chat_18722012 = "What's the matter? You are scared of my darts?",
  str_homestory_chat_18723001 = "Relax.",
  str_homestory_chat_18723002 = "It's safe here. You don't have to be on alert at all times.",
  str_homestory_chat_18723003 = "I've come here upon your invitation. Now it's my duty to protect the civilian.",
  str_homestory_chat_18723004 = "Thank you for your service.",
  str_homestory_chat_18723005 = "You are very welcome. The blue blood comes with great responsibilities.",
  str_homestory_chat_18723006 = "Although everyone is equal here...",
  str_homestory_chat_18723007 = "My strength is still part of my identity.",
  str_homestory_chat_15699999 = "How's your day, kid?",
  str_homestory_chat_15601001 = "Pretty good!",
  str_homestory_chat_15601002 = "That's lovely.",
  str_homestory_chat_15621001 = "What are you thinking?",
  str_homestory_chat_15621002 = "A night like this is perfect for meditation.",
  str_homestory_chat_15621003 = "Would you like to try?",
  str_homestory_chat_15621004 = "Sure!",
  str_homestory_chat_15621005 = "I'll pick a quiet spot for you.",
  str_homestory_chat_15621006 = "Don't forget our promise.",
  str_homestory_chat_15621007 = "I'll pass...",
  str_homestory_chat_15621008 = "You're scared?",
  str_homestory_chat_15621009 = "Don't worry. Nothing can harm you here.",
  str_homestory_chat_15622001 = "How are you getting along here?",
  str_homestory_chat_15622002 = "To my surprise, I like it better than the Northland...",
  str_homestory_chat_15622003 = "I can't believe I have settled down here.",
  str_homestory_chat_15622004 = "Not too long ago, settling down seemed so far away from me.",
  str_homestory_chat_15622005 = "That's good...",
  str_homestory_chat_15622006 = "To be honest, I prefer this mild weather.",
  str_homestory_chat_15622007 = "The Northland is too cold and harsh...",
  str_homestory_chat_15622008 = "That's a relief.",
  str_homestory_chat_19599999 = "Greetings, sir! Is there anything I can do for you?",
  str_homestory_chat_19501001 = "Not at the moment.",
  str_homestory_chat_19501002 = "Anything within my power... I'll give it my absolute best.",
  str_homestory_chat_19501003 = "I appreciate.",
  str_homestory_chat_19521001 = "What's that in your hand?",
  str_homestory_chat_19521002 = "Wild fruits, sir.",
  str_homestory_chat_19521003 = "I found a lot in the woods lately.",
  str_homestory_chat_19521004 = "Would you like to have a look?",
  str_homestory_chat_19521005 = "Sure!",
  str_homestory_chat_19521006 = "But I have some other things to take care of...",
  str_homestory_chat_19521007 = "I'll leave you to it, sir.",
  str_homestory_chat_19521008 = "We can go when you are free.",
  str_homestory_chat_19521009 = "Not really...",
  str_homestory_chat_19521010 = "No problem. I can bring some back for you.",
  str_homestory_chat_19521011 = "That would be fantastic! Thank you.",
  str_homestory_chat_19522001 = "How are you settling?",
  str_homestory_chat_19522002 = "The cave is very comfortable. I've placed many things inside.",
  str_homestory_chat_19522003 = "I'm happy to give you a tour whenever you have time.",
  str_homestory_chat_19522004 = "You prefer staying in a cave?",
  str_homestory_chat_19522005 = "Yes, I do. But most Aurorians don't like the gloomy and humid environment.",
  str_homestory_chat_19522006 = "Maybe you don't mind it.",
  str_homestory_chat_16299999 = "Hi, PlayerName. Pleased to see you.",
  str_homestory_chat_16201001 = "What's your plan for the day?",
  str_homestory_chat_16201002 = "I might take a walk in the forest.",
  str_homestory_chat_16221001 = "You seem to like it here.",
  str_homestory_chat_16221002 = "Thank you, PlayerName, for inviting me here.",
  str_homestory_chat_16221003 = "I've made many friends since I arrived.",
  str_homestory_chat_16221004 = "Good to know.",
  str_homestory_chat_16221005 = "It doesn't matter where we stay as long as we have truthful friends around.",
  str_homestory_chat_16221006 = "That said, life here is very comfortable and relaxing.",
  str_homestory_chat_16222001 = "Having questions to ask?",
  str_homestory_chat_16222002 = "Do you mind if I grow some more vines in the room?",
  str_homestory_chat_16222003 = "Not at all.",
  str_homestory_chat_16222004 = "Any particular type you have in mind? I can help you search.",
  str_homestory_chat_16222005 = "Thank you very much. Your approval is already a big help.",
  str_homestory_chat_16222006 = "I don't think that's a good idea...",
  str_homestory_chat_16222007 = "Ah, I see...",
  str_homestory_chat_16222008 = "What if I grow them in pots?",
  str_homestory_chat_16223001 = "Was this simply spontaneous?",
  str_homestory_chat_16223002 = "Yes, every time I come here, I cannot help but marvel at this place's advantages.",
  str_homestory_chat_16223003 = "Advantages?",
  str_homestory_chat_16223004 = "It's secluded, safe, with a pleasant climate and ample water and grass.",
  str_homestory_chat_16223005 = "If there were such a place in Northland... that would be great.",
  str_homestory_chat_16223006 = "Wasn't the place you used to stand guard, Windward Forest, just like that?",
  str_homestory_chat_16223007 = "I remember it being a particularly nice part of Northland.",
  str_homestory_chat_16223008 = "However, that's only compared to other parts of Northland. I still think Cloud Gardens is better.",
  str_homestory_chat_16223009 = "Sometimes, I even wonder if I were to become the guardian of this place...",
  str_homestory_chat_16223010 = "I'm afraid things would be much easier, and I'd also have time to think about some of my own problems.",
  str_homestory_chat_16223011 = "You're in Cloud Gardens now, you don't have to worry about things like standing guard.",
  str_homestory_chat_16223012 = "You can just take some time to reflect and relax.",
  str_homestory_chat_16223013 = "Indeed. Thank you very much for the invitation.",
  str_homestory_chat_16223014 = "Don't mention it.",
  str_homestory_chat_16224001 = "Water?",
  str_homestory_chat_16224002 = "Yes. May I ask, do you understand water, Navigator?",
  str_homestory_chat_16224003 = "I understand water.",
  str_homestory_chat_16224004 = "So what about the bubble Leah made? Do you know what it means?",
  str_homestory_chat_16224005 = "Erm... I really have no idea.",
  str_homestory_chat_16224006 = "I don't understand.",
  str_homestory_chat_16224007 = "Ah... So if I wish to know about Leah's bubble, I'll have to ask someone else.",
  str_homestory_chat_16224008 = "But why do you want to know about that bubble all of a sudden?",
  str_homestory_chat_16224009 = "I find it very interesting, much like the dew in the forest after being exposed to sunlight.",
  str_homestory_chat_16224010 = "Right.",
  str_homestory_chat_16224011 = "I once found a seed in a drop of dew. It had probably been blown there by the wind.",
  str_homestory_chat_16224012 = "These seeds usually look turquoise, or brown, or even black.",
  str_homestory_chat_16224013 = "What I'm trying to say is that it seemed to have a certain natural aura. Do you understand, Navigator?",
  str_homestory_chat_16224014 = "Yes.",
  str_homestory_chat_16224015 = "But the seed I saw looked like an emerald in the sunlight.",
  str_homestory_chat_16224016 = "Water... is miraculous, just like Leah.",
  str_homestory_chat_16224017 = "I see...",
  str_homestory_chat_16225001 = "Swordsmanship teacher?",
  str_homestory_chat_16225002 = "A trainer, to be precise.",
  str_homestory_chat_16225003 = "My father once said that if you want to improve your swordsmanship, you need a trainer.",
  str_homestory_chat_16225004 = "It's just like how certain vines need other trees to help them grow.",
  str_homestory_chat_16225005 = "So, what kind of trainer do you want?",
  str_homestory_chat_16225006 = "Someone whose swordsmanship is at the same level as mine. Is there anyone like that in Cloud Gardens right now?",
  str_homestory_chat_16225007 = "Yes",
  str_homestory_chat_16225008 = "There should be a lot of potential candidates. Lumopolis and Illumina both have quite a few...",
  str_homestory_chat_16225009 = "No",
  str_homestory_chat_16225010 = "Is battle training okay too? There's no need for you to aim so high.",
  str_homestory_chat_16225011 = "It should be okay...",
  str_homestory_chat_16225012 = "But why did you suddenly want to improve your swordsmanship?",
  str_homestory_chat_16225013 = "If it's just daily training, you can do it by yourself and enjoy a more laid-back life in Cloud Gardens.",
  str_homestory_chat_16225014 = "That makes sense...",
  str_homestory_chat_20199999 = "Greetings, PlayerName!",
  str_homestory_chat_20101001 = "Hi, Ansia.",
  str_homestory_chat_20101002 = "What message would you like to send today?",
  str_homestory_chat_20101003 = "Nothing. Just wanted to say hi.",
  str_homestory_chat_20101004 = "I see...",
  str_homestory_chat_20121001 = "What a relaxing day!",
  str_homestory_chat_20121002 = "Right... PlayerName, you better be careful walking.",
  str_homestory_chat_20121003 = "How come?",
  str_homestory_chat_20121004 = "Because I tend to pull pranks when I don't have much to do.",
  str_homestory_chat_20121005 = "It could be a trap or a sticker...",
  str_homestory_chat_20121006 = "Just watch out.",
  str_homestory_chat_20121007 = "... I don't know if I should take any step today!",
  str_homestory_chat_20122001 = "Today's messages...",
  str_homestory_chat_20122002 = "I've put together for you!",
  str_homestory_chat_20122003 = "Please give order!",
  str_homestory_chat_20122004 = "I'll have a listen.",
  str_homestory_chat_20122005 = "Should I read it for you?",
  str_homestory_chat_20122006 = "That won't be necessary. Just send them to my Terminal.",
  str_homestory_chat_20122007 = "Wait a second...",
  str_homestory_chat_20122008 = "I'm kind of busy right now. Could you please send these messages to my Terminal?",
  str_homestory_chat_20122009 = "No problem!",
  str_homestory_chat_20123001 = "You're in a good mood today!",
  str_homestory_chat_20123002 = "Yes, because I figured out a new way to communicate.",
  str_homestory_chat_20123003 = "With pigeons! I bet you've never seen it before.",
  str_homestory_chat_20123004 = "How?",
  str_homestory_chat_20123005 = "Send messages with them?",
  str_homestory_chat_20123006 = "No, that's too simple.",
  str_homestory_chat_20123007 = "Tie a speaker and a walkie-talkie to the pigeon, and the sound will play from the sky!",
  str_homestory_chat_20123008 = "It'd be very effective.",
  str_homestory_chat_20123009 = "I don't think a pigeon can fly with a load that heavy...",
  str_homestory_chat_20123010 = "You might be right. Should we try another Aurorian? Like Dove?",
  str_homestory_chat_20123011 = "I doubt she'd be willing.",
  str_homestory_chat_20299999 = "Hello!",
  str_homestory_chat_20201001 = "Hi, Tessa.",
  str_homestory_chat_20201002 = "It's a beautiful day.",
  str_homestory_chat_20201003 = "Yes.",
  str_homestory_chat_20221001 = "Wanna chat?",
  str_homestory_chat_20221002 = "Don't you find all conversations end with complaints?",
  str_homestory_chat_20221003 = "I think you are right...",
  str_homestory_chat_20221004 = "I rarely chat with people.",
  str_homestory_chat_20221005 = "I don't like to hear people complain.",
  str_homestory_chat_20221006 = "Maybe I just don't have much to complain about myself.",
  str_homestory_chat_20221007 = "I can't agree with you.",
  str_homestory_chat_20221008 = "People share feelings when they talk, even if the whole conversation is made up of complaints.",
  str_homestory_chat_20221009 = "You might be right.",
  str_homestory_chat_20221010 = "Still, I don't like to hear complaints.",
  str_homestory_chat_20222001 = "What are you eating?",
  str_homestory_chat_20222002 = "A candy from Vice. It tastes pretty good.",
  str_homestory_chat_20222003 = "Would you like to try?",
  str_homestory_chat_20222004 = "Yes, please!",
  str_homestory_chat_20222005 = "Hmm... I've finished them all.",
  str_homestory_chat_20222006 = "Wait here. I'll go and get some for you.",
  str_homestory_chat_20222007 = "Okay.",
  str_homestory_chat_20222008 = "Thank you but no...",
  str_homestory_chat_20222009 = "Hmm... I don't have any left anyway.",
  str_homestory_chat_20222010 = "It saves me a trip.",
  str_homestory_chat_20223001 = "How are you adjusting to the new life?",
  str_homestory_chat_20223002 = "Really well. It's better than Umbraton.",
  str_homestory_chat_20223003 = "So you like it here?",
  str_homestory_chat_20223004 = "Very much. I feel completely at home here.",
  str_homestory_chat_20223005 = "Not many places left on this continent where you can feel free.",
  str_homestory_chat_20223006 = "Don't you like Umbraton?",
  str_homestory_chat_20223007 = "It's not that I don't like it there.",
  str_homestory_chat_20223008 = "But the disorder and confusion upsets me at times.",
  str_homestory_chat_20223009 = "Anyway, here is better.",
  str_homestory_chat_19499999 = "Hmm...",
  str_homestory_chat_19401001 = "Hello, Leah.",
  str_homestory_chat_19401002 = "... Did you just greet me?",
  str_homestory_chat_19401003 = "Sorry, I didn't hear you. I guess I was in a trance...",
  str_homestory_chat_19401004 = "It's okay.",
  str_homestory_chat_19421001 = "What are you thinking?",
  str_homestory_chat_19421002 = "This is the first real spring for me...",
  str_homestory_chat_19421003 = "You've never had a spring before?",
  str_homestory_chat_19421004 = "Hmm... The Northland is always covered with ice and snow.",
  str_homestory_chat_19421005 = "Some other places have spring all year round...",
  str_homestory_chat_19421006 = "I don't think it's a proper spring when there is no summer to follow...",
  str_homestory_chat_19421007 = "You have a point.",
  str_homestory_chat_19422001 = "What are you doing?",
  str_homestory_chat_19422002 = "I'm on patrol... Is it not needed?",
  str_homestory_chat_19422003 = "You don't have to patrol here.",
  str_homestory_chat_19422004 = "Really? But I'm used to going on patrol every day.",
  str_homestory_chat_19422005 = "I'll take a break then.",
  str_homestory_chat_19422006 = "Ah! Thank you!",
  str_homestory_chat_19422007 = "You're very welcome... Going on patrol has become a habit of mine.",
  str_homestory_chat_19422008 = "I'm happy to do this for you...",
  str_homestory_chat_20799999 = "Yes.",
  str_homestory_chat_20701001 = "Hi.",
  str_homestory_chat_20701002 = "Are you about to start today's training?",
  str_homestory_chat_20701003 = "Yes, please leave me.",
  str_homestory_chat_20701004 = "Okay.",
  str_homestory_chat_20721001 = "Can we chat a bit?",
  str_homestory_chat_20721002 = "... I got things to do.",
  str_homestory_chat_20721003 = "... I see.",
  str_homestory_chat_20899999 = "... Don't come too close.",
  str_homestory_chat_20801001 = "Okay.",
  str_homestory_chat_20801002 = "Please move away slowly.",
  str_homestory_chat_20801003 = "Ah... As you wish.",
  str_homestory_chat_20821001 = "What's your plan for the day?",
  str_homestory_chat_20821002 = "... Nothing much.",
  str_homestory_chat_20821003 = "Remember. Don't get too close to me. Not safe.",
  str_homestory_chat_20821004 = "You got it...",
  str_homestory_chat_20999999 = "...",
  str_homestory_chat_20901001 = "Hello.",
  str_homestory_chat_20901002 = "Hi, there.",
  str_homestory_chat_20901003 = "Didn't think you would wave back.",
  str_homestory_chat_20921001 = "Do you mind talking about your past?",
  str_homestory_chat_20921002 = "... Hmm... Not now...",
  str_homestory_chat_20921003 = "I see...",
  str_homestory_chat_21099999 = "Hello.",
  str_homestory_chat_21001001 = "Good day to you.",
  str_homestory_chat_21001002 = "You look happy today.",
  str_homestory_chat_21001003 = "A rare occasion.",
  str_homestory_chat_21021001 = "How are you getting along here?",
  str_homestory_chat_21021002 = "... Hmm... Not bad.",
  str_homestory_chat_21021003 = "Please let me know if you need anything.",
  str_homestory_chat_21021004 = "... I will.",
  str_homestory_chat_16799999 = "Hello, PlayerName.",
  str_homestory_chat_16701001 = "Hi, Alice.",
  str_homestory_chat_16701002 = "Any new story book?",
  str_homestory_chat_16701003 = "Ah, sorry. I haven't found any.",
  str_homestory_chat_16701004 = "No rush. Come and play with me.",
  str_homestory_chat_16721001 = "You have a question for me?",
  str_homestory_chat_16721002 = "Would anyone here transform into a rabbit?",
  str_homestory_chat_16721003 = "I don't think so...",
  str_homestory_chat_16721004 = "Hmm... I heard some rabbit here can turn into a man...",
  str_homestory_chat_16721005 = "Never mind then...",
  str_homestory_chat_16721006 = "I guess so...",
  str_homestory_chat_16721007 = "Where? Could you show me?",
  str_homestory_chat_16721008 = "Hahah. Look around carefully and you'll find it.",
  str_homestory_chat_16722001 = "Your ears...",
  str_homestory_chat_16722002 = "Huh, my ears are liked by many here!",
  str_homestory_chat_16722003 = "Aren't you troubled by this?",
  str_homestory_chat_16722004 = "Why would I?",
  str_homestory_chat_16722005 = "Isn't it a good thing to be liked?",
  str_homestory_chat_16722006 = "It's no big deal to have my ears stroked.",
  str_homestory_chat_16723001 = "What are you looking for?",
  str_homestory_chat_16723002 = "Are there little elves living in the grass?",
  str_homestory_chat_16723003 = "Possible...",
  str_homestory_chat_16723004 = "Would you help me look for them?",
  str_homestory_chat_16723005 = "Hmm... Don't worry if you are busy. Next time!",
  str_homestory_chat_16723006 = "I wouldn't think so.",
  str_homestory_chat_16723007 = "No elves... There must be goblins then!",
  str_homestory_chat_16723008 = "I'll find them.",
  str_homestory_chat_13099999 = "PlayerName, good to see you again!",
  str_homestory_chat_13001001 = "Hi, Sinsa.",
  str_homestory_chat_13001002 = "I see you strolling up and down here all day long.",
  str_homestory_chat_13001003 = "... I've been busy.",
  str_homestory_chat_13021001 = "What are you up to?",
  str_homestory_chat_13021002 = "PlayerName, is there any trash to pick up?",
  str_homestory_chat_13021003 = "Why do you want to pick trash?",
  str_homestory_chat_13021004 = "What kind of question is this? Because there's often good stuff awaiting to be discovered.",
  str_homestory_chat_13021005 = "Can be sold for money!",
  str_homestory_chat_13021006 = "Oh? Let me know when you find a garbage dump.",
  str_homestory_chat_13021007 = "What trash?",
  str_homestory_chat_13021008 = "Good ones with hidden treasures.",
  str_homestory_chat_13021009 = "Last time, I found a...",
  str_homestory_chat_13021010 = "Component that made an explosion sound and a water filtering device...",
  str_homestory_chat_13021011 = "Sounds like ancient technology?",
  str_homestory_chat_13022001 = "You want to see me?",
  str_homestory_chat_13022002 = "PlayerName, when can we have another drag race?",
  str_homestory_chat_13022003 = "Drag race? Sure!",
  str_homestory_chat_13022004 = "When I'm less busy.",
  str_homestory_chat_13022005 = "Okay. You think about it.",
  str_homestory_chat_13022006 = "We could invite more people...",
  str_homestory_chat_13022007 = "Even those dwelling in odd corners should come out!",
  str_homestory_chat_13022008 = "I'd rather not...",
  str_homestory_chat_13022009 = "My heart is permanently scarred during the last race...",
  str_homestory_chat_13022010 = "Then you must have another one. It will help heal your scar.",
  str_homestory_chat_13023001 = "You look at leisure...",
  str_homestory_chat_13023002 = "That's right! I'm so bored! I haven't robbed any shop for ages!",
  str_homestory_chat_13023003 = "Don't you think about committing robbery here!",
  str_homestory_chat_13023004 = "I know! That's why I'm so cooped up!",
  str_homestory_chat_13023005 = "Don't show off your valuables in front of me...",
  str_homestory_chat_13023006 = "I don't know how much longer I can control myself.",
  str_homestory_chat_20599999 = "Hello, PlayerName.",
  str_homestory_chat_20501001 = "Hi, Eve!",
  str_homestory_chat_20501002 = "Anything fun happened today?",
  str_homestory_chat_20501003 = "Hmm... Let me think.",
  str_homestory_chat_20501004 = "Okay. Tell me everything when you finish thinking!",
  str_homestory_chat_20521001 = "What are you looking for?",
  str_homestory_chat_20521002 = "PlayerName, have you seen my brother?",
  str_homestory_chat_20521003 = "No...",
  str_homestory_chat_20521004 = "Uhh... Where did brother go?",
  str_homestory_chat_20521005 = "Please let me know if you see him!",
  str_homestory_chat_20521006 = "You got it!",
  str_homestory_chat_20521007 = "Over there.",
  str_homestory_chat_20521008 = "Ah! Thank you, PlayerName!",
  str_homestory_chat_20521009 = "Everything's better when brother is around.",
  str_homestory_chat_20522001 = "How are you getting along here?",
  str_homestory_chat_20522002 = "I thought I would miss the Rediesel Desert after some time...",
  str_homestory_chat_20522003 = "But I'm doing great here, even better than I thought I would!",
  str_homestory_chat_20522004 = "That's awesome!",
  str_homestory_chat_20522005 = "I guess all the familiar faces help...",
  str_homestory_chat_20522006 = "And PlayerName's company.",
  str_homestory_chat_20522007 = "I'm very content.",
  str_homestory_chat_20523001 = "What are you thinking?",
  str_homestory_chat_20523002 = "I'd like to try some new clothes...",
  str_homestory_chat_20523003 = "PlayerName, what style should I go for?",
  str_homestory_chat_20523004 = "Resplendent?",
  str_homestory_chat_20523005 = "Resplendent... Would it be very heavy?",
  str_homestory_chat_20523006 = "Since it's PlayerName's advise... I'll give it some serious thought!",
  str_homestory_chat_20523007 = "Handsome?",
  str_homestory_chat_20523008 = "Ah huh! PlayerName thinks I can handle a handsome outfit?",
  str_homestory_chat_20523009 = "I'll give it a try!",
  str_homestory_chat_20523010 = "Simple clothing would look good on you.",
  str_homestory_chat_20523011 = "Yes, simple dresses will give me more mobility!",
  str_homestory_chat_20523012 = "I'll buy a few casual suits.",
  str_homestory_chat_20524001 = "You got a question to ask?",
  str_homestory_chat_20524002 = "PlayerName, when can we go on a picnic again?",
  str_homestory_chat_20524003 = "Soon!",
  str_homestory_chat_20524004 = "Really?",
  str_homestory_chat_20524005 = "I can't wait!",
  str_homestory_chat_20524006 = "Let me know the date as soon as you decide!",
  str_homestory_chat_20524007 = "I'm not sure...",
  str_homestory_chat_20524008 = "I've been so busy lately...",
  str_homestory_chat_20524009 = "I see... I can help PlayerName.",
  str_homestory_chat_20524010 = "Just let me know!",
  str_homestory_chat_20499999 = "PlayerName?",
  str_homestory_chat_20401001 = "Yes.",
  str_homestory_chat_20401002 = "I heard you.",
  str_homestory_chat_20401003 = "You can tell people apart just by their voices?",
  str_homestory_chat_20401004 = "Every voice is unique. Listen carefully and you will be able to tell the difference.",
  str_homestory_chat_20421001 = "How do you tell it's a cloudy day?",
  str_homestory_chat_20421002 = "By feelings... The weak sunlight on my skin and moist on my hair...",
  str_homestory_chat_20421003 = "However... It's always the same warm and pleasant here...",
  str_homestory_chat_20421004 = "I find it hard to tell an overcast day from a sunny day sometimes.",
  str_homestory_chat_20421005 = "What would you do then?",
  str_homestory_chat_20421006 = "The quickest solution is to ask someone.",
  str_homestory_chat_20422001 = "Can you distinguish between different flowers?",
  str_homestory_chat_20422002 = "By their scent...",
  str_homestory_chat_20422003 = "Of course!",
  str_homestory_chat_20422004 = "I can also picture a flower in my head by gently touching it.",
  str_homestory_chat_20422005 = "This also helps me determine the type of a flower.",
  str_homestory_chat_20422006 = "I can teach you if you are interested.",
  str_homestory_chat_20423001 = "What are you looking for?",
  str_homestory_chat_20423002 = "Do you happen to know where Eve is?",
  str_homestory_chat_20423003 = "Not here...",
  str_homestory_chat_20423004 = "... I don't think I've heard her voice for quite some time.",
  str_homestory_chat_20423005 = "I wonder if she's been taking good care of our dawn flower.",
  str_homestory_chat_20423006 = "Right there.",
  str_homestory_chat_20423007 = "Should I walk you over?",
  str_homestory_chat_20423008 = "No need. I think I hear her already.",
  str_homestory_chat_20423009 = "Thank you, PlayerName.",
  str_homestory_chat_17199999 = "Hello, kid!",
  str_homestory_chat_17101001 = "Hello, Taki.",
  str_homestory_chat_17101002 = "Any new quest for me?",
  str_homestory_chat_17101003 = "No...",
  str_homestory_chat_17101004 = "That's unfortunate. I would give you a discount today.",
  str_homestory_chat_17121001 = "What's up?",
  str_homestory_chat_17121002 = "Kid, you're well informed. Tell me...",
  str_homestory_chat_17121003 = "Have you seen any unusual rock lately?",
  str_homestory_chat_17121004 = "Well informed?",
  str_homestory_chat_17121005 = "Honestly, I can't believe how many friends you have.",
  str_homestory_chat_17121006 = "With all these friends, I bet you get all kinds of information.",
  str_homestory_chat_17121007 = "I don't know about that...",
  str_homestory_chat_17121008 = "Unusual rock?",
  str_homestory_chat_17121009 = "I mean gems.",
  str_homestory_chat_17121010 = "I see... You'll be the first one to know if something comes to my mind.",
  str_homestory_chat_17122001 = "You want to see me?",
  str_homestory_chat_17122002 = "Fancy a drink with me?",
  str_homestory_chat_17122003 = "Sure!",
  str_homestory_chat_17122004 = "That's fast. Let's go!",
  str_homestory_chat_17122005 = "Wait! Like now?",
  str_homestory_chat_17122006 = "Can't do it. Maybe another day...",
  str_homestory_chat_17122007 = "Thank you for the invite but I'll pass...",
  str_homestory_chat_17122008 = "Just one drink... You can have a soft one if you so desire.",
  str_homestory_chat_17122009 = "Or do you have things to do right now?",
  str_homestory_chat_17122010 = "Hmm... What are you up to? If you have too much to handle, send some quest my way...",
  str_homestory_chat_17122011 = "I'll lend you a hand.",
  str_homestory_chat_17123001 = "So you saw it...",
  str_homestory_chat_17123002 = "Yeah, I noticed someone bathing in the river.",
  str_homestory_chat_17123003 = "Hmm... A bunch of fools who know nothing about the real pleasure of life.",
  str_homestory_chat_17123004 = "Why did you say so?",
  str_homestory_chat_17123005 = "Don't you understand? Another one who doesn't know how to enjoy.",
  str_homestory_chat_17123006 = "Never mind. I'll take you to a hot spring one of these days.",
  str_homestory_chat_17123007 = "Then you'll see the art of enjoying.",
  str_homestory_chat_21199999 = "Hello, PlayerName.",
  str_homestory_chat_21101001 = "Hi, Beryl.",
  str_homestory_chat_21101002 = "Haven't seen you for a while.",
  str_homestory_chat_21101003 = "But I see you often.",
  str_homestory_chat_21101004 = "Really? I guess I was zoning out.",
  str_homestory_chat_21121001 = "These crystals...",
  str_homestory_chat_21121002 = "Very heavy.",
  str_homestory_chat_21121003 = "It's been so long but I'm still getting used to them.",
  str_homestory_chat_21121004 = "It must be a pain to walk?",
  str_homestory_chat_21121005 = "Put a few sand bags around your legs and you can have a taste of my life.",
  str_homestory_chat_21121006 = "I wish there was some way to get rid of all these...",
  str_homestory_chat_21122001 = "Wanna chat?",
  str_homestory_chat_21122002 = "I often see you enjoying a conversation with others.",
  str_homestory_chat_21122003 = "Is it really that fun?",
  str_homestory_chat_21122004 = "It's a good way to learn about each other.",
  str_homestory_chat_21122005 = "It feels nice when strangers become familiar!",
  str_homestory_chat_21122006 = "... Is that so? Come chat with me more often then.",
  str_homestory_chat_21122007 = "Communication gives me pleasure.",
  str_homestory_chat_21122008 = "Happiness doubles when you share, and worries halve.",
  str_homestory_chat_21122009 = "... But sometimes I get irritated when people talk to me.",
  str_homestory_chat_21122010 = "They can't learn anything about me.",
  str_homestory_chat_21122011 = "Maybe... You could?",
  str_homestory_chat_21123001 = "Looks like you've settled here.",
  str_homestory_chat_21123002 = "Yes, I can be a picky dweller.",
  str_homestory_chat_21123003 = "Here I feel it's okay to temporarily put aside the painful past.",
  str_homestory_chat_21123004 = "So glad to hear!",
  str_homestory_chat_21123005 = "PlayerName, thank you for inviting me here.",
  str_homestory_chat_21123006 = "Please let me know if I can help you with anything.",
  str_homestory_chat_21299999 = "It's you again!",
  str_homestory_chat_21221001 = "... Hello?",
  str_homestory_chat_21221002 = "Don't take me wrong. It's just that when you keep running into the same person...",
  str_homestory_chat_21221003 = "It gets boring.",
  str_homestory_chat_21222001 = "What are you up to?",
  str_homestory_chat_21222002 = "Nothing much. PlayerName, what do you do for fun?",
  str_homestory_chat_21222003 = "For fun?",
  str_homestory_chat_21222004 = "Anything new and exciting!",
  str_homestory_chat_21222005 = "I play games.",
  str_homestory_chat_21222006 = "Hmm... Racing games are alright. Board games bore me.",
  str_homestory_chat_21222007 = "Fishing?",
  str_homestory_chat_21222008 = "No way! Only if Eclipsites are involved!",
  str_homestory_chat_21222009 = "Running?",
  str_homestory_chat_21222010 = "Like being chased by Eclipsites?",
  str_homestory_chat_21222011 = "...",
  str_homestory_chat_21222012 = "Why did you ask anyway?",
  str_homestory_chat_21222013 = "Nothing is fun here. I'm looking for inspiration.",
  str_homestory_chat_21223001 = "Is something wrong with me?",
  str_homestory_chat_21223002 = "You are wearing these clothes again?",
  str_homestory_chat_21223003 = "Shouldn't I?",
  str_homestory_chat_21223004 = "If your plan for today is gardening, sweeping the floor and carrying bricks...",
  str_homestory_chat_21223005 = "It's quite suitable.",
  str_homestory_chat_21223006 = "Don't you like it?",
  str_homestory_chat_21223007 = "Not too shabby. It doesn't sully the image of the city.",
  str_homestory_chat_21223008 = "Why did you say \"again\"?",
  str_homestory_chat_21223009 = "Because you keep wearing these same clothes...",
  str_homestory_chat_21223010 = "Never mind. I'll take you to go shopping one of these days.",
  str_homestory_chat_21224001 = "I heard you went down to the river the other day.",
  str_homestory_chat_21224002 = "The river was quite nice.",
  str_homestory_chat_21224003 = "How so?",
  str_homestory_chat_21224004 = "Smoke would come out of my mouth after a fight.",
  str_homestory_chat_21224005 = "Before in Umbraton I had to sit still and let myself cool off.",
  str_homestory_chat_21224006 = "Here I poke my head into the river and the problem is solved in three minutes.",
  str_homestory_chat_21224007 = "...",
  str_homestory_chat_21225001 = "You seem to have nothing to do.",
  str_homestory_chat_21225002 = "That's right... PlayerName, who should we fight today?",
  str_homestory_chat_21225003 = "Why do we have to fight someone?",
  str_homestory_chat_21225004 = "We've got no Eclipsites here. Of course we need to find someone to throw some blows at.",
  str_homestory_chat_21225005 = "... I mean... Why do we have to fight?",
  str_homestory_chat_21225006 = "Do we fight someone often?",
  str_homestory_chat_21225007 = "... Don't be so serious!",
  str_homestory_chat_21225008 = "It was a casual question. Please don't overthink.",
  str_homestory_chat_21699999 = "PlayerName, hello.",
  str_homestory_chat_21601001 = "Hi, Fleur.",
  str_homestory_chat_21601002 = "Do you have anything for me to fix today?",
  str_homestory_chat_21601003 = "I guess so... Let me think.",
  str_homestory_chat_21601004 = "Take your time. No rush.",
  str_homestory_chat_21621001 = "Working?",
  str_homestory_chat_21621002 = "Yeah! Up for a tour?",
  str_homestory_chat_21621003 = "Recently I came up with many ideas about modifying mechas.",
  str_homestory_chat_21621004 = "Sure!",
  str_homestory_chat_21621005 = "When?",
  str_homestory_chat_21621006 = "How about tomorrow at noon?",
  str_homestory_chat_21621007 = "Okay... That works for me.",
  str_homestory_chat_21621008 = "I'd love to but...",
  str_homestory_chat_21621009 = "I'm really busy at the moment...",
  str_homestory_chat_21621010 = "No worries. Come back when you have time.",
  str_homestory_chat_21622001 = "You look very much at peace.",
  str_homestory_chat_21622002 = "I am. Finally I can focus on my work now.",
  str_homestory_chat_21622003 = "Why is that?",
  str_homestory_chat_21622004 = "My horns and tail seem to be unusually appealing...",
  str_homestory_chat_21622005 = "It caused me quite some trouble.",
  str_homestory_chat_21622006 = "Really? They look normal to me...",
  str_homestory_chat_21623001 = "Anything new?",
  str_homestory_chat_21623002 = "You are here to chat with me again?",
  str_homestory_chat_21623003 = "Am I disturbing you?",
  str_homestory_chat_21623004 = "Not at all. I quite enjoy your company.",
  str_homestory_chat_21623005 = "Should I repeat the mecha knowledge I shared with you last time?",
  str_homestory_chat_21399999 = "Hello, PlayerName. Fancy a song from my servant?",
  str_homestory_chat_21321001 = "I'd love to but...",
  str_homestory_chat_21321002 = "First I need to squeeze some time.",
  str_homestory_chat_21321003 = "Hmm. My servant and I will rehearse until you are ready.",
  str_homestory_chat_21322001 = "No need. That ribbon...",
  str_homestory_chat_21322002 = "Hmm? You are curious about the ribbon around my wrist?",
  str_homestory_chat_21322003 = "Can it be untied?",
  str_homestory_chat_21322004 = "Not yet... You didn't notice?",
  str_homestory_chat_21322005 = "Notice what?",
  str_homestory_chat_21322006 = "I would untie one knot on the ribbon before battle...",
  str_homestory_chat_21322007 = "To release the Power of Luminatics.",
  str_homestory_chat_21322008 = "It's better to keep it tied in normal times.",
  str_homestory_chat_21322009 = "I see...",
  str_homestory_chat_21323001 = "That song was very profound...",
  str_homestory_chat_21323002 = "You think so. I've met many people here who at quite good at music...",
  str_homestory_chat_21323003 = "Like who?",
  str_homestory_chat_21323004 = "... I don't know their names but their instruments...",
  str_homestory_chat_21323005 = "Sound much better than those we have in Lumopolis.",
  str_homestory_chat_21323006 = "I can introduce them to you.",
  str_homestory_chat_21323007 = "To be honest, I can't remember most of their names...",
  str_homestory_chat_21323008 = "I'd love a formal introduction if you don't mind.",
  str_homestory_chat_21323009 = "Thank you.",
  str_homestory_chat_21324001 = "Any new song?",
  str_homestory_chat_21324002 = "No... PlayerName, did you chance upon any new scores lately?",
  str_homestory_chat_21324003 = "Yes!",
  str_homestory_chat_21324004 = "Where? Could you show me?",
  str_homestory_chat_21324005 = "Or you could buy them for me. I'll pay you back after...",
  str_homestory_chat_21324006 = "No rush. Let me think where I saw them...",
  str_homestory_chat_21324007 = "Okay. You think.",
  str_homestory_chat_21324008 = "No...",
  str_homestory_chat_21324009 = "If you see any, please let me know!",
  str_homestory_chat_21324010 = "You got it!",
  str_homestory_chat_21499999 = "What's up?",
  str_homestory_chat_21421001 = "Nothing much.",
  str_homestory_chat_21421002 = "Fancy a drink with me?",
  str_homestory_chat_21421003 = "Just came to say hi.",
  str_homestory_chat_21421004 = "If you want to drink, the first round is on me.",
  str_homestory_chat_21422001 = "Such a lovely day!",
  str_homestory_chat_21422002 = "It's perfect weather for a ride.",
  str_homestory_chat_21422003 = "What do you think, PlayerName?",
  str_homestory_chat_21422004 = "That's exactly what I was thinking!",
  str_homestory_chat_21422005 = "Shall we go for a short ride?",
  str_homestory_chat_21422006 = "... Hold on. Do I need to find you a horse first?",
  str_homestory_chat_21422007 = "I'm quite alright without...",
  str_homestory_chat_21422008 = "Why?",
  str_homestory_chat_21422009 = "Give me your reason. Don't leave me puzzled all day.",
  str_homestory_chat_21423001 = "Having something is on your mind?",
  str_homestory_chat_21423002 = "I got a sudden craving...",
  str_homestory_chat_21423003 = "For what?",
  str_homestory_chat_21423004 = "Alcohol. Gin in particular...",
  str_homestory_chat_21423005 = "I haven't had any for two days and five hours.",
  str_homestory_chat_21423006 = "Other drinks might be able to quench the thirst but can't satisfy my desire.",
  str_homestory_chat_21423007 = "I can probably get you some.",
  str_homestory_chat_21423008 = "That's very sweet and thoughtful of you.",
  str_homestory_chat_21423009 = "Thank you. I'll get you a gift in return.",
  str_homestory_chat_21424001 = "What's new?",
  str_homestory_chat_21424002 = "You just love to chat, don't you?",
  str_homestory_chat_21424003 = "Or is it just me?",
  str_homestory_chat_21424004 = "I do enjoy talking to people.",
  str_homestory_chat_21424005 = "I've learned a lot from you and others.",
  str_homestory_chat_21424006 = "So I'm your teacher now?",
  str_homestory_chat_21424007 = "You need my permission to be my student though.",
  str_homestory_chat_21424008 = "I do enjoy talking to you.",
  str_homestory_chat_21424009 = "Hah. I like your frankness.",
  str_homestory_chat_21424010 = "Don't fall to much for me. My funs won't like it.",
  str_homestory_chat_22799999 = "PlayerName? Were you greeting me?",
  str_homestory_chat_22701001 = "Yes?",
  str_homestory_chat_22701002 = "Aww... That makes me happy...",
  str_homestory_chat_22721001 = "What's up?",
  str_homestory_chat_22721002 = "Was there any complaint lodged against me lately?",
  str_homestory_chat_22721003 = "No.",
  str_homestory_chat_22721004 = "That's a relief...",
  str_homestory_chat_22721005 = "I thought someone would blame me for polluting the environment with scraps of paper...",
  str_homestory_chat_22721006 = "What happened?",
  str_homestory_chat_22721007 = "I saw someone working really hard cleaning scraps of paper off the ground...",
  str_homestory_chat_22721008 = "I swear it was not me!",
  str_homestory_chat_22721009 = "I can control my paper very well!",
  str_homestory_chat_22722001 = "You want to see me?",
  str_homestory_chat_22722002 = "PlayerName, did you read any interesting story book recently?",
  str_homestory_chat_22722003 = "Yes!",
  str_homestory_chat_22722004 = "Excellent! Could you give me the name?",
  str_homestory_chat_22722005 = "Hmm... I hope there's a happy ending...",
  str_homestory_chat_22722006 = "Sure. I'll make a list for you!",
  str_homestory_chat_22722007 = "Not really...",
  str_homestory_chat_22722008 = "Ah... I see...",
  str_homestory_chat_22722009 = "I'll let you know if I come across any good book.",
  str_homestory_chat_22722010 = "That'd be fantastic! Thank you!",
  str_homestory_chat_21799999 = "Hey, PlayerName.",
  str_homestory_chat_21701001 = "Hello, Gram.",
  str_homestory_chat_21701002 = "How's your day?",
  str_homestory_chat_21701003 = "Pretty good.",
  str_homestory_chat_21701004 = "I love to see you young folks in fine fettle.",
  str_homestory_chat_21721001 = "You want to see me?",
  str_homestory_chat_21721002 = "Wanna see my training plan for you?",
  str_homestory_chat_21721003 = "You will become a real fight in 30 days!",
  str_homestory_chat_21721004 = "For real?",
  str_homestory_chat_21721005 = "Try and find out.",
  str_homestory_chat_21721006 = "Come. Today's program is a 5k run!",
  str_homestory_chat_21721007 = "... Ah? No... I definitely don't need that!",
  str_homestory_chat_21721008 = "I'm quite alright without a plan...",
  str_homestory_chat_21721009 = "You didn't even look at it!",
  str_homestory_chat_21721010 = "Is this how you young folks do things these days?",
  str_homestory_chat_21721011 = "... I don't need to look. I'm sure your plan features ridiculous events like a 5k run and such.",
  str_homestory_chat_21721012 = "I'm not ready to die during a workout session.",
  str_homestory_chat_21722001 = "What's on the menu today?",
  str_homestory_chat_21722002 = "I got quite a lot of potatoes today. Interested?",
  str_homestory_chat_21722003 = "Fried shredded potato?",
  str_homestory_chat_21722004 = "Sure. I just need a sharp kitchen knife.",
  str_homestory_chat_21722005 = "French fries?",
  str_homestory_chat_21722006 = "Deep fried stuff is no good for your young body...",
  str_homestory_chat_21722007 = "But it doesn't hurt to have once in a while.",
  str_homestory_chat_21722008 = "Mashed potato?",
  str_homestory_chat_21722009 = "Not a bad idea. We'll make this!",
  str_homestory_chat_21723001 = "How do you like your new home?",
  str_homestory_chat_21723002 = "Very comfortable.",
  str_homestory_chat_21723003 = "I was worried you might have a hard time adjusting.",
  str_homestory_chat_21723004 = "I'm relieved to hear that.",
  str_homestory_chat_21723005 = "What is it? You don't think I would enjoy an easy life of leisure?",
  str_homestory_chat_21723006 = "... Well, some veterans might find this life style hard to accept.",
  str_homestory_chat_21723007 = "But I'm different.",
  str_homestory_chat_21999999 = "PlayerName, were you waving at me?",
  str_homestory_chat_21901001 = "Yes.",
  str_homestory_chat_21901002 = "I'll greet you next time.",
  str_homestory_chat_21921001 = "What are you doing?",
  str_homestory_chat_21921002 = "Just had half a box of spicy riceballs...",
  str_homestory_chat_21921003 = "I think my tongue is swollen.",
  str_homestory_chat_21921004 = "That's a lot.",
  str_homestory_chat_21921005 = "I didn't plan to but it tastes so good...",
  str_homestory_chat_21921006 = "Phew... Sizzle...",
  str_homestory_chat_21922001 = "What are you thinking?",
  str_homestory_chat_21922002 = "I don't have to wait for a rainy day to shower.",
  str_homestory_chat_21922003 = "Why is that?",
  str_homestory_chat_21922004 = "I can jump in the river any time. Cleaner than the rain.",
  str_homestory_chat_21922005 = "Our river is quite versatile.",
  str_homestory_chat_21923001 = "You look bored.",
  str_homestory_chat_21923002 = "A little. Why don't we have any Eclipsite to chop? My sword is getting rusty.",
  str_homestory_chat_21923003 = "Could you help chop some wood?",
  str_homestory_chat_21923004 = "Wood... I guess it's better than nothing.",
  str_homestory_chat_21923005 = "Okay. Lead the way.",
  str_homestory_chat_21923006 = "Could you help chop some rock?",
  str_homestory_chat_21923007 = "You want to test if my claymore is harder than rocks?",
  str_homestory_chat_21923008 = "I can cut Eclipsites into halves...",
  str_homestory_chat_21923009 = "Rocks won't be a problem.",
  str_homestory_chat_22299999 = "PlayerName?",
  str_homestory_chat_22201001 = "Hi, Allura.",
  str_homestory_chat_22201002 = "More antique pieces to sell?",
  str_homestory_chat_22201003 = "Not really.",
  str_homestory_chat_22201004 = "You must be looking for something to buy then.",
  str_homestory_chat_22221001 = "You look really angry.",
  str_homestory_chat_22221002 = "... A guy just came out of nowhere and asked to buy my pocket watch!",
  str_homestory_chat_22221003 = "I need a sticker for my watch. Not for sale!",
  str_homestory_chat_22221004 = "Good idea.",
  str_homestory_chat_22221005 = "This should prevent some inquiries for price.",
  str_homestory_chat_22221006 = "Although I'm a trader, I don't sell everything.",
  str_homestory_chat_22221007 = "There might be some other ways.",
  str_homestory_chat_22221008 = "Such as?",
  str_homestory_chat_22221009 = "You could put your pocket watch away when there are potential customers around...",
  str_homestory_chat_22221010 = "And enjoy it when you are alone.",
  str_homestory_chat_22221011 = "Sounds like a plan.",
  str_homestory_chat_22222001 = "What are watching birds?",
  str_homestory_chat_22222002 = "So many kinds of them.",
  str_homestory_chat_22222003 = "You know a lot about birds?",
  str_homestory_chat_22222004 = "I have a lot more to learn but I know here are 23 different species of birds...",
  str_homestory_chat_22222005 = "Am I right?",
  str_homestory_chat_22222006 = "Err... Can't tell you.",
  str_homestory_chat_22223001 = "I believe you are looking for a shop to rent.",
  str_homestory_chat_22223002 = "Yes. I don't think I can stay in this antique shop much longer.",
  str_homestory_chat_22223003 = "I'm considering renting a place here.",
  str_homestory_chat_22223004 = "I'll get you a spot for free!",
  str_homestory_chat_22223005 = "That's really generous of you.",
  str_homestory_chat_22223006 = "I'll give you an antique piece for free when my shop is open!",
  str_homestory_chat_22223007 = "And a special discount for you always!",
  str_homestory_chat_22223008 = "How big a discount? We can talk about it.",
  str_homestory_chat_22199999 = "Hi, PlayerName.",
  str_homestory_chat_22101001 = "How are you, Paloma?",
  str_homestory_chat_22101002 = "What if I tell you I'm not good?",
  str_homestory_chat_22101003 = "Err...",
  str_homestory_chat_22101004 = "Never mind. I don't mean to make it hard for you...",
  str_homestory_chat_22101005 = "Good day to you, PlayerName.",
  str_homestory_chat_22121001 = "That coin of yours...",
  str_homestory_chat_22121002 = "Interested in this coin I wear?",
  str_homestory_chat_22121003 = "Not really...",
  str_homestory_chat_22121004 = "Admit it if you are curious.",
  str_homestory_chat_22121005 = "I don't bite.",
  str_homestory_chat_22121006 = "A little...",
  str_homestory_chat_22121007 = "I don't have a lot to explain to satisfy your interest and curiosity.",
  str_homestory_chat_22121008 = "But I don't mind if you want to play with it a little.",
  str_homestory_chat_22122001 = "How are you feeling?",
  str_homestory_chat_22122002 = "It's not bad being here.",
  str_homestory_chat_22122003 = "Glad to hear.",
  str_homestory_chat_22122004 = "No one is yelling hypocritical beliefs at my face.",
  str_homestory_chat_22122005 = "My ears can finally have some peace.",
  str_homestory_chat_22122006 = "It's all thanks to you.",
  str_homestory_chat_22123001 = "What's new?",
  str_homestory_chat_22123002 = "What would you do if you came up to speak to me but I didn't answer?",
  str_homestory_chat_22123003 = "Walk away quietly?",
  str_homestory_chat_22123004 = "Aww... That sounds pathetic.",
  str_homestory_chat_22123005 = "Okay. I will try my best to respond.",
  str_homestory_chat_22123006 = "Keep talking...",
  str_homestory_chat_22123007 = "Until you reply... Something like that.",
  str_homestory_chat_22123008 = "I'm afraid you would be parched.",
  str_homestory_chat_22124001 = "They say I could find your thorns here.",
  str_homestory_chat_22124002 = "Yes. Actually, I planted them.",
  str_homestory_chat_22124003 = "Planted? Why?",
  str_homestory_chat_22124004 = "Say, what kind of plant do you think thorns are?",
  str_homestory_chat_22124005 = "Normal plants.",
  str_homestory_chat_22124006 = "Special plants.",
  str_homestory_chat_22124007 = "Actually, thorns are some kind of environment.",
  str_homestory_chat_22124008 = "Environment?",
  str_homestory_chat_22124009 = "Many plants have prickles. When they group together, they become thorns.",
  str_homestory_chat_22124010 = "I don't think so. I'm sure thorns are their own kind, the ones with prickly vines...",
  str_homestory_chat_22124011 = "It's a universal term! Any abundance of prickly plants can be called thorns.",
  str_homestory_chat_22124012 = "Especially when they're overgrown and overrun everything, then you have a proverbial thorny situation.",
  str_homestory_chat_22124013 = "I-I see! I think I get it now.",
  str_homestory_chat_22125001 = "You're asking about the Chubbs?",
  str_homestory_chat_22125002 = "Yes. How do you see them?",
  str_homestory_chat_22125003 = "Natives of this location.",
  str_homestory_chat_22125004 = "Unique creatures.",
  str_homestory_chat_22125005 = "Intelligent, perhaps...?",
  str_homestory_chat_22125006 = "Wait, what's that got to do with you wanting to know about the Chubbs?",
  str_homestory_chat_22125007 = "And how do you see them, Paloma?",
  str_homestory_chat_22125008 = "They're truly very fine creatures, maybe even the best.",
  str_homestory_chat_22125009 = "Why, because of how they look? I heard their square shape has a huge appeal.",
  str_homestory_chat_22125010 = "That's one of the factors, but the main reason is how honest they are.",
  str_homestory_chat_22125011 = "Honest?",
  str_homestory_chat_22125012 = "They never lie to you. Whatever you want, you can just trade with them for it.",
  str_homestory_chat_22125013 = "They don't price-gouge, change their minds on a dime, or renege later.",
  str_homestory_chat_22125014 = "And they have the patience to listen to you talk about anything.",
  str_homestory_chat_22125015 = "Uh, so, did you do something to the Chubbs lately...?",
  str_homestory_chat_22126001 = "What are you doing?",
  str_homestory_chat_22126002 = "Observing the weather, which is very important.",
  str_homestory_chat_22126003 = "But your eyes were closed.",
  str_homestory_chat_22126004 = "My eyes were closed?",
  str_homestory_chat_22126005 = "Yeah, for a long while too... You sure you're following the weather?",
  str_homestory_chat_22126006 = "It's important to meditate sometimes.",
  str_homestory_chat_22126007 = "I think you're just taking time off...",
  str_homestory_chat_22126008 = "Why, I never!",
  str_homestory_chat_22126009 = "Necessary rumination is crucial, especially in daily work.",
  str_homestory_chat_22126010 = "Like the gears on the machine, you need to stop churning after a while.",
  str_homestory_chat_22126011 = "Pretty sure that's called taking time off.",
  str_homestory_chat_22127001 = "It's a pretty nice day today.",
  str_homestory_chat_22127002 = "Indeed. But why do you say that when it's this way every day?",
  str_homestory_chat_22127003 = "Just try to make a conversation.",
  str_homestory_chat_22127004 = "Because it is indeed a nice day.",
  str_homestory_chat_22127005 = "Oh, you've been lousy with your opening lines lately.",
  str_homestory_chat_22127006 = "Even though you got so many people you can practice on.",
  str_homestory_chat_22127007 = "Friends aren't for practicing...",
  str_homestory_chat_22127008 = "You're wrong.",
  str_homestory_chat_22127009 = "Oh?",
  str_homestory_chat_22127010 = "If they want to be around you and are willing to come to Cloud Gardens, that means they want to be your friends.",
  str_homestory_chat_22127011 = "For example, idle chitchats, telling absurd stories, or even...",
  str_homestory_chat_22127012 = "Emm, certain unique ideas.",
  str_homestory_chat_22127013 = "So they're receptive to you trying out opening lines, no matter how awkward.",
  str_homestory_chat_22127014 = "Take \"What a nice day,\" for example... What if it's not a nice day?",
  str_homestory_chat_22127015 = "Change it to \"What a crappy day\"?",
  str_homestory_chat_22127016 = "There you go, you finally get it now!",
  str_homestory_chat_22127017 = "Huh? That's it, really?",
  str_homestory_chat_22128001 = "Eclipsites?",
  str_homestory_chat_22128002 = "I feel there's a need to discuss them.",
  str_homestory_chat_22128003 = "Are you concerned about the security here? Don't worry, it's too secluded for them to get to.",
  str_homestory_chat_22128004 = "No, not that kind of question. Have you ever wondered why they attack us?",
  str_homestory_chat_22128005 = "Yes",
  str_homestory_chat_22128006 = "Oh? Why?",
  str_homestory_chat_22128007 = "Maybe it's their instinct.",
  str_homestory_chat_22128008 = "Instinct, eh...",
  str_homestory_chat_22128009 = "No",
  str_homestory_chat_22128010 = "Maybe... it's their instinct?",
  str_homestory_chat_22128011 = "Possibly.",
  str_homestory_chat_21599999 = "Greetings, PlayerName!",
  str_homestory_chat_21501001 = "Hello, Naroxel.",
  str_homestory_chat_21501002 = "May the Nature bless you! Have a beautiful day.",
  str_homestory_chat_21501003 = "Ah! Thank you for the blessing.",
  str_homestory_chat_21501004 = "That's the least I can do.",
  str_homestory_chat_21521001 = "You know this place well.",
  str_homestory_chat_21521002 = "Yes, I've learned everything about it.",
  str_homestory_chat_21521003 = "Come and see me if you have goods to transport in this region.",
  str_homestory_chat_21521004 = "I will!",
  str_homestory_chat_21521005 = "I can also take on the job delivering mail for Aurorians here.",
  str_homestory_chat_21521006 = "Thank you!",
  str_homestory_chat_21521007 = "I can't trouble you like that...",
  str_homestory_chat_21521008 = "I never had a chance to thank you for having me here.",
  str_homestory_chat_21521009 = "Performing these small tasks would be my way of showing gratitude.",
  str_homestory_chat_21522001 = "Such a lovely day!",
  str_homestory_chat_21522002 = "The pleasantly warm weather here refreshes and gladdens my heart.",
  str_homestory_chat_21522003 = "The temperature might drop a little but it never gets too cold.",
  str_homestory_chat_21522004 = "You don't like the cold?",
  str_homestory_chat_21522005 = "A frigid climate can be hard on my body...",
  str_homestory_chat_21522006 = "You prefer warm places?",
  str_homestory_chat_21522007 = "For me, there's no perfect weather. Everything is part of nature.",
  str_homestory_chat_21522008 = "However, I can't stay in a cold place for too long.",
  str_homestory_chat_21522009 = "The weather here suits me just fine.",
  str_homestory_chat_21523001 = "What have you been doing here?",
  str_homestory_chat_21523002 = "... Me?",
  str_homestory_chat_21523003 = "Yes.",
  str_homestory_chat_21523004 = "I don't see you very often...",
  str_homestory_chat_21523005 = "Hmm... I guess I spend lots of time walking in the forest.",
  str_homestory_chat_21523006 = "Join me if you need to loosen up a little.",
  str_homestory_chat_16599999 = "Hallo, Navigator!",
  str_homestory_chat_16501001 = "Hey, Tweety.",
  str_homestory_chat_16501002 = "Do you have latters for me to deliver today?",
  str_homestory_chat_16501003 = "Not today. Thank you though.",
  str_homestory_chat_16521001 = "What are you looking for?",
  str_homestory_chat_16521002 = "Navigator! Do we have snowflates here?",
  str_homestory_chat_16521003 = "Yes!",
  str_homestory_chat_16521004 = "Quite a few of us here can make snowflakes.",
  str_homestory_chat_16521005 = "Where? I want to fint them!",
  str_homestory_chat_16521006 = "I don't think so...",
  str_homestory_chat_16521007 = "Reary?",
  str_homestory_chat_16521008 = "I better use the ice mochine to make some myself!",
  str_homestory_chat_16522001 = "What do you want to tell me?",
  str_homestory_chat_16522002 = "Navigator, do I tolk funny?",
  str_homestory_chat_16522003 = "When I was a massenger, people always laughed at me whenever I spoke.",
  str_homestory_chat_16522004 = "You sound just fine.",
  str_homestory_chat_16522005 = "It's normal to have an accent.",
  str_homestory_chat_16522006 = "As long as we can communicate, there's nothing to laugh at.",
  str_homestory_chat_16522007 = "Aww... Sank you for your kind words.",
  str_homestory_chat_16523001 = "So hot today...",
  str_homestory_chat_16523002 = "Yes, very hot.",
  str_homestory_chat_16523003 = "Navigator, do you know any cool flace?",
  str_homestory_chat_16523004 = "It's nice and cool in the shade.",
  str_homestory_chat_16523005 = "I'm escaping into the shate.",
  str_homestory_chat_16523006 = "Come and find me in the shate if you need me.",
  str_homestory_chat_16523007 = "Some ice cream would help.",
  str_homestory_chat_16523008 = "I needs a lat of ice cream.",
  str_homestory_chat_22699999 = "Hello, Navigator.",
  str_homestory_chat_22601001 = "Hello, Lady Bethel.",
  str_homestory_chat_22601002 = "You have a great sense of social graces.",
  str_homestory_chat_22601003 = "May I help you with anything?",
  str_homestory_chat_22601004 = "Not really. I'm very happy to see you!",
  str_homestory_chat_22621001 = "What's new?",
  str_homestory_chat_22621002 = "You need to make an appointment to chat with me.",
  str_homestory_chat_22621003 = "An appointment to chat?",
  str_homestory_chat_22621004 = "Which part of it don't you understand?",
  str_homestory_chat_22621005 = "Huh... How to make an appointment?",
  str_homestory_chat_22621006 = "I won't say this ever again. You better remember.",
  str_homestory_chat_22621007 = "First, find my assistant. She'll help arrange our meeting.",
  str_homestory_chat_22621008 = "That sounds inconvenient.",
  str_homestory_chat_22621009 = "Well, I have some time now. Make it short.",
  str_homestory_chat_22622001 = "How can I help you?",
  str_homestory_chat_22622002 = "PlayerName, I'd like to organize a book club here. What do you think?",
  str_homestory_chat_22622003 = "Sounds great!",
  str_homestory_chat_22622004 = "What kind of a book club are we talking about?",
  str_homestory_chat_22622005 = "That's a trade secret. I'm sorry.",
  str_homestory_chat_22622006 = "Would people join?",
  str_homestory_chat_22622007 = "Of course! I've made a detailed plan.",
  str_homestory_chat_22622008 = "I'm serious about finding other book lovers.",
  str_homestory_chat_22623001 = "How are you getting along here?",
  str_homestory_chat_22623002 = "I get along just fine wherever I go.",
  str_homestory_chat_22623003 = "Umbraton and this place are not too different for me.",
  str_homestory_chat_22623004 = "The only thing that has changed is I'm way less busy now.",
  str_homestory_chat_22623005 = "Are you bored?",
  str_homestory_chat_22623006 = "I see it as a vacation.",
  str_homestory_chat_22999999 = "Good to see you.",
  str_homestory_chat_22901001 = "Hey! Very pleased to see you.",
  str_homestory_chat_22901002 = "Any new quest for me?",
  str_homestory_chat_22901003 = "Not really...",
  str_homestory_chat_22901004 = "Fine. I can rest a little.",
  str_homestory_chat_22921001 = "Could you take off the mask?",
  str_homestory_chat_22921002 = "... You are not comfortable talking to a masked man?",
  str_homestory_chat_22921003 = "A little...",
  str_homestory_chat_22921004 = "I know masks can cause a sense of distance for some people...",
  str_homestory_chat_22921005 = "Try to focus on my eyes. You might feel better.",
  str_homestory_chat_22921006 = "I'd take off my mask if you can't get used to this.",
  str_homestory_chat_22921007 = "Not like that...",
  str_homestory_chat_22921008 = "So you are just curious?",
  str_homestory_chat_22921009 = "Curiosity is a good thing. I'm not offended at all.",
  str_homestory_chat_22922001 = "What are you thinking?",
  str_homestory_chat_22922002 = "Recently, quite some people came to me for a drawing on their clothes.",
  str_homestory_chat_22922003 = "What drawing?",
  str_homestory_chat_22922004 = "Like the favorite corner of home...",
  str_homestory_chat_22922005 = "That's a bit odd, don't you think?",
  str_homestory_chat_22922006 = "It's the trend to have a scene of home painted on the clothes.",
  str_homestory_chat_22922007 = "I wonder who started this.",
  str_homestory_chat_22922008 = "I could make you one for free if you are interested.",
  str_homestory_chat_22923001 = "You look really happy...",
  str_homestory_chat_22923002 = "What's the good news?",
  str_homestory_chat_22923003 = "Good news?",
  str_homestory_chat_22923004 = "Oh. I went to the forest and watched insects for hours.",
  str_homestory_chat_22923005 = "That makes me happy.",
  str_homestory_chat_22923006 = "Are you interested in insects?",
  str_homestory_chat_22923007 = "Very!",
  str_homestory_chat_22923008 = "Come with me next time.",
  str_homestory_chat_22923009 = "Not my cup of tea...",
  str_homestory_chat_22923010 = "You never know. You might develop an interest after a few forest trips.",
  str_homestory_chat_22923011 = "Would you like to come with me next time?",
  str_homestory_chat_15599999 = "It's working time... Ah! Hey.",
  str_homestory_chat_15501001 = "Hi. Am I disturbing?",
  str_homestory_chat_15501002 = "Oh... I'm sorry. I've got a bad habit.",
  str_homestory_chat_15501003 = "Good to see you, PlayerName.",
  str_homestory_chat_15501004 = "Did I disturb you from work before?",
  str_homestory_chat_15501005 = "Not at all. It's my problem. I'm too immersed in my work.",
  str_homestory_chat_15521001 = "Are you interested in this place?",
  str_homestory_chat_15521002 = "Yes. I've written quite a few travel notes already since my arrival.",
  str_homestory_chat_15521003 = "Everything here is strange and refreshing.",
  str_homestory_chat_15521004 = "I can't help writing about them.",
  str_homestory_chat_15521005 = "I hope it's not a problem.",
  str_homestory_chat_15521006 = "Not at all. Write as you please.",
  str_homestory_chat_15522001 = "Why are you staring at me?",
  str_homestory_chat_15522002 = "Have you been working out recently?",
  str_homestory_chat_15522003 = "Yes.",
  str_homestory_chat_15522004 = "Excellent. You are qualified to hunt down the escaped convict.",
  str_homestory_chat_15522005 = "Not really...",
  str_homestory_chat_15522006 = "I guess I'll have to chase the escaped convict by myself.",
  str_homestory_chat_15522007 = "We've got a convict at large?",
  str_homestory_chat_15522008 = "Hmm... I probably shouldn't have called it an escaped convict...",
  str_homestory_chat_15522009 = "What on earth are we talking about?",
  str_homestory_chat_15522010 = "Cough... A rabbit. It destroyed many flowers in the garden...",
  str_homestory_chat_15523001 = "Looking for me?",
  str_homestory_chat_15523002 = "PlayerName, do you have plans to open a school?",
  str_homestory_chat_15523003 = "Why are you asking?",
  str_homestory_chat_15523004 = "The ruins here are so rich in ancient wisdom and intelligence...",
  str_homestory_chat_15523005 = "Don't you want to pass it on?",
  str_homestory_chat_15523006 = "You are right. I'll give it some serious thought.",
  str_homestory_chat_22099999 = "Good to see you again, PlayerName.",
  str_homestory_chat_22001001 = "Hello, Hedy.",
  str_homestory_chat_22001002 = "Hi... I really like this book I just read...",
  str_homestory_chat_22001003 = "But I'm not sure if it's up your alley.",
  str_homestory_chat_22001004 = "I'm sure it's very interesting.",
  str_homestory_chat_22021001 = "Are you on a stroll?",
  str_homestory_chat_22021002 = "Yes, I'm walking Pompey on the grass.",
  str_homestory_chat_22021003 = "Finally I don't have to worry that he might trample something down.",
  str_homestory_chat_22021004 = "You are welcome to join us.",
  str_homestory_chat_22021005 = "You sure?",
  str_homestory_chat_22021006 = "It must be cool to walk with Pompey!",
  str_homestory_chat_22021007 = "I'd love to but...",
  str_homestory_chat_22021008 = "I'm quite busy right now.",
  str_homestory_chat_22021009 = "Don't worry. You are welcome any time.",
  str_homestory_chat_22022001 = "We are having a party soon...",
  str_homestory_chat_22022002 = "Would you like to join?",
  str_homestory_chat_22022003 = "Thank you for the invite but I don't like large gatherings.",
  str_homestory_chat_22022004 = "I see...",
  str_homestory_chat_22022005 = "I could go to a higher ground nearer your party venue...",
  str_homestory_chat_22022006 = "Observing is a kind of participation.",
  str_homestory_chat_22022007 = "Ah?",
  str_homestory_chat_22023001 = "How can I help?",
  str_homestory_chat_22023002 = "Could you please find me a few books?",
  str_homestory_chat_22023003 = "Sure.",
  str_homestory_chat_22023004 = "But you just bought a high stack of books several days ago...",
  str_homestory_chat_22023005 = "You've finished them all?",
  str_homestory_chat_22023006 = "Yes. Sometimes it troubles me that I read too fast.",
  str_homestory_chat_22399999 = "Hello!",
  str_homestory_chat_22301001 = "Hi, Cordy!",
  str_homestory_chat_22301002 = "I'm maintaining law and order like always!",
  str_homestory_chat_22301003 = "Ah! Thank you for your service.",
  str_homestory_chat_22301004 = "It's an honor to help create a safe environment for everyone!",
  str_homestory_chat_22321001 = "You are leaving?",
  str_homestory_chat_22321002 = "Hmm... It occurred to me that I didn't clean my room today...",
  str_homestory_chat_22321003 = "But our conversation only started.",
  str_homestory_chat_22321004 = "I'd love to stay and chat more...",
  str_homestory_chat_22321005 = "But I can't think anything right now other than my messy room...",
  str_homestory_chat_22321006 = "Ugh! I can't put it off any longer. Sorry! Have to go!",
  str_homestory_chat_22322001 = "You're in such a good mood today.",
  str_homestory_chat_22322002 = "Yes! I got a new uniform!",
  str_homestory_chat_22322003 = "I guess you like new clothes?",
  str_homestory_chat_22322004 = "Not all of them...",
  str_homestory_chat_22322005 = "This uniform is not yet washed or starched. It feels extremely soft.",
  str_homestory_chat_22322006 = "I can't help smiling thinking about wearing this soft dress...",
  str_homestory_chat_22322007 = "Aww... Please don't laugh at me.",
  str_homestory_chat_22323001 = "Hmm? Is that a trail of tears I'm looking at?",
  str_homestory_chat_22323002 = "What happened?",
  str_homestory_chat_22323003 = "Nothing...",
  str_homestory_chat_22323004 = "It's okay. You can tell me.",
  str_homestory_chat_22323005 = "They... they were not tears of sadness...",
  str_homestory_chat_22323006 = "As a Sheriff, I often have to deal with emergency... Sometimes it's quite frightening...",
  str_homestory_chat_22323007 = "I see.",
  str_homestory_chat_22323008 = "Let me help you next time.",
  str_homestory_chat_22323009 = "Are you sure you are okay?",
  str_homestory_chat_22323010 = "I'm fine... Please carry on with your day.",
  str_homestory_chat_22323011 = "I'll leave you to it then... You know you can tell me anything.",
  str_homestory_chat_11599999 = "PlayerName, it's a lovely day.",
  str_homestory_chat_11501001 = "Hey.",
  str_homestory_chat_11501002 = "Would you like to buy a painting?",
  str_homestory_chat_11501003 = "Is there any connection between a lovely day and painting shopping?",
  str_homestory_chat_11501004 = "There is if PlayerName thinks so.",
  str_homestory_chat_11501005 = "But the way you speak is more and more like him...",
  str_homestory_chat_11521001 = "What are you thinking?",
  str_homestory_chat_11521002 = "When can we afford an Airship?",
  str_homestory_chat_11521003 = "According to Gin, we need to sell 10,000 more paintings.",
  str_homestory_chat_11521004 = "I heard you could borrow...",
  str_homestory_chat_11521005 = "Borrow? Good idea!",
  str_homestory_chat_11521006 = "Don't go borrowing from those loan sharks though. They can be ruthless...",
  str_homestory_chat_11521007 = "We could build one.",
  str_homestory_chat_11521008 = "You're right.",
  str_homestory_chat_11521009 = "But do you know how?",
  str_homestory_chat_11521010 = "I'm not one of those Rediesel Wrench geeks...",
  str_homestory_chat_11522001 = "It's quite hot today.",
  str_homestory_chat_11522002 = "Today? I find it a little chilly...",
  str_homestory_chat_11522003 = "That's strange.",
  str_homestory_chat_11522004 = "Our feelings are the opposite.",
  str_homestory_chat_11522005 = "We are quite different after all...",
  str_homestory_chat_11522006 = "Yeah. I'll go back to grab a jacket!",
  str_homestory_chat_11523001 = "I heard someone is hosting a salon?",
  str_homestory_chat_11523002 = "Not a party?",
  str_homestory_chat_11523003 = "I guess the news got twisted as it spread...",
  str_homestory_chat_11523004 = "Must be Gin.",
  str_homestory_chat_11523005 = "I'll ask him right away.",
  str_homestory_chat_11523006 = "I guess it's just a regular party.",
  str_homestory_chat_23199999 = "Such a small world, PlayerName.",
  str_homestory_chat_23101001 = "Hi, Novio.",
  str_homestory_chat_23101002 = "You are also taking a walk here?",
  str_homestory_chat_23101003 = "Yes.",
  str_homestory_chat_23101004 = "May I join you?",
  str_homestory_chat_23121001 = "How do you feel about this place?",
  str_homestory_chat_23121002 = "I used to get homesick every time I left the Northland.",
  str_homestory_chat_23121003 = "But I haven't felt this way here.",
  str_homestory_chat_23121004 = "Sounds like you are adjusting just fine.",
  str_homestory_chat_23121005 = "I should probably give the credit to you.",
  str_homestory_chat_23122001 = "What are you looking for?",
  str_homestory_chat_23122002 = "Fresh carrots?",
  str_homestory_chat_23122003 = "What for?",
  str_homestory_chat_23122004 = "My rabbit family has just grown.",
  str_homestory_chat_23122005 = "Carrots for three meals before are now eaten in two meals.",
  str_homestory_chat_23122006 = "I'm troubled...",
  str_homestory_chat_23122007 = "Ah, I see... I'll ask around for you.",
  str_homestory_chat_23123001 = "Are you looking for Her Majesty the Queen?",
  str_homestory_chat_23123002 = "Yes. Do you happen to know where Her Majesty might be?",
  str_homestory_chat_23123003 = "Yes.",
  str_homestory_chat_23123004 = "Right there.",
  str_homestory_chat_23123005 = "Excellent. I just made a gem brooch...",
  str_homestory_chat_23123006 = "Can't wait to see Her Majesty try it on.",
  str_homestory_chat_23123007 = "Sorry, I don't know...",
  str_homestory_chat_23123008 = "I just made a gem brooch and wanted to present it to Her Majesty...",
  str_homestory_chat_23123009 = "Who should I gift it now?",
  str_homestory_chat_23123010 = "Sigh... I'll just put it away.",
  str_homestory_chat_23124001 = "What are you listening to?",
  str_homestory_chat_23124002 = "The sounds of nature. Sometimes they're better than music.",
  str_homestory_chat_23124003 = "Speaking of which, do you like music?",
  str_homestory_chat_23124004 = "Yes.",
  str_homestory_chat_23124005 = "Not really.",
  str_homestory_chat_23124006 = "I see. I heard you're good at the piano? Especially the one on the Colossus...",
  str_homestory_chat_23124007 = "Are you interested?",
  str_homestory_chat_23124008 = "Just curious.",
  str_homestory_chat_23125001 = "Taking a walk?",
  str_homestory_chat_23125002 = "Yes, something has been bothering me for a few days, so I decided to take a stroll for a change.",
  str_homestory_chat_23125003 = "What do you usually do in this situation?",
  str_homestory_chat_23125004 = "Take a walk.",
  str_homestory_chat_23125005 = "Walk around the neighborhood and try to empty my mind.",
  str_homestory_chat_23125006 = "Read a book.",
  str_homestory_chat_23125007 = "Especially those that I don't need to think about while reading. Like the bland swashbuckler stories in Umbraton...",
  str_homestory_chat_23125008 = "That's a lot of effort to keep your mind from being distracted by trivial things.",
  str_homestory_chat_23125009 = "I suppose the responsibility of guarding this place can be stressful.",
  str_homestory_chat_23125010 = "Um, how are things?",
  str_homestory_chat_23299999 = "Heheh. Good to see you again!",
  str_homestory_chat_23201001 = "That's right!",
  str_homestory_chat_23201002 = "Fancy a honey muffin?",
  str_homestory_chat_23201003 = "My secret recipe. It won't make you fat!",
  str_homestory_chat_23201004 = "That sounds fantastic!",
  str_homestory_chat_23221001 = "What are you looking for?",
  str_homestory_chat_23221002 = "Honey! I have finished all the honey brought from the Northland...",
  str_homestory_chat_23221003 = "I'm vanishing from this world. Only honey muffins can save me!",
  str_homestory_chat_23221004 = "Really?",
  str_homestory_chat_23221005 = "Hmm... Of course not!",
  str_homestory_chat_23221006 = "I just want to make a point that honey is essential for me!",
  str_homestory_chat_23222001 = "You look very sleepy.",
  str_homestory_chat_23222002 = "*Yawns* Is it time for bed yet?",
  str_homestory_chat_23222003 = "It's getting late.",
  str_homestory_chat_23222004 = "Yes. Get some rest.",
  str_homestory_chat_23222005 = "Talk to you tomorrow!",
  str_homestory_chat_23222006 = "This early?",
  str_homestory_chat_23222007 = "My parents told me I should sleep when I'm tired. Is it wrong?",
  str_homestory_chat_23222008 = "Err...",
  str_homestory_chat_23222009 = "I'm going to bed... See you tomorrow.",
  str_homestory_chat_23223001 = "What are you looking for?",
  str_homestory_chat_23223002 = "Do we have wild roses here?",
  str_homestory_chat_23223003 = "Yes.",
  str_homestory_chat_23223004 = "Terrific!",
  str_homestory_chat_23223005 = "I want a big armful to make a lei...",
  str_homestory_chat_23223006 = "For you!",
  str_homestory_chat_23223007 = "I'm afraid not...",
  str_homestory_chat_23223008 = "No? Other flowers are also okay...",
  str_homestory_chat_23899999 = "Hello, PlayerName. It seems to me that you don't have a job. How leisurely and carefree!",
  str_homestory_chat_23801001 = "Ah... Good day to you.",
  str_homestory_chat_23801002 = "I actually have many things to do.",
  str_homestory_chat_23801003 = "Really? I see you wander around all the time.",
  str_homestory_chat_23801004 = "Do I?",
  str_homestory_chat_23821001 = "Looking for Vice?",
  str_homestory_chat_23821002 = "Yes. Vice is still working so hard on the map.",
  str_homestory_chat_23821003 = "Send her to see me. My spiders have figured this place out.",
  str_homestory_chat_23821004 = "Okay.",
  str_homestory_chat_23821005 = "I believe Vice needs exact data for her map...",
  str_homestory_chat_23821006 = "Are you questioning my spiders' ability?",
  str_homestory_chat_23821007 = "They know exactly how many flowers there are in the garden.",
  str_homestory_chat_23822001 = "What are you up to?",
  str_homestory_chat_23822002 = "You're the third one who greeted me today...",
  str_homestory_chat_23822003 = "You'll have good luck today.",
  str_homestory_chat_23822004 = "You believe in this?",
  str_homestory_chat_23822005 = "You seem surprised?",
  str_homestory_chat_23822006 = "A scientific researcher doesn't have to be rational all the time...",
  str_homestory_chat_23822007 = "Little hobbies like this can help regulate mood.",
  str_homestory_chat_23822008 = "Really?",
  str_homestory_chat_23822009 = "3 is my lucky number.",
  str_homestory_chat_23822010 = "Trust me. It will bring you good luck.",
  str_homestory_chat_23823001 = "Have you been drinking?",
  str_homestory_chat_23823002 = "Hmm... Excuse me. I just had a little...",
  str_homestory_chat_23823003 = "Please don't look at me like that... I won't do anything strange, okay?",
  str_homestory_chat_23823004 = "I think it was more than a little.",
  str_homestory_chat_23823005 = "It might be a lot for you, but it was very little for me...",
  str_homestory_chat_23823006 = "Can you stand still without wobbling?",
  str_homestory_chat_23823007 = "... I'm pretty sure it was quite a lot for you.",
  str_homestory_chat_23823008 = "Are you sure about this?",
  str_homestory_chat_23823009 = "Hmm... You better keep some distance...",
