  str_homestory_chat_23824007 = "Ah... I better get going before my stomach complains.",
  str_homestory_chat_23824008 = "See you next time.",
  str_homestory_chat_23999999 = "...",
  str_homestory_chat_23901001 = "Hello, Erica.",
  str_homestory_chat_23901002 = "... You... Did you just greet me?",
  str_homestory_chat_23901003 = "Pick a different hour next time. I was napping...",
  str_homestory_chat_23901004 = "Napping standing up...",
  str_homestory_chat_23921001 = "What are you looking at?",
  str_homestory_chat_23921002 = "I'm afraid I just can't get away from the otherworldly gaze...",
  str_homestory_chat_23921003 = "Otherworld?",
  str_homestory_chat_23921004 = "You're unaware of any of this...",
  str_homestory_chat_23921005 = "Good for you. Those who can see the reality often can't escape from misfortune.",
  str_homestory_chat_23921006 = "Gaze?",
  str_homestory_chat_23921007 = "Can't you see?",
  str_homestory_chat_23921008 = "The pair of eyes in the void...",
  str_homestory_chat_23921009 = "Ahh! Don't scare me!",
  str_homestory_chat_23922001 = "What are you doing?",
  str_homestory_chat_23922002 = "... Is it time to work?",
  str_homestory_chat_23922003 = "Not really...",
  str_homestory_chat_23922004 = "I just want to talk to you.",
  str_homestory_chat_23922005 = "Phew... I see.",
  str_homestory_chat_23922006 = "Let me have a candy first.",
  str_homestory_chat_23922007 = "... Candies can quickly clear our mind.",
  str_homestory_chat_23922008 = "Would you like one?",
  str_homestory_chat_23923001 = "Would you like to come to our party?",
  str_homestory_chat_23923002 = "Are parties really that fun?",
  str_homestory_chat_23923003 = "A group of Aurorians get together for a moment of joy without knowing that dangers are approaching...",
  str_homestory_chat_23923004 = "That sounds quite pathetic to me.",
  str_homestory_chat_23923005 = "Uhh...",
  str_homestory_chat_23923006 = "However, don't be too scared.",
  str_homestory_chat_23923007 = "I'll keep you safe on the Judgment Day.",
  str_homestory_chat_24099999 = "Good day, PlayerName.",
  str_homestory_chat_24001001 = "How are you, Florine?",
  str_homestory_chat_24001002 = "Thank you for asking. You look just like yesterday.",
  str_homestory_chat_24001003 = "This is a good thing.",
  str_homestory_chat_24001004 = "Really?",
  str_homestory_chat_24021001 = "Hi, Florine!",
  str_homestory_chat_24021002 = "You look great. Had an early night last night?",
  str_homestory_chat_24021003 = "You're correct!",
  str_homestory_chat_24021004 = "Very well. Going to bed early is a good habit.",
  str_homestory_chat_24021005 = "You could join my Early to Bed group and stick to it every day.",
  str_homestory_chat_24021006 = "Err... Not really...",
  str_homestory_chat_24021007 = "I don't think going to bed early has anything to do with my complexion.",
  str_homestory_chat_24021008 = "I can tell you that sleeping early improves your complexion...",
  str_homestory_chat_24021009 = "But a good complexion is not entirely the result of keeping early hours.",
  str_homestory_chat_24021010 = "Hmm... Give me a minute to digest this.",
  str_homestory_chat_24022001 = "What's wrong?",
  str_homestory_chat_24022002 = "Cough...",
  str_homestory_chat_24022003 = "I just had something really spicy by accident.",
  str_homestory_chat_24022004 = "I don't feel very well.",
  str_homestory_chat_24022005 = "You can't eat spicy cold?",
  str_homestory_chat_24022006 = "I can... But I just really don't like it.",
  str_homestory_chat_24022007 = "It just doesn't taste healthy to me...",
  str_homestory_chat_24023001 = "Looking for me?",
  str_homestory_chat_24023002 = "Watch out when you walk.",
  str_homestory_chat_24023003 = "What happened?",
  str_homestory_chat_24023004 = "Alba snuck into the grass. If you step on it...",
  str_homestory_chat_24023005 = "Oh no...",
  str_homestory_chat_24023006 = "Don't be scared. I'll get it back right away.",
  str_homestory_chat_24023007 = "Ah... I'll keep an eye out.",
  str_homestory_chat_24023008 = "Aren't afraid of snakes?",
  str_homestory_chat_24199999 = "Hello, PlayerName.",
  str_homestory_chat_24101001 = "Hi, Ruby.",
  str_homestory_chat_24101002 = "Would you like to go on an adventure with me?",
  str_homestory_chat_24101003 = "Like now?",
  str_homestory_chat_24101004 = "What are you thinking?",
  str_homestory_chat_24101005 = "A professional explorer would never set out unprepared!",
  str_homestory_chat_24121001 = "Those two hamsters...",
  str_homestory_chat_24121002 = "Bently and Lompty found a lot more good stuff!",
  str_homestory_chat_24121003 = "Ownerless ones?",
  str_homestory_chat_24121004 = "Hmm... You're right...",
  str_homestory_chat_24121005 = "I'll make a Lost & Found post!",
  str_homestory_chat_24121006 = "The unclaimed ones in the end will be mine!",
  str_homestory_chat_24122001 = "What's the matter?",
  str_homestory_chat_24122002 = "Did you hear a scream?",
  str_homestory_chat_24122003 = "I believe so...",
  str_homestory_chat_24122004 = "Oh no... Must have hit someone!",
  str_homestory_chat_24122005 = "No.",
  str_homestory_chat_24122006 = "Phew... That's a relief...",
  str_homestory_chat_24122007 = "What did you do?",
  str_homestory_chat_24122008 = "I hit a tin with my baseball bat...",
  str_homestory_chat_24123001 = "What are you doing?",
  str_homestory_chat_24123002 = "A new adventure route has been planned!",
  str_homestory_chat_24123003 = "Would you like to see?",
  str_homestory_chat_24123004 = "Sure!",
  str_homestory_chat_24123005 = "Okay... Let me find it for you...",
  str_homestory_chat_24123006 = "...",
  str_homestory_chat_24123007 = "I can't find it anywhere... Did Bently and Lompty steal it?",
  str_homestory_chat_24299999 = "Hey, you! PlayerName!",
  str_homestory_chat_24221001 = "Ah. Hello.",
  str_homestory_chat_24221002 = "Last time I asked you to gather materials...",
  str_homestory_chat_24221003 = "Please give me two more days!",
  str_homestory_chat_24221004 = "No rush. Take your time.",
  str_homestory_chat_24222001 = "Are you looking for Ruby?",
  str_homestory_chat_24222002 = "Where is Ruby?",
  str_homestory_chat_24222003 = "Maybe she's in danger!",
  str_homestory_chat_24222004 = "Over there.",
  str_homestory_chat_24222005 = "Ah! I see her! Thank you, PlayerName!",
  str_homestory_chat_24222006 = "Gotta go. Talk to you next time!",
  str_homestory_chat_24222007 = "Haven't seen her for a while.",
  str_homestory_chat_24222008 = "What shall I do?",
  str_homestory_chat_24222009 = "I installed a tracker on Bently and Lompty a few days ago...",
  str_homestory_chat_24222010 = "Maybe this can help locate her...",
  str_homestory_chat_24223001 = "What's that sound?",
  str_homestory_chat_24223002 = "Hmm... My stomach...",
  str_homestory_chat_24223003 = "Hey! How long have you been there?",
  str_homestory_chat_24223004 = "Very hungry?",
  str_homestory_chat_24223005 = "Just a little...",
  str_homestory_chat_24223006 = "Some roasted meat would be great... Roasted meat...",
  str_homestory_chat_24223007 = "Look at you...",
  str_homestory_chat_24224001 = "Hungry?",
  str_homestory_chat_24224002 = "Yes! When will food be ready?",
  str_homestory_chat_24224003 = "Very soon.",
  str_homestory_chat_24224004 = "Terrific!",
  str_homestory_chat_24224005 = "By the way, the food here is pretty good!",
  str_homestory_chat_24224006 = "As soon as I finish my breakfast, I'm looking forward to lunch.",
  str_homestory_chat_24224007 = "We have to wait a bit longer.",
  str_homestory_chat_24224008 = "Ah... That sucks...",
  str_homestory_chat_24224009 = "It has been a hundred years since I last eat.",
  str_homestory_chat_24224010 = "Come on. Don't be so dramatic!",
  str_homestory_chat_24399999 = "Hello, Navigator.",
  str_homestory_chat_24301001 = "Hi, Rinne.",
  str_homestory_chat_24301002 = "Do you need the priestess to drive out vile presence for you today?",
  str_homestory_chat_24301003 = "That won't be necessary...",
  str_homestory_chat_24321001 = "What do you think about this place?",
  str_homestory_chat_24321002 = "This land is extremely clean.",
  str_homestory_chat_24321003 = "Looks like you don't really need a priestess...",
  str_homestory_chat_24321004 = "That's not true!",
  str_homestory_chat_24321005 = "I mean... You are very welcome to stay as a guest.",
  str_homestory_chat_24321006 = "You don't have to work here as a priestess.",
  str_homestory_chat_24321007 = "Great. I'll stay here as Rinne.",
  str_homestory_chat_24322001 = "Can I help you?",
  str_homestory_chat_24322002 = "Navigator, we need to make a regular cleaning day.",
  str_homestory_chat_24322003 = "Good idea!",
  str_homestory_chat_24322004 = "Ahh... Didn't expect you to agree so quickly...",
  str_homestory_chat_24322005 = "I prepared a long speech to persuade you...",
  str_homestory_chat_24322006 = "Huh? Why?",
  str_homestory_chat_24322007 = "Regular elimination of the vile presence can help the residents ward off ill fortune, stay healthy and feel good.",
  str_homestory_chat_24322008 = "What do you think?",
  str_homestory_chat_24323001 = "What's new?",
  str_homestory_chat_24323002 = "Navigator, I have discovered a perfect place for self cultivation.",
  str_homestory_chat_24323003 = "Where is it?",
  str_homestory_chat_24323004 = "It's hard to give a specific address but I can describe it for you...",
  str_homestory_chat_24323005 = "It's not far from the river...",
  str_homestory_chat_24323006 = "Listen carefully if you want to find this place.",
  str_homestory_chat_24323007 = "Beautiful music plays there every day at dusk.",
  str_homestory_chat_24323008 = "Sounds like you've chanced upon a secret base of some music loving Aurorian.",
  str_homestory_chat_24499999 = "Ah...",
  str_homestory_chat_24401001 = "Hello, Kayano.",
  str_homestory_chat_24401002 = "You greeted me? Aww... I'm so happy...",
  str_homestory_chat_24401003 = "You look fresh and sharp.",
  str_homestory_chat_24401004 = "Because those things are very quiet today.",
  str_homestory_chat_24421001 = "I don't see you much...",
  str_homestory_chat_24421002 = "This hasn't changed after you relocated here.",
  str_homestory_chat_24421003 = "Really? I guess I'm hiding most of the time...",
  str_homestory_chat_24421004 = "Why?",
  str_homestory_chat_24421005 = "Too many Aurorians are around...",
  str_homestory_chat_24421006 = "And... Those things are dangerous...",
  str_homestory_chat_24421007 = "I see...",
  str_homestory_chat_24422001 = "How do you like it here?",
  str_homestory_chat_24422002 = "I feel very lucky to be here...",
  str_homestory_chat_24422003 = "I don't have to work but there's always food. When I want to be left alone, no one comes to disturb me...",
  str_homestory_chat_24422004 = "Hmm... You didn't hear anything. Those words were not mine...",
  str_homestory_chat_24422005 = "Relax.",
  str_homestory_chat_24422006 = "I'm glad that you like it here.",
  str_homestory_chat_24422007 = "Really?",
  str_homestory_chat_24423001 = "You are quite tall.",
  str_homestory_chat_24423002 = "Sigh... But... Never mind.",
  str_homestory_chat_24423003 = "Are you troubled by your height?",
  str_homestory_chat_24423004 = "A little...",
  str_homestory_chat_24423005 = "But I think your height is perfect.",
  str_homestory_chat_24423006 = "Never.",
  str_homestory_chat_24423007 = "That's nice.",
  str_homestory_chat_24423008 = "Are you unhappy with your height?",
  str_homestory_chat_24423009 = "Hmm... No, but it did get me some problems...",
  str_homestory_chat_24423010 = "I'm used to looking at the crown of people already.",
  str_homestory_chat_24423011 = "It would be quite strange if I have to look up at someone.",
  str_homestory_chat_24599999 = "Good day, Navigator.",
  str_homestory_chat_24521001 = "No need to be so formal.",
  str_homestory_chat_24521002 = "I want to show my respect for you. If it bothers you...",
  str_homestory_chat_24521003 = "Please bear with me.",
  str_homestory_chat_24522001 = "What are you looking at?",
  str_homestory_chat_24522002 = "Every morning when I wake up, I feel confused for a moment...",
  str_homestory_chat_24522003 = "As if I were a little girl once again.",
  str_homestory_chat_24522004 = "This place reminds you of home?",
  str_homestory_chat_24522005 = "No, actually this place has nothing in common with my home.",
  str_homestory_chat_24522006 = "I think this feeling comes from inner peace, which I finally find again after way too long.",
  str_homestory_chat_24523001 = "What's the matter?",
  str_homestory_chat_24523002 = "Navigator, have you noticed an unpleasant smell in the air?",
  str_homestory_chat_24523003 = "Not until you mentioned it...",
  str_homestory_chat_24523004 = "You can't stand the smell of garlic chives just like me.",
  str_homestory_chat_24523005 = "It's unbelievable some people would describe this ponging smell as fragrant!",
  str_homestory_chat_24523006 = "The smell of garlic chives?",
  str_homestory_chat_24523007 = "I can't smell anything...",
  str_homestory_chat_24523008 = "I'm afraid your sense of smell is quite dull.",
  str_homestory_chat_24523009 = "Good for you. At least you don't have to suffer this awful smell.",
  str_homestory_chat_24524001 = "Hmm? Your clothes...",
  str_homestory_chat_24524002 = "You were wearing something different an hour ago.",
  str_homestory_chat_24524003 = "Getting changed quickly is an essential skill for ninja.",
  str_homestory_chat_24524004 = "This is how we escape from pursuers.",
  str_homestory_chat_24524005 = "Oh... I see...",
  str_homestory_chat_24524006 = "Is anyone following you here?",
  str_homestory_chat_24524007 = "...",
  str_homestory_chat_24524008 = "Ahem... Ninja can also get changed when they feel good.",
  str_homestory_chat_24699999 = "Hi! Good to see you today!",
  str_homestory_chat_24601001 = "Hello, Yao.",
  str_homestory_chat_24601002 = "Is there any problem you need my fist to help settle?",
