  str_homestory_chat_24621007 = "Buy me two boxes of chili powder. That's all.",
  str_homestory_chat_24621008 = "Sigh... The food here is so bland...",
  str_homestory_chat_24621009 = "In your world, the commission for some chili powder is 100,000 Nightium...",
  str_homestory_chat_24622001 = "What are you staring at me for?",
  str_homestory_chat_24622002 = "PlayerName, are your clothes comfortable?",
