  str_homestory_chat_24622004 = "Woah! Really? Tell me. Where did you buy them?",
  str_homestory_chat_24622005 = "I can use a few!",
  str_homestory_chat_24622006 = "Not really...",
  str_homestory_chat_24622007 = "Why not get changed?",
  str_homestory_chat_24622008 = "There's a boutique I visit often. Their clothes are very comfy.",
  str_homestory_chat_24622009 = "I'll bring you along next time when I go shopping.",
