  str_homestory_chat_24623002 = "Ah! I've improved a lot!",
  str_homestory_chat_24623003 = "Wanna try?",
  str_homestory_chat_24623004 = "But... But I don't know any martial art...",
  str_homestory_chat_24623005 = "Don't worry. I won't throw kicks and punches at you.",
  str_homestory_chat_24623006 = "Stay out of the way and watch me split this rock with my hand.",
