  str_homestory_chat_24624002 = "Tastes incredible!",
  str_homestory_chat_24624003 = "As a thank-you gesture, I decide to cook Mapo Tofu for you.",
  str_homestory_chat_24624004 = "Sounds great!",
  str_homestory_chat_24624005 = "Hahah. You are also a big Mapo Tofu fan!",
  str_homestory_chat_24624006 = "Eat a lot once I'm done!",
  str_homestory_chat_24624007 = "I can't trouble you like that...",
