  str_homestory_chat_24799999 = "Hello!",
  str_homestory_chat_24701001 = "Hi!",
  str_homestory_chat_24701002 = "Have you eaten yet?",
  str_homestory_chat_24701003 = "Yes. I'm still very full.",
  str_homestory_chat_24721001 = "I heard you are opening another branch?",
  str_homestory_chat_24721002 = "I'm here to ask you about it!",
  str_homestory_chat_24721003 = "I support you unconditionally!",
