  str_homestory_chat_24721005 = "Let's prepare for a new branch!",
  str_homestory_chat_24721006 = "I need to think about it...",
  str_homestory_chat_24721007 = "If you agree...",
  str_homestory_chat_24721008 = "All your ramen will be on the house from now on!",
  str_homestory_chat_24722001 = "What is this smell?",
  str_homestory_chat_24722002 = "A very familiar scent...",
  str_homestory_chat_24722003 = "Must be the vanilla from last time!",
  str_homestory_chat_24722004 = "Last time?",
  str_homestory_chat_24722005 = "A fantastic vanilla grows here...",
  str_homestory_chat_24722006 = "Ramen tastes great with it!",
  str_homestory_chat_24722007 = "I picked too much last time.",
  str_homestory_chat_24722008 = "That's how the grass became barren...",
  str_homestory_chat_24723001 = "Looking for me?",
  str_homestory_chat_24723002 = "Dear customer, are we having a party soon?",
  str_homestory_chat_24723003 = "Our profit has dropped...",
