  str_homestory_chat_24723011 = "Excellent...",
  str_homestory_chat_24723012 = "The Kaniya Ramen is saved!",
  str_homestory_chat_24723013 = "A party...",
  str_homestory_chat_24723014 = "We sell 100 bowls!",
  str_homestory_chat_26399999 = "Whoa! The Airship Boss!",
  str_homestory_chat_26301001 = "Don't.",
  str_homestory_chat_26301002 = "Don't call me that! It sounds so weird!",
  str_homestory_chat_26301003 = "How about... Colossus Boss?",
  str_homestory_chat_26301004 = "... Whatever...",
  str_homestory_chat_26321001 = "How are you adjusting to the new life?",
  str_homestory_chat_26321002 = "Not bad. Thank you for your generosity.",
  str_homestory_chat_26321003 = "Boss, do you play Al***my St**s?",
