  str_homestory_chat_26321006 = "Enough. Not going to work!",
  str_homestory_chat_26321007 = "Yes!",
  str_homestory_chat_26321008 = "Whoa! That's great!",
  str_homestory_chat_26321009 = "I'll find you a game machine right away!",
  str_homestory_chat_26322001 = "You want to see me?",
  str_homestory_chat_26322002 = "Was there a new skilled painter recently?",
  str_homestory_chat_26322003 = "Yes.",
  str_homestory_chat_26322004 = "Really? Could you introduce me?",
  str_homestory_chat_26322005 = "I'll create a character like you in Al***my St**s in return!",
  str_homestory_chat_26322006 = "I don't think so...",
  str_homestory_chat_26322007 = "Urghh...",
  str_homestory_chat_26322008 = "I guess I must go on another world travel.",
  str_homestory_chat_26323001 = "You look really happy.",
  str_homestory_chat_26323002 = "I saw a perfect painting the other day!",
  str_homestory_chat_26323003 = "With graceful lines and bold but harmonious colors!",
  str_homestory_chat_26323004 = "And it covers all secrets of the universe!",
  str_homestory_chat_26323005 = "I spent a fortune on it. I actually have nothing left to keep up with the cost of living!",
  str_homestory_chat_26323006 = "What are you trying to say?",
  str_homestory_chat_26323007 = "Boss! I'm broke... Would you feed me?",
  str_homestory_chat_24899999 = "Huh, Caelestite?",
  str_homestory_chat_24801001 = "Hello, Azure.",
  str_homestory_chat_24801002 = "Wanna play with me?",
  str_homestory_chat_24801003 = "Just came to say hi...",
  str_homestory_chat_24801004 = "That's all? You sure there's nothing more you want to do?",
  str_homestory_chat_24821001 = "What's your plan for today?",
  str_homestory_chat_24821002 = "Washing my car. Are you coming?",
  str_homestory_chat_24821003 = "Where?",
  str_homestory_chat_24821004 = "I don't think we have a carwash nearby...",
