  str_homestory_chat_24821007 = "How to wash?",
  str_homestory_chat_24821008 = "Hahah. What kind of question is this?",
  str_homestory_chat_24821009 = "Of course with water.",
  str_homestory_chat_24821010 = "Come. Let me show you how to wash a car.",
  str_homestory_chat_24822001 = "You want to ask me something?",
  str_homestory_chat_24822002 = "Don't we have a shooting range here?",
  str_homestory_chat_24822003 = "No...",
  str_homestory_chat_24822004 = "Sigh... Boring...",
  str_homestory_chat_24822005 = "I'll have to aim at flower pots.",
