  str_homestory_chat_24822007 = "I said aim, not fire.",
  str_homestory_chat_24822008 = "Of course we do!",
  str_homestory_chat_24822009 = "Those who lie to my face will suffer painfully.",
  str_homestory_chat_24822010 = "If I can't find the shooting range you have promised, guess what would happen to you.",
  str_homestory_chat_24823001 = "Are you looking for someone?",
  str_homestory_chat_24823002 = "Where are those Umbraton blokes?",
  str_homestory_chat_24823003 = "I haven't seen any...",
  str_homestory_chat_24823004 = "Sigh... Not sure if you are a good drinker.",
  str_homestory_chat_24823005 = "Since I can't find any of them, I guess it's not bad to have a drink with you.",
  str_homestory_chat_24823006 = "They are over there.",
  str_homestory_chat_24823007 = "... Those? Not good enough to drink with me.",
  str_homestory_chat_24823008 = "Who should I drink with?",
  str_homestory_chat_24824001 = "How are you settling?",
  str_homestory_chat_24824002 = "Getting bored...",
  str_homestory_chat_24824003 = "The only fun I have here is from watching lovely young boys.",
  str_homestory_chat_24824004 = "PlayerName, who do you think is the cutest here?",
  str_homestory_chat_24824005 = "Hard to say...",
  str_homestory_chat_24824006 = "Everyone is quite lovely in my opinion!",
  str_homestory_chat_24824007 = "Including me?",
  str_homestory_chat_24824008 = "Err...",
  str_homestory_chat_24824009 = "Me.",
  str_homestory_chat_24824010 = "... Ah... That's a bit of an immodest outcry.",
  str_homestory_chat_24999999 = "What brought you to see this old man?",
  str_homestory_chat_24901001 = "Nothing in particular..",
  str_homestory_chat_24901002 = "I was passing by and stopped to say hi...",
  str_homestory_chat_24901003 = "That's very honest of you.",
  str_homestory_chat_24901004 = "Or is it because you couldn't say any deceptive sweet words to my face?",
  str_homestory_chat_24921001 = "You like dolls?",
  str_homestory_chat_24921002 = "Yes, young man. How about you?",
  str_homestory_chat_24921003 = "Me too!",
  str_homestory_chat_24921004 = "There are a few reward dolls left from last race. Do you mind keeping them?",
  str_homestory_chat_24921005 = "Not at all!",
  str_homestory_chat_24921006 = "Excellent. I'll drop them by shortly.",
  str_homestory_chat_24921007 = "Not a fan...",
  str_homestory_chat_24921008 = "Ahh... The little ones in my family all seem to enjoy them...",
  str_homestory_chat_24921009 = "I thought you'd be the same.",
  str_homestory_chat_24921010 = "I guess the pile of bunny dolls will have to stay in my room.",
  str_homestory_chat_24922001 = "You seem bored.",
  str_homestory_chat_24922002 = "Yeah... The little ones left a few days ago for a climbing trip...",
  str_homestory_chat_24922003 = "Staying here all by myself is quite lonely.",
  str_homestory_chat_24922004 = "Why didn't you go?",
  str_homestory_chat_24922005 = "Just look at my leg...",
  str_homestory_chat_24922006 = "Take a few extra steps and it will be cracking.",
  str_homestory_chat_24922007 = "Climbing mountains is not for me anymore.",
  str_homestory_chat_24923001 = "How do you feel about this place?",
  str_homestory_chat_24923002 = "... Such a wonderful place.",
  str_homestory_chat_24923003 = "That guy would have loved it here was he still around...",
  str_homestory_chat_24923004 = "... You didn't hear my murmuring, did you?",
  str_homestory_chat_24923005 = "I heard everything...",
  str_homestory_chat_24923006 = "... At least I didn't say anything bad about this place.",
  str_homestory_chat_24923007 = "Announce yourself before approaching next time!",
  str_homestory_chat_24923008 = "Not at all.",
  str_homestory_chat_24923009 = "Sigh... Not a good liar...",
  str_homestory_chat_24923010 = "It doesn't really matter if you heard.",
  str_homestory_chat_25299999 = "...",
  str_homestory_chat_25201001 = "Hello, May.",
  str_homestory_chat_25201002 = "You... You greeted me?",
  str_homestory_chat_25201003 = "What shall I do? How should I reply?",
  str_homestory_chat_25201004 = "... I really wish I could answer you... Are you upset with me?",
  str_homestory_chat_25201005 = "I just came to say hi. It's no big deal.",
  str_homestory_chat_25221001 = "What are you doing?",
  str_homestory_chat_25221002 = "There, there. Mommy is here...",
  str_homestory_chat_25221003 = "Obviously looking after my Mr. Beau.",
  str_homestory_chat_25221004 = "Beau's hair gets tangled easily... It irritates me...",
  str_homestory_chat_25221005 = "No! I must be patient for my baby!",
  str_homestory_chat_25221006 = "(I should probably just go...)",
  str_homestory_chat_25222001 = "What's on your mind?",
  str_homestory_chat_25222002 = "Do you like flowers?",
  str_homestory_chat_25222003 = "Very.",
  str_homestory_chat_25222004 = "I can pick some flowers and sew them on your clothes. How does it sound?",
  str_homestory_chat_25222005 = "I... Gift you things you like...",
  str_homestory_chat_25222006 = "Would you like me a little more?",
  str_homestory_chat_25222007 = "Nah.",
  str_homestory_chat_25222008 = "No? What do you like then?",
  str_homestory_chat_25222009 = "Why did you ask all of a sudden?",
  str_homestory_chat_25222010 = "I... I... It's okay if you don't want to answer.",
  str_homestory_chat_25223001 = "Were you sucking your fingers?",
  str_homestory_chat_25223002 = "Um...",
  str_homestory_chat_25223003 = "Don't!",
  str_homestory_chat_25223004 = "It's unhygienic!",
  str_homestory_chat_25223005 = "Ah... PlayerName, is this the start of your dislike for me?",
  str_homestory_chat_25223006 = "Nonsense...",
  str_homestory_chat_25223007 = "You didn't realize?",
  str_homestory_chat_25223008 = "Let me check for teeth mark first...",
  str_homestory_chat_25099999 = "PlayerName, finally you have tasks for Lenore?",
  str_homestory_chat_25001001 = "No, not really.",
  str_homestory_chat_25001002 = "Just came to say hi.",
  str_homestory_chat_25001003 = "What should Lenore do?",
  str_homestory_chat_25001004 = "Just make yourself comfortable...",
  str_homestory_chat_25021001 = "What was that?",
  str_homestory_chat_25021002 = "It was my stomach talking to me.",
  str_homestory_chat_25021003 = "Ahh?",
  str_homestory_chat_25021004 = "Listen. It rumbles.",
  str_homestory_chat_25021005 = "Hungry?",
  str_homestory_chat_25021006 = "Shall we eat something?",
  str_homestory_chat_25021007 = "Is this an order from PlayerName?",
  str_homestory_chat_25021008 = "It could be if it can end your suffering from hunger.",
  str_homestory_chat_25022001 = "What are you murmuring?",
  str_homestory_chat_25022002 = "Remember... Wind it up today...",
  str_homestory_chat_25022003 = "Wind it up?",
  str_homestory_chat_25022004 = "Ah... I completely forgot. I don't need this anymore.",
  str_homestory_chat_25022005 = "I'm already an Aurorian but some old habit is still there...",
  str_homestory_chat_25022006 = "Don't worry. Take all the time you need to slowly adjust.",
  str_homestory_chat_25023001 = "Are you looking at me?",
  str_homestory_chat_25023002 = "PlayerName, does it make you happy seeing other people laughing?",
  str_homestory_chat_25023003 = "Yes.",
  str_homestory_chat_25023004 = "Happiness is contagious!",
  str_homestory_chat_25023005 = "Lenore's right.",
  str_homestory_chat_25023006 = "I feel happy when I see you.",
  str_homestory_chat_25023007 = "And I learned new things today.",
  str_homestory_chat_25023008 = "Not really.",
  str_homestory_chat_25023009 = "Lenore saw you laughing today and Lenore wanted to laugh...",
  str_homestory_chat_25023010 = "What was that feeling Lenore had?",
  str_homestory_chat_25024001 = "You went for a long walk?",
  str_homestory_chat_25024002 = "Lenore walked a lot today.",
  str_homestory_chat_25024003 = "Before, walking was just walking for Lenore...",
  str_homestory_chat_25024004 = "Now I can feel the wind, smell the flowers and rub rocks under my feet...",
  str_homestory_chat_25024005 = "Those are some delicate feelings you have...",
  str_homestory_chat_25024006 = "PlayerName, you are welcome to join Lenore.",
  str_homestory_chat_25199999 = "Hmm? PlayerName...",
  str_homestory_chat_25101001 = "Hello, Giles.",
  str_homestory_chat_25101002 = "You must be here for my new nursery rhyme!",
  str_homestory_chat_25101003 = "Would you like to hear?",
  str_homestory_chat_25101004 = "Err... Hmm...",
  str_homestory_chat_25121001 = "Can you smell this lovely fragrance?",
  str_homestory_chat_25121002 = "Fragrance? Yes!",
  str_homestory_chat_25121003 = "But the source of this smell is already in my stomach.",
  str_homestory_chat_25121004 = "What did you eat?",
  str_homestory_chat_25121005 = "Hahah. Is this your face of terror?",
  str_homestory_chat_25121006 = "I had...",
  str_homestory_chat_25121007 = "Meat!",
  str_homestory_chat_25122001 = "What's the matter?",
  str_homestory_chat_25122002 = "... I think... I just had another dream...",
  str_homestory_chat_25122003 = "Did I talk in my sleep?",
  str_homestory_chat_25122004 = "I didn't hear a thing...",
  str_homestory_chat_25122005 = "Thank heaven. Or you'll become the next victim of nightmares.",
  str_homestory_chat_25122006 = "I believe so...",
  str_homestory_chat_25122007 = "You didn't hear what I said, did you?",
  str_homestory_chat_25122008 = "You wouldn't be like this if you did.",
  str_homestory_chat_25123001 = "You said...",
  str_homestory_chat_25123002 = "You hadn't written any nursery rhyme for a long time...",
  str_homestory_chat_25123003 = "PlayerName, what kind of nursery rhymes would you like to hear?",
  str_homestory_chat_25123004 = "About Aurorians?",
  str_homestory_chat_25123005 = "Silly yet smart, too noisy to ever quiet down...",
  str_homestory_chat_25123006 = "Navigator, take a guess. What Aurorian is this?",
  str_homestory_chat_25123007 = "About Eclipsites?",
  str_homestory_chat_25123008 = "Sure!",
  str_homestory_chat_25123009 = "As long as PlayerName is not afraid of nightmares.",
  str_homestory_chat_25123010 = "About home?",
  str_homestory_chat_25123011 = "Speaking of home... *Yawns* I'm getting sleepy...",
  str_homestory_chat_25123012 = "I'll sing you a song about home after this nap.",
  str_homestory_chat_25399999 = "Oh, hi!",
  str_homestory_chat_25301001 = "Woah!",
  str_homestory_chat_25301002 = "Couldn't help standing up straight...",
  str_homestory_chat_25321001 = "Why are you staring at me?",
  str_homestory_chat_25321002 = "Hungry?",
  str_homestory_chat_25321003 = "A little...",
  str_homestory_chat_25321004 = "How does risotto sound?",
  str_homestory_chat_25321005 = "Please call everyone over to have a taste of my cooking!",
  str_homestory_chat_25321006 = "Not yet.",
  str_homestory_chat_25321007 = "That's okay.",
  str_homestory_chat_25321008 = "I plan to cook risotto for everyone.",
  str_homestory_chat_25321009 = "You cook?",
  str_homestory_chat_25321010 = "Hahah. You seem surprised?",
  str_homestory_chat_25321011 = "You shouldn't be surprised by anything I do.",
  str_homestory_chat_25322001 = "How do you like this place?",
  str_homestory_chat_25322002 = "How leisurely.",
  str_homestory_chat_25322003 = "Stay here a bit longer and I'll forget all about what war even looks like.",
  str_homestory_chat_25322004 = "Do you think that this isn't a good thing?",
  str_homestory_chat_25322005 = "Who said that?",
  str_homestory_chat_25322006 = "To make Illumina, and the entire continent...",
  str_homestory_chat_25322007 = "A land of peace and happiness like this is my life's dream.",
  str_homestory_chat_25323001 = "Hey! How's your day?",
  str_homestory_chat_25323002 = "... You look worn out.",
  str_homestory_chat_25323003 = "Do I?",
  str_homestory_chat_25323004 = "I stayed up late last night playing games... Could that be the reason?",
  str_homestory_chat_25323005 = "Go for a run and the wind will freshen you up.",
  str_homestory_chat_25323006 = "You sound a little strange.",
  str_homestory_chat_25323007 = "Hahah. I guess normally I would just tell you to buck up.",
  str_homestory_chat_25323008 = "Maybe...",
  str_homestory_chat_25323009 = "You are the host here and I'm a guest.",
  str_homestory_chat_25323010 = "I understand the social etiquette.",
  str_homestory_chat_25324001 = "You want to see me?",
  str_homestory_chat_25324002 = "I was talking to Vice and learned that you've been training hard recently.",
  str_homestory_chat_25324003 = "Ah... You heard.",
  str_homestory_chat_25324004 = "I don't mean to interfere with your exercising...",
  str_homestory_chat_25324005 = "But in my humble opinion, it can be helpful to have a reliable partner.",
  str_homestory_chat_25324006 = "Come to me when you run into any problems during training.",
  str_homestory_chat_25324007 = "I'll help you anytime.",
  str_homestory_chat_25499999 = "Hi, PlayerName. It's a lovely day today.",
  str_homestory_chat_25401001 = "Hi, Vice.",
  str_homestory_chat_25401002 = "You look...",
  str_homestory_chat_25401003 = "We all should try a different style once in a while. What do you think?",
  str_homestory_chat_25401004 = "It suits you!",
  str_homestory_chat_25421001 = "How do you feel today?",
  str_homestory_chat_25421002 = "I did some target practice just now.",
  str_homestory_chat_25421003 = "With that crossbow?",
  str_homestory_chat_25421004 = "Yes. And I figured out how to fire quickly.",
  str_homestory_chat_25421005 = "Basically, it's all about how to quickly load the bow...",
  str_homestory_chat_25421006 = "Ah... Sounds like some Illumina Tech is employed.",
  str_homestory_chat_25421007 = "That's right!",
  str_homestory_chat_25421008 = "However, the drawback is quite significant... The string would break after a short while.",
  str_homestory_chat_25421009 = "I guess this needs further improvement.",
  str_homestory_chat_25422001 = "Any new plans?",
  str_homestory_chat_25422002 = "Yes. I'd like to reorganize the shooting range.",
  str_homestory_chat_25422003 = "Shooting range? We have one of those?",
  str_homestory_chat_25422004 = "Ah? I mean those trees over there...",
  str_homestory_chat_25422005 = "I've been using them as my target...",
  str_homestory_chat_25422006 = "Ah... Perfect. Those trees are thick and rough anyway.",
  str_homestory_chat_25422007 = "You could also use rocks.",
  str_homestory_chat_25422008 = "Rock target... A bit too low.",
  str_homestory_chat_25422009 = "And it's no good for the head of my bolt.",
  str_homestory_chat_25422010 = "Hmm... Sounds like we need a proper shooting range.",
  str_homestory_chat_25423001 = "Looking for me?",
  str_homestory_chat_25423002 = "PlayerName, do you know how to fish?",
  str_homestory_chat_25423003 = "Yes.",
  str_homestory_chat_25423004 = "Really?",
  str_homestory_chat_25423005 = "I just went the other day and got a few...",
  str_homestory_chat_25423006 = "It might just be a lucky day...",
  str_homestory_chat_25423007 = "Not really...",
  str_homestory_chat_25423008 = "Don't worry. I have a secret weapon.",
  str_homestory_chat_25423009 = "I'll modify this crossbow...",
  str_homestory_chat_25423010 = "Add a hook to the head of the bolt and attach it to a rope...",
  str_homestory_chat_25423011 = "This way you will catch fish, very quickly.",
  str_homestory_chat_25423012 = "Err... I don't think it can still be called fishing.",
  str_homestory_chat_25599999 = "Hello there! Hahah!",
  str_homestory_chat_25501001 = "Your clothes...",
  str_homestory_chat_25501002 = "Don't make such a big deal. I often dress like this.",
  str_homestory_chat_25501003 = "Alright, I'll get used to it.",
  str_homestory_chat_25501004 = "Yes, I look more impressive this way, according to many.",
  str_homestory_chat_25501005 = "I wonder who these people are.",
  str_homestory_chat_25521001 = "You want to ask me something?",
  str_homestory_chat_25521002 = "Which do you think is more effective in battle, a sword or a gun?",
  str_homestory_chat_25521003 = "A sword.",
  str_homestory_chat_25521004 = "I agree! It serves to pressure the enemy.",
  str_homestory_chat_25521005 = "In close-quarters combat, a swordsman can launch a series of strikes quickly.",
  str_homestory_chat_25521006 = "This is why this sword is my weapon of choice.",
  str_homestory_chat_25521007 = "A gun.",
  str_homestory_chat_25521008 = "Hmm... For a Caelestite?",
  str_homestory_chat_25521009 = "You guys have very sharp perception. You should be very accurate shots then.",
  str_homestory_chat_25521010 = "But I...",
  str_homestory_chat_25521011 = "You just need more practice. I'll draft up an intense training plan for you!",
  str_homestory_chat_25521012 = "And you will become a marksman after!",
  str_homestory_chat_25521013 = "Okay.",
  str_homestory_chat_25521014 = "I have no idea...",
  str_homestory_chat_25521015 = "Understandable. You are not a fighter after all.",
  str_homestory_chat_25521016 = "I should probably talk to someone else, such as Vice...",
  str_homestory_chat_25521017 = "Don't think too much about combat...",
  str_homestory_chat_25522001 = "Looking for me?",
  str_homestory_chat_25522002 = "My sword is getting dull. Do we have a decent whetstone here?",
  str_homestory_chat_25522003 = "Yes.",
  str_homestory_chat_25522004 = "A good one, smooth with fine barbs...",
  str_homestory_chat_25522005 = "Then I don't think we have any.",
  str_homestory_chat_25522006 = "No.",
  str_homestory_chat_25522007 = "Sigh... You're a Caelestite alright.",
  str_homestory_chat_25522008 = "A man of peace...",
  str_homestory_chat_25522009 = "Know nothing about the importance of weapon maintenance.",
  str_homestory_chat_25523001 = "What are you doing?",
  str_homestory_chat_25523002 = "... It's so quiet here.",
  str_homestory_chat_25523003 = "This seems like a good place to retire.",
  str_homestory_chat_25523004 = "Barton...",
  str_homestory_chat_25523005 = "Ah? You heard me? I was muttering to myself!",
  str_homestory_chat_25523006 = "Retire...",
  str_homestory_chat_25523007 = "But Barton, you are so young...",
  str_homestory_chat_25523008 = "Ah... I lost my mind for a second.",
  str_homestory_chat_25523009 = "I don't want to retire ever if it's up to me.",
  str_homestory_chat_25523010 = "It would be glorious to die fighting in a great war at a ripe old age.",
  str_homestory_chat_25523011 = "That's the best ending for a soldier.",
  str_homestory_chat_25523012 = "But you are a general...",
  str_homestory_chat_25699999 = "Hi PlayerName, nice seeing you again.",
  str_homestory_chat_25601001 = "Hi Nina.",
  str_homestory_chat_25601002 = "I want to ask you a question every time I come here.",
  str_homestory_chat_25601003 = "A question?",
  str_homestory_chat_25601004 = "Do all the Caelestites have a plain taste like this?",
  str_homestory_chat_25601005 = "Um... I guess.",
  str_homestory_chat_25601006 = "But it matches with the surrounding surprisingly, and it's a comfortable place to live in.",
  str_homestory_chat_25601007 = "Keep it this way then, don't follow those tacky trends in Umbraton.",
  str_homestory_chat_25601008 = "Thank you.",
  str_homestory_chat_25621001 = "You always carry an umbrella...",
  str_homestory_chat_25621002 = "Caelestite, what kind of umbrella are you talking about?",
  str_homestory_chat_25621003 = "I keep having this feeling that you are avoiding something.",
  str_homestory_chat_25621004 = "It's a parasol.",
  str_homestory_chat_25621005 = "I'm pleased that my teaching these days has been successful.",
  str_homestory_chat_25621006 = "(Phew... Finally, I guessed right.)",
  str_homestory_chat_25621007 = "What are you muttering about?",
  str_homestory_chat_25621008 = "Ah, nothing, bye.",
  str_homestory_chat_25621009 = "It's just an umbrella.",
  str_homestory_chat_25621010 = "I have told you so many times! It's a \"parasol,\" not an \"umbrella\"!",
  str_homestory_chat_25621011 = "Sigh... It's getting tiring that I have to repeat this every time.",
  str_homestory_chat_25621012 = "I, I will remember.",
  str_homestory_chat_25621013 = "Don't forget what we just talked about.",
  str_homestory_chat_25622001 = "Any plan later?",
  str_homestory_chat_25622002 = "I want to have afternoon tea, but I don't know if there is any tea here.",
  str_homestory_chat_25622003 = "I remember buying it from Umbraton and putting it in the store...",
  str_homestory_chat_25622004 = "So, is there a place for afternoon tea?",
  str_homestory_chat_25622005 = "You need to have a place?",
  str_homestory_chat_25622006 = "Afternoon tea is more than just drinking tea, it's about enjoying the moment.",
  str_homestory_chat_25622007 = "Location is very important, it should be a quiet, comfortable place with natural sounds.",
  str_homestory_chat_25622008 = "Natural sounds?",
  str_homestory_chat_25622009 = "For example, the occasional chirping of insects and passing birds, and the rustling of leaves.",
  str_homestory_chat_25622010 = "I'll try to find a place like this.",
  str_homestory_chat_25623001 = "What are you looking for?",
  str_homestory_chat_25623002 = "Do you have any good novels?",
  str_homestory_chat_25623003 = "What do you like?",
  str_homestory_chat_25623004 = "Do you have anything scary?",
  str_homestory_chat_25623005 = "Like horror novels...",
  str_homestory_chat_25623006 = "Actually... I do!",
  str_homestory_chat_25623007 = "I got \"108 Umbraton Horror Tales.\"",
  str_homestory_chat_25623008 = "What a cheap title... But looks like you like it?",
  str_homestory_chat_25623009 = "Alright, I'll read it with you then.",
  str_homestory_chat_25799999 = "Mr. Navigator, um... Hello.",
  str_homestory_chat_25701001 = "Hello.",
  str_homestory_chat_25701002 = "Um... I'm cleaning and working hard. I'm not slacking off.",
  str_homestory_chat_25701003 = "That's not what I mean...",
  str_homestory_chat_25701004 = "I just want to say hi.",
  str_homestory_chat_25701005 = "Wahhh... Well... I misunderstood, sorry.",
  str_homestory_chat_25701006 = "You don't have to be so polite, continue then.",
  str_homestory_chat_25721001 = "Your work...",
  str_homestory_chat_25721002 = "Ah! Am I doing it badly?",
  str_homestory_chat_25721003 = "No.",
  str_homestory_chat_25721004 = "You have done a lot, I mean, a little bit too much actually.",
  str_homestory_chat_25721005 = "This is... what a maid should do, right?",
  str_homestory_chat_25721006 = "You should take a break from time to time too.",
  str_homestory_chat_25721007 = "A little...",
  str_homestory_chat_25721008 = "Wahhh! Did I do something wrong?",
  str_homestory_chat_25721009 = "You are working too hard.",
  str_homestory_chat_25721010 = "Huh? Too hard?",
  str_homestory_chat_25721011 = "Doing the cleaning so early in the morning may wake people up.",
  str_homestory_chat_25721012 = "Well, I'll pay attention to that.",
  str_homestory_chat_25722001 = "How have you been lately?",
  str_homestory_chat_25722002 = "Wahhh, Mr. Navigator!",
  str_homestory_chat_25722003 = "I found something tasty the other day, and I think it's something local!",
  str_homestory_chat_25722004 = "What is it?",
  str_homestory_chat_25722005 = "There are a lot of small fish in the river, and they are hard to catch.",
  str_homestory_chat_25722006 = "Yeah, they are small and fast, quite hard to catch.",
  str_homestory_chat_25722007 = "So I made a fishing net, scooped them up, washed them...",
  str_homestory_chat_25722008 = "Then I mashed them, mixed the fish with salt, and made a sandwich with it. It tasted so fresh and tender!",
  str_homestory_chat_25722009 = "You had it raw?",
  str_homestory_chat_25722010 = "You should cook it properly next time, or you might get sick...",
  str_homestory_chat_25722011 = "Oh, I won't! I should make it for you next time.",
  str_homestory_chat_25722012 = "Err... I think I'll pass.",
  str_homestory_chat_25723001 = "Sanae, err...",
  str_homestory_chat_25723002 = "Wahhh, did I do something wrong again?",
  str_homestory_chat_25723003 = "I heard...",
  str_homestory_chat_25723004 = "You accidentally pulled the door out when you were cleaning it the other day.",
  str_homestory_chat_25723005 = "And shocked the nearby Chubbs.",
  str_homestory_chat_25723006 = "I-I'm sorry! It's hard to control myself...",
  str_homestory_chat_25723007 = "I have fixed the door!",
  str_homestory_chat_25723008 = "Well, it was not your fault actually, there was something wrong with that door.",
  str_homestory_chat_25723009 = "Ahhh, Mr. Navigator! I'll work on that!",
  str_homestory_chat_25723010 = "Hmmm... It's a party, nothing bad...",
  str_homestory_chat_25723011 = "It's, it's about the door, right?",
  str_homestory_chat_25723012 = "Ah, that. It's fine. You have fixed it anyway.",
  str_homestory_chat_25723013 = "It's just, your strength is...",
  str_homestory_chat_25723014 = "It's a pity for you to be a maid, isn't it?",
  str_homestory_chat_25723015 = "Pleeeease don't fire me!",
  str_homestory_chat_25723016 = "I'll work even harder! Pay attention to every detail, wahhh...",
  str_homestory_chat_25723017 = "That's not what I mean...",
  str_homestory_chat_26499999 = "We meet again, PlayerName.",
  str_homestory_chat_26401001 = "Welcome.",
  str_homestory_chat_26401002 = "What brings you to Cloud Gardens today?",
  str_homestory_chat_26401003 = "I wanted to check out the buildings here.",
  str_homestory_chat_26401004 = "And think about the relationship between Cloud Gardens and Lumopolis.",
  str_homestory_chat_26401005 = "You look very serious.",
  str_homestory_chat_26401006 = "Hm? Yeah, I guess so.",
  str_homestory_chat_26401007 = "I think about deep things whenever I put on these clothes.",
  str_homestory_chat_26401008 = "You should relax while you're here.",
  str_homestory_chat_26402001 = "Are you free right now?",
  str_homestory_chat_26402002 = "Yes, because Cloud Gardens is a very relaxing place.",
  str_homestory_chat_26402003 = "If I want to exercise or train here, what would you suggest me do?",
  str_homestory_chat_26402004 = "Martial arts?",
  str_homestory_chat_26402005 = "Not bad, but I don't think that goes with the vibe here.",
  str_homestory_chat_26402006 = "It feels wrong to swing weapons here.",
  str_homestory_chat_26402007 = "True. How about a stroll by the river?",
  str_homestory_chat_26402008 = "It's not really a vigorous workout, but it's good for the body if you do it for a long time.",
  str_homestory_chat_26402009 = "Not bad. The view is great, and helps with the thinking.",
  str_homestory_chat_26402010 = "Chess?",
  str_homestory_chat_26402011 = "A good suggestion. It's a game of war fought on a board.",
  str_homestory_chat_26402012 = "It trains focus, strategy, and the ability to see the bigger picture.",
  str_homestory_chat_26402013 = "I suppose I'll play a few rounds tonight.",
  str_homestory_chat_26403001 = "What are you thinking?",
  str_homestory_chat_26403002 = "I'm thinking about your view on Cloud Gardens.",
  str_homestory_chat_26403003 = "A home.",
  str_homestory_chat_26403004 = "A shelter.",
  str_homestory_chat_26403005 = "They're more or less the same. That means it's the only answer in your heart.",
  str_homestory_chat_26403006 = "It's not that different from what I expected. It's your home, after all.",
  str_homestory_chat_26403007 = "But maybe Lumopolis is a different story.",
  str_homestory_chat_26403008 = "What do you mean?",
  str_homestory_chat_26403009 = "To the rest of the continent, Cloud Gardens feels like a paradise.",
  str_homestory_chat_26403010 = "It doesn't always feel real.",
  str_homestory_chat_26404001 = "Looking for me?",
  str_homestory_chat_26404002 = "Have you considered the Cloud Gardens' construction issues?",
  str_homestory_chat_26404003 = "I don't think so...",
  str_homestory_chat_26404004 = "They require extensive pre-planning.",
  str_homestory_chat_26404005 = "You're right. Got any ideas?",
  str_homestory_chat_26404006 = "Some, but I always feel like I'm short on labor and money.",
  str_homestory_chat_26404007 = "Such as?",
  str_homestory_chat_26404008 = "It takes a lot of labor to build a wall to protect the city.",
  str_homestory_chat_26404009 = "I... I think that's not necessary.",
  str_homestory_chat_26405001 = "What is it?",
  str_homestory_chat_26405002 = "You're the owner of Cloud Gardens now, and its leader.",
  str_homestory_chat_26405003 = "What do you think about leadership? What do you suppose is the most important thing when it comes to it?",
  str_homestory_chat_26405004 = "Affinity.",
  str_homestory_chat_26405005 = "The power to gather people around you?",
  str_homestory_chat_26405006 = "I just like to be around people.",
  str_homestory_chat_26405007 = "That makes sense. I didn't think of this.",
  str_homestory_chat_26405008 = "Decisiveness.",
  str_homestory_chat_26405009 = "Of course! A leader doesn't need to be perfect in every single aspect, but they do need to be able to make key decisions.",
  str_homestory_chat_26405010 = "But it's more like a talent you're born with, and not something that can be trained.",
  str_homestory_chat_26599999 = "PlayerName! Here you are!",
  str_homestory_chat_26501001 = "Hey! What are you up to?",
  str_homestory_chat_26501002 = "I was thinking about a new formula I saw the other day.",
  str_homestory_chat_26501003 = "About how to apply the conversion in real life.",
  str_homestory_chat_26501004 = "Construction material? Or reinforcing an existing structure?",
  str_homestory_chat_26501005 = "I'll leave you to it.",
  str_homestory_chat_26502001 = "What are you looking for?",
  str_homestory_chat_26502002 = "Do you have any special ores?",
  str_homestory_chat_26502003 = "I've been looking for new materials.",
  str_homestory_chat_26502004 = "I'm not sure. They all look the same to me.",
  str_homestory_chat_26502005 = "I knew you would say that.",
  str_homestory_chat_26502006 = "I guess I'll have to check it one by one, and run analysis on the soil...",
  str_homestory_chat_26502007 = "You... have to do this for the entire Cloud Gardens?",
  str_homestory_chat_26502008 = "Yes, that's what I have to do to find rare ores and discover new materials.",
  str_homestory_chat_26502009 = "That's going to take a long time.",
  str_homestory_chat_26502010 = "Maybe get the Chubbs to help?",
  str_homestory_chat_26502011 = "...I think I'll pass.",
  str_homestory_chat_26503001 = "What are you doing?",
  str_homestory_chat_26503002 = "I'm measuring.",
  str_homestory_chat_26503003 = "Measuring?",
  str_homestory_chat_26503004 = "Yes, the angle of the sun, the direction of the wind, the intensity of the sounds of nature...",
  str_homestory_chat_26503005 = "What for?",
  str_homestory_chat_26503006 = "I'm looking for the perfect position for a hammock.",
  str_homestory_chat_26503007 = "A hammock?",
  str_homestory_chat_26503008 = "Yes, don't they look comfortable?",
  str_homestory_chat_26503009 = "When you're on one, it feels like you're flying in the sky.",
  str_homestory_chat_26503010 = "You can fall asleep easily.",
  str_homestory_chat_26503011 = "But what does the hammock have to do with what you're measuring?",
  str_homestory_chat_26503012 = "Because it has to do with where I want to take a nice nap on a sunny afternoon.",
  str_homestory_chat_26503013 = "A nap outside sounds pretty good.",
  str_homestory_chat_26503014 = "You should give it a try, PlayerName.",
  str_homestory_chat_26504001 = "You were looking for me?",
  str_homestory_chat_26504002 = "Is it possible to renovate the dorms?",
  str_homestory_chat_26504003 = "That's going to be difficult.",
  str_homestory_chat_26504004 = "Construction-wise, there's nothing to worry about!",
  str_homestory_chat_26504005 = "I'm worried about the trouble it'll bring, because once renovation starts, we can't have any guests.",
  str_homestory_chat_26504006 = "You're right, I didn't think about that.",
  str_homestory_chat_26504007 = "Can we ask them to not come to Cloud Gardens for a while?",
  str_homestory_chat_26504008 = "Probably not...",
  str_homestory_chat_26504009 = "How are you planning to renovate?",
  str_homestory_chat_26504010 = "Add load-bearing walls and shear walls on the sides to create two rooms, and convert the room in the middle into a lounge.",
  str_homestory_chat_26504011 = "That way there are spaces for both sleeping and hanging out. I've also taken daylighting into consideration.",
  str_homestory_chat_26504012 = "But this sounds like it's going to take a long time, and I don't think we have the manpower...",
  str_homestory_chat_26504013 = "I can take care of all the labor!",
  str_homestory_chat_26504014 = "The mecha can dig foundations, lay down beams and even build walls.",
  str_homestory_chat_26504015 = "It'll also excavate ancient ruins and drill tunnels!",
  str_homestory_chat_26504016 = "Amazing!",
  str_homestory_chat_26504017 = "But shouldn't this be applied elsewhere? Like building a subway for Illumina or something.",
  str_homestory_chat_26504018 = "That's your actual job. Cloud Gardens is for when you want to take a break.",
  str_homestory_chat_26504019 = "Made sense.",
  str_homestory_chat_26699999 = "Hey, PlayerName!",
  str_homestory_chat_26601001 = "Hey, Fia!",
  str_homestory_chat_26601002 = "Why are you imitating me?",
  str_homestory_chat_26601003 = "I think it brings us closer.",
  str_homestory_chat_26601004 = "You could have used a different greeting.",
  str_homestory_chat_26601005 = "I think \"hey\" goes well with you.",
  str_homestory_chat_26601006 = "Well, fine then.",
  str_homestory_chat_26602001 = "Are you looking for critters?",
  str_homestory_chat_26602002 = "Yes! I thought they'd be all over Cloud Gardens, but I haven't seen a single one!",
  str_homestory_chat_26602003 = "Have you seen any? You must have!",
  str_homestory_chat_26602004 = "Nope.",
  str_homestory_chat_26602005 = "Hmph, I bet you're lying!",
  str_homestory_chat_26602006 = "Should I take out my gun?",
  str_homestory_chat_26602007 = "Fia!",
  str_homestory_chat_26602008 = "You're making me angry.",
  str_homestory_chat_26602009 = "I... I'll look for them myself then.",
  str_homestory_chat_26602010 = "Of course!",
  str_homestory_chat_26602011 = "Really? Where?",
  str_homestory_chat_26602012 = "There are plenty of fish in the river.",
  str_homestory_chat_26602013 = "They don't count!",
  str_homestory_chat_26602014 = "Why not?",
  str_homestory_chat_26602015 = "I'm looking for the ones that are really cute and smart!",
  str_homestory_chat_26602016 = "Oh, wondrous beasts. Then... maybe we don't have them.",
  str_homestory_chat_26603001 = "What are you looking for?",
  str_homestory_chat_26603002 = "How about something shiny? Like...",
  str_homestory_chat_26603003 = "Ores?",
  str_homestory_chat_26603004 = "Fish?",
  str_homestory_chat_26603005 = "Not *those*!",
  str_homestory_chat_26603006 = "I'm talking about shiny and exquisite things!",
  str_homestory_chat_26603007 = "Like stuff you can put on your bags and shoes.",
  str_homestory_chat_26603008 = "Pearls?",
  str_homestory_chat_26603009 = "Yes! Where can I find those?",
  str_homestory_chat_26603010 = "By the river? I think others have fished up shells before.",
  str_homestory_chat_26603011 = "But you could also end up with torn boots or weeds.",
  str_homestory_chat_26603012 = "I don't know if I can trust you...",
  str_homestory_chat_26604001 = "How's Kyllo been?",
  str_homestory_chat_26604002 = "It's gotten plump!",
  str_homestory_chat_26604003 = "Plump?",
  str_homestory_chat_26604004 = "Yes, it hasn't been exercising lately, and just hangs around me all day.",
  str_homestory_chat_26604005 = "Maybe you shouldn't feed it so much food?",
  str_homestory_chat_26604006 = "But Kyllo doesn't even need to eat...",
  str_homestory_chat_26604007 = "Then maybe take it out more often.",
  str_homestory_chat_26605001 = "Are you looking for trees?",
  str_homestory_chat_26605002 = "Yes! Aren't there a lot of strange looking trees in Cloud Gardens?",
  str_homestory_chat_26605003 = "Do you think there are wondrous beasts up there?",
  str_homestory_chat_26605004 = "Maybe?",
  str_homestory_chat_26605005 = "Really?! Then please pay attention when you take care of the trees.",
  str_homestory_chat_26605006 = "Okay.",
  str_homestory_chat_26605007 = "I feel like my tasks just keep piling on...",
  str_homestory_chat_26605008 = "Not really.",
  str_homestory_chat_26605009 = "Is that so? I think the trees are very interesting.",
  str_homestory_chat_26605010 = "Doesn't mean that the critters will take to them though.",
  str_homestory_chat_26799999 = "Have you discovered any new miracles around you today?",
  str_homestory_chat_26701001 = "What are you doing?",
  str_homestory_chat_26701002 = "I noticed that the Chubbs almost never stop working.",
  str_homestory_chat_26701003 = "So I've been thinking about performing magic tricks for them.",
  str_homestory_chat_26701004 = "I don't think they need it.",
  str_homestory_chat_26701005 = "No, I think they need entertainment.",
  str_homestory_chat_26701006 = "I guess... you do you then.",
  str_homestory_chat_26702001 = "Can you tell fortunes?",
  str_homestory_chat_26702002 = "It's a piece of cake.",
  str_homestory_chat_26702003 = "What do you want to know about? Career? Relationships? Wealth?",
  str_homestory_chat_26702004 = "Work.",
  str_homestory_chat_26702005 = "It'll go very smoothly.",
  str_homestory_chat_26702006 = "Really?",
  str_homestory_chat_26702007 = "At least your job here, anyway. Keep working, and good things will come.",
  str_homestory_chat_26702008 = "Thank you.",
  str_homestory_chat_26702009 = "Must be because it's so peaceful here.",
  str_homestory_chat_26702010 = "Wealth.",
  str_homestory_chat_26702011 = "You will constantly be spending a lot of money in the foreseeable future, but it's for your own good.",
  str_homestory_chat_26702012 = "For my own good?",
  str_homestory_chat_26702013 = "Maybe it's for developing this place further.",
  str_homestory_chat_26703001 = "Your magic...",
  str_homestory_chat_26703002 = "Is it the sleight of hand type? Or is it Luminatics?",
  str_homestory_chat_26703003 = "What do you think?",
  str_homestory_chat_26703004 = "Sleight of hand.",
  str_homestory_chat_26703005 = "Luminatics.",
  str_homestory_chat_26703006 = "They're both right, and they're both wrong.",
  str_homestory_chat_26703007 = "I don't get it.",
  str_homestory_chat_26703008 = "It depends on your perspective.",
  str_homestory_chat_26703009 = "If you think the magic is not real, then it's sleight of hand.",
  str_homestory_chat_26703010 = "If you think it's real, then it's Luminatics.",
  str_homestory_chat_26703011 = "This is not helping...",
  str_homestory_chat_26704001 = "What's on your mind?",
  str_homestory_chat_26704002 = "Sometimes I wonder if we need to perceive magic differently.",
  str_homestory_chat_26704003 = "How so?",
  str_homestory_chat_26704004 = "For example, sometimes you ask an audience to come up for a card trick.",
  str_homestory_chat_26704005 = "Most people only think about how the magician will fool the audience.",
  str_homestory_chat_26704006 = "Yep.",
  str_homestory_chat_26704007 = "But what if the magician already worked it out with the person?",
  str_homestory_chat_26704008 = "I see, it's a matter of perspective.",
  str_homestory_chat_26705001 = "What's your favorite drink?",
  str_homestory_chat_26705002 = "Black coffee, with no sugar and no milk.",
  str_homestory_chat_26705003 = "But that's bitter.",
  str_homestory_chat_26705004 = "The sweetness comes after the bitterness.",
  str_homestory_chat_26705005 = "And it doesn't make me gain weight.",
  str_homestory_chat_26705006 = "Ah, so that's actually why.",
  str_homestory_chat_26705007 = "As a magician, I must stay agile at all times.",
  str_homestory_chat_26899999 = "How's your day going?",
  str_homestory_chat_26801001 = "What are you doing?",
  str_homestory_chat_26801002 = "I'm tuning my water pistol and getting ready to cool everyone off!",
  str_homestory_chat_26801003 = "How?",
  str_homestory_chat_26801004 = "I'm just gonna spray some water, get a little drizzle going! I can water the plants that way, too.",
  str_homestory_chat_26801005 = "Watering plants is fine, but if you're gonna make it rain, we'll need umbrellas, and that's a pain.",
  str_homestory_chat_26802001 = "You want to swim?",
  str_homestory_chat_26802002 = "Yeah, there's a river nearby, right?",
  str_homestory_chat_26802003 = "The waters don't seem too turbulent, and the depth looks just right.",
  str_homestory_chat_26802004 = "You really like swimming, don't you?",
  str_homestory_chat_26802005 = "Because I grew up by... no, ON the sea.",
  str_homestory_chat_26802006 = "The ocean is my family.",
  str_homestory_chat_26802007 = "But the water in the river is fresh, can you get used to it?",
  str_homestory_chat_26802008 = "I'm not an ocean fish, you know.",
  str_homestory_chat_26802009 = "Oh, right. Sorry about that.",
  str_homestory_chat_26802010 = "Anyway, let's go swimming when we get a chance.",
  str_homestory_chat_26803001 = "What are you up to?",
  str_homestory_chat_26803002 = "I'm trying to practice my sight and agility.",
  str_homestory_chat_26803003 = "Why?",
  str_homestory_chat_26803004 = "It's really hard to catch fish in the river.",
  str_homestory_chat_26803005 = "They're fast, and I don't know what lies under the water. But also...",
  str_homestory_chat_26803006 = "The fish are not exactly where they are when seen from above.",
  str_homestory_chat_26803007 = "Right, something about refraction.",
  str_homestory_chat_26803008 = "Wait, didn't you grow up on the sea? You should be a veteran when it comes to catching fish.",
  str_homestory_chat_26803009 = "Yes, but I used to dive into the ocean to do that, so there's no refraction.",
  str_homestory_chat_26803010 = "And they're in large schools, so they were easy to catch.",
  str_homestory_chat_26803011 = "I see. I guess you'll just have to practice.",
  str_homestory_chat_26804001 = "You want to see me?",
  str_homestory_chat_26804002 = "That's right. Can you please find me some wood?",
  str_homestory_chat_26804003 = "What are you planning to do?",
  str_homestory_chat_26804004 = "I want to build a fleet on the water.",
  str_homestory_chat_26804005 = "A... fleet? Where?",
  str_homestory_chat_26804006 = "On the river! To protect Cloud Gardens.",
  str_homestory_chat_26804007 = "The fleet will fill up the river, because it's not very wide.",
  str_homestory_chat_26804008 = "Maybe a small... or a micro fleet.",
  str_homestory_chat_26804009 = "Build some small boats for patrolling...",
  str_homestory_chat_26804010 = "Who will pilot them?",
  str_homestory_chat_26804011 = "Good question! Chubbs?",
  str_homestory_chat_26804012 = "They're short, so the cabins can be smaller.",
  str_homestory_chat_26804013 = "What if they run into enemies?",
  str_homestory_chat_26804014 = "That's another good problem. Slingshot? Stones?",
  str_homestory_chat_26804015 = "Let's just hope it never comes down to that.",
  str_homestory_chat_27099999 = "How have you been lately, PlayerName?",
  str_homestory_chat_27001001 = "Not bad. You?",
  str_homestory_chat_27001002 = "Somewhat disappointed, to be honest.",
  str_homestory_chat_27001003 = "Disappointed?",
  str_homestory_chat_27001004 = "Mostly because it didn't rain enough! And it only drizzled!",
  str_homestory_chat_27001005 = "You like watching the rain, I see...",
  str_homestory_chat_27021001 = "I heard you've been looking for me?",
  str_homestory_chat_27021002 = "That's right. I want to build a huge playground.",
  str_homestory_chat_27021003 = "With slides, carousels, seesaws, and others for kids to play all day long.",
  str_homestory_chat_27021004 = "Why the sudden idea?",
  str_homestory_chat_27021005 = "Because it's not just for kids, many adults also like it.",
  str_homestory_chat_27021006 = "Especially some of your friends who are young at heart.",
  str_homestory_chat_27021007 = "The way you put it does make sense... Let me think about it.",
  str_homestory_chat_27022001 = "What would you like to know?",
  str_homestory_chat_27022002 = "Is there a smith familiar with guns around here?",
  str_homestory_chat_27022003 = "Nope.",
  str_homestory_chat_27022004 = "Yes.",
  str_homestory_chat_27022005 = "But I got to look for one.",
  str_homestory_chat_27022006 = "Is your gun broken?",
  str_homestory_chat_27022007 = "It needs recalibrating. Like people, guns get \"sick\" sometimes.",
  str_homestory_chat_27022008 = "This is when a smith is needed. They are doctors to the guns.",
  str_homestory_chat_27022009 = "Why not check out Umbraton?",
  str_homestory_chat_27022010 = "It's too far, and it would be nice for Cloud Gardens to have a resident gunsmith.",
  str_homestory_chat_27022011 = "I'm sure many of your buddies would need one, too. So, how about hiring a smith?",
  str_homestory_chat_27022012 = "I can recommend one to you, who's not expensive at all.",
  str_homestory_chat_27022013 = "What are you getting at now...?",
  str_homestory_chat_27023001 = "What are you looking at?",
  str_homestory_chat_27023002 = "Everything's great in Cloud Gardens, except it's a bit remote.",
  str_homestory_chat_27023003 = "That makes it hard to keep up with the trends in Umbraton.",
  str_homestory_chat_27023004 = "Have you been to Umbraton lately? Any new arrivals in fashion stores?",
  str_homestory_chat_27023005 = "I've been there.",
  str_homestory_chat_27023006 = "What new style do they have now? What's trending?",
  str_homestory_chat_27023007 = "Uh, I didn't pay attention to that...",
  str_homestory_chat_27023008 = "Nope.",
  str_homestory_chat_27023009 = "Argh, I knew I couldn't count on you.",
  str_homestory_chat_27023010 = "You ought to make more money and tell Chubbs to open a fashion store here.",
  str_homestory_chat_27023011 = "Or at least let the couriers deliver some fashion magazines...",
  str_homestory_chat_27024001 = "What are you doing?",
  str_homestory_chat_27024002 = "Not a thing. I haven't felt so laidback for a long time.",
  str_homestory_chat_27024003 = "This is indeed a peaceful place, and that can be frightening.",
  str_homestory_chat_27024004 = "Why is that?",
  str_homestory_chat_27024005 = "Peace would make you complacent. You need to be alert once in a while.",
  str_homestory_chat_27024006 = "It's very safe here. Not good to be wound up tight all the time, either.",
  str_homestory_chat_27024007 = "Okay... I see.",
  str_homestory_chat_27024008 = "No.",
  str_homestory_chat_27024009 = "Peace is nice. You can't be fighting and killing day in and day out.",
  str_homestory_chat_27024010 = "But you got to be prepared for danger...",
  str_homestory_chat_27199999 = "What's up?",
  str_homestory_chat_27101001 = "Nothing much.",
  str_homestory_chat_27101002 = "Okay, see you.",
  str_homestory_chat_27101003 = "Uh, Casta...",
  str_homestory_chat_27101004 = "Yeah?",
  str_homestory_chat_27101005 = "Well, it doesn't sit right with me to keep ending our conversations like this.",
  str_homestory_chat_27101006 = "Were we conversing?",
  str_homestory_chat_27101007 = "Got a point there. Well, talk to you later.",
  str_homestory_chat_27121001 = "Any plans lately?",
  str_homestory_chat_27121002 = "I'm looking for a high vantage point, like a tall tree or building. Got any of that around?",
  str_homestory_chat_27121003 = "Yes.",
  str_homestory_chat_27121004 = "How about the Gardens Dorm?",
  str_homestory_chat_27121005 = "No, that's too low... But the Hyacinth Tower will do just fine.",
  str_homestory_chat_27121006 = "Don't think so.",
  str_homestory_chat_27121007 = "Really? But I think the Hyacinth Tower will do just fine.",
  str_homestory_chat_27121008 = "The Chubbs might not give me access, though.",
  str_homestory_chat_27121009 = "Why do you want to do that?",
  str_homestory_chat_27121010 = "Convert the high ground into a watchtower that doubles as a sniper's nest.",
  str_homestory_chat_27121011 = "That's the most basic defensive position.",
  str_homestory_chat_27121012 = "Uh, I don't think that's necessary here...",
  str_homestory_chat_27122001 = "I heard you like coffee.",
  str_homestory_chat_27122002 = "Yes, especially straight black, no sugar or creamer. You?",
  str_homestory_chat_27122003 = "I like it, too.",
  str_homestory_chat_27122004 = "You're addicted to the taste as well, I see.",
  str_homestory_chat_27122005 = "Especially when it gets you to think about many other things...",
  str_homestory_chat_27122006 = "Uh... It's one of my likes, that's all.",
  str_homestory_chat_27122007 = "That's too bad. Hope you could expand your horizons soon.",
  str_homestory_chat_27122008 = "I don't like it.",
  str_homestory_chat_27122009 = "It's too bitter if you don't add anything.",
  str_homestory_chat_27122010 = "That's the popular opinion, so I guess I'm in the minority.",
  str_homestory_chat_27122011 = "It's all right, just opinions.",
  str_homestory_chat_27123001 = "You seem distracted.",
  str_homestory_chat_27123002 = "I've been told I'm a straight shooter and that makes people uncomfortable. Is that true?",
  str_homestory_chat_27123003 = "No.",
  str_homestory_chat_27123004 = "Okay, I feel better now.",
  str_homestory_chat_27123005 = "Yeah, somewhat.",
  str_homestory_chat_27123006 = "But I think that's cool.",
  str_homestory_chat_27123007 = "That's how you are, and a big part of who you are right now.",
  str_homestory_chat_27123008 = "So, keep being you.",
  str_homestory_chat_23099999 = "Any cases today?",
  str_homestory_chat_23001001 = "Uh...",
  str_homestory_chat_23001002 = "I take it as a \"yes.\" I'll start the proceedings then.",
  str_homestory_chat_23001003 = "First, we have the judge—that's me, of course—then we need bailiffs to guard the court...",
  str_homestory_chat_23001004 = "Wait, I never said we have a case. I was just mulling over my response.",
  str_homestory_chat_23001005 = "Argh, how boring.",
  str_homestory_chat_23021001 = "What are you up to lately?",
  str_homestory_chat_23021002 = "I need a favor from you. Can I borrow a few Chubbs?",
  str_homestory_chat_23021003 = "What do you need them for?",
  str_homestory_chat_23021004 = "They are the perfect shape for components.",
  str_homestory_chat_23021005 = "It sounds like you want to do something to them... Please don't hurt them.",
  str_homestory_chat_23021006 = "I can't? But I want to make statues out of them...",
  str_homestory_chat_23021007 = "Then we can all appreciate them as walking statues.",
  str_homestory_chat_23021008 = "Let me reiterate, please don't hurt them!",
  str_homestory_chat_23021009 = "Are you upset? Okay, okay.",
  str_homestory_chat_23022001 = "Need my help?",
  str_homestory_chat_23022002 = "Yes. Are you free to go to Umbraton and buy me magazines?",
  str_homestory_chat_23022003 = "Nope.",
  str_homestory_chat_23022004 = "You sure? You don't look busy at all and just hang out all day every day...",
  str_homestory_chat_23022005 = "Just do me the favor and treat it as a field trip.",
  str_homestory_chat_23022006 = "I got a lot to do here, not to mention that Umbraton is pretty far.",
  str_homestory_chat_23022007 = "Fine, you lazy pig...",
  str_homestory_chat_23022008 = "What kind of magazines?",
  str_homestory_chat_23022009 = "The kind with premium covers, content, and print quality...",
  str_homestory_chat_23022010 = "That sounds interesting.",
  str_homestory_chat_23022011 = "Yeah, you can imagine that, can't you?",
  str_homestory_chat_23022012 = "Do you mean Sculpture Art? I remember seeing it.",
  str_homestory_chat_23022013 = "Huh? What... Ah...",
  str_homestory_chat_23023001 = "Are you looking for something?",
  str_homestory_chat_23023002 = "I want to buy a massive amount of paper and ink...",
  str_homestory_chat_23023003 = "What for? Writing books?",
  str_homestory_chat_23023004 = "Yes. As a judge, it pains me to see there are no written laws here.",
  str_homestory_chat_23023005 = "I don't think we need any actual written laws...",
  str_homestory_chat_23023006 = "Verbal agreements are inferior to written contracts!",
  str_homestory_chat_23023007 = "I'm sure you just want to make some rules, especially ones that benefit you.",
  str_homestory_chat_23023008 = "No way, all the rules I make will be fair!",
  str_homestory_chat_23023009 = "For example, one must always follow the orders of a judge from Lumopolis...",
  str_homestory_chat_23023010 = "I rest my case.",
  str_homestory_chat_27299999 = "Is there anything I can film, PlayerName?",
  str_homestory_chat_27221001 = "No.",
  str_homestory_chat_27221002 = "Do you ever stop thinking about filming...?",
  str_homestory_chat_27221003 = "Hey, it's not my fault that the scenery around here is so amazing! Now if I could just put a story to them...",
  str_homestory_chat_27221004 = "Argh, what a pain! Why do I have to be a screenwriter too?",
  str_homestory_chat_27221005 = "Are you sure there's nothing interesting going on here? Maybe something like \"The Nine Incredible Legends of Cloud Gardens\"?",
  str_homestory_chat_27221006 = "N-Nothing like that, no...",
  str_homestory_chat_27222001 = "What do you want to buy?",
  str_homestory_chat_27222002 = "Do you have a stand lying around somewhere? Preferably one with wheels, so I can move it around.",
  str_homestory_chat_27222003 = "What do you need one for?",
  str_homestory_chat_27222004 = "To film, of course! Cellulo's arms get tired from holding the camera all the time, you know?",
  str_homestory_chat_27222005 = "Our budget is pretty tight too. Otherwise, I'd hire a professional to do it.",
  str_homestory_chat_27222006 = "I see... Wouldn't it be better to look for that kind of thing in Umbraton instead?",
  str_homestory_chat_27222007 = "Yeah, but Umbraton's expensive!",
  str_homestory_chat_27223001 = "You don't seem too busy today?",
  str_homestory_chat_27223002 = "That's because I'm all out of good stories to read. Anyway, do you have stuff you like reading?",
  str_homestory_chat_27223003 = "Not at all.",
  str_homestory_chat_27223004 = "I guess...?",
  str_homestory_chat_27223005 = "I sometimes read the books Vice and the others gift me.",
  str_homestory_chat_27223006 = "Sigh. Somehow, I feel like I'm talking to the wrong person here.",
  str_homestory_chat_27223007 = "I'm looking for short story recommendations! Especially good thrillers, if you know of any...",
  str_homestory_chat_27223008 = "You seem to really like horror. Don't you get scared?",
  str_homestory_chat_27223009 = "Hah! What's scarier than being broke?",
  str_homestory_chat_27223010 = "Besides, what if one day they make film adaptations for some of these stories? They might cast me as the female lead if I know the material inside and out!",
  str_homestory_chat_27223011 = "Then, I can finally be the star I'm destined to be... Hehehehe...",
  str_homestory_chat_27223012 = "Right. I'm gonna take my leave now.",
  str_homestory_chat_27224001 = "Fans?",
  str_homestory_chat_27224002 = "You're kinda famous yourself. You have fans, right?",
  str_homestory_chat_27224003 = "I think so?",
  str_homestory_chat_27224004 = "Ooh! Like who?",
  str_homestory_chat_27224005 = "I... don't really know...",
  str_homestory_chat_27224006 = "Not at all.",
  str_homestory_chat_27224007 = "How unfortunate.",
  str_homestory_chat_27224008 = "Well, whether or not you have fans, you should always work hard for your own sake, not theirs!",
  str_homestory_chat_27224009 = "Of course!",
  str_homestory_chat_27224010 = "That's why you gotta cheer yourself on every once in a while, right?",
  str_homestory_chat_27224011 = "Sure, but... Why are you telling me this? Did something happen?",
  str_homestory_chat_27224012 = "I just... get tired sometimes, that's all.",
  str_homestory_chat_27225001 = "What do you want to buy?",
  str_homestory_chat_27225002 = "I'm craving fish...",
  str_homestory_chat_27225003 = "Aren't there lots of fish in the river? Can't Cellulo catch some for you?",
  str_homestory_chat_27225004 = "But I don't wanna eat freshwater fish... I want something from the sea!",
  str_homestory_chat_27225005 = "Like clam chowder... Or maybe a bowl of seafood stew over rice!",
  str_homestory_chat_27225006 = "You could just make those things with freshwater fish.",
  str_homestory_chat_27225007 = "Absolutely not! Are you kidding?!",
  str_homestory_chat_27225008 = "Seafood is totally different! Just one bite, and you can practically taste the ocean!",
  str_homestory_chat_27225009 = "That taste alone is enough to make you feel invincible! Like you can achieve even your wildest dreams!",
  str_homestory_chat_27225010 = "Are we... still talking about food?",
  str_homestory_chat_27399999 = "Good day, PlayerName. I'm at your service, should you require anything.",
  str_homestory_chat_27301001 = "Hi, Minos.",
  str_homestory_chat_27301002 = "You don't have to be so courteous here in Cloud Gardens all the time. Just take it easy, okay?",
  str_homestory_chat_27301003 = "Impossible. As a proud butler, I must be prepared to serve my master at any given moment.",
  str_homestory_chat_27301004 = "But your master isn't here right now... is he?",
  str_homestory_chat_27301005 = "No, but I must also be prepared in the event he decides to come here.",
  str_homestory_chat_27321001 = "Your weapon...",
  str_homestory_chat_27321002 = "Ah, I've been looking for you, my friend. Tell me, is there a master craftsman here in Cloud Gardens who can repair weapons?",
  str_homestory_chat_27321003 = "Yeah.",
  str_homestory_chat_27321004 = "Which Chubb should I speak to?",
  str_homestory_chat_27321005 = "Er... I don't think any of them can help you, but maybe one of my friends can try?",
  str_homestory_chat_27321006 = "Nope.",
  str_homestory_chat_27321007 = "Sigh... What a pity.",
  str_homestory_chat_27321008 = "Is your gun broken?",
  str_homestory_chat_27321009 = "Of course not. As a proud butler, it's my duty to ensure all of my equipment is in proper working order, and weapons are no exception.",
  str_homestory_chat_27321010 = "There's no telling when my master might find himself in a dangerous predicament.",
  str_homestory_chat_27321011 = "That's very professional of you...",
  str_homestory_chat_27322001 = "How can I help?",
  str_homestory_chat_27322002 = "Good day, PlayerName. Could you please provide me with the exact time right now?",
  str_homestory_chat_27322003 = "Sure...? Is something wrong with your watch?",
  str_homestory_chat_27322004 = "Even the most precise instrument can fail at times. In fact, just this morning...",
  str_homestory_chat_27322005 = "I noticed that my watch seemed to be running a fraction of a second slower than it was yesterday.",
  str_homestory_chat_27322006 = "You notice stuff like that?!",
  str_homestory_chat_27322007 = "As a proud butler, it's my duty to keep track of the time at all times.",
  str_homestory_chat_27322008 = "After all, even the smallest deviation from the exact time on my part could ruin my master's entire schedule for the day.",
  str_homestory_chat_27322009 = "I can't help but feel jealous of your master...",
  str_homestory_chat_27322010 = "If only I had someone like you to help keep me on schedule...",
  str_homestory_chat_27323001 = "Is something on your mind, Minos?",
  str_homestory_chat_27323002 = "There is, indeed. Tell me, how do you think a butler best serves his master?",
  str_homestory_chat_27323003 = "By following orders?",
  str_homestory_chat_27323004 = "Total obedience...",
  str_homestory_chat_27323005 = "If I may speak frankly... I completely disagree.",
  str_homestory_chat_27323006 = "By supporting them?",
  str_homestory_chat_27323007 = "You're right!",
  str_homestory_chat_27323008 = "A butler's duty is not simply to obey his master's commands. More often than not, he must help his master realize his own mistakes.",
  str_homestory_chat_27323009 = "In this respect, a butler and his master can see one another as equals.",
  str_homestory_chat_27323010 = "That is true, yeah.",
  str_homestory_chat_27324001 = "How do you feel about this place?",
  str_homestory_chat_27324002 = "It's a lovely place. Vast, but incredibly clean.",
  str_homestory_chat_27324003 = "The Chubbs appear to maintain the area quite well.",
  str_homestory_chat_27324004 = "It's not just them, you know? Everyone does their part to take care of Cloud Gardens too.",
  str_homestory_chat_27324005 = "My dear PlayerName, you're absolutely right.",
  str_homestory_chat_27324006 = "Truth be told, I'm quite envious of how habitable this place is.",
  str_homestory_chat_27324007 = "The clean environment, the fresh air, and even the amount of sunshine this place receives... All of it is simply outstanding.",
  str_homestory_chat_27324008 = "But most importantly, it's almost entirely free of harmful insects and other pesky rodents. My work here is a lot less burdensome as a result.",
  str_homestory_chat_27324009 = "I'm glad you like it here, Minos!",
  str_homestory_chat_26999999 = "Yo yo yo, I see you wandering, bro.",
  str_homestory_chat_26901001 = "Hi, Sadie.",
  str_homestory_chat_26901002 = "Yo, yo, yo! I'm just hangin' out, you know?",
  str_homestory_chat_26901003 = "Why are you copying the way I speak?",
  str_homestory_chat_26901004 = "S-Sorry, it just sort of slipped out...",
  str_homestory_chat_26901005 = "Yo yo yo, looks like you've caught on to my flow.",
  str_homestory_chat_26921001 = "What are you reading?",
  str_homestory_chat_26921002 = "The Annual Swashbuckler Comic Omnibus. It just came out in Umbraton!",
  str_homestory_chat_26921003 = "I came to Cloud Gardens just so I could read it three more times.",
  str_homestory_chat_26921004 = "Three more times?",
  str_homestory_chat_26921005 = "Yeah! I could read it a hundred times and still wouldn't get tired of it!",
  str_homestory_chat_26921006 = "Judging by how pumped up you are, I'd say you've already read it three hundred times, haven't you?",
  str_homestory_chat_26921007 = "Nah, more like 666 times!",
  str_homestory_chat_26921008 = "Hah?!",
  str_homestory_chat_26922001 = "Are you smiling?",
  str_homestory_chat_26922002 = "I just thought of something that made me super happy, just like when you think of Cloud Gardens!",
  str_homestory_chat_26922003 = "Something happy?",
  str_homestory_chat_26922004 = "Whenever I think of swashbuckling, I can't help but smile!",
  str_homestory_chat_26922005 = "Especially when I think of how I can foil the bad guys' plans every time!",
  str_homestory_chat_26922006 = "Cloud Gardens?",
  str_homestory_chat_26922007 = "That's right! I've been watching you for a while now, and I've noticed that whenever you're in Cloud Gardens, you always have a smile on your face.",
  str_homestory_chat_26922008 = "Unconsciously, and involuntarily.",
  str_homestory_chat_26922009 = "So... Why are you smiling?",
  str_homestory_chat_26922010 = "A swashbuckler smiles when the bad guys cry!",
  str_homestory_chat_26922011 = "Whenever I think about this, I can't help but drop some freestyle verses!",
  str_homestory_chat_26922012 = "The swashbuckler, the villain sees! A fist comes flyin' and the villain starts cryin'!",
  str_homestory_chat_26922013 = "Yeah! Uh-huh, uh-huh!",
  str_homestory_chat_26923001 = "You really like baseball, huh?",
  str_homestory_chat_26923002 = "Not especially. Why do you ask?",
  str_homestory_chat_26923003 = "Well, I never see you without your baseball cap or your bat...",
  str_homestory_chat_26923004 = "I just like the look. Doesn't it look cool to you?",
  str_homestory_chat_26923005 = "Cool?",
  str_homestory_chat_26923006 = "You know, like I'm about to do something extremely awesome...?",
  str_homestory_chat_26923007 = "Baseball was never my style, you know? But when it comes to rap, I got the coolest flow!",
  str_homestory_chat_26923008 = "Super Sadie 666, carries a bat, Super Sadie 666, swings a bat.",
  str_homestory_chat_26923009 = "So basically you just use it as a weapon.",
  str_homestory_chat_26923010 = "Super Sadie 666, wears a cap, Super Sadie 666, she really slaps!",
  str_homestory_chat_26923011 = "Alright, I get it. You can stop doing that now...",
  str_homestory_chat_27599999 = "*Yawn* You're having a leisurely stroll again today.",
  str_homestory_chat_27521001 = "It's you again.",
  str_homestory_chat_27521002 = "Were you yawning just now? Are you tired?",
  str_homestory_chat_27521003 = "No, I'm always like this.",
  str_homestory_chat_27521004 = "True. There aren't any signs of fatigue on your face...",
  str_homestory_chat_27521005 = "Everyone tells me that.",
  str_homestory_chat_27521006 = "I guess this is one of your special traits.",
  str_homestory_chat_27522001 = "Do you always wear that outfit?",
  str_homestory_chat_27522002 = "Indeed I do. Is there something wrong with it?",
  str_homestory_chat_27522003 = "It doesn't fit you very well.",
  str_homestory_chat_27522004 = "That's because tight clothes make me uncomfortable. Sometimes I even have difficulty breathing.",
  str_homestory_chat_27522005 = "I've tried wearing them before, but I couldn't stand it.",
  str_homestory_chat_27522006 = "One day, my father told me I could wear clothes one size up.",
  str_homestory_chat_27522007 = "After that, my clothes no longer gave me trouble.",
  str_homestory_chat_27522008 = "I see.",
  str_homestory_chat_27522009 = "You're always wearing that...",
  str_homestory_chat_27522010 = "It's because I have many sets of the same outfit.",
  str_homestory_chat_27522011 = "That's not really my point, though. Haven't you tried wearing other clothes?",
  str_homestory_chat_27522012 = "No, I like clothes like these. They're very comfortable.",
  str_homestory_chat_27522013 = "I guess so...",
  str_homestory_chat_27523001 = "The lamps?",
  str_homestory_chat_27523002 = "Yes, I want to change the street lamps here.",
  str_homestory_chat_27523003 = "Change them in what way?",
  str_homestory_chat_27523004 = "I want to replace them with colorful neon lights. I bet that would look nice.",
  str_homestory_chat_27523005 = "The Chubbs would certainly like it.",
  str_homestory_chat_27523006 = "That feels like a big undertaking.",
  str_homestory_chat_27523007 = "Does this mean you're okay with it?",
  str_homestory_chat_27523008 = "Do you want me to figure out how much work would be involved?",
  str_homestory_chat_27523009 = "Um, that won't be necessary...",
  str_homestory_chat_27524001 = "Can you speak a little louder?",
  str_homestory_chat_27524002 = "Am I speaking too softly? Are you unable to communicate with me?",
  str_homestory_chat_27524003 = "I can't hear you properly sometimes.",
  str_homestory_chat_27524004 = "Then we should stand a little closer when we talk.",
  str_homestory_chat_27524005 = "This is as loud as my voice goes.",
  str_homestory_chat_27524006 = "But sometimes it isn't that convenient to be too close to one another.",
  str_homestory_chat_27524007 = "Why is that?",
  str_homestory_chat_27524008 = "Isn't a shorter distance between us better for communication?",
  str_homestory_chat_27524009 = "Er... Let's put this topic on-hold for the time being.",
  str_homestory_chat_27525001 = "Candy?",
  str_homestory_chat_27525002 = "Yes, PlayerName, do you like candy?",
  str_homestory_chat_27525003 = "Yes.",
  str_homestory_chat_27525004 = "I once ate these gummies in Umbraton that weren't too sweet and didn't stick to my teeth...",
  str_homestory_chat_27525005 = "You have to take me there to try them one day. I'd be grateful.",
  str_homestory_chat_27525006 = "Sure thing, but you don't look that excited to me.",
  str_homestory_chat_27525007 = "No, I'm really looking forward to it.",
  str_homestory_chat_27525008 = "No.",
  str_homestory_chat_27525009 = "What a shame. I wanted to recommend all sorts of candy to you.",
  str_homestory_chat_27525010 = "Especially pop rocks...",
  str_homestory_chat_27699999 = "Hi! I'm in a good mood today!",
  str_homestory_chat_27601001 = "Hello!",
  str_homestory_chat_27601002 = "I heard you were looking for something to do?",
  str_homestory_chat_27601003 = "That's right. Although this isn't Lumopolis, after I came here...",
  str_homestory_chat_27601004 = "I haven't been able to shake the feeling that I have an obligation to contribute to this place. So I just want to do something.",
  str_homestory_chat_27601005 = "There's no rush. A city can't be built in a day, after all.",
  str_homestory_chat_27601006 = "That's what Lady Raphael said too... Okay then.",
  str_homestory_chat_27621001 = "Growing flowers?",
  str_homestory_chat_27621002 = "Yes. There are a ton of interesting flowers here, especially those tall ones!",
  str_homestory_chat_27621003 = "Those... are Unique Trees...",
  str_homestory_chat_27621004 = "Oh, how amazing! Some of them look just like flowers, especially the canopy one. Did you grow them all yourself?",
  str_homestory_chat_27621005 = "Yes.",
  str_homestory_chat_27621006 = "The Chubbs did most of the work.",
  str_homestory_chat_27621007 = "Can I grow some too? I'm good at taking care of plants!",
  str_homestory_chat_27621008 = "Hmm... I need to think about it.",
  str_homestory_chat_27622001 = "You mentioned birds...",
  str_homestory_chat_27622002 = "Cloud Gardens is so big. I bet lots of birds come here.",
  str_homestory_chat_27622003 = "I want to build them a nest so they have a place to rest when they come.",
  str_homestory_chat_27622004 = "What a good idea! You're very observant, and you love birds.",
  str_homestory_chat_27622005 = "Actually... this was Lady Raphael's idea.",
  str_homestory_chat_27622006 = "She said this would make me more patient and less rash.",
  str_homestory_chat_27622007 = "After coming here, I've had nothing to do, and I think it's made me revert back to my old self a lot.",
  str_homestory_chat_27622008 = "That's why I came to ask you where I can find birds. I'm gonna go look for them!",
  str_homestory_chat_27622009 = "There's that impatience of yours again...",
  str_homestory_chat_27622010 = "What did you say? Where are they?",
  str_homestory_chat_27622011 = "Ah, what I mean is that you can't be impatient. You need to look for them slowly.",
  str_homestory_chat_27622012 = "This trains you to be more patient too, right?",
  str_homestory_chat_27622013 = "Hmm, you're right.",
  str_homestory_chat_27623001 = "Medical drills?",
  str_homestory_chat_27623002 = "Yes. Cloud Gardens is quite peaceful, but we still need to do these types of drills.",
  str_homestory_chat_27623003 = "We need to be prepared for accidents even if enemies aren't attacking us.",
  str_homestory_chat_27623004 = "For example, someone could drown or fall off the roof.",
  str_homestory_chat_27623005 = "I suppose you're right.",
  str_homestory_chat_27623006 = "How should we start? Do I need to find some of the others to coordinate with you?",
  str_homestory_chat_27623007 = "That won't be necessary! There are a lot of Chubbs here!",
  str_homestory_chat_27623008 = "Hold on! But they're not Aurorians...?",
  str_homestory_chat_27623009 = "Will the medical drills really be effective this way?",
  str_homestory_chat_27623010 = "It's fine as long as my skills don't get rusty!",
  str_homestory_chat_27623011 = "A-Alright, then.",
  str_homestory_chat_27799999 = "Hi! You look pretty good today!",
  str_homestory_chat_27721001 = "You're always so cheerful.",
  str_homestory_chat_27721002 = "How do you do it? What's your secret?",
  str_homestory_chat_27721003 = "It's just because idols are always like this, even if their hearts are full of sadness...",
  str_homestory_chat_27721004 = "They stay positive at all times and put on their best act for everyone!",
  str_homestory_chat_27721005 = "After all, how else can we fill the entire continent with the healing power of love?",
  str_homestory_chat_27721006 = "When you put it like that, you really are amazing...",
  str_homestory_chat_27722001 = "You were looking for me?",
  str_homestory_chat_27722002 = "PlayerName, I need to ask you a very serious question, and you must answer it honestly.",
  str_homestory_chat_27722003 = "W-Why? What's wrong?",
  str_homestory_chat_27722004 = "Do you think that recently... my weight...",
  str_homestory_chat_27722005 = "(She seems worried about her weight. How should I answer her...?)",
  str_homestory_chat_27722006 = "You do look more... round.",
  str_homestory_chat_27722007 = "I knew it! I bet it's because I overate recently.",
  str_homestory_chat_27722008 = "And life is too laid back here... I can't go on like this!",
  str_homestory_chat_27722009 = "Looks like I won't be eating anything tonight! And I'll have to run 50 laps!",
  str_homestory_chat_27722010 = "You look fine.",
  str_homestory_chat_27722011 = "Really? Tell me the truth, or I'll never trust you again!",
  str_homestory_chat_27722012 = "Well... Maybe you've gained just a little weight?",
  str_homestory_chat_27722013 = "I knew I overate a few days ago! I need to start being more strict with myself!",
  str_homestory_chat_27722014 = "I mean, there's no need to overreact. It's just a little bit of extra weight...",
  str_homestory_chat_27722015 = "Even a little is too much. This is the price of being an idol.",
  str_homestory_chat_27722016 = "You're so strict with yourself.",
  str_homestory_chat_27723001 = "Are you going to exercise?",
  str_homestory_chat_27723002 = "Performance rehearsing, actually! Is there a special training room around here?",
  str_homestory_chat_27723003 = "Erm...",
  str_homestory_chat_27723004 = "Sigh, this really is the perfect place for a vacation.",
  str_homestory_chat_27723005 = "But I can't let up on my training... An idol should always be at her best.",
  str_homestory_chat_27723006 = "Maybe we can do some training without professional equipment?",
  str_homestory_chat_27723007 = "Alright! Let me see what we have here...",
  str_homestory_chat_27723008 = "Long-distance running, swimming, mountaineering, dancing... There are so many things to do!",
  str_homestory_chat_27723009 = "You've got this.",
  str_homestory_chat_27724001 = "A room?",
  str_homestory_chat_27724002 = "Right, I want a special room just for Marshmallow.",
  str_homestory_chat_27724003 = "You mean your dog?",
  str_homestory_chat_27724004 = "Yes. You see, he never gets a good night's sleep outside, and sometimes it rains here too.",
  str_homestory_chat_27724005 = "That's true...",
  str_homestory_chat_27724006 = "That's it! I'll make a little den for him under my bed! I just need a blanket.",
  str_homestory_chat_27724007 = "Good idea!",
  str_homestory_chat_27724008 = "I'm going to ask the Chubbs to do it!",
  str_homestory_chat_27724009 = "You seem to already have this all planned out.",
  str_homestory_chat_27725001 = "You look pretty good, too.",
  str_homestory_chat_27725002 = "Indeed! And it's mainly because there's no bitter melon here.",
  str_homestory_chat_27725003 = "Bitter melon? You don't like bitter melon?",
  str_homestory_chat_27725004 = "Are you telling me you do?!",
  str_homestory_chat_27725005 = "I don't mind it.",
  str_homestory_chat_27725006 = "You don't mind it! Incredible! But that bitter taste...",
  str_homestory_chat_27725007 = "Oh! I see... You're trying to lose weight, right?",
  str_homestory_chat_27725008 = "Erm... N-No...",
  str_homestory_chat_27725009 = "Sigh, you seem to understand the importance of weight management too. It's hard, isn't it?",
  str_homestory_chat_27725010 = "Honestly, I'm not...",
  str_homestory_chat_27725011 = "It's disgusting.",
  str_homestory_chat_27725012 = "Right! So, don't let bitter melon come anywhere near here! Don't forget!",
  str_homestory_chat_27725013 = "No problem.",
  str_homestory_chat_27899999 = "Hmm? What's up?",
  str_homestory_chat_27821001 = "What are you up to?",
  str_homestory_chat_27821002 = "I was wondering whether I should make a rocking chair or a hammock...",
  str_homestory_chat_27821003 = "For what reason?",
  str_homestory_chat_27821004 = "For resting on, naturally. What else would I use them for, exercise?",
  str_homestory_chat_27821005 = "Imagine lying in the sun, the breeze tickling your cheek... Ah!",
  str_homestory_chat_27821006 = "Sounds incredibly leisurely...",
  str_homestory_chat_27822001 = "You look very relaxed.",
  str_homestory_chat_27822002 = "Yes, this is a rare place where one can come to relax completely.",
  str_homestory_chat_27822003 = "Don't you enjoy this kind of feeling too, PlayerName?",
  str_homestory_chat_27822004 = "I do.",
  str_homestory_chat_27822005 = "That's right! I knew you'd get it!",
  str_homestory_chat_27822006 = "I knew you'd like the carefree feeling of relaxation too.",
  str_homestory_chat_27822007 = "I especially love doing nothing—just looking up and watching the wind gently nudging the clouds along.",
  str_homestory_chat_27822008 = "Or listening to the sound of the leaves and letting my mind go completely blank.",
  str_homestory_chat_27822009 = "It's great for alleviating mental fatigue.",
  str_homestory_chat_27822010 = "Alright, I'll try it someday.",
  str_homestory_chat_27822011 = "It's not bad, but...",
  str_homestory_chat_27822012 = "It's not good to relax too much... We should spend our time actually doing things.",
  str_homestory_chat_27822013 = "Like build a new structure? But we can get the Chubbs to do it.",
  str_homestory_chat_27822014 = "You can and should spend more time relaxing.",
  str_homestory_chat_27822015 = "That's... not exactly what I meant.",
  str_homestory_chat_27823001 = "What do you want?",
  str_homestory_chat_27823002 = "I heard there were some strange-looking animals around these parts.",
  str_homestory_chat_27823003 = "I haven't seen any.",
  str_homestory_chat_27823004 = "What a shame! I thought I might find something interesting here.",
  str_homestory_chat_27823005 = "But I can also just consider this a sabbatical.",
  str_homestory_chat_27823006 = "Ah... Yeah, there are.",
  str_homestory_chat_27823007 = "I had a good feeling about this place! Now I can enjoy my vacation and look for wondrous beasts at the same time!",
  str_homestory_chat_27823008 = "Two birds, one stone!",
  str_homestory_chat_27823009 = "Slacking off seems to have been your main goal...",
  str_homestory_chat_27824001 = "Fishing?",
  str_homestory_chat_27824002 = "Yeah, there's a lot of fish in the nearby river, so many people go fishing there.",
  str_homestory_chat_27824003 = "Indeed.",
  str_homestory_chat_27824004 = "Do you like fishing?",
  str_homestory_chat_27824005 = "Sure.",
  str_homestory_chat_27824006 = "It's alright, I guess.",
  str_homestory_chat_27824007 = "Hmm... Anyway, I prefer observing the fish rather than catching them myself.",
  str_homestory_chat_27824008 = "I feel so laid back watching them wade through the water.",
  str_homestory_chat_27824009 = "You could just go to the Fountain of Hope.",
  str_homestory_chat_27824010 = "Well, that's different. After all, being caught in the Wishing Fountain's embrace gives you a completely different feeling.",
  str_homestory_chat_27824011 = "That makes sense...",
  str_homestory_chat_27825001 = "Need something to drink?",
  str_homestory_chat_27825002 = "Right. It's great here, but it's missing something...",
  str_homestory_chat_27825003 = "And that something is a bottle of booze!",
  str_homestory_chat_27825004 = "Drinking in the daytime...",
  str_homestory_chat_27825005 = "Just a little drink and nothing more. With such a gentle breeze, if there were another rocking chair...",
  str_homestory_chat_27825006 = "Wonderful!",
  str_homestory_chat_27825007 = "So, you're not going to look for wondrous beasts anymore?",
  str_homestory_chat_27825008 = "I came here to relax! But if there's no booze...",
  str_homestory_chat_27825009 = "Maybe the stream over there has what I'm looking for? Right!",
  str_homestory_chat_27825010 = "Well... It's up to you.",
  str_homestory_chat_28099999 = "What are you gossiping about these days?",
  str_homestory_chat_28001001 = "Huh? I'm not gossiping about anything...",
  str_homestory_chat_28001002 = "Why do you like gossip so much?",
  str_homestory_chat_28001003 = "Because it's so intriguing!",
  str_homestory_chat_28001004 = "For example, I heard that some important person in one of the big guilds actually dreams of being a novelist, or something like that...",
  str_homestory_chat_28001005 = "Don't you think that's just fascinating?!",
  str_homestory_chat_28001006 = "That's... to each their own, I guess.",
  str_homestory_chat_28001007 = "That's why I have to collect a lot of info to meet the needs of different readers!",
  str_homestory_chat_28001008 = "Well, I wish you luck.",
  str_homestory_chat_28021001 = "That device...",
  str_homestory_chat_28021002 = "You seem to take it with you everywhere. You really need to take photos anytime, anyplace?",
  str_homestory_chat_28021003 = "Of course! And that's because gossip is always founded upon the truth!",
  str_homestory_chat_28021004 = "Huh? Are you sure about that?",
  str_homestory_chat_28021005 = "What's your opinion on this, then?",
  str_homestory_chat_28021006 = "Rumors should be based on truth.",
  str_homestory_chat_28021007 = "That's right!",
  str_homestory_chat_28021008 = "But making things up once in a while...",
  str_homestory_chat_28021009 = "I guess it doesn't really matter? It wouldn't be a matter of great importance either way.",
  str_homestory_chat_28021010 = "No!",
  str_homestory_chat_28021011 = "Don't say that! Even gossip should be true, otherwise, readers will lose interest sooner or later.",
  str_homestory_chat_28021012 = "Gossip must hold a certain degree of authenticity to attract readers!",
  str_homestory_chat_28021013 = "I suppose not even gossip should be written callously.",
  str_homestory_chat_28022001 = "Your bag...",
  str_homestory_chat_28022002 = "Why is it so big? And you always carry it around with you.",
  str_homestory_chat_28022003 = "It's big because it's full of journalistic materials: notes, photos, newspapers, even leaflets...",
  str_homestory_chat_28022004 = "Do you need to take all that around with you? Can't you leave it in your office?",
  str_homestory_chat_28022005 = "No way! News is always connected!",
  str_homestory_chat_28022006 = "Sometimes, the first scent of a big story is hidden in the most insignificant news.",
  str_homestory_chat_28022007 = "Once you come across people or things that could possibly contain a story, you never know when you might need them!",
  str_homestory_chat_28022008 = "But don't you think such gossip would get stale over time?",
  str_homestory_chat_28022009 = "That's why I need to take this bag with me. I had it custom-made!",
  str_homestory_chat_28022010 = "Not only is it huge, it also has loads of compartments, so I can find information I need whenever I need it!",
  str_homestory_chat_28022011 = "I remember the specific location of each and every document!",
  str_homestory_chat_28022012 = "If your memory is so good, why don't you just memorize all the info instead...",
  str_homestory_chat_28023001 = "Got any gossip?",
  str_homestory_chat_28023002 = "Ah... Nope, nothing. Life here is so boring.",
  str_homestory_chat_28023003 = "It's all just Chubbs, Chubbs, Chubbs.",
  str_homestory_chat_28023004 = "There are no coffee shops or newsstands where I can eavesdrop for information.",
  str_homestory_chat_28023005 = "It's a good opportunity to take a break though.",
  str_homestory_chat_28023006 = "What good is that? I'd miss out on all the latest news!",
  str_homestory_chat_28023007 = "But life here is really just that peaceful. Why don't you find something else to do?",
  str_homestory_chat_28023008 = "Something else... I've got it!",
  str_homestory_chat_28023009 = "I can train the Chubbs to find out the latest gossip for me!",
  str_homestory_chat_28023010 = "That way... hehehe...",
  str_homestory_chat_28023011 = "Please don't!",
  str_homestory_chat_28199999 = "What are you up to lately, my young friend?",
  str_homestory_chat_28121001 = "So what are your hobbies?",
  str_homestory_chat_28121002 = "I love woodcarving.",
  str_homestory_chat_28121003 = "Woodcarving?",
  str_homestory_chat_28121004 = "Yes, take a piece of ordinary wood, a good carving knife...",
  str_homestory_chat_28121005 = "And a work of art will form in your hands.",
  str_homestory_chat_28121006 = "Sometimes it makes me happier than winning a battle.",
  str_homestory_chat_28121007 = "You really like it, don't you?",
  str_homestory_chat_28122001 = "Unique Tree?",
  str_homestory_chat_28122002 = "An idea came to me when I saw the wonderful trees here.",
  str_homestory_chat_28122003 = "You want to carve something with them, don't you?",
  str_homestory_chat_28122004 = "That is correct. May I?",
  str_homestory_chat_28122005 = "No.",
  str_homestory_chat_28122006 = "A flat-out \"No\", huh? These trees must be important to you.",
  str_homestory_chat_28122007 = "Mainly because... they are so hard to grow.",
  str_homestory_chat_28122008 = "Let's think...",
  str_homestory_chat_28122009 = "Do you need a lot of materials for woodcarving?",
  str_homestory_chat_28122010 = "Yes, I have never carved one before, so there might be a lot of wasted materials.",
  str_homestory_chat_28122011 = "They probably have very different characteristics from the wood I normally use for carving.",
  str_homestory_chat_28122012 = "Then... I'm afraid not.",
  str_homestory_chat_28122013 = "Right... I suppose I will stop trying to find good wood here.",
  str_homestory_chat_28122014 = "Or maybe I should purchase some from foreign locations...",
  str_homestory_chat_28123001 = "You like cats?",
  str_homestory_chat_28123002 = "Yes, that's why I have three of them.",
  str_homestory_chat_28123003 = "Three?!",
  str_homestory_chat_28123004 = "But I have only seen one.",
  str_homestory_chat_28123005 = "Because they have different duties.",
  str_homestory_chat_28123006 = "Different duties? Really?",
  str_homestory_chat_28123007 = "Yixin fights with me, Yimeng spends time with me here, and as for Yinuo...",
  str_homestory_chat_28123008 = "Yinuo is very elusive, and I don't even know where it is most of the time.",
  str_homestory_chat_28123009 = "Does that even count as having a cat?",
  str_homestory_chat_28124001 = "Are you looking to buy something?",
  str_homestory_chat_28124002 = "I want to get some... interesting pieces for my room. It'll make me feel like living in Twin Pavilions Bay.",
  str_homestory_chat_28124003 = "Interesting pieces... like antiques? Longzhou antiques are hard to get.",
  str_homestory_chat_28124004 = "Doesn't have to be Longzhou antiques. I'm actually hoping for antiques from Astra.",
  str_homestory_chat_28124005 = "Like swords from Lumopolis, Vintage Wine from Umbraton, Bone Carvings from Northland...",
  str_homestory_chat_28124006 = "Looks like you are a man with a wide range of interests.",
  str_homestory_chat_28124007 = "Thank you. I figured since I'm here, that I should try to appreciate the culture of the place.",
  str_homestory_chat_28124008 = "It's a good chance to get to know Astra.",
  str_homestory_chat_28124009 = "I'll keep an eye out for you.",
  str_homestory_chat_28125001 = "Different carvings?",
  str_homestory_chat_28125002 = "Yes. Do you know anything about them?",
  str_homestory_chat_28125003 = "I know a little.",
  str_homestory_chat_28125004 = "Oh? Then tell me, what types of carvings are there on this continent?",
  str_homestory_chat_28125005 = "Mostly stone and wood ones, and Northland has bone carvings.",
  str_homestory_chat_28125006 = "I hear that Illumina and Rediesel Wrench have rare iron carvings!",
  str_homestory_chat_28125007 = "I see, so there are so many... But no root carvings, it seems.",
  str_homestory_chat_28125008 = "Root carvings?",
  str_homestory_chat_28125009 = "It's something that is unique to Longzhou. I'll explain it to you when I have a chance.",
  str_homestory_chat_28125010 = "Now I'm really intrigued.",
  str_homestory_chat_28125011 = "I don't get it at all...",
  str_homestory_chat_28125012 = "That's a shame, we'll have to stop here.",
  str_homestory_chat_28125013 = "I feel like I need to say something...",
  str_homestory_chat_28299999 = "What is it?",
  str_homestory_chat_28221001 = "You want to know where you can swim?",
  str_homestory_chat_28221002 = "Yes, I've spent too much time on land, and my swimming skill is getting rusty.",
  str_homestory_chat_28221003 = "In the river?",
  str_homestory_chat_28221004 = "That's a little too shallow, I think. I'm looking for something deeper, preferably with waves.",
  str_homestory_chat_28221005 = "Waves of varying magnitudes, like the ocean.",
  str_homestory_chat_28221006 = "So why not just go to the beach and swim in the ocean...",
  str_homestory_chat_28222001 = "What do you like to eat?",
  str_homestory_chat_28222002 = "You may not like what I like. For example, river snail noodles.",
  str_homestory_chat_28222003 = "It's alright...",
  str_homestory_chat_28222004 = "You like it too?! That's great!",
  str_homestory_chat_28222005 = "Well, I don't find it repulsive, but I try not to eat it when there are other people around.",
  str_homestory_chat_28222006 = "Right, I get it.",
  str_homestory_chat_28222007 = "You're already brave enough for being able to eat this. A true Astra hero!",
  str_homestory_chat_28222008 = "Well, that's too much...",
  str_homestory_chat_28222009 = "You have a point.",
  str_homestory_chat_28222010 = "It does have a very pungent smell.",
  str_homestory_chat_28222011 = "I usually eat it alone.",
  str_homestory_chat_28222012 = "That's very considerate of you!",
  str_homestory_chat_28223001 = "Are you looking for medicine?",
  str_homestory_chat_28223002 = "Yes, for seasickness. Do you have any?",
  str_homestory_chat_28223003 = "No.",
  str_homestory_chat_28223004 = "I might...",
  str_homestory_chat_28223005 = "Wait, why do you need it?",
  str_homestory_chat_28223006 = "Aren't you a seasoned skipper?",
  str_homestory_chat_28223007 = "It's for other people, of course. More people get seasick than you think.",
  str_homestory_chat_28223008 = "Even some veteran sailors get it sometimes.",
  str_homestory_chat_28223009 = "I see, I'll go look for some.",
  str_homestory_chat_28224001 = "I heard you're looking for a boat?",
  str_homestory_chat_28224002 = "Yes, I thought of this when I saw the river.",
  str_homestory_chat_28224003 = "Cloud Gardens is closed off to the outside world, and one can't get in or out through the mountains. But this river seems like a smooth passage.",
  str_homestory_chat_28224004 = "So I'm wondering if I can conduct some simple trades using the river.",
  str_homestory_chat_28224005 = "Don't.",
  str_homestory_chat_28224006 = "Why?",
  str_homestory_chat_28224007 = "While it's nice and smooth, the Chubbs say that the currents are quite unfavorable in many sections of the river.",
  str_homestory_chat_28224008 = "And there are reefs in shallow waters that tip over boats easily.",
  str_homestory_chat_28224009 = "Perhaps.",
  str_homestory_chat_28224010 = "Really? Are you sure?",
  str_homestory_chat_28224011 = "The Chubbs say the waters can get pretty complicated sometimes.",
  str_homestory_chat_28224012 = "But I don't know the details.",
  str_homestory_chat_28224013 = "Complicated you say? Looks like a proper survey is required.",
  str_homestory_chat_28224014 = "Maybe... I jumped the gun a little.",
  str_homestory_chat_28225001 = "Your blade...",
  str_homestory_chat_28225002 = "What about it?",
  str_homestory_chat_28225003 = "Someone has lodged a complaint against you.",
  str_homestory_chat_28225004 = "Huh? Who? Why would they do that?",
  str_homestory_chat_28225005 = "The Chubbs. They see that you're always playing with it.",
  str_homestory_chat_28225006 = "And they think you might hurt them.",
  str_homestory_chat_28225007 = "Well, they're right.",
  str_homestory_chat_28225008 = "That's why I'm here in Cloud Gardens. To hunt Chubbs.",
  str_homestory_chat_28225009 = "Are you serious?!",
  str_homestory_chat_28225010 = "Did you seriously believe that?",
  str_homestory_chat_28225011 = "Of course I'm not!",
  str_homestory_chat_28225012 = "So don't worry about it. Just tell them that I mean no harm.",
  str_homestory_chat_28225013 = "They shouldn't be scared, because fidgeting with my knife is just a habit of mine.",
  str_homestory_chat_28225014 = "R-right.",
  str_homestory_chat_28399999 = "PlayerName, wanna try some herbs?",
  str_homestory_chat_28301001 = "Looks like you found a lot of them!",
  str_homestory_chat_28301002 = "Yes, the climate here is great for growing herbs.",
  str_homestory_chat_28301003 = "Many plants in nature have medicinal effects.",
  str_homestory_chat_28301004 = "Not to mention those wonderful trees...",
  str_homestory_chat_28301005 = "Are you... after the Unique Tree now?",
  str_homestory_chat_28301006 = "Not yet. After all, the Chubbs are really protective of them.",
  str_homestory_chat_28301007 = "So I've been thinking about transplanting some of the Longzhou herbs here.",
  str_homestory_chat_28301008 = "That's a good idea.",
  str_homestory_chat_28321001 = "Snacks?",
  str_homestory_chat_28321002 = "I've been eating porridge for a while now, so I'm looking for snacks for a change.",
  str_homestory_chat_28321003 = "I asked the Chubb Merchant, but they don't have anything!",
  str_homestory_chat_28321004 = "Are there no good snacks in Astra?",
  str_homestory_chat_28321005 = "No, there are!",
  str_homestory_chat_28321006 = "Keep talking.",
  str_homestory_chat_28321007 = "Gummies from Northland.",
  str_homestory_chat_28321008 = "They are soft, not too sweet, and don't get stuck to your teeth. The faintly sweet aftertaste is to die for.",
  str_homestory_chat_28321009 = "Chocolates from Umbraton.",
  str_homestory_chat_28321010 = "Pure chocolate is really bitter, so many shops add milk, sugar, and even a variety of nuts to it.",
  str_homestory_chat_28321011 = "Like hazelnuts, pine nuts, acorns...",
  str_homestory_chat_28321012 = "Stop.",
  str_homestory_chat_28321013 = "You're drooling...",
  str_homestory_chat_28321014 = "One day, I will try them all! But for now...",
  str_homestory_chat_28321015 = "I guess I'll make do with my imagination.",
  str_homestory_chat_28321016 = "In some way, you really are something.",
  str_homestory_chat_28322001 = "A steelyard?",
  str_homestory_chat_28322002 = "Yes, check this out.",
  str_homestory_chat_28322003 = "After coming to Astra, I realize the way you weigh things is different.",
  str_homestory_chat_28322004 = "You use the thing on the ground that has a dish on each side.",
  str_homestory_chat_28322005 = "You mean a scale.",
  str_homestory_chat_28322006 = "Yes, but they don't look very portable, and you need a flat surface to use them.",
  str_homestory_chat_28322007 = "My steelyard is much easier to use. Why is Astra behind on this?",
  str_homestory_chat_28322008 = "Actually, they use steelyards in Umbraton.",
  str_homestory_chat_28322009 = "Wait, what?",
  str_homestory_chat_28322010 = "At least the Lin Guild, I think. Besides, scales are very accurate.",
  str_homestory_chat_28322011 = "Steelyards... can be affected by the person operating them.",
  str_homestory_chat_28322012 = "I see. I guess it's like Buzi said, \"adopt measures suiting local conditions!\"",
  str_homestory_chat_28322013 = "You mean, each have their merits.",
  str_homestory_chat_28323001 = "You're looking for a cat?",
  str_homestory_chat_28323002 = "Well, more accurately, my brother is looking for a companion.",
  str_homestory_chat_28323003 = "Your brother?",
  str_homestory_chat_28323004 = "Tinytail! Anyway, do you have a cat or not?",
  str_homestory_chat_28323005 = "Not here, but those who come to stay might bring one or two.",
  str_homestory_chat_28323006 = "Why don't you ask them?",
  str_homestory_chat_28323007 = "But they're from Astra, and I don't know them well.",
  str_homestory_chat_28323008 = "You all live here, it'll be fine!",
  str_homestory_chat_28323009 = "R-really?",
  str_homestory_chat_28323010 = "You're so outgoing, it won't be a problem.",
  str_homestory_chat_28323011 = "I guess I'll have to do it! I'm going to ask them in a day or two.",
  str_homestory_chat_28499999 = "It seems you have a lot of free time today, little Caelestite.",
  str_homestory_chat_28421001 = "It seems you do too.",
  str_homestory_chat_28421002 = "I'm just going for a stroll.",
  str_homestory_chat_28421003 = "A stroll?",
  str_homestory_chat_28421004 = "Since I don't have any important tasks to attend to, and there's not much work to do in Cloud Gardens...",
  str_homestory_chat_28421005 = "Not to mention that hardly anything around here can arouse my interest, so... Yeah.",
  str_homestory_chat_28421006 = "Okay.",
  str_homestory_chat_28422001 = "You want to talk about food?",
  str_homestory_chat_28422002 = "Right. I don't know what you like to eat, little Caelestite.",
  str_homestory_chat_28422003 = "Desserts",
  str_homestory_chat_28422004 = "You actually like sweet things... How trite.",
  str_homestory_chat_28422005 = "But everyone likes sweet stuff, like chocolate.",
  str_homestory_chat_28422006 = "However, chocolate is actually bitter. The reason you think it's sweet is actually because of the added sugar.",
  str_homestory_chat_28422007 = "So... do you like bitter things?",
  str_homestory_chat_28422008 = "Not really...",
  str_homestory_chat_28422009 = "Meat",
  str_homestory_chat_28422010 = "Good taste! What about liver? Especially snacks made from liver...?",
  str_homestory_chat_28422011 = "Erm... I don't think so.",
  str_homestory_chat_28422012 = "Oh, how unfortunate.",
  str_homestory_chat_28423001 = "Are you looking for wood?",
  str_homestory_chat_28423002 = "Yes, I want to build a small nest in my room. Is that okay?",
  str_homestory_chat_28423003 = "Sure.",
  str_homestory_chat_28423004 = "That's not such a good idea.",
  str_homestory_chat_28423005 = "But... what do you want to build a nest for?",
  str_homestory_chat_28423006 = "To make a home for it. It hasn't been sleeping well recently...",
  str_homestory_chat_28423007 = "Who?",
  str_homestory_chat_28423008 = "Sacred Python of course, it can't be expected to sleep on someone else's bed every night...",
  str_homestory_chat_28423009 = "O-Of course not! What a terrifying thought...",
  str_homestory_chat_28423010 = "So, it's alright then?",
  str_homestory_chat_28423011 = "Well... You can make one under your bed.",
  str_homestory_chat_28424001 = "Books?",
  str_homestory_chat_28424002 = "Right. I want to ask you, little Caelestite, what do you like to read?",
  str_homestory_chat_28424003 = "Novels.",
  str_homestory_chat_28424004 = "What a plain reply...",
  str_homestory_chat_28424005 = "But there are so many good novels, especially all those Umbraton mystery novels...",
  str_homestory_chat_28424006 = "It seems this genre is really very popular...",
  str_homestory_chat_28424007 = "Biographies.",
  str_homestory_chat_28424008 = "Oh? Interesting... Are you interested in history?",
  str_homestory_chat_28424009 = "I want to know more about Astra history.",
  str_homestory_chat_28424010 = "Hey, what books do you like, Jeriah?",
  str_homestory_chat_28424011 = "Philosophy.",
  str_homestory_chat_28424012 = "Yikes!",
  str_homestory_chat_28424013 = "You seem surprised. Philosophy is actually very interesting. I'll recommend some books to you when I have time.",
  str_homestory_chat_28424014 = "A-Alright.",
  str_homestory_chat_28425001 = "A Chubb?",
  str_homestory_chat_28425002 = "Yes. I've noticed that one of the Chubbs is really very intelligent.",
  str_homestory_chat_28425003 = "Which Chubb?",
  str_homestory_chat_28425004 = "The one with the beard in Hyacinth Square.",
  str_homestory_chat_28425005 = "Elder Chubb?",
  str_homestory_chat_28425006 = "Yes. It's called the Elder, so it must be wise.",
  str_homestory_chat_28425007 = "Just because of this...?",
  str_homestory_chat_28425008 = "In fact, the \"Elder\" is also known as \"Beardy\"...",
  str_homestory_chat_28425009 = "Beardy?",
  str_homestory_chat_28425010 = "I think it just stuck a fake beard on its face to look smart.",
  str_homestory_chat_28425011 = "Umm... I see.",
  str_homestory_chat_28425012 = "Well, that's embarrassing...",
  str_homestory_chat_28425013 = "I think I should leave.",
  str_homestory_chat_28599999 = "Hi, PlayerName. What's going on today?",
  str_homestory_chat_28501001 = "Nothing much. You good?",
  str_homestory_chat_28501002 = "I want to find a part-time job in Cloud Gardens.",
  str_homestory_chat_28501003 = "A part-time job?",
  str_homestory_chat_28501004 = "I've already asked the Elder Chubb and the Chubb Merchant, but they don't seem to have anything suitable for me.",
  str_homestory_chat_28501005 = "Yeah, there's not much work available here, and we all just take care of our own affairs.",
  str_homestory_chat_28501006 = "Don't you have any delivery work available? Sending mail is important, you know!",
  str_homestory_chat_28501007 = "This place isn't too big. There's no delivery work, plus, people come here to take a break from all that.",
  str_homestory_chat_28501008 = "*sigh* Oh well...",
  str_homestory_chat_28521001 = "Is something bugging you?",
  str_homestory_chat_28521002 = "Yes, and it's the kind of thing that simply cannot be tolerated for a moment.",
  str_homestory_chat_28521003 = "Erm... Eclipsites?",
  str_homestory_chat_28521004 = "Everyone hates Eclipsites...",
  str_homestory_chat_28521005 = "Bad guys?",
  str_homestory_chat_28521006 = "What does that mean?",
  str_homestory_chat_28521007 = "Like... people who hurt your friends.",
  str_homestory_chat_28521008 = "I see.",
  str_homestory_chat_28521009 = "So, what do you hate, Kya?",
  str_homestory_chat_28521010 = "People who are late!",
  str_homestory_chat_28521011 = "How can anyone bear not to be punctual? And sometimes we've already set the time in advance.",
  str_homestory_chat_28521012 = "People who don't care about being on time... should all be taught a lesson!",
  str_homestory_chat_28521013 = "Right...",
  str_homestory_chat_28522001 = "Are you looking to buy something?",
  str_homestory_chat_28522002 = "Yes, I'd like to buy a watch.",
  str_homestory_chat_28522003 = "But we don't sell watches in Cloud Gardens. Are you sure you're in the right place?",
  str_homestory_chat_28522004 = "No, I heard you have a special service here.",
  str_homestory_chat_28522005 = "Special service?",
  str_homestory_chat_28522006 = "Yes, the legendary \"Cloud Gardens Discount\" I've heard about.",
  str_homestory_chat_28522007 = "It's supposed to be a huge discount. Some say it's up to a quarter of the usual price!",
  str_homestory_chat_28522008 = "That's ridiculous! Who told you that?",
  str_homestory_chat_28522009 = "Huh? So that won't do...?",
  str_homestory_chat_28522010 = "What a pity... I came across a watch in Umbraton that I really liked...",
  str_homestory_chat_28522011 = "But it's too expensive. It'll take me ten years to afford it... With a discount, it'll only take two and a half years...",
  str_homestory_chat_28522012 = "Wow... You need to ask for a raise.",
  str_homestory_chat_28522013 = "It's all because Umbraton is too expensive! I curse those soulless merchants!",
  str_homestory_chat_28522014 = "Right!",
  str_homestory_chat_28523001 = "Food?",
  str_homestory_chat_28523002 = "Yes, I don't even know what you usually like to eat, PlayerName.",
  str_homestory_chat_28523003 = "Hmm... I just eat whatever's on offer.",
  str_homestory_chat_28523004 = "You really don't care?",
  str_homestory_chat_28523005 = "I drank the nutrient solution the Colossus made for me for years on end...",
  str_homestory_chat_28523006 = "So... you don't really know how to enjoy food... but I guess I'm the same.",
  str_homestory_chat_28523007 = "Oh? Really?",
  str_homestory_chat_28523008 = "Sometimes I just eat a biscuit or some jerky so my orders aren't late.",
  str_homestory_chat_28523009 = "It's only after I finish work that I eat whatever I want, like spicy fried noodles.",
  str_homestory_chat_28523010 = "It seems you're always working hard too, PlayerName... But maybe that's the only way we've managed to achieve what we have.",
  str_homestory_chat_28523011 = "Erm... I think you completely misunderstood the situation there.",
  str_homestory_chat_28699999 = "You look so laid-back, PlayerName.",
  str_homestory_chat_28621001 = "So do you.",
  str_homestory_chat_28621002 = "Indeed, this feeling is so relaxing that it makes me sleepy, yawn—",
  str_homestory_chat_28621003 = "Yawn—",
  str_homestory_chat_28621004 = "It looks like you're the same.",
  str_homestory_chat_28621005 = "Is this sleepiness infectious?",
  str_homestory_chat_28621006 = "How interesting... Are you going to take a nap?",
  str_homestory_chat_28621007 = "No, I have somewhere else I need to go first.",
  str_homestory_chat_28621008 = "I hope you stay motivated then!",
  str_homestory_chat_28622001 = "Your hand...",
  str_homestory_chat_28622002 = "Are you referring to my Divine Hand?",
  str_homestory_chat_28622003 = "Yes.",
  str_homestory_chat_28622004 = "Oh it's a long story... You just need to know it can use powerful Luminatics.",
  str_homestory_chat_28622005 = "I see...",
  str_homestory_chat_28622006 = "No.",
  str_homestory_chat_28622007 = "It's your left hand.",
  str_homestory_chat_28622008 = "My left hand? Sure, I do get asked about that quite often too.",
  str_homestory_chat_28622009 = "That's right... Your left hand is powerful. Is that the power of the Divine Hand?",
  str_homestory_chat_28622010 = "Oh... Not at all. It's because I always use my left hand.",
  str_homestory_chat_28622011 = "It became really strong without me realizing it...",
  str_homestory_chat_28622012 = "I guess this counts as a type of indirect training.",
  str_homestory_chat_28623001 = "Eclipsites?",
  str_homestory_chat_28623002 = "It seems that the Eclipsites have never come here.",
  str_homestory_chat_28623003 = "That's right.",
  str_homestory_chat_28623004 = "It would be a big deal if they really do come here.",
  str_homestory_chat_28623005 = "Eh... Then how can I find it...",
  str_homestory_chat_28623006 = "It?",
  str_homestory_chat_28623007 = "Oh, uh, nothing! Even if there are no Eclipsites, it should be okay to ask where there are traces of Eclipsites, right?",
  str_homestory_chat_28623008 = "Do you know anything about it?",
  str_homestory_chat_28623009 = "Either way, there are none here, so you should just give up on your idea.",
  str_homestory_chat_28623010 = "I guess I'll have to ask those Chubbs then.",
  str_homestory_chat_28623011 = "They don't know either!",
  str_homestory_chat_28624001 = "You want to do business?",
  str_homestory_chat_28624002 = "Actually, I just want to buy some things like books.",
  str_homestory_chat_28624003 = "You can't really get those here in Cloud Gardens. Why don't you go to Umbraton?",
  str_homestory_chat_28624004 = "Because it's too far. I just want to see if there's a bookstore nearby to buy random books to pass the time.",
  str_homestory_chat_28624005 = "Isn't Lumopolis and Umbraton quite close...?",
  str_homestory_chat_28624006 = "But I'm already here. Does the Chubb Merchant have anything to sell?",
  str_homestory_chat_28624007 = "As far as I know, no.",
  str_homestory_chat_28624008 = "Oh? It looks like I can only...Yawn...",
  str_homestory_chat_28624009 = "Go take a nap. That's also a way to pass the time.",
  str_homestory_chat_28625001 = "Snacks?",
  str_homestory_chat_28625002 = "Yes. What snacks do you like to eat?",
  str_homestory_chat_28625003 = "Small cakes.",
  str_homestory_chat_28625004 = "So you like sweets... Do you feel unwell in any way after eating them?",
  str_homestory_chat_28625005 = "No, Tina. You don't like sweet things?",
  str_homestory_chat_28625006 = "Cookies.",
  str_homestory_chat_28625007 = "Especially slightly salty ones because they taste so good with some hot water.",
  str_homestory_chat_28625008 = "You've made a good choice. Desserts don't have to be sweet...",
  str_homestory_chat_28625009 = "Eating snacks with a variety of flavors is the way to go!",
  str_homestory_chat_28625010 = "It seems that you don't like sweet things...",
  str_homestory_chat_28625011 = "I hate them because I get inexplicably anxious and have difficulty sleeping after eating them.",
  str_homestory_chat_28625012 = "It's very painful to toss and turn in bed. Do you know what it's like?",
  str_homestory_chat_28625013 = "It's happened to me before. I felt so tired the next day.",
  str_homestory_chat_28625014 = "Yes, that's why I sometimes need to sleep during the day too.",
  str_homestory_chat_28625015 = "But you're always sleeping even when you haven't eaten anything sweet...",
  str_homestory_chat_28999999 = "PlayerName, what do you need me to do?",
  str_homestory_chat_28921001 = "Oh? Let's just chat casually.",
  str_homestory_chat_28921002 = "It looks like you're quite free yourself. Do you want to develop some hobbies?",
  str_homestory_chat_28921003 = "Like what?",
  str_homestory_chat_28921004 = "It's quite nice to plant flowers.",
  str_homestory_chat_28921005 = "You get to watch the sown seeds sprout and grow before finally blooming into magnificent flowers...",
  str_homestory_chat_28921006 = "It'll make you sigh at the beauty of nature.",
  str_homestory_chat_28921007 = "I'm already planting trees...",
  str_homestory_chat_28921008 = "That's good too. Keep it up, and you'll be inspired one day.",
  str_homestory_chat_28922001 = "Your weapon...",
  str_homestory_chat_28922002 = "What about it?",
  str_homestory_chat_28922003 = "Sometimes it doesn't seem like a weapon, especially that drill bit.",
  str_homestory_chat_28922004 = "I understand. It doesn't look like the standard weapons used by the Lumo Knights, right?",
  str_homestory_chat_28922005 = "Exactly! And many knights use swords, spears, and others...",
  str_homestory_chat_28922006 = "Is there a reason for this?",
  str_homestory_chat_28922007 = "The reason isn't important, just like how the weapon a knight uses isn't important.",
  str_homestory_chat_28922008 = "Not important?",
  str_homestory_chat_28922009 = "Because a knight's chivalry is the thing that makes a knight who they are.",
  str_homestory_chat_28922010 = "I know! Like they say, a knight's virtues include humility, tolerance, and so on...",
  str_homestory_chat_28922011 = "Yes, that's what makes a knight a knight—not weapons.",
  str_homestory_chat_28922012 = "I understand.",
  str_homestory_chat_28923001 = "What do you want to buy?",
  str_homestory_chat_28923002 = "I want to buy some oil.",
  str_homestory_chat_28923003 = "What oil?",
  str_homestory_chat_28923004 = "I should have some cooking oil around here.",
  str_homestory_chat_28923005 = "I need it to lubricate parts. I should be able to get them in Umbraton.",
  str_homestory_chat_28923006 = "Well...",
  str_homestory_chat_28923007 = "There's some difficulty, right? I mean, this is a place full of natural scenery.",
  str_homestory_chat_28923008 = "Hmm... It's true that we really don't need much of that here.",
  str_homestory_chat_28923009 = "I mainly want to use it to do some maintenance. My weapon seems to be getting stuck recently.",
  str_homestory_chat_28923010 = "I hear this creaking sound that makes my teeth ache when I swing it.",
  str_homestory_chat_28923011 = "In that case... Let's make time to go to Umbraton.",
  str_homestory_chat_28924001 = "What's on your mind?",
  str_homestory_chat_28924002 = "I'm thinking about something really important, but I can't seem to find an answer.",
  str_homestory_chat_28924003 = "Why don't you tell me about it?",
  str_homestory_chat_28924004 = "What do you think is more important, fairness or equality?",
  str_homestory_chat_28924005 = "Fairness.",
  str_homestory_chat_28924006 = "So do you agree that the disadvantaged should have more rights?",
  str_homestory_chat_28924007 = "Such as granting them immunity even if they commit some light crimes?",
  str_homestory_chat_28924008 = "Let me think...",
  str_homestory_chat_28924009 = "Equality.",
  str_homestory_chat_28924010 = "Let's say two runners are competing in a sprint.",
  str_homestory_chat_28924011 = "One practice sprinting a lot, while the other is a soldier with a broken leg.",
  str_homestory_chat_28924012 = "According to you, the criteria for winning should not take the physical condition of these two into account.",
  str_homestory_chat_28924013 = "Yes.",
  str_homestory_chat_28924014 = "But is that really good?",
  str_homestory_chat_28924015 = "Ahhhh! These questions are so annoying, and I can't find the right answer.",
  str_homestory_chat_28924016 = "Yes... that's why I'm pacing back and forth here.",
  str_homestory_chat_28925001 = "The Rediesel Desert?",
  str_homestory_chat_28925002 = "I've heard that you've traveled to many places. Have you visited this place?",
  str_homestory_chat_28925003 = "I don't have much of an impression of this place.",
  str_homestory_chat_28925004 = "Oh... How unfortunate.",
  str_homestory_chat_28925005 = "It sounds like you've been there before, Leyn?",
  str_homestory_chat_28925006 = "I've been fortunate enough to visit it several times. The scenery there is truly different from Lumopolis.",
  str_homestory_chat_28925007 = "The residents there see things differently from the residents of Lumopolis too. No matter how difficult life is, there's no shortage of those who rise to the occasion.",
  str_homestory_chat_28925008 = "It sounds like you have quite a story to tell about your experiences in the Rediesel Desert...",
  str_homestory_chat_28925009 = "I'll tell you about it if I have the opportunity.",
  str_homestory_chat_28925010 = "Yes, I've been there.",
  str_homestory_chat_28925011 = "What do you think about the local culture and customs?",
  str_homestory_chat_28925012 = "They're passionate and unrestrained... just like the desert.",
  str_homestory_chat_28925013 = "Indeed. Although I couldn't really adapt to them, I think their existence is necessary for this land.",
  str_homestory_chat_28925014 = "It's the same for many things in this world.",
  str_homestory_chat_29099999 = "PlayerName, today is a good day for taking a walk.",
  str_homestory_chat_29001001 = "Hi, Matthieu.",
  str_homestory_chat_29001002 = "It looks like today is another relaxing day for you. The commoners here sure are relaxed.",
  str_homestory_chat_29001003 = "There are no commoners here. Everyone is equal.",
  str_homestory_chat_29001004 = "What about those square fellows?",
  str_homestory_chat_29001005 = "You mean the Chubbs?",
  str_homestory_chat_29001006 = "Yes, I see them working everywhere at all hours of the day.",
  str_homestory_chat_29001007 = "Some of them are guides at Hyacinth Tower, while others water plants or do accounts all day long.",
  str_homestory_chat_29001008 = "That's what they're passionate about...",
  str_homestory_chat_29021001 = "You want to build something?",
  str_homestory_chat_29021002 = "Yes, I have more money than I can spend anyway.",
  str_homestory_chat_29021003 = "That's not what I meant... Don't you live in Lumopolis?",
  str_homestory_chat_29021004 = "Shouldn't you build something there?",
  str_homestory_chat_29021005 = "It's because there's something I can't tolerate here.",
  str_homestory_chat_29021006 = "What's that?",
  str_homestory_chat_29021007 = "The mud caused by the rain! I'm going to build a roof over the valley.",
  str_homestory_chat_29021008 = "One that can block the whole sky.",
  str_homestory_chat_29021009 = "That's huge!",
  str_homestory_chat_29021010 = "What about our lighting needs then?",
  str_homestory_chat_29021011 = "You don't need to worry about that. I heard you can install a device that opens the roof up when it's sunny and closes it when it rains.",
  str_homestory_chat_29021012 = "I heard about this from the Illumina members here. Apparently, that's what they do in their Undercities.",
  str_homestory_chat_29021013 = "I feel like you've learned some strange things...",
  str_homestory_chat_29021014 = "So you agree then! I'll let you estimate the cost then.",
  str_homestory_chat_29021015 = "Wait! I haven't agreed to it yet!",
  str_homestory_chat_29022001 = "Tableware?",
  str_homestory_chat_29022002 = "The tableware here is too crude. Look at them—they make even the most delicious foods unpalatable.",
  str_homestory_chat_29022003 = "That's a bit of an exaggeration!",
  str_homestory_chat_29022004 = "I'm telling the truth. See for yourself if you don't believe me! Everything is made of either wood or clay.",
  str_homestory_chat_29022005 = "There isn't even one silver table knife to cut bread.",
  str_homestory_chat_29022006 = "You must have been starving these last few days...",
  str_homestory_chat_29022007 = "So, can you please get us a set of silver tableware?",
  str_homestory_chat_29022008 = "Consider getting a white porcelain tea set for afternoon tea if you can.",
  str_homestory_chat_29022009 = "That costs a lot, right? It sounds really expensive. Do you know what it costs approximately?",
  str_homestory_chat_29022010 = "The price? I have no idea.",
  str_homestory_chat_29022011 = "You don't know the price but you want me to buy it... Are you thinking of making me pay for it first?",
  str_homestory_chat_29022012 = "That's a given. You can ask my butler for the money after you buy it.",
  str_homestory_chat_29022013 = "Hold on! I haven't said yes!",
  str_homestory_chat_29023001 = "You want to hire a servant?",
  str_homestory_chat_29023002 = "Yes, I'll offer great pay.",
  str_homestory_chat_29023003 = "What I want to know is why you suddenly want to hire a servant.",
  str_homestory_chat_29023004 = "We don't have any servants here.",
  str_homestory_chat_29023005 = "Why do you suddenly want to do this?",
  str_homestory_chat_29023006 = "It's so I can let my servant deal with all the miscellaneous things that arise.",
  str_homestory_chat_29023007 = "A noble like me must spend my time on more important matters.",
  str_homestory_chat_29023008 = "Such as considering the development of Cloud Gardens or exploring a nearby gem vein.",
  str_homestory_chat_29023009 = "I think you should experience what ordinary life is like when you're here...",
  str_homestory_chat_29023010 = "Maybe... those square fellows would be good candidates.",
  str_homestory_chat_29023011 = "The Chubbs?",
  str_homestory_chat_29023012 = "Good guess!",
  str_homestory_chat_29023013 = "No way!",
  str_homestory_chat_29199999 = "Are you patrolling Cloud Gardens or just out on a stroll?",
  str_homestory_chat_29101001 = "What are you up to?",
  str_homestory_chat_29101002 = "Nothing at all, so just spacing out.",
  str_homestory_chat_29101003 = "That's really an honest answer...",
  str_homestory_chat_29101004 = "I have nothing to do, so I've been hanging out and thinking.",
  str_homestory_chat_29101005 = "Yeah, you can take this opportunity to relax a little.",
  str_homestory_chat_29121001 = "Children?",
  str_homestory_chat_29121002 = "Yeah, since there're no children here, it's a bit... too quiet.",
  str_homestory_chat_29121003 = "There are.",
  str_homestory_chat_29121004 = "Where?",
  str_homestory_chat_29121005 = "Those guys, for example, are from Lumopolis, Rediesel Wrench...",
  str_homestory_chat_29121006 = "They should come to stay at Cloud Gardens for a few days.",
  str_homestory_chat_29121007 = "You mean them? Sigh...",
  str_homestory_chat_29121008 = "Why are you sighing?",
  str_homestory_chat_29121009 = "They're not kids anymore. They're capable of being independent.",
  str_homestory_chat_29121010 = "That's true.",
  str_homestory_chat_29121011 = "There really aren't any.",
  str_homestory_chat_29121012 = "Sigh. I'll have to go see Chubb, then.",
  str_homestory_chat_29121013 = "Why? What are you planning to do?",
  str_homestory_chat_29121014 = "Relax, I'm just going to watch them from afar and help only when there's a problem.",
  str_homestory_chat_29121015 = "Like tripping and falling.",
  str_homestory_chat_29121016 = "Why are you being so nice?",
  str_homestory_chat_29121017 = "What are you getting at?",
  str_homestory_chat_29121018 = "Nothing! Thanks!",
  str_homestory_chat_29122001 = "Word puzzles?",
  str_homestory_chat_29122002 = "You like word puzzles?",
  str_homestory_chat_29122003 = "Yes.",
  str_homestory_chat_29122004 = "Not really.",
  str_homestory_chat_29122005 = "Why do you ask?",
  str_homestory_chat_29122006 = "I'm bored and got no word puzzles to solve.",
  str_homestory_chat_29122007 = "I thought the Chubb with glasses would like them, but all it could think about was bean-counting.",
  str_homestory_chat_29122008 = "And the bearded Chubb just putz around all day like you...",
  str_homestory_chat_29122009 = "Ahem, I'm checking out the whole Cloud Gardens, not putzing around.",
  str_homestory_chat_29122010 = "As for you, Hati, you can't figure out a way to relax other than solving word puzzles?",
  str_homestory_chat_29122011 = "That's because word puzzles are liberating, especially when you solve a very difficult one...",
  str_homestory_chat_29122012 = "You just can't describe how that feels!",
  str_homestory_chat_29122013 = "I think you ought to focus on relaxing your mind...",
  str_homestory_chat_29123001 = "What are you getting?",
  str_homestory_chat_29123002 = "Needle and threads.",
  str_homestory_chat_29123003 = "You must be sewing something. Is there a hole or rip in your clothes?",
  str_homestory_chat_29123004 = "You may have strong psychic ability, but you're not observant.",
  str_homestory_chat_29123005 = "What?",
  str_homestory_chat_29123006 = "I have to mend a damaged doll.",
  str_homestory_chat_29123007 = "You mend those things?",
  str_homestory_chat_29123008 = "Something wrong? I can make them too, just need rags, needles and threads.",
  str_homestory_chat_29123009 = "You don't seem like the kind...",
  str_homestory_chat_29123010 = "So to you, I'm someone who shouldn't be into that, PlayerName?",
  str_homestory_chat_29123011 = "That's because you seemed too cool and straightforward for that type of things.",
  str_homestory_chat_29123012 = "That's stereotyping on your part.",
  str_homestory_chat_29123013 = "Being cool and straightforward has no relevance to dollmaking.",
  str_homestory_chat_29123014 = "True.",
  str_homestory_chat_29124001 = "Spices?",
  str_homestory_chat_29124002 = "I want some spices for seasoning purpose.",
  str_homestory_chat_29124003 = "It sounds to me you're cooking something delicious.",
  str_homestory_chat_29124004 = "That's right, I'm making a stew!",
  str_homestory_chat_29124005 = "Stew!",
  str_homestory_chat_29124006 = "So what meat did you bring, specifically?",
  str_homestory_chat_29124007 = "Meat? I got no meat.",
  str_homestory_chat_29124008 = "What?",
  str_homestory_chat_29124009 = "It's too big to carry and it will rot. Does anyone sell meat around here?",
  str_homestory_chat_29124010 = "Uh... No.",
  str_homestory_chat_29124011 = "Then we have a big problem, especially when I don't see a prey anywhere.",
  str_homestory_chat_29124012 = "So fishing might be the only alternative, then? Substitute meat with fish?",
  str_homestory_chat_29124013 = "Wouldn't that be a fish dish instead?",
  str_homestory_chat_29124014 = "Fish stew is fine too. It can be yummy, and not much seasoning is needed.",
  str_homestory_chat_29124015 = "I get the feeling you're over the meat problem.",
  str_homestory_chat_29399999 = "Are you busy?",
  str_homestory_chat_29321001 = "Spear training?",
  str_homestory_chat_29321002 = "I would like to know if there's a spear instructor in Cloud Gardens.",
  str_homestory_chat_29321003 = "This is a place of peace...",
  str_homestory_chat_29321004 = "It's just for practice and to be in shape, or the spear might turn dull.",
  str_homestory_chat_29321005 = "Why are you striving so hard when you're only here for a few days?",
  str_homestory_chat_29321006 = "I cannot be complacent! I must maintain discipline as a noble of Lumopolis!",
  str_homestory_chat_29321007 = "Okay, you can start practicing by yourself, I guess...",
  str_homestory_chat_29322001 = "Somebody filed a complaint about you.",
  str_homestory_chat_29322002 = "Really? Who is it?",
  str_homestory_chat_29322003 = "Your roommates.",
  str_homestory_chat_29322004 = "Did they find my daily spear practice unsettling?",
  str_homestory_chat_29322005 = "Yes.",
  str_homestory_chat_29322006 = "There's more, as well.",
  str_homestory_chat_29322007 = "Did they find my getting up too early irritating?",
  str_homestory_chat_29322008 = "That too...",
  str_homestory_chat_29322009 = "So you're saying there's more to it?",
  str_homestory_chat_29322010 = "Yes, mostly griping about how you'd always fold the blankets into perfect cubes.",
  str_homestory_chat_29322011 = "Should it be that way? It's disgusting to just leave them sprawled on the beds!",
  str_homestory_chat_29322012 = "The point is, you cannot demand others to do the same.",
  str_homestory_chat_29322013 = "But...",
  str_homestory_chat_29322014 = "Anyway, don't be so strict with others.",
  str_homestory_chat_29323001 = "What would you like to ask Chubbs?",
  str_homestory_chat_29323002 = "I want to know if they could be my squires.",
  str_homestory_chat_29323003 = "There's no precedence for that in Cloud Gardens, but you can do that in Lumopolis?",
  str_homestory_chat_29323004 = "I am a knight, therefore have the right to enlist squires. Do I have your approval, Master of Cloud Gardens?",
  str_homestory_chat_29323005 = "Yes.",
  str_homestory_chat_29323006 = "Let me think about that.",
  str_homestory_chat_29323007 = "Wait a minute, what made you want them to be your squires?",
  str_homestory_chat_29323008 = "Because I think they're fit for the duty!",
  str_homestory_chat_29323009 = "Square-jawed, barrel-chested...",
  str_homestory_chat_29323010 = "They are certainly squire material who will follow the knightly virtues!",
  str_homestory_chat_29323011 = "I think you got it all wrong...",
  str_homestory_chat_29323012 = "No way! They have the looks for it and I know they can do it!",
  str_homestory_chat_29323013 = "Well, then you have to pardon my rejection because it won't work.",
  str_homestory_chat_29324001 = "Opera?",
  str_homestory_chat_29324002 = "What impression do you have of opera?",
  str_homestory_chat_29324003 = "A pretty good one.",
  str_homestory_chat_29324004 = "It's not a problem, then!",
  str_homestory_chat_29324005 = "Can't say I cared enough...",
  str_homestory_chat_29324006 = "Sigh. I see it's going to be a problem.",
  str_homestory_chat_29324007 = "What are you up to?",
  str_homestory_chat_29324008 = "I'd like to build a stage in Cloud Gardens so I can invite troupes to perform.",
  str_homestory_chat_29324009 = "If there's room, it would be nice to make it a full-blown opera house, plus a resident troupe or two.",
  str_homestory_chat_29324010 = "Then we can see the newest opera anytime.",
  str_homestory_chat_29324011 = "Uh, I don't think that's possible...",
  str_homestory_chat_29999999 = "Hi, how have you been recent??",
  str_homestory_chat_29901001 = "Pretty good, and you?",
  str_homestory_chat_29901002 = "I've adapted to life in Cloud Gardens, but I feel that the pace here is a bit slow.",
  str_homestory_chat_29901003 = "Slow?",
  str_homestory_chat_29901004 = "Wouldn't it be great if there were a few challenges here occasionally, like a tree-felling competition?",
  str_homestory_chat_29901005 = "Let's just sit back and relax.",
  str_homestory_chat_29921001 = "Drinks?",
  str_homestory_chat_29921002 = "What would you like?",
  str_homestory_chat_29921003 = "Coffee",
  str_homestory_chat_29921004 = "A very popular choice. Would it be right to say that others have an influence on you?",
  str_homestory_chat_29921005 = "Yes, and I often find it to be quite fun, making coffee for yourself and things like that...",
  str_homestory_chat_29921006 = "If you go to a cafe, you can also chat with your friends while sipping your coffee.",
  str_homestory_chat_29921007 = "That makes sense.",
  str_homestory_chat_29921008 = "Tea",
  str_homestory_chat_29921009 = "What do you like about tea? I heard some teas are very bitter.",
  str_homestory_chat_29921010 = "If you add a little something to it, it can taste great. Also, if you only add tea leaves...",
  str_homestory_chat_29921011 = "The first taste might be bitter, but you'll feel an inexplicable sweetness in your throat afterward.",
  str_homestory_chat_29921012 = "I heard it can also refresh the mind.",
  str_homestory_chat_29921013 = "That's right. I suggest giving it a try next time.",
  str_homestory_chat_29921014 = "Juice",
  str_homestory_chat_29921015 = "So, you prefer natural flavors... Well, that makes sense—you're a Caelestite.",
  str_homestory_chat_29921016 = "Some mixed juice can also be quite nice... I think I just simply like the refreshing sensation.",
  str_homestory_chat_29921017 = "And it can also help to supplement various nutrients, making it beneficial for your body. I'll consider it next time.",
  str_homestory_chat_29921018 = "Right! That's great!",
  str_homestory_chat_29921019 = "Soda water",
  str_homestory_chat_29921020 = "You really enjoy burping after every sip? Unbelievable!",
  str_homestory_chat_29921021 = "Don't you think you're overreacting...?",
  str_homestory_chat_29922001 = "You want to grow something here?",
  str_homestory_chat_29922002 = "I want to start working on a patch here in Cloud Gardens and grow some beans.",
  str_homestory_chat_29922003 = "Sure",
  str_homestory_chat_29922004 = "There should still be a lot of open space here... but first, we need to ask the Chubbs.",
  str_homestory_chat_29922005 = "No",
  str_homestory_chat_29922006 = "Wait, why beans?",
  str_homestory_chat_29922007 = "According to Illumina's research, these beans are the most suitable crops for large-scale cultivation, and they boast relatively high nutrition.",
  str_homestory_chat_29922008 = "What about the taste?",
  str_homestory_chat_29922009 = "There are countless flavors and myriad ways to prepare beans!",
  str_homestory_chat_29922010 = "I remember there being a lot of kinds in Umbraton... I think there was one called tofu.",
  str_homestory_chat_29922011 = "I know tofu! I hear it's from the Far East—a miracle food that transforms beans into magic!",
  str_homestory_chat_29922012 = "It melts in the mouth, and without any seasoning, it still possesses a natural bean flavor...",
  str_homestory_chat_29922013 = "And it's versatile! Whether sweet, salty, sour, or spicy, tofu can be paired with any seasoning!",
  str_homestory_chat_29922014 = "That's really impressive...",
  str_homestory_chat_29923001 = "You want to go to Umbraton?",
  str_homestory_chat_29923002 = "After being in Cloud Gardens for so long, I've come to realize that there isn't much communication between here and Umbraton.",
  str_homestory_chat_29923003 = "Yeah, Cloud Gardens is a relatively secluded place.",
  str_homestory_chat_29923004 = "But this is a pretty unique feature—this seclusion allows for undisturbed tranquility.",
  str_homestory_chat_29923005 = "And it's not too much trouble getting to Umbraton from here...",
  str_homestory_chat_29923006 = "I'd like to be able to buy some milk from Umbraton regularly.",
  str_homestory_chat_29923007 = "Milk?",
  str_homestory_chat_29923008 = "Illumina provides milk rations, but there's nothing like this in Cloud Gardens, and there doesn't seem to be a store where I can buy some either.",
  str_homestory_chat_29923009 = "Right. If you want to drink milk, you can only get it from outside.",
  str_homestory_chat_29923010 = "If you really want some, remind me the next time I go to Umbraton and I'll pick up a few boxes for you.",
  str_homestory_chat_29923011 = "But Umbraton isn't exactly close by, so I'm afraid I won't get to sample the fresh milk they have on offer...",
  str_homestory_chat_29923012 = "In that case... how about yogurt?",
  str_homestory_chat_29923013 = "Sure, yogurt is good!",
  str_homestory_chat_29923014 = "Glad to hear it.",
  str_homestory_chat_29924001 = "A birdhouse?",
  str_homestory_chat_29924002 = "Right, to hang from the window or on the roof.",
  str_homestory_chat_29924003 = "I mean... why do you want a birdhouse?",
  str_homestory_chat_29924004 = "For Aoha. I can't let it perch at my fingertips all the time.",
  str_homestory_chat_29924005 = "Especially when I'm sleeping... I feel like it has nowhere to go.",
  str_homestory_chat_29924006 = "It does sound less than ideal.",
  str_homestory_chat_29924007 = "So, I'd like to give it a little house. It doesn't need to be a big one.",
  str_homestory_chat_29924008 = "I've seen some small birdhouses in Umbraton. They looked simple enough, but the wood...",
  str_homestory_chat_29924009 = "I've already asked the Chubbs to buy some.",
  str_homestory_chat_29924010 = "Of course you did, Yingel. You're so efficient.",
  str_homestory_chat_29924011 = "You agree with me, yes?",
  str_homestory_chat_29924012 = "I don't see any reason why not... As long as you don't take up anyone else's space.",
  str_homestory_chat_29924013 = "Now we need to find a carpenter...",
  str_homestory_chat_29924014 = "That looks like we still have a way to go before it's finished.",
  str_homestory_chat_29299999 = "It's a pleasure to see you.",
  str_homestory_chat_29201001 = "How's it going?",
  str_homestory_chat_29201002 = "Peace, prosperity—Cloud Gardens is truly a paradise. It's an honor to be able to take a break here.",
  str_homestory_chat_29201003 = "Enjoy it, and relax to your heart's content.",
  str_homestory_chat_29201004 = "This is why I often think to myself that I should also redouble my efforts to protect this paradise.",
  str_homestory_chat_29201005 = "And in particular, we shouldn't allow some decaying sludge to pollute this place, thereby drawing the invasion of evil entities.",
  str_homestory_chat_29201006 = "Thanks for your hard work.",
  str_homestory_chat_29221001 = "What fruit do you like?",
  str_homestory_chat_29221002 = "Why would you ask me that all of a sudden?",
  str_homestory_chat_29221003 = "It just popped into my head.",
  str_homestory_chat_29221004 = "I like the fruits from the south, mainly because they are juicy, nutritious, and have a wide variety of flavors.",
  str_homestory_chat_29221005 = "And you?",
  str_homestory_chat_29221006 = "Apples",
  str_homestory_chat_29221007 = "That's a very common kind of fruit. What do you like about them?",
  str_homestory_chat_29221008 = "Perhaps it's because they're so common. Also, apples are quite sweet and have a crispy texture.",
  str_homestory_chat_29221009 = "That's right. Because they're so common, there are so many ways to prepare them.",
  str_homestory_chat_29221010 = "I hear that they can also be seasoned. With this in mind, they can indeed be considered a fruit truly benefitting the public.",
  str_homestory_chat_29221011 = "Right.",
  str_homestory_chat_29221012 = "Grapes",
  str_homestory_chat_29221013 = "Grapes are very common, and they have become a popular source of many beverages.",
  str_homestory_chat_29221014 = "Like what?",
  str_homestory_chat_29221015 = "People would drink wine during meals in Lumopolis, and some soft drinks in Illumina would also add grape juice.",
  str_homestory_chat_29221016 = "I've also heard that some people eat dried grapes as snacks in the Rediesel Desert.",
  str_homestory_chat_29221017 = "We're not talking about drinks anymore, are we?",
  str_homestory_chat_29221018 = "Right, but those raisins can actually be used as an ingredient in sweet bread.",
  str_homestory_chat_29221019 = "That's really amazing.",
  str_homestory_chat_29222001 = "What food do you like?",
  str_homestory_chat_29222002 = "I like hot food, especially simply-cooked meat without any complicated techniques.",
  str_homestory_chat_29222003 = "What do you mean?",
  str_homestory_chat_29222004 = "Simply put, I like boiled meat, paired with my favorite seasonings.",
  str_homestory_chat_29222005 = "It sounds very convenient.",
  str_homestory_chat_29222006 = "Yes—for soldiers, this kind of food is both convenient and delicious, and can quickly replenish one's physical strength.",
  str_homestory_chat_29222007 = "Therefore, it's important to always pay attention to meat supplies to ensure there's always hot food available on the battlefield.",
  str_homestory_chat_29222008 = "It can also be a complicated matter...",
  str_homestory_chat_29222009 = "Complicated?",
  str_homestory_chat_29222010 = "There are many things to consider, the first being which fuel to use to cook the food.",
  str_homestory_chat_29222011 = "Then the considerations range from preserving the meat to satisfying the taste preferences of each soldier.",
  str_homestory_chat_29222012 = "These are all things leaders need to consider, and a single mistake made in any one of these respects can lead to low morale.",
  str_homestory_chat_29222013 = "Wow... I had no idea how thorough you were.",
  str_homestory_chat_29223001 = "Drawing a map?",
  str_homestory_chat_29223002 = "Yes. Are you versed in the art of cartography?",
  str_homestory_chat_29223003 = "I know a little.",
  str_homestory_chat_29223004 = "Excellent. Then I could really use your help.",
  str_homestory_chat_29223005 = "Not really.",
  str_homestory_chat_29223006 = "What do you want a map for?",
  str_homestory_chat_29223007 = "I've been here for many days now, yet I still feel a certain uneasiness in my heart.",
  str_homestory_chat_29223008 = "Why do you feel that way?",
  str_homestory_chat_29223009 = "After much contemplation, I can only assume that it's due to my unfamiliarity with Cloud Gardens.",
  str_homestory_chat_29223010 = "Let me put it like this—I'm not very familiar with this place, and I always feel somewhat unsafe when in unfamiliar places.",
  str_homestory_chat_29223011 = "You don't have to worry about outsiders coming here. You can relax.",
  str_homestory_chat_29223012 = "Be that as it may... I still feel as though I'll need to master the terrain by surveying and mapping it to feel at ease.",
  str_homestory_chat_29223013 = "Right... Keep it up then.",
  str_homestory_chat_29224001 = "Looking to buy some weapons?",
  str_homestory_chat_29224002 = "Oh, it seems you misunderstood me. I wanted to ask you if you would consider building a museum.",
  str_homestory_chat_29224003 = "A museum?",
  str_homestory_chat_29224004 = "One celebrating the weapons of the world, such as the long halberd of Lumopolis and the command saber of Illumina...",
  str_homestory_chat_29224005 = "Do you really need to build a museum for that? It sounds like there aren't even that many kinds of weapons available. Can't we just designate a collection room?",
  str_homestory_chat_29224006 = "That's not it! Even somewhere like Illumina, with its tradition of mass-produced weapons, has a wealth of models and varieties!",
  str_homestory_chat_29224007 = "There are dozens of lances, handguns, military knives and daggers, as well as all the melee weapons, long-range weapons, cold weapons, and hot weapons...",
  str_homestory_chat_29224008 = "Moreover, the weapons used by the nobles of Lumopolis also come in different styles and bear unique insignias.",
  str_homestory_chat_29224009 = "I could go on about the details forever. Anyhow, that's why a single collection room won't suffice.",
  str_homestory_chat_29224010 = "So, there really are so many kinds... Wait! Do you own all these weapons?",
  str_homestory_chat_29224011 = "Only a small portion, but that won't hinder me from starting a collection from this moment forward.",
  str_homestory_chat_29224012 = "So, you don't have that many right now... That makes me feel a bit better.",
  str_homestory_chat_29224013 = "Considering how safe this place is, I should be able to keep my collection safe here. That's why I want to build a dedicated weaponry museum.",
  str_homestory_chat_29224014 = "Let me think about it.",
  str_homestory_chat_30099999 = "Any news today?",
  str_homestory_chat_30021001 = "Hey, do you have any hobbies?",
  str_homestory_chat_30021002 = "Hobbies... Why do you ask, PlayerName?",
  str_homestory_chat_30021003 = "I just want to know, is all.",
  str_homestory_chat_30021004 = "Perhaps observation is my only real hobby... How about you?",
  str_homestory_chat_30021005 = "I don't really have any hobbies.",
  str_homestory_chat_30021006 = "Actually, I'm not quite sure.",
  str_homestory_chat_30021007 = "Maybe it's... walking?",
  str_homestory_chat_30021008 = "Wait, wasn't I the one asking you?",
  str_homestory_chat_30021009 = "And that's my answer.",
  str_homestory_chat_30021010 = "So... your hobby is gathering intelligence...?",
  str_homestory_chat_30022001 = "You seem to enjoy taking notes.",
  str_homestory_chat_30022002 = "That's right. As the saying goes, \"a poor record is better than a brilliant mind.\"",
  str_homestory_chat_30022003 = "I always see you writing and drawing. It looks exhausting.",
  str_homestory_chat_30022004 = "I'm used to it—and I have my secret weapon.",
  str_homestory_chat_30022005 = "Secret weapon?",
  str_homestory_chat_30022006 = "It's called shorthand.",
  str_homestory_chat_30022007 = "It sounds powerful... like some kind of secret technique that can't be passed down.",
  str_homestory_chat_30022008 = "You need to memorize loads of abbreviations, mnemonics, symbols, and so on, right?",
  str_homestory_chat_30022009 = "Erm, not really. In fact, the shorthand method is mainly developed based on an individual's own writing habits.",
  str_homestory_chat_30022010 = "Huh?",
  str_homestory_chat_30022011 = "In many cases, the corresponding abbreviations only need to be understood by you yourself, because you'll still write a proper one in the end.",
  str_homestory_chat_30022012 = "I see.",
  str_homestory_chat_30023001 = "I hear you want to buy something?",
  str_homestory_chat_30023002 = "I want to buy a telescope for observation.",
  str_homestory_chat_30023003 = "Do you enjoy observing animals or plants?",
  str_homestory_chat_30023004 = "Ah... That's part of it.",
  str_homestory_chat_30023005 = "A part of it?",
  str_homestory_chat_30023006 = "Intelligence gathered on animals and plants can only be considered auxiliary to a certain extent...",
  str_homestory_chat_30023007 = "I mainly observe the daily activity in Cloud Gardens, such as the lives of the Chubbs...",
  str_homestory_chat_30023008 = "Them again...",
  str_homestory_chat_30023009 = "Again?",
  str_homestory_chat_30023010 = "It seems a lot of people are interested in them these days.",
  str_homestory_chat_30023011 = "Because, unlike us, they are native to this place.",
  str_homestory_chat_30023012 = "The more I learn, the more I can know about Cloud Gardens, which will naturally be of use to you.",
  str_homestory_chat_30023013 = "I think... it's still better to just spend your time relaxing as much as you can.",
  str_homestory_chat_30024001 = "Raising fish?",
  str_homestory_chat_30024002 = "This place feels like it would be very suitable for fish farming. Do you have a fish pond?",
  str_homestory_chat_30024003 = "We have one here.",
  str_homestory_chat_30024004 = "Not at the moment...",
  str_homestory_chat_30024005 = "So, you want to raise some fish?",
  str_homestory_chat_30024006 = "Yes. When I saw the pool at the square, I suddenly thought raising fish in Cloud Gardens might be good.",
  str_homestory_chat_30024007 = "However, the fish I like is quite strange and I wish to raise it separately.",
  str_homestory_chat_30024008 = "Are you talking about Bubble? It seems a bit dangerous.",
  str_homestory_chat_30024009 = "Don't worry about that, it's just an ordinary creature. My main concern is that it's not suitable for raising in a group, so I wish to raise it separately.",
  str_homestory_chat_30024010 = "Understood... I'll look into it.",
  str_homestory_chat_30299999 = "Are you surveying your territory again?",
  str_homestory_chat_30221001 = "Just going for a walk.",
  str_homestory_chat_30221002 = "Have you ever thought about security issues here?",
  str_homestory_chat_30221003 = "Yes.",
  str_homestory_chat_30221004 = "That is what an owner should do! What is your conclusion?",
  str_homestory_chat_30221005 = "I checked, and given the Gardens' terrain, it's fine the way it is.",
  str_homestory_chat_30221006 = "Keeping it the same...? I feel that is rather lax. You should bolster security measures.",
  str_homestory_chat_30221007 = "I'll take it into consideration.",
  str_homestory_chat_30221008 = "Nope.",
  str_homestory_chat_30221009 = "This is too complacent!",
  str_homestory_chat_30221010 = "Well, this is a very hard place to find, and everyone came here to relax.",
  str_homestory_chat_30221011 = "It's not necessary to fuss over security issues.",
  str_homestory_chat_30221012 = "Are you sure?",
  str_homestory_chat_30221013 = "Yeah, it's not a problem!",
  str_homestory_chat_30221014 = "What about you, have you thought about it?",
  str_homestory_chat_30221015 = "I have made several rounds over the past few days, and it is safe by normal standards.",
  str_homestory_chat_30221016 = "I'm relieved to hear you say that.",
  str_homestory_chat_30221017 = "But still, do not let your guard down since one can never be too careful...",
  str_homestory_chat_30221018 = "A-All right.",
  str_homestory_chat_30221019 = "There's no need for that.",
  str_homestory_chat_30221020 = "How can you be so complacent? Have you ever given it any serious thought?",
  str_homestory_chat_30221021 = "Well, I'll examine it in detail.",
  str_homestory_chat_30222001 = "I'm thinking about Eraveil.",
  str_homestory_chat_30222002 = "It seems you are finally contemplating how to govern this land!",
  str_homestory_chat_30222003 = "Yes.",
  str_homestory_chat_30222004 = "Though I haven't made much headway.",
  str_homestory_chat_30222005 = "Oh, not yet.",
  str_homestory_chat_30222006 = "Do you have any ideas or suggestions?",
  str_homestory_chat_30222007 = "It is best to assign the locals to oversee.",
  str_homestory_chat_30222008 = "By locals, you mean...",
  str_homestory_chat_30222009 = "The Chubbs, of course.",
  str_homestory_chat_30222010 = "That makes sense.",
  str_homestory_chat_30223001 = "Actually...",
  str_homestory_chat_30223002 = "It's a nice day today, so I decided to take a walk.",
  str_homestory_chat_30223003 = "I see you like to go for a walk in such nice weather. It does clear the mind.",
  str_homestory_chat_30223004 = "A leisurely walk in peaceful surroundings on a sunny day is conducive to thinking.",
  str_homestory_chat_30223005 = "Or you don't even have to think and just relax, take it easy.",
  str_homestory_chat_30223006 = "After all, the point is to enjoy the relaxing environment here.",
  str_homestory_chat_30223007 = "The environment is indeed relaxing, but I am not accustomed to this.",
  str_homestory_chat_30223008 = "Why is that?",
  str_homestory_chat_30223009 = "In Lumopolis, even though it is bright and sunny, I feel my shoulders are weighed down.",
  str_homestory_chat_30223010 = "And it is called responsibility, which also makes me ruminate nonstop.",
  str_homestory_chat_30223011 = "That's gotta be a heavy load. You should take it easy now that you're here.",
  str_homestory_chat_30223012 = "No, it is an armor that can protect me and hone me to take on challenges.",
  str_homestory_chat_30223013 = "Uh, maybe you shouldn't be so uptight...",
  str_homestory_chat_30224001 = "I'm thinking about the book I read a few days ago.",
  str_homestory_chat_30224002 = "What is it?",
  str_homestory_chat_30224003 = "Mystery novel",
  str_homestory_chat_30224004 = "It's very popular in Umbraton lately and the romance aspects were particularly interesting...",
  str_homestory_chat_30224005 = "A novel, you said? Fictions are good only for relaxation. They contained very limited knowledge for you to gain.",
  str_homestory_chat_30224006 = "If you truly want to read, you ought to opt for history books.",
  str_homestory_chat_30224007 = "History book",
  str_homestory_chat_30224008 = "Great choice.",
  str_homestory_chat_30224009 = "You like reading history books too?",
  str_homestory_chat_30224010 = "That's right.",
  str_homestory_chat_30224011 = "It is grounded in facts for you to review the past and even predict the future.",
  str_homestory_chat_30224012 = "While prognostication is somewhat a hyperbole, you can at least glean much knowledge.",
  str_homestory_chat_30224013 = "It is much more intellectually rewarding than fabricated tales.",
  str_homestory_chat_30224014 = "Sure, I'll read more.",
  str_homestory_chat_30225001 = "Yes.",
  str_homestory_chat_30225002 = "\"Never stop sowing, whether day or night.\"",
  str_homestory_chat_30225003 = "What's that?",
  str_homestory_chat_30225004 = "It is a Lumopolis proverb, meaning one must work hard all the time. You did it, and I hope you can maintain the attitude.",
  str_homestory_chat_30225005 = "I will.",
  str_homestory_chat_30225006 = "In that case, I can consider granting you a title. It would be Lumopolis' fortune to have more nobles like you.",
  str_homestory_chat_30225007 = "Really?",
  str_homestory_chat_30225008 = "It is a joke, obviously.",
  str_homestory_chat_30225009 = "Oh, never mind, then.",
  str_homestory_chat_30199999 = "Are you by yourself too?",
  str_homestory_chat_30121001 = "Yes",
  str_homestory_chat_30121002 = "I-I see you like to be alone too...",
  str_homestory_chat_30121003 = "Actually, I'm just taking a walk since it's a nice day out, and I got nothing better to do.",
  str_homestory_chat_30121004 = "So you spend your downtime taking a walk? It seems you like it very much.",
  str_homestory_chat_30121005 = "Or do you have another solo hobby?",
  str_homestory_chat_30121006 = "Well, a stroll is just one of the options. I like to hang out with friends sometimes too.",
  str_homestory_chat_30121007 = "I-I see...",
  str_homestory_chat_30122001 = "No",
  str_homestory_chat_30122002 = "So where are your friends?",
  str_homestory_chat_30122003 = "W-What I meant is I was looking to hang out with somebody and ran into you.",
  str_homestory_chat_30122004 = "I guess you like to hang out and chat.",
  str_homestory_chat_30122005 = "Yes, actually.",
  str_homestory_chat_30122006 = "I get the urge to chat sometimes... Do you get that too?",
  str_homestory_chat_30122007 = "I do feel that way.",
  str_homestory_chat_30122008 = "Ah, I thought you just liked being alone.",
  str_homestory_chat_30122009 = "That's true, but like you, I want to talk with others on occasion.",
  str_homestory_chat_30122010 = "Sometimes, I guess.",
  str_homestory_chat_30122011 = "Oh? I thought you love to chat.",
  str_homestory_chat_30122012 = "Not really. Sometimes I'd prefer to be alone, other times I'd want to chat.",
  str_homestory_chat_30122013 = "It all depends on my mood at the time. What about you?",
  str_homestory_chat_30122014 = "I'd prefer solitude most of the time, but I would like to talk occasionally, like you.",
  str_homestory_chat_30122015 = "Particularly to her... I always believed I had a lot to say to her if I ever met her.",
  str_homestory_chat_30122016 = "I hope you do.",
  str_homestory_chat_30123001 = "What are you doing?",
  str_homestory_chat_30123002 = "Thinking about how I'm going to make Knight's Black Tea here.",
  str_homestory_chat_30123003 = "Knight's Black Tea?",
  str_homestory_chat_30123004 = "It's a drink in Lumopolis, very popular.",
  str_homestory_chat_30123005 = "I heard about it, though the ingredient is tough to deal with.",
  str_homestory_chat_30123006 = "That's right. You'll need imported tea...",
  str_homestory_chat_30123007 = "As well as top-quality teaware, fine techniques and flavor adjustments.",
  str_homestory_chat_30123008 = "Making a fine cup of Knight's Black Tea might take a whole afternoon.",
  str_homestory_chat_30123009 = "That's a long time!",
  str_homestory_chat_30123010 = "Yeah, it's afternoon tea, after all.",
  str_homestory_chat_30123011 = "If you make it in the morning, you could be drinking it at noon, right?",
  str_homestory_chat_30123012 = "But that would be noon tea, then? Or morning tea if even earlier?",
  str_homestory_chat_30123013 = "That thought never crossed my mind...",
  str_homestory_chat_30124001 = "What games do you like to play?",
  str_homestory_chat_30124002 = "The solo kind...",
  str_homestory_chat_30124003 = "Solo games? Chess with yourself? Or just taking a walk?",
  str_homestory_chat_30124004 = "I'd play poker myself sometimes. What do you do when you're alone?",
  str_homestory_chat_30124005 = "Fishing.",
  str_homestory_chat_30124006 = "That's a nice activity. I heard it's very calming.",
  str_homestory_chat_30124007 = "Heard? You've never fished before?",
  str_homestory_chat_30124008 = "I didn't get many chances to try, or many opportunities to even get out.",
  str_homestory_chat_30124009 = "You should enjoy that here, then.",
  str_homestory_chat_30124010 = "Playing cards?",
  str_homestory_chat_30124011 = "Speaking of playing cards, tell me how to play poker alone.",
  str_homestory_chat_30124012 = "The rules are... rather complicated. I'll show you when we get a chance.",
  str_homestory_chat_30124013 = "All right.",
  str_homestory_chat_30125001 = "How do you feel?",
  str_homestory_chat_30125002 = "It feels great here, especially when I can come out during the daytime.",
  str_homestory_chat_30125003 = "Come out during the daytime?",
  str_homestory_chat_30125004 = "Yeah, because of my status...",
  str_homestory_chat_30125005 = "Got you.",
  str_homestory_chat_30125006 = "But it's still different from the likes of Umbraton, right?",
  str_homestory_chat_30125007 = "Yes... Not many streets and no shops.",
  str_homestory_chat_30125008 = "Is it boring to you?",
  str_homestory_chat_30125009 = "No, not at all.",
  str_homestory_chat_30125010 = "It's a little bland, but the natural scenery is very nice.",
  str_homestory_chat_30125011 = "Hearing the birds chirp, staring at the glistening streams under the sun...",
  str_homestory_chat_30125012 = "That sounded a little forced... I'll get the Chubbs to order more merch next time.",
  str_homestory_chat_30125013 = "The Fountain of Hope, Hyacinth Tower, and Museum are pretty fun to visit too...",
  str_homestory_chat_30125014 = "Okay, got it...",
  str_homestory_chat_30399999 = "Want a divination?",
  str_homestory_chat_30321001 = "I'd like to know...",
  str_homestory_chat_30321002 = "All right, work, finally! What do you want a reading on?",
  str_homestory_chat_30321003 = "Career",
  str_homestory_chat_30321004 = "Money",
  str_homestory_chat_30321005 = "Romance",
  str_homestory_chat_30321006 = "Decided? Let's begin!",
  str_homestory_chat_30321007 = "Wait, that's not I want...",
  str_homestory_chat_30321008 = "Then what is it? I'm all set to go.",
  str_homestory_chat_30321009 = "I just want to know if the divination would actually work.",
  str_homestory_chat_30321010 = "What are you getting at? I've been practicing since I was very little!",
  str_homestory_chat_30321011 = "S-So you should be able to tell the future, right? You could just do divination for everything.",
  str_homestory_chat_30321012 = "Not really. First, the setting and timing must be right, then you need inspiration...",
  str_homestory_chat_30321013 = "And luck is the greatest factor, since I failed to get an outcome several times!",
  str_homestory_chat_30321014 = "In other words, divination could fail!",
  str_homestory_chat_30321015 = "I see.",
  str_homestory_chat_30323001 = "I don't need one right now, then...",
  str_homestory_chat_30323002 = "But I was inspired and you just ruined it.",
  str_homestory_chat_30323003 = "Oh, sorry.",
  str_homestory_chat_30323004 = "Gotta figure out the design for the new family outfit.",
  str_homestory_chat_30323005 = "Family outfit?",
  str_homestory_chat_30323006 = "It's for Whisper. We gotta be in matching outfits.",
  str_homestory_chat_30323007 = "I-It needs clothes too?",
  str_homestory_chat_30323008 = "Yeah. Whisper might get sick when it gets cold.",
  str_homestory_chat_30323009 = "Wearing something can keep it warm, not to mention matching fashion!",
  str_homestory_chat_30323010 = "Impressive! But for Whisper's outfit...",
  str_homestory_chat_30323011 = "That's up to me to design and sew!",
  str_homestory_chat_30322001 = "I heard you like stories?",
  str_homestory_chat_30322002 = "Yes, especially during divination!",
  str_homestory_chat_30322003 = "You need that for your divination?",
  str_homestory_chat_30322004 = "I need to get the client's full attention so they can listen to every word I say.",
  str_homestory_chat_30322005 = "Even if the divination fails, the client won't feel it's a total waste of money!",
  str_homestory_chat_30322006 = "Isn't that almost like a... scam?",
  str_homestory_chat_30322007 = "Absolutely not! Exciting tales are worth it!",
  str_homestory_chat_30322008 = "That's why I talk to Louise a lot, I even take her to a lot of places for that!",
  str_homestory_chat_30322009 = "Louise?",
  str_homestory_chat_30322010 = "Yeah, she's from Northland too, and a great storyteller.",
  str_homestory_chat_30322011 = "I think you two may be qualified to write novels in Umbraton now...",
  str_homestory_chat_30324001 = "Are you trying to find rocks?",
  str_homestory_chat_30324002 = "Yeah. You know where the nice-looking rocks are?",
  str_homestory_chat_30324003 = "By the river.",
  str_homestory_chat_30324004 = "In the woods.",
  str_homestory_chat_30324005 = "Thanks!",
  str_homestory_chat_30324006 = "Are the rocks for your divination?",
  str_homestory_chat_30324007 = "No, no, just for fashion accessories.",
  str_homestory_chat_30324008 = "The Chubbs looked so drab walking around in plain white every day.",
  str_homestory_chat_30324009 = "I get it's simple, but wouldn't they look better with necklaces made out of colorful rocks?",
  str_homestory_chat_30324010 = "But you haven't asked them yet!",
  str_homestory_chat_30324011 = "It's okay, they'll love it!",
  str_homestory_chat_30324012 = "A-Are you sure about that...?",
  str_homestory_chat_30499999 = "We meet again. You certainly are a hard worker.",
  str_homestory_chat_30421001 = "Yeah, just making the rounds.",
  str_homestory_chat_30421002 = "I heard you're well-traveled. Where do you think is suitable for living in seclusion?",
  str_homestory_chat_30421003 = "Living in seclusion? You mean places where you can live all by yourself?",
  str_homestory_chat_30421004 = "Not entirely accurate. Preferably, inconspicuous but still with neighbors around.",
  str_homestory_chat_30421005 = "Hmm, let me think...",
  str_homestory_chat_30421006 = "Umbraton.",
  str_homestory_chat_30421007 = "I recall the phrase—hiding in plain sight.",
  str_homestory_chat_30421008 = "So when it's crowded with all kinds of people, no one will notice you.",
  str_homestory_chat_30421009 = "It's an option to consider.",
  str_homestory_chat_30421010 = "Northland.",
  str_homestory_chat_30421011 = "At the base of the World's Spine...?",
  str_homestory_chat_30421012 = "Cold, quiet, remote. A good destination.",
  str_homestory_chat_30421013 = "Fewer people there, so the land is sparsely populated and somewhat closed off.",
  str_homestory_chat_30421014 = "I guess that's the price for security and privacy...",
  str_homestory_chat_30421015 = "Rediesel Wrench.",
  str_homestory_chat_30421016 = "What? Isn't that a band of wild, wandering nomads?",
  str_homestory_chat_30421017 = "Yes, but they also supposedly have a lot of people from different factions.",
  str_homestory_chat_30421018 = "And once you join and get used to the customs, they're great people.",
  str_homestory_chat_30421019 = "That doesn't sound too bad.",
  str_homestory_chat_30421020 = "A small town.",
  str_homestory_chat_30421021 = "You can find it almost anywhere, so that's probably the last option.",
  str_homestory_chat_30421022 = "True.",
  str_homestory_chat_30422001 = "You seem to smile often.",
  str_homestory_chat_30422002 = "That's because I love it here.",
  str_homestory_chat_30422003 = "Thanks.",
  str_homestory_chat_30422004 = "The landscape isn't exceptional, but it's very comforting and serene to me.",
  str_homestory_chat_30422005 = "It's a feeling difficult to find elsewhere.",
  str_homestory_chat_30422006 = "Maybe because it's more out-of-way here?",
  str_homestory_chat_30422007 = "No, it's the overall mood, especially the attitude.",
  str_homestory_chat_30422008 = "The smile on everyone's face, and those laidback Chubbs...",
  str_homestory_chat_30422009 = "Those lazy bums... were they goofing off again?",
  str_homestory_chat_30422010 = "You're missing the point, child.",
  str_homestory_chat_30423001 = "You're up very early.",
  str_homestory_chat_30423002 = "Because I have to make the bed.",
  str_homestory_chat_30423003 = "Make the bed? Personally?",
  str_homestory_chat_30423004 = "Yes, what's the matter?",
  str_homestory_chat_30423005 = "I just didn't think you would do this kind of housework.",
  str_homestory_chat_30423006 = "Did you feel that way because of who I was?",
  str_homestory_chat_30423007 = "Uh...",
  str_homestory_chat_30423008 = "It's nothing, I did it mostly because I liked making beds for the kids.",
  str_homestory_chat_30423009 = "Sometimes, when I got up in the morning, I'd start doing it out of habit, even though they were still in bed.",
  str_homestory_chat_30423010 = "So they had no choice but to get up early, and would complain sometimes.",
  str_homestory_chat_30423011 = "I can imagine.",
  str_homestory_chat_30423012 = "But that's a part of instilling discipline. Can't sleep in, and that goes for you too!",
  str_homestory_chat_30423013 = "What? Uh, yeah, of course!",
  str_homestory_chat_30424001 = "Music?",
  str_homestory_chat_30424002 = "That's right. What kind of music do you like?",
  str_homestory_chat_30424003 = "The softer kind.",
  str_homestory_chat_30424004 = "I like the music I heard in Lumopolis last time.",
  str_homestory_chat_30424005 = "Gentle, elegant vibe.",
  str_homestory_chat_30424006 = "Easy listening is certainly very nice music.",
  str_homestory_chat_30424007 = "The more intense kind.",
  str_homestory_chat_30424008 = "You mean the kind that sounded like noise...",
  str_homestory_chat_30424009 = "It's more than that. It has rhythms too.",
  str_homestory_chat_30424010 = "Is that so...?",
  str_homestory_chat_30424011 = "But don't you feel it's too quiet not having music here?",
  str_homestory_chat_30424012 = "The sounds of nature will do. You can call that music too.",
  str_homestory_chat_30424013 = "But if it's another kind of music you want, you still have to go to the proper venues.",
  str_homestory_chat_30424014 = "You're right. I should enjoy this music for as long as I'm in Cloud Gardens.",
  str_homestory_chat_30425001 = "What don't I like?",
  str_homestory_chat_30425002 = "I can't think of anything off-hand... Why do you feel like asking that?",
  str_homestory_chat_30425003 = "The dorm felt somewhat humid this morning from the rain a few days ago...",
  str_homestory_chat_30425004 = "So it reminded me of my days back in Umbraton.",
  str_homestory_chat_30425005 = "Umbraton... Did you catch the rainy season?",
  str_homestory_chat_30425006 = "Sigh, it was drizzling all day, and the bed wasn't comfortable no matter what you do...",
  str_homestory_chat_30425007 = "I heard it is that way in Umbraton, especially for those months...",
  str_homestory_chat_30425008 = "But we don't get much of that in Cloud Gardens.",
  str_homestory_chat_30425009 = "Which is why it feels nice here.",
  str_homestory_chat_30599999 = "What are you up to?",
  str_homestory_chat_30521001 = "I heard you're looking for perfumes?",
  str_homestory_chat_30521002 = "Yes. The air is very clean here, but it could use some perfume to accentuate it.",
  str_homestory_chat_30521003 = "Why perfumes?",
  str_homestory_chat_30521004 = "It's mostly for the Chubbs. I think they make perfect guides.",
  str_homestory_chat_30521005 = "But it's hard to tell many of them apart, unless you have perfumes.",
  str_homestory_chat_30521006 = "So, it's just to tell them apart? Isn't it absurd to use perfumes for that?",
  str_homestory_chat_30521007 = "True... With permanent markers, then? Like \"#1\", \"#2\" and so on.",
  str_homestory_chat_30521008 = "Uh... Never mind.",
  str_homestory_chat_30522001 = "Tea shop?",
  str_homestory_chat_30522002 = "We don't have anything like that here.",
  str_homestory_chat_30522003 = "Oh, no, I want to open a tea shop here and am doing research.",
  str_homestory_chat_30522004 = "Research on what?",
  str_homestory_chat_30522005 = "What everybody likes. For example, what do you like to drink?",
  str_homestory_chat_30522006 = "Milk.",
  str_homestory_chat_30522007 = "Hmm, a healthy choice.",
  str_homestory_chat_30522008 = "Soda pops.",
  str_homestory_chat_30522009 = "Oh? That's special.",
  str_homestory_chat_30522010 = "Coffee.",
  str_homestory_chat_30522011 = "Not bad.",
  str_homestory_chat_30522012 = "Black tea.",
  str_homestory_chat_30522013 = "You got good taste!",
  str_homestory_chat_30522014 = "By the way, you're surveying people other than me, right?",
  str_homestory_chat_30522015 = "How many do you have?",
  str_homestory_chat_30522016 = "I'm still asking one at a time, and then I have to sort through the early, mid and late responses, while updating every once in a while.",
  str_homestory_chat_30522017 = "That's a lot of trouble to go through...",
  str_homestory_chat_30522018 = "That's the only way to get accurate data for nailing down the signature drink.",
  str_homestory_chat_30522019 = "Somehow, I don't get the feeling it's ever going to open...",
  str_homestory_chat_30523001 = "Dance party?",
  str_homestory_chat_30523002 = "Yes. I've been feeling lethargic lately.",
  str_homestory_chat_30523003 = "I thought it over and realized I hadn't been to a dance party for a long time.",
  str_homestory_chat_30523004 = "I don't think there's a place for that here.",
  str_homestory_chat_30523005 = "Then throw one! All you need is a simple setup.",
  str_homestory_chat_30523006 = "Such as a square, chairs, banners and whatnot.",
  str_homestory_chat_30523007 = "But the band could be a problem. I think we should hire someone.",
  str_homestory_chat_30523008 = "Like the Chubbs, maybe...?",
  str_homestory_chat_30523009 = "Hold it, they don't know how to play instruments.",
  str_homestory_chat_30523010 = "They should start training, then.",
  str_homestory_chat_30523011 = "We need a special boot camp, the intense ten-day kind.",
  str_homestory_chat_30523012 = "Ten days?!",
  str_homestory_chat_30523013 = "Too much? Make it three, then.",
  str_homestory_chat_30523014 = "You're better off going to Lumopolis for a party...",
  str_homestory_chat_30524001 = "A guide?",
  str_homestory_chat_30524002 = "Yes, I feel this is a very big place ever since I got here.",
  str_homestory_chat_30524003 = "We need to have a guide so newcomers won't get lost.",
  str_homestory_chat_30524004 = "Hmm...",
  str_homestory_chat_30524005 = "So you agree?",
  str_homestory_chat_30524006 = "Well, you do have a point.",
  str_homestory_chat_30524007 = "This is a very big place and a guide would be very valuable.",
  str_homestory_chat_30524008 = "Let me think it over.",
  str_homestory_chat_30524009 = "Speaking of that, do you have a candidate already?",
  str_homestory_chat_30524010 = "The Chubbs!",
  str_homestory_chat_30524011 = "What? Them?",
  str_homestory_chat_30524012 = "They spend all day here and know the place inside out. They're perfect.",
  str_homestory_chat_30524013 = "Uh, tell you what, let me dwell on that...",
  str_homestory_chat_30699999 = "Any interesting project?",
  str_homestory_chat_30621001 = "Building an amusement park?",
  str_homestory_chat_30621002 = "Good idea, but it's too remote here, so how are we going to attract visitors? Or maybe targeting the locals?",
  str_homestory_chat_30621003 = "The Chubbs?",
  str_homestory_chat_30621004 = "That's right! It's a small population, but when taking the future into consideration...",
  str_homestory_chat_30621005 = "How's their birthrate? Can they proliferate quickly? How do they reproduce?",
  str_homestory_chat_30621006 = "It's similar to, uh, the Aurorians...?",
  str_homestory_chat_30621007 = "That didn't sound like you're sure at all.",
  str_homestory_chat_30621008 = "They probably can't reproduce.",
  str_homestory_chat_30621009 = "Really?",
  str_homestory_chat_30621010 = "Yeah. I never saw them being born, as if they all came out of nowhere.",
  str_homestory_chat_30621011 = "Interesting race... But I guess I can't make money off them.",
  str_homestory_chat_30621012 = "Wait, what if we try a different approach...? I got it!",
  str_homestory_chat_30621013 = "Let's hear it.",
  str_homestory_chat_30621014 = "Less means it's rare, rare means it's precious, precious means it attracts audience, audience means tickets!",
  str_homestory_chat_30621015 = "Are you thinking...",
  str_homestory_chat_30621016 = "Make them into stars and put them on shows throughout Astra!",
  str_homestory_chat_30621017 = "We'll call it the \"A Mysterious Race's World Tour!\" How's that?",
  str_homestory_chat_30621018 = "I think you should just quit now.",
  str_homestory_chat_30621019 = "Why?",
  str_homestory_chat_30621020 = "You're making them into a freak show...",
  str_homestory_chat_30621021 = "That may be doable.",
  str_homestory_chat_30621022 = "\"Superstar Chubbs\" is an intriguing proposal, but we got to get their thoughts first.",
  str_homestory_chat_30621023 = "No problem! Let me know what they say!",
  str_homestory_chat_30622001 = "Let's talk about Cloud Gardens.",
  str_homestory_chat_30622002 = "Sure, I wanted to discuss it, anyway.",
  str_homestory_chat_30622003 = "What is it?",
  str_homestory_chat_30622004 = "Real estate development. It's long on nature and short on convenience. ",
  str_homestory_chat_30622005 = "No food court, shopping district, entertainment... You can't attract tourists.",
  str_homestory_chat_30622006 = "I never wanted to attract tourists... I'm fine as long as my friends find it accommodating here.",
  str_homestory_chat_30622007 = "No! That might be sustainable for now, but ever wondered what's going to happen in the future?",
  str_homestory_chat_30622008 = "How long can you hold out once you run out of revenue?",
  str_homestory_chat_30622009 = "Rather than waiting for the future, you should be worrying about now! How about letting me run Cloud Gardens, what do you say?",
  str_homestory_chat_30622010 = "What are you getting at?",
  str_homestory_chat_30622011 = "Sell it to me. I'll make it into the premier business district in the world!",
  str_homestory_chat_30622012 = "I'd rather maintain the status quo.",
  str_homestory_chat_30623001 = "Let's talk about your hair, instead.",
  str_homestory_chat_30623002 = "My hair? There's nothing to talk about. It's pretty normal.",
  str_homestory_chat_30623003 = "I bet that hairdo is a big hassle.",
  str_homestory_chat_30623004 = "I just go to a hair salon. It's only a few thousand Nightium a pop.",
  str_homestory_chat_30623005 = "A few thousand! What do they do that's so expensive?",
  str_homestory_chat_30623006 = "Cut, trim, styling and so on. Speaking of, I just got an idea for a project.",
  str_homestory_chat_30623007 = "What is it?",
  str_homestory_chat_30623008 = "Open a hair salon here! I imagine there are enough people who need a hairdresser here, right?",
  str_homestory_chat_30623009 = "It will probably be small with a light staff, but as long as it has everything necessary and we can import products from Umbraton.",
  str_homestory_chat_30623010 = "A salon owner I know happens to have the right connections...",
  str_homestory_chat_30623011 = "I'm guessing you just want to have your hair done here.",
  str_homestory_chat_30623012 = "Of course I get to have it done for free if I owned it. You get 20% off, though!",
  str_homestory_chat_30623013 = "Only 20% off...?",
  str_homestory_chat_30623014 = "So you agreed?! I'll start the wheel turning tomorrow!",
  str_homestory_chat_30623015 = "Wait a minute, I was still pondering the option!",
  str_homestory_chat_30624001 = "I heard you got your eyes on the Chubbs lately?",
  str_homestory_chat_30624002 = "Correct. Interested in turning them over to me?",
  str_homestory_chat_30624003 = "They're not merchandise!",
  str_homestory_chat_30624004 = "No way!",
  str_homestory_chat_30624005 = "Got it. They signed a contract with you, right? Name your price.",
  str_homestory_chat_30624006 = "Compensations, transfer fees, signing bonuses... Everything's negotiable.",
  str_homestory_chat_30624007 = "What's that gotta do with anything? Why do you want them to work for you suddenly?",
  str_homestory_chat_30624008 = "I'm launching a big project and need some competent workers.",
  str_homestory_chat_30624009 = "Competent workers? You think Chubbs fit that description?",
  str_homestory_chat_30624010 = "Not a problem! For example, you don't realize what good workers Chubb Scholar and Chubb Merchant are!",
  str_homestory_chat_30624011 = "They can read and do math, know a lot, don't eat much, and probably don't sleep at all.",
  str_homestory_chat_30624012 = "What a perfect worker! Don't worry, I'll pay for overtime!",
  str_homestory_chat_30624013 = "Double wage for workdays, triple for holidays!",
  str_homestory_chat_30624014 = "Hold it, they might not be willing to do that!",
  str_homestory_chat_30625001 = "Stop thinking about projects and get a sip of something.",
  str_homestory_chat_30625002 = "But there's nothing to drink in Cloud Gardens. All I see is cold water.",
  str_homestory_chat_30625003 = "It's a hassle to bring coffee or tea from Umbraton.",
  str_homestory_chat_30625004 = "Is there no local specialty drink here?",
  str_homestory_chat_30625005 = "Supposedly, the leaves of certain unique trees give off a distinctive scent, but I don't know how it tastes in hot water.",
  str_homestory_chat_30625006 = "Unique trees, eh? That's an option to consider.",
  str_homestory_chat_30625007 = "Don't tell me you thought of another business idea?",
  str_homestory_chat_30625008 = "I'll have to taste it first before I can explore the commercial potential.",
  str_homestory_chat_30625009 = "Since you suggested it, I'll look into it when I have free time.",
  str_homestory_chat_30799999 = "What are you doing?",
  str_homestory_chat_30721001 = "Just making the round.",
  str_homestory_chat_30721002 = "Can't you do something more meaningful?",
  str_homestory_chat_30721003 = "This is a hobby of mine. You're probably bored out of your mind, though.",
  str_homestory_chat_30721004 = "You're right... Any activity to recommend in Cloud Gardens?",
  str_homestory_chat_30721005 = "Fishing?",
  str_homestory_chat_30721006 = "Too quiet, and it's embarrassing when you don't catch anything.",
  str_homestory_chat_30721007 = "Gardening?",
  str_homestory_chat_30721008 = "I see only big, weird trees around... Too awkward for my liking.",
  str_homestory_chat_30721009 = "Check out the museum.",
  str_homestory_chat_30721010 = "Nothing much to see there.",
  str_homestory_chat_30721011 = "You're just not into anything! Why don't you nap in your room?",
  str_homestory_chat_30721012 = "Don't get riled up. I was just trying to get you to relax and take it easy.",
  str_homestory_chat_30721013 = "Every time I see you, you're either making the round or working. I'm worried about you...",
  str_homestory_chat_30721014 = "Life is not limited to expanding Cloud Gardens.",
  str_homestory_chat_30721015 = "It's all good. Making the round to me is taking it easy. Call it a leisurely stroll.",
  str_homestory_chat_30721016 = "All right, got it. Please continue.",
  str_homestory_chat_30722001 = "I'm just taking a walk. You?",
  str_homestory_chat_30722002 = "I'm just looking for you. Mind going to Umbraton with me if you're free?",
  str_homestory_chat_30722003 = "Umbraton? Now?",
  str_homestory_chat_30722004 = "Someone gave me two VIP passes to a fancy restaurant so I can bring a guest.",
  str_homestory_chat_30722005 = "There's no such thing as a free lunch...",
  str_homestory_chat_30722006 = "You got a favor to ask, don't you?",
  str_homestory_chat_30722007 = "You didn't try to invite anyone else?",
  str_homestory_chat_30722008 = "Or should I say, you got nobody else you can invite?",
  str_homestory_chat_30722009 = "Is that how you feel about our friendship? We can't just sit down and share a meal?",
  str_homestory_chat_30722010 = "Let me think about it.",
  str_homestory_chat_30723001 = "I'm thinking about checking out the unique trees right now.",
  str_homestory_chat_30723002 = "Unique trees, you said... I heard some of them gave off mesmerizing scent.",
  str_homestory_chat_30723003 = "I'm pondering whether it can be made into perfume.",
  str_homestory_chat_30723004 = "They took a long time to grow, so don't mess with them.",
  str_homestory_chat_30723005 = "Not just me, the Chubbs wouldn't like it, either.",
  str_homestory_chat_30723006 = "That's bad. What am I going to do about my date?",
  str_homestory_chat_30723007 = "Your date?",
  str_homestory_chat_30723008 = "I promised to bring her special unique perfume.",
  str_homestory_chat_30723009 = "What is that supposed to be?",
  str_homestory_chat_30723010 = "A blend of unique tree pollens and evening dews, made just for her. The only one in the world.",
  str_homestory_chat_30723011 = "Will that smell good?",
  str_homestory_chat_30723012 = "Not necessarily, but it's fine as long as she thinks it's special.",
  str_homestory_chat_30723013 = "Guess that's what somebody called \"secrets of dating\"... Regardless, unique trees are out of the question.",
  str_homestory_chat_30723014 = "Fine, I see I'll have to break out other \"secrets.\"",
  str_homestory_chat_30724001 = "You're looking for Chubbs?",
  str_homestory_chat_30724002 = "Yes, I want to discuss issues about them.",
  str_homestory_chat_30724003 = "What's wrong?",
  str_homestory_chat_30724004 = "As the keepers of Cloud Gardens, they are charmless.",
  str_homestory_chat_30724005 = "But isn't serving people and ensuring the workings of Cloud Gardens enough?",
  str_homestory_chat_30724006 = "Wrong!",
  str_homestory_chat_30724007 = "If the keepers aren't charming, who would want to live here?",
  str_homestory_chat_30724008 = "Look at how square and boring they are.",
  str_homestory_chat_30724009 = "Cloud Gardens aren't amusement parks. We don't need a clientele.",
  str_homestory_chat_30724010 = "Everyone comes here to relax. The Chubbs just have to maintain the daily upkeep.",
  str_homestory_chat_30724011 = "Is that how it operates... I see.",
  str_homestory_chat_30725001 = "I heard you're looking for me?",
  str_homestory_chat_30725002 = "What I really want is to buy a plot here.",
  str_homestory_chat_30725003 = "Don't tell me someone wants to build a resort and is hiring you to run it?",
  str_homestory_chat_30725004 = "No, wrong, dude. I'm looking to retire here.",
  str_homestory_chat_30725005 = "Isn't it still too early for that?",
  str_homestory_chat_30725006 = "Just a thought. The environment here is nice, after all. Secluded, tranquil...",
  str_homestory_chat_30725007 = "Hope I make it to the day I can retire here.",
  str_homestory_chat_30899999 = "I'm here!",
  str_homestory_chat_30801001 = "Hi, Bopper!",
  str_homestory_chat_30801002 = "You saw me!",
  str_homestory_chat_30801003 = "That's because you waved at me.",
  str_homestory_chat_30801004 = "The guys in Rediesel Wrench always ignored me. I usually can't get a response out of them.",
  str_homestory_chat_30801005 = "No way! Have you tried to express yourself more, like tossing out suggestions?",
  str_homestory_chat_30801006 = "That's the reason I became a strategist! But only Giant Lizard seemed to pay attention to my plans...",
  str_homestory_chat_30801007 = "If only Sinsa would take my advice once in a while...",
  str_homestory_chat_30801008 = "I'm sure the day will come. Don't give up, Bopper!",
  str_homestory_chat_30821001 = "What's up with you lately?",
  str_homestory_chat_30821002 = "I think I'm going to eat in a bit. I'm a little hungry.",
  str_homestory_chat_30821003 = "Cloud Gardens is a little far from Rediesel Desert and probably don't have what I like, though.",
  str_homestory_chat_30821004 = "Rediesel Desert food... You mean lizard jerky and cacti?",
  str_homestory_chat_30821005 = "That's not all of it. What's available to eat in Cloud Gardens?",
  str_homestory_chat_30821006 = "Bread.",
  str_homestory_chat_30821007 = "That's common. Do you eat it dry without jams?",
  str_homestory_chat_30821008 = "Just the bread is good enough.",
  str_homestory_chat_30821009 = "Okay.",
  str_homestory_chat_30821010 = "Coffee.",
  str_homestory_chat_30821011 = "It's a nice pick-me-up, but a bit bitter and needs a lot of sugar...",
  str_homestory_chat_30821012 = "Risotto.",
  str_homestory_chat_30821013 = "It's very filling, but better with side dishes.",
  str_homestory_chat_30821014 = "Fruit pies.",
  str_homestory_chat_30821015 = "I didn't know you like sweets that much.",
  str_homestory_chat_30821016 = "You don't seem to be too interested in those food.",
  str_homestory_chat_30821017 = "Nah, I miss Rediesel Desert whenever I talk about food.",
  str_homestory_chat_30821018 = "The sandstorm might be awful, but the food is nice...",
  str_homestory_chat_30821019 = "Like the lizard ice creams and puffs, or fried rediesel worms.",
  str_homestory_chat_30821020 = "Maybe open a rediesel cafe in Cloud Gardens? Will that work?",
  str_homestory_chat_30821021 = "It will go out of business for sure.",
  str_homestory_chat_30822001 = "Hey, how are you settling in so far?",
  str_homestory_chat_30822002 = "Hi PlayerName! It's nice here, quiet, comfortable, it's just...",
  str_homestory_chat_30822003 = "Here comes the bad part...",
  str_homestory_chat_30822004 = "I keep sneezing sometimes, like... Achoo!",
  str_homestory_chat_30822005 = "I don't know why, but I'm fine when I leave here.",
  str_homestory_chat_30822006 = "Something in the environment, maybe? Pollens, perhaps?",
  str_homestory_chat_30822007 = "Achoo! Probably, since flowers are rare in Rediesel Desert.",
  str_homestory_chat_30822008 = "All you see is sand, sand, and more sand, which I have no issue with.",
  str_homestory_chat_30822009 = "Whether I get it in the nose or my eyes, I can get it out in two shakes.",
  str_homestory_chat_30822010 = "But the pollens you spoke of... Achoo! They're very annoying!",
  str_homestory_chat_30822011 = "Try stay away from them, or come over another time.",
  str_homestory_chat_30822012 = "Or bear it for a few days until you get used to it.",
  str_homestory_chat_30822013 = "The nature in Cloud Gardens certainly differed from Rediesel Desert.",
  str_homestory_chat_30822014 = "It is very relaxing and even captivating. Achoo!",
  str_homestory_chat_30823001 = "What are you looking at?",
  str_homestory_chat_30823002 = "I'm trying to find the Giant Eagle. Where did you park it?",
  str_homestory_chat_30823003 = "Outside.",
  str_homestory_chat_30823004 = "Aren't you worried that might be dangerous?",
  str_homestory_chat_30823005 = "He can protect himself. Even if not, he can just fly away.",
  str_homestory_chat_30823006 = "Why are you looking for him?",
  str_homestory_chat_30823007 = "Just curious where it is and whether it can protect itself.",
  str_homestory_chat_30823008 = "He's fine, don't you worry.",
  str_homestory_chat_30823009 = "However, if you're here, where's Giant Lizard?",
  str_homestory_chat_30823010 = "I rode in a car. The Giant Lizard preferred not to leave the desert.",
  str_homestory_chat_30823011 = "It's probably hanging out with those unreliable guys...",
  str_homestory_chat_30823012 = "That's not the way to talk about your friends...",
  str_homestory_chat_30999999 = "What are you up to?",
  str_homestory_chat_30921001 = "Just taking a walk. You?",
  str_homestory_chat_30921002 = "Got something on your mind?",
  str_homestory_chat_30921003 = "You bet I do, and you came just in time to hear all about it. I need your opinion on something.",
  str_homestory_chat_30921004 = "What is it...?",
  str_homestory_chat_30921005 = "Have a look at these generals. Who among them do you reckon would make a decent Grand Marshal?",
  str_homestory_chat_30921006 = "Hmm... Let me think.",
  str_homestory_chat_30921007 = "Sharona.",
  str_homestory_chat_30921008 = "Um. Not a bad candidate. For this job, she has the perfect leadership, strategic insight, and loyalty.",
  str_homestory_chat_30921009 = "Unfortunately, however, she's from Lumopolis, and even though she's basically severed all ties to her past life...",
  str_homestory_chat_30921010 = "In the eyes of \"those people,\" she's still far from perfect.",
  str_homestory_chat_30921011 = "I see...",
  str_homestory_chat_30921012 = "Barton.",
  str_homestory_chat_30921013 = "He's at best a general. The man's only at home when he's on the battlefield.",
  str_homestory_chat_30921014 = "In peacetime, he'll either end up as a nuisance to the public, or become a good-for-nothing idler.",
  str_homestory_chat_30921015 = "Wow, you're harsh.",
  str_homestory_chat_30921016 = "Just telling the truth.",
  str_homestory_chat_30921017 = "Hiiro.",
  str_homestory_chat_30921018 = "Her bravery is beyond reproach, and she commands her troops with the utmost discipline and authority. Unfortunately...",
  str_homestory_chat_30921019 = "Hiiro sometimes goes far beyond \"brave\" that she often loses herself in the heat of battle.",
  str_homestory_chat_30921020 = "Of course, it goes without saying that a soldier should be brave, but bravery should never come at the cost of victory.",
  str_homestory_chat_30921021 = "The two don't always go hand in hand... I'm not sure if you can notice the subtle difference there.",
  str_homestory_chat_30921022 = "I think I get it... to an extent.",
  str_homestory_chat_30921023 = "So, it looks like... no one's really suitable for the role.",
  str_homestory_chat_30921024 = "Well, actually, just look at this from another angle: If these candidates had suitable adjutants, staff officers, or whatever, to help them out...",
  str_homestory_chat_30921025 = "They could totally make decent Grand Marshals.",
  str_homestory_chat_30922001 = "Just heading off to see if any of my buddies are about.",
  str_homestory_chat_30922002 = "Speaking of buddies, what do you think of Reinhardt? Would you say she's a good buddy or a good boss?",
  str_homestory_chat_30922003 = "She's a good buddy.",
  str_homestory_chat_30922004 = "She's a good boss.",
  str_homestory_chat_30922005 = "Why are you asking me this all of a sudden?",
  str_homestory_chat_30922006 = "Perhaps you already know that the two of us were classmates.",
  str_homestory_chat_30922007 = "She used to be my commanding officer... Her wish was my command back then.",
  str_homestory_chat_30922008 = "However, from the looks of things, I might become her superior in the future.",
  str_homestory_chat_30922009 = "I see... You're thinking about how to get along with her, right?",
  str_homestory_chat_30922010 = "That's right.",
  str_homestory_chat_30922011 = "No need to be overconcerned about it. Just go with the flow.",
  str_homestory_chat_30922012 = "I knew you'd say that, but that still counts as a solid advice in my book.",
  str_homestory_chat_30922013 = "Thanks, PlayerName.",
  str_homestory_chat_30923001 = "Just wanna go take a break.",
  str_homestory_chat_30923002 = "What do you usually do to relax?",
  str_homestory_chat_30923003 = "Take a walk.",
  str_homestory_chat_30923004 = "Sounds pretty basic.",
  str_homestory_chat_30923005 = "Go fishing.",
  str_homestory_chat_30923006 = "That's so clichéd.",
  str_homestory_chat_30923007 = "I heard the Caelestites developed a unique method of relaxation called \"meditation.\"",
  str_homestory_chat_30923008 = "Personally, I rarely meditate... Why are you interested in meditation all of a sudden?",
  str_homestory_chat_30923009 = "You wanna give it a try?",
  str_homestory_chat_30923010 = "Meditation is a form of relaxation, and also a form of training.",
  str_homestory_chat_30923011 = "As you relax, you can find your true path and reinforce the trajectory of your progress.",
  str_homestory_chat_30923012 = "This training method is crucial to me—it helps me recharge my \"batteries,\" so to speak.",
  str_homestory_chat_30923013 = "I'll give it a try later...",
  str_homestory_chat_30924001 = "Just walking.",
  str_homestory_chat_30924002 = "Seems it really fits you, this walking business.",
  str_homestory_chat_30924003 = "Why do you say that?",
  str_homestory_chat_30924004 = "Because you look terrific! The secret lies in all those walks, right?",
  str_homestory_chat_30924005 = "No.",
  str_homestory_chat_30924006 = "What's your secret, then?",
  str_homestory_chat_30924007 = "Nothing secret. Just having a sound sleep and keeping a healthy, balanced life.",
  str_homestory_chat_30924008 = "Well you, on the contrary, are always looking under the weather... Is it because you often stay up too late? Don't kill yourself for the sake of work.",
  str_homestory_chat_30924009 = "You could say it's the price of responsibility.",
  str_homestory_chat_30925001 = "Just patrolling Cloud Gardens.",
  str_homestory_chat_30925002 = "Tough break. No rest for the wicked, huh?",
  str_homestory_chat_30925003 = "Nah... A nice walk is exactly what I needed.",
  str_homestory_chat_30925004 = "Really? So this is how you run Cloud Gardens, eh?",
  str_homestory_chat_30925005 = "More or less. The Chubbs take care of most of the work, while I just take a look around sometimes.",
  str_homestory_chat_30925006 = "Gosh, I wish running Illumina were as simple as running Cloud Gardens.",
  str_homestory_chat_30925007 = "They're so different though.",
  str_homestory_chat_30925008 = "After all, the Illumina Federation is responsible for fighting off invading Eclipsites...",
  str_homestory_chat_30925009 = "And it's obviously much larger than Cloud Gardens...",
  str_homestory_chat_30925010 = "That's right.",
  str_homestory_chat_30925011 = "You should learn to let go of some of that pressure. Now that you're in Cloud Gardens, just take a load off and have some fun here.",
  str_homestory_chat_31099999 = "White Night up high. How is your day going so far?",
  str_homestory_chat_31001001 = "Ah, nothing special.",
  str_homestory_chat_31001002 = "This is a good thing. It means peace has been preserved here.",
  str_homestory_chat_31001003 = "It's clear that you really love days like this.",
  str_homestory_chat_31001004 = "Everyone in Twilight lives a life of stress.",
  str_homestory_chat_31001005 = "Physically, and spiritually...",
  str_homestory_chat_31001006 = "So close are the Eclipsites to the town's perimeter that the townspeople can almost feel them breathing down their necks.",
  str_homestory_chat_31001007 = "So upon arriving here, one cannot help but marvel at how serene it is.",
  str_homestory_chat_31001008 = "If only this peace could spread across the entire continent, what a wonderful thing that would be.",
  str_homestory_chat_31021001 = "Pretty good. You?",
  str_homestory_chat_31021002 = "I was wondering to myself... How do you personally regard the various regions of the world?",
  str_homestory_chat_31021003 = "Such as...?",
  str_homestory_chat_31021004 = "Hmm... Lumopolis.",
  str_homestory_chat_31021005 = "It's the center of civilization.",
  str_homestory_chat_31021006 = "Ruler of the continent.",
  str_homestory_chat_31021007 = "What do you think of Lumopolis?",
  str_homestory_chat_31021008 = "It's the... center of civilization, no?",
  str_homestory_chat_31021009 = "Something about your tone tells me you're not so sure about that.",
  str_homestory_chat_31021010 = "That's because I've lived in Twilight for so long and seldom venture to Lumopolis.",
  str_homestory_chat_31021011 = "What do you think of the Illumina Federation then, PlayerName?",
  str_homestory_chat_31021012 = "It's the frontline of the fight against the Eclipsites.",
  str_homestory_chat_31021013 = "It's a united organization.",
  str_homestory_chat_31021014 = "Why are you asking me about this?",
  str_homestory_chat_31021015 = "When I think about what's going on in Twilight, I can't help but worry about Twilight's future.",
  str_homestory_chat_31021016 = "Those townspeople... What will become of them?",
  str_homestory_chat_31021017 = "Do you think about these things often?",
  str_homestory_chat_31021018 = "With a life in Twilight, I have no choice but to think about these things...",
  str_homestory_chat_31021019 = "I hope the almighty God of Light will answer my prayers and grant sanctuary to the townspeople.",
  str_homestory_chat_31022001 = "Just about to stroll around for a while.",
  str_homestory_chat_31022002 = "It appears you're finally ready to enjoy your leisure time.",
  str_homestory_chat_31022003 = "I guess I am. What are you up to right now?",
  str_homestory_chat_31022004 = "I haven't decided yet. After I arrived in Cloud Gardens, I felt somewhat out of place.",
  str_homestory_chat_31022005 = "Why do you say that?",
  str_homestory_chat_31022006 = "Cloud Gardens is so different from Twilight—a place where you must wield your sword almost every day to survive...",
  str_homestory_chat_31022007 = "Fighting Eclipsites?",
  str_homestory_chat_31022008 = "Precisely.",
  str_homestory_chat_31022009 = "I've always been wondering what life might be like if I didn't have to bear arms every day?",
  str_homestory_chat_31022010 = "And now you can experience that life first-hand.",
  str_homestory_chat_31022011 = "Ah... It would be amazing if everyone in Twilight could live like this.",
  str_homestory_chat_31023001 = "Just usual stuff. What are you doing over here?",
  str_homestory_chat_31023002 = "I'm absorbing traces of light.",
  str_homestory_chat_31023003 = "Absorbing traces of light? Oh! Are you sunbathing? It's good for you, you know?",
  str_homestory_chat_31023004 = "No, I'm actually praying.",
  str_homestory_chat_31023005 = "Praying?",
  str_homestory_chat_31023006 = "Because the Light is my faith...",
  str_homestory_chat_31023007 = "Unlike Twilight, Cloud Gardens rarely sees an overcast sky.",
  str_homestory_chat_31023008 = "Being here in this wonderful place, I can't help but feel a desire of invocation rising in my heart.",
  str_homestory_chat_31023009 = "Okay. Go ahead and pray... I'll leave you to it.",
  str_homestory_chat_31199999 = "What are you up to, Navigator?",
  str_homestory_chat_31121001 = "Hey Antony, I'm planning on heading out...",
  str_homestory_chat_31121002 = "To explore some ruins.",
  str_homestory_chat_31121003 = "Ruins? You mean the unexplored kind?",
  str_homestory_chat_31121004 = "Can I come along?",
  str_homestory_chat_31121005 = "Sure, why not?",
  str_homestory_chat_31121006 = "But don't get your hopes up.",
  str_homestory_chat_31121007 = "These ruins we're going to have been explored many times before.",
  str_homestory_chat_31121008 = "Yes, I understand.",
  str_homestory_chat_31121009 = "But sometimes, even a simple stone can hold vital secrets.",
  str_homestory_chat_31121010 = "Well, with your big brain guiding us, we might actually have a chance of finding something special.",
  str_homestory_chat_31121011 = "To get some rest.",
  str_homestory_chat_31121012 = "Rest? Then I know just the place for you.",
  str_homestory_chat_31121013 = "I heard there are some ruins nearby.",
  str_homestory_chat_31121014 = "Ruins adorned with many mysterious cave paintings.",
  str_homestory_chat_31121015 = "How does that have anything to do with me having some rest?",
  str_homestory_chat_31121016 = "Absolutely.",
  str_homestory_chat_31121017 = "Lying in the ruins, looking up at the paintings...",
  str_homestory_chat_31121018 = "It feels as though you've traveled back in time to that era.",
  str_homestory_chat_31121019 = "To me, that counts as a form of relax.",
  str_homestory_chat_31121020 = "Wall paintings, you say? Well now you've got my attention.",
  str_homestory_chat_31121021 = "Then I'll go get ready for the trip.",
  str_homestory_chat_31121022 = "Sure. See you in a bit.",
  str_homestory_chat_31122001 = "I got nothing on hand. You?",
  str_homestory_chat_31122002 = "I'm making adjustments to the All-Purpose Staff.",
  str_homestory_chat_31122003 = "Any new innovations to implement?",
  str_homestory_chat_31122004 = "Hardly, just trying to bolster the illumination device.",
  str_homestory_chat_31122005 = "Light diffusion is still somewhat weak.",
  str_homestory_chat_31122006 = "I'm applying the knowledge I learned from the Colossus to improve the lighting effects.",
  str_homestory_chat_31122007 = "Would you like to hear the particular principle behind it?",
  str_homestory_chat_31122008 = "Specifically, it's to raise the actual output through the following equations...",
  str_homestory_chat_31122009 = "Oh, I just remembered I do have something to do...",
  str_homestory_chat_31122010 = "Have to go now. See you around.",
  str_homestory_chat_31123001 = "Just hanging out.",
  str_homestory_chat_31123002 = "Might go see other Aurorians later on.",
  str_homestory_chat_31123003 = "Speaking of other Aurorians, how do you feel about No. 33, Navigator?",
  str_homestory_chat_31123004 = "A very good companion.",
  str_homestory_chat_31123005 = "Yes, indeed.",
  str_homestory_chat_31123006 = "However, don't you think it's marvelous that she was born in ancient times?",
  str_homestory_chat_31123007 = "Uh, you're not looking to study her, are you?",
  str_homestory_chat_31123008 = "Oh, no. I only want to study her helmet, that's all...",
  str_homestory_chat_31123009 = "An enigmatic girl?",
  str_homestory_chat_31123010 = "You feel the same way too! I see.",
  str_homestory_chat_31123011 = "It's hard for an Aurorian born in ancient times to not raise some eyebrows.",
  str_homestory_chat_31123012 = "Uh, you're not looking to study her, are you?",
  str_homestory_chat_31123013 = "Oh, no. I only want to study her helmet, that's all...",
  str_homestory_chat_31123014 = "Then why not go talk to her yourself?",
  str_homestory_chat_31123015 = "She should be able to answer most of your questions.",
  str_homestory_chat_31124001 = "Going to read a book.",
  str_homestory_chat_31124002 = "What a coincidence, Navigator.",
  str_homestory_chat_31124003 = "You come here to read books too.",
  str_homestory_chat_31124004 = "What book are you reading, Antony?",
  str_homestory_chat_31124005 = "Errors and Deviations in Star Trajectories.",
  str_homestory_chat_31124006 = "Um... How profound...",
  str_homestory_chat_31124007 = "Actually, it's not hard. You'll get it when you read it, Navigator.",
  str_homestory_chat_31124008 = "I'll give it a try...",
  str_homestory_chat_31125001 = "Going to tidy up my room.",
  str_homestory_chat_31125002 = "Oh? Speaking of sorting stuff, do you have any preferences?",
  str_homestory_chat_31125003 = "Neatness.",
  str_homestory_chat_31125004 = "What about you?",
  str_homestory_chat_31125005 = "Take my backpack for example, I'd put the emphasis on efficiency.",
  str_homestory_chat_31125006 = "Arranging the items in the order of necessity.",
  str_homestory_chat_31125007 = "The most important ones go on top. The ones hardly needed go to the bottom.",
  str_homestory_chat_31125008 = "Efficiency.",
  str_homestory_chat_31125009 = "Me too.",
  str_homestory_chat_31125010 = "When I organize my backpack, I'd put the emphasis on efficiency too.",
  str_homestory_chat_31125011 = "Let me help you tidy up the room.",
  str_homestory_chat_31125012 = "Alright. Thanks for the help.",
  str_homestory_chat_31299999 = "Any plans for today?",
  str_homestory_chat_31221001 = "Haven't decided yet...",
  str_homestory_chat_31221002 = "What about you?",
  str_homestory_chat_31221003 = "Practice Luminatics, of course.",
  str_homestory_chat_31221004 = "You say that every time. Sounds to me that you're working too hard.",
  str_homestory_chat_31221005 = "You can relax once in a while, you know.",
  str_homestory_chat_31221006 = "It's not good to stay taut as a bowstring all the time.",
  str_homestory_chat_31221007 = "Is that right...?",
  str_homestory_chat_31222001 = "Going to patrol all day long...",
  str_homestory_chat_31222002 = "You sure don't have it easy, Navigator.",
  str_homestory_chat_31222003 = "So busy every day.",
  str_homestory_chat_31222004 = "Please let me know if you need my help on anything!",
  str_homestory_chat_31222005 = "Well, there's nothing I need help with...",
  str_homestory_chat_31222006 = "Let me think about it...",
  str_homestory_chat_31222007 = "Oh, I have an idea.",
  str_homestory_chat_31222008 = "Have you heard of cold massage therapy?",
  str_homestory_chat_31222009 = "Placing ice cubes on the right parts to relax the body...",
  str_homestory_chat_31222010 = "That sounds like a job I can do easily!",
  str_homestory_chat_31222011 = "It feels a little scary to me when you're doing it.",
  str_homestory_chat_31222012 = "What? Don't you mean pleasant?!",
  str_homestory_chat_31222013 = "However, when I'm done patrolling...",
  str_homestory_chat_31222014 = "Maybe I do need a massage.",
  str_homestory_chat_31222015 = "Wonderful, I'll show you my skills!",
  str_homestory_chat_31223001 = "Going out for a stroll.",
  str_homestory_chat_31223002 = "Can I come with you?",
  str_homestory_chat_31223003 = "Sure.",
  str_homestory_chat_31223004 = "Where are you going, Navigator?",
  str_homestory_chat_31223005 = "The beach!",
  str_homestory_chat_31223006 = "Shopping district!",
  str_homestory_chat_31223007 = "I've never been to either one...",
  str_homestory_chat_31223008 = "It's also your dream to see the world, right?",
  str_homestory_chat_31223009 = "They're very interesting places.",
  str_homestory_chat_31223010 = "Then give me a minute to get ready.",
  str_homestory_chat_31224001 = "Going to see a friend.",
  str_homestory_chat_31224002 = "Are you visiting No. 33, Navigator?",
  str_homestory_chat_31224003 = "How do you know that?",
  str_homestory_chat_31224004 = "Just a hunch.",
  str_homestory_chat_31224005 = "I was with No. 33 just a few minutes ago.",
  str_homestory_chat_31224006 = "I get the feeling that No. 33 cares a lot about you.",
  str_homestory_chat_31224007 = "That's probably because of Alina.",
  str_homestory_chat_31224008 = "No. 33 probably saw her in me.",
  str_homestory_chat_31224009 = "I feel the same way, though.",
  str_homestory_chat_31224010 = "Even though I know No. 33 can never replace Alina...",
  str_homestory_chat_31224011 = "If possible, I'd still like to be her sister.",
  str_homestory_chat_31225001 = "Finalize the plan for the upcoming trip.",
  str_homestory_chat_31225002 = "Speaking of that, the pictures from the last trip... \"Pictures\" is the right word, right?",
  str_homestory_chat_31225003 = "Yes, correct.",
  str_homestory_chat_31225004 = "I was just looking at the pictures.",
  str_homestory_chat_31225005 = "Modern technology is truly amazing.",
  str_homestory_chat_31225006 = "How does such a small machine manage to \"store\" people and scenery?",
  str_homestory_chat_31225007 = "It's rather complicated to explain...",
  str_homestory_chat_31225008 = "If you're interested, Zarya, you can talk to Antony about it.",
  str_homestory_chat_31225009 = "He'll be glad to answer your questions.",
  str_homestory_chat_31399999 = "No. 33 on standby. Please input command.",
  str_homestory_chat_31321001 = "Rest.",
  str_homestory_chat_31321002 = "Command error.",
  str_homestory_chat_31321003 = "Standby is resting.",
  str_homestory_chat_31321004 = "According to the calculation, it is not necessary for me to shift to sleeping mode at present.",
  str_homestory_chat_31321005 = "Don't you get tired at all?",
  str_homestory_chat_31321006 = "Thank you for your concern, but I'm not feeling fatigued at the moment.",
  str_homestory_chat_31321007 = "Without further instructions, I will remain on standby.",
  str_homestory_chat_31322001 = "Go on a patrol.",
  str_homestory_chat_31322002 = "Command acknowledged. Executing the mission list now.",
  str_homestory_chat_31322003 = "Wait, that actually worked?!",
  str_homestory_chat_31322004 = "I was only kidding...",
  str_homestory_chat_31322005 = "Do you not trust my ability to accomplish missions?",
  str_homestory_chat_31322006 = "According to cumulative records, I have carried out a total of 5,005 patrols and am very experienced.",
  str_homestory_chat_31322007 = "It's not I don't trust you, No. 33.",
  str_homestory_chat_31322008 = "But that's my duty. I have to do it myself.",
  str_homestory_chat_31322009 = "Understood. I respect your decision.",
  str_homestory_chat_31323001 = "Input nothing.",
  str_homestory_chat_31323002 = "Please input command.",
  str_homestory_chat_31323003 = "Repeat, please input command.",
  str_homestory_chat_31323004 = "Are you confused by the phrase, \"Input command\"?",
  str_homestory_chat_31323005 = "Searching for a more appropriate expression...",
  str_homestory_chat_31323006 = "\"Please let me know if there is anything you need me to do.\"",
  str_homestory_chat_31323007 = "Well, got nothing urgent right now...",
  str_homestory_chat_31323008 = "Very well. Please inform me when you have a need.",
  str_homestory_chat_31323009 = "No. 33 will serve you throughout.",
  str_homestory_chat_31324001 = "Go hang out with a friend.",
  str_homestory_chat_31324002 = "Like...",
  str_homestory_chat_31324003 = "Zarya.",
  str_homestory_chat_31324004 = "Miss Zarya? She is indeed a very important companion to me.",
  str_homestory_chat_31324005 = "I will schedule new Luminatics training programs for her to improve her power.",
  str_homestory_chat_31324006 = "No, that's not it. Just hang out and chat with her.",
  str_homestory_chat_31324007 = "Antony.",
  str_homestory_chat_31324008 = "I think you and Mr. Antony will have a lot to talk about.",
  str_homestory_chat_31324009 = "If you are referring to the mastery of knowledge, I concur.",
  str_homestory_chat_31324010 = "Although based on our previous fifty encounters...",
  str_homestory_chat_31324011 = "I believe he is perhaps more intrigued by my structural and technological compositions.",
  str_homestory_chat_31324012 = "Nevertheless, it is possible that he could deduce the information I have forgotten...",
  str_homestory_chat_31324013 = "That sounds perfect!",
  str_homestory_chat_31324014 = "You should go then, No. 33.",
  str_homestory_chat_31324015 = "I should get on with something else too.",
  str_homestory_chat_28899999 = "May I ask what you're doing right now?",
  str_homestory_chat_28801001 = "Actually, I was just about to ask how you've been adjusting to life over here.",
  str_homestory_chat_28801002 = "This place is much different from the other cities of Astra, let alone cities in Longzhou.",
  str_homestory_chat_28801003 = "There's something unique about this place.",
  str_homestory_chat_28801004 = "Unique?",
  str_homestory_chat_28801005 = "Something very peaceful, which makes one forget about all of the strife in the outside world.",
  str_homestory_chat_28801006 = "Then it sounds like you've gotten used to it here... I'm glad to hear it.",
  str_homestory_chat_28821001 = "Growing flowers?",
  str_homestory_chat_28821002 = "Yes. May I ask if there are any exotic flowers here as well?",
  str_homestory_chat_28821003 = "Yes",
  str_homestory_chat_28821004 = "Will you take me to see them?",
  str_homestory_chat_28821005 = "Sure, but... the Chubbs are taking care of them now.",
  str_homestory_chat_28821006 = "I see... Rare flowers naturally require much more care and protection.",
  str_homestory_chat_28821007 = "But there are still plenty of other plants and flowers to see here in Eraveil! Feel free to take a look around!",
  str_homestory_chat_28821008 = "Thank you for letting me know, PlayerName.",
  str_homestory_chat_28821009 = "No",
  str_homestory_chat_28821010 = "What a pity. It appears I'll have to pursue a new mission now...",
  str_homestory_chat_28821011 = "Let's fill Eraveil with a sea of Longzhou flowers, like begonias! What do you think?",
  str_homestory_chat_28821012 = "I'll think about it.",
  str_homestory_chat_28822001 = "Tinkering with a device?",
  str_homestory_chat_28822002 = "A device made up of all kinds of smaller mechanisms, to be exact. I hear there are many things like this here in Astra.",
  str_homestory_chat_28822003 = "Like what?",
  str_homestory_chat_28822004 = "I once saw an expertly-crafted clock, one that not only told the time but also produced a small bird.",
  str_homestory_chat_28822005 = "A small bird?",
  str_homestory_chat_28822006 = "That's right. Every hour, a small bird would pop out with a \"ding,\" and chirp to signal the time.",
  str_homestory_chat_28822007 = "A \"ding\"? I thought it sounded more like a \"cuckoo\"...",
  str_homestory_chat_28822008 = "Yes! That was the sound it made!",
  str_homestory_chat_28822009 = "Oh, that's a cuckoo clock. Those are pretty interesting, yes.",
  str_homestory_chat_28822010 = "Then when can I have one installed in my room?",
  str_homestory_chat_28822011 = "Uh... Those can be pretty expensive, but I'll think about it...",
  str_homestory_chat_28823001 = "Making a drink?",
  str_homestory_chat_28823002 = "Yes. Ever since coming here, I've missed many things from my homeland, including the drinks.",
  str_homestory_chat_28823003 = "Do you have any drink recommendations yourself, PlayerName?",
  str_homestory_chat_28823004 = "Black tea.",
  str_homestory_chat_28823005 = "We have this kind of tea in Astra too, and I hear a lot of people love it.",
  str_homestory_chat_28823006 = "But... people here are more concerned with the snacks that go with their tea...",
  str_homestory_chat_28823007 = "I see. I'll have to consider that as well.",
  str_homestory_chat_28823008 = "Soda.",
  str_homestory_chat_28823009 = "What's that...?",
  str_homestory_chat_28823010 = "It's a slightly sweet drink with a really interesting mouthfeel.",
  str_homestory_chat_28823011 = "And what kind of mouthfeel would that be?",
  str_homestory_chat_28823012 = "It feels like a bunch of tiny bubbles dancing on your tongue. It even makes you burp if you drink it too fast!",
  str_homestory_chat_28823013 = "That sounds slightly beyond my tastes...",
  str_homestory_chat_28824001 = "Making breakfast?",
  str_homestory_chat_28824002 = "Yes. Breakfast is very important for one's health. \"A day's meals start with the dawn,\" as the saying goes.",
  str_homestory_chat_28824003 = "What an odd saying...",
  str_homestory_chat_28824004 = "I find a number of Astra's breakfast customs to be odd, as well.",
  str_homestory_chat_28824005 = "For example, I heard that the Rediesel Wrench eats grilled skewers for breakfast, while certain people in Umbraton only drink water in the morning.",
  str_homestory_chat_28824006 = "Uh... Those are just a couple of special cases, to be honest.",
  str_homestory_chat_28824007 = "The grilled skewers?",
  str_homestory_chat_28824008 = "That's just a personal preference for a certain someone in the Rediesel Wrench...",
  str_homestory_chat_28824009 = "And the water?",
  str_homestory_chat_28824010 = "A-Ahem, I'm pretty sure they're either trying to lose weight or cut down on their daily expenses.",
  str_homestory_chat_28824011 = "Either way, those aren't very good representations of Astra's normal breakfast habits.",
  str_homestory_chat_28824012 = "So what does a normal breakfast look like?",
  str_homestory_chat_28824013 = "Bread, milk, eggs, that sort of thing.",
  str_homestory_chat_28824014 = "I see. Those sound far more reasonable, although they still differ greatly from our own breakfast foods.",
  str_homestory_chat_28799999 = "What's the matter?",
  str_homestory_chat_28701001 = "You look pretty free right now.",
  str_homestory_chat_28701002 = "What? I actually have something very important to discuss with you.",
  str_homestory_chat_28701003 = "Me?",
  str_homestory_chat_28701004 = "Yes, you! I need to tell your fortune right now!",
  str_homestory_chat_28701005 = "It sounds like you just came up with that...",
  str_homestory_chat_28701006 = "Of course not! I came up with this much earlier—I mean, I've been worried about you for quite some time now.",
  str_homestory_chat_28701007 = "From what I can tell, your fortune indicates that you're critically prone to distractions...",
  str_homestory_chat_28701008 = "No kidding?",
  str_homestory_chat_28701009 = "Yes! And for many, the cause of this serious disorder is an excess of idle time...",
  str_homestory_chat_28701010 = "Now you're just calling me lazy, aren't you?!",
  str_homestory_chat_28701011 = "Indeed.",
  str_homestory_chat_28721001 = "How do you feel about this place?",
  str_homestory_chat_28721002 = "I must say, the feng shui here is truly remarkable...",
  str_homestory_chat_28721003 = "My divination tells me that this place is perfectly suitable for living one's days in peace and safety.",
  str_homestory_chat_28721004 = "It's especially suitable for raising all kinds of animals, like birds for instance...",
  str_homestory_chat_28721005 = "You want to keep birds here?",
  str_homestory_chat_28721006 = "That's right! May I ask if there are any other spirit birds here?",
  str_homestory_chat_28721007 = "Yes.",
  str_homestory_chat_28721008 = "No.",
  str_homestory_chat_28721009 = "Ah... What a pity.",
  str_homestory_chat_28721010 = "Still, I have to ask... Why do you want to keep more birds?",
  str_homestory_chat_28721011 = "I had hoped to give Squawk and Jabber some new companions. After all, they've been here for a long time as well.",
  str_homestory_chat_28721012 = "Companions, huh...? Seems to me they don't really need anyone else but you.",
  str_homestory_chat_28721013 = "To properly adjust to Astra's customs, they naturally need companions from Astra as well.",
  str_homestory_chat_28721014 = "And with new friends, perhaps they won't stay at my side every hour of the day.",
  str_homestory_chat_28721015 = "It sounds like you just need a break from them.",
  str_homestory_chat_28722001 = "Buying some candy?",
  str_homestory_chat_28722002 = "Why yes! After eating and sleeping well, I felt refreshed and ready for a small treat.",
  str_homestory_chat_28722003 = "My thoughts wandered to the sugar figurines made by the fortune-tellers of my homeland, so I thought to ask the Chubbs about them...",
  str_homestory_chat_28722004 = "Only to discover there are hardly any sweets here! Do Astra's people dislike them so much?",
  str_homestory_chat_28722005 = "Not at all! Lumopolis and Umbraton are famous for some of their desserts!",
  str_homestory_chat_28722006 = "In fact, they have all kinds of cakes with beautiful designs...",
  str_homestory_chat_28722007 = "Are there sweet buns with sugar figurines?",
  str_homestory_chat_28722008 = "It's cake.",
  str_homestory_chat_28722009 = "They're both desserts, so it's the same to me.",
  str_homestory_chat_28722010 = "... Never mind. In any case, there are plenty of cakes with pretty flower patterns on them.",
  str_homestory_chat_28722011 = "As for sugar figurines... I don't think I've ever seen any.",
  str_homestory_chat_28722012 = "Then it seems I'll have to display my unique talents very soon. When can you take me to see these cakes?",
  str_homestory_chat_28722013 = "Uh... Probably not for a few days.",
  str_homestory_chat_28723001 = "Are you planning something?",
  str_homestory_chat_28723002 = "Indeed I am. Did my banner catch your eye? What do you think of it?",
  str_homestory_chat_28723003 = "It's alright...",
  str_homestory_chat_28723004 = "Sharp eyes!",
  str_homestory_chat_28723005 = "It's an incredible banner, to be sure.",
  str_homestory_chat_28723006 = "It just seems like an ordinary banner.",
  str_homestory_chat_28723007 = "Sigh... you just can't see the greatness before your eyes.",
  str_homestory_chat_28723008 = "This banner contains immense power: the wisdom of the heavens above, and the knowledge of the earth below...",
  str_homestory_chat_28723009 = "Did you just...",
  str_homestory_chat_28723010 = "In any case, it's a very powerful and extraordinary banner.",
  str_homestory_chat_28723011 = "For this reason, you're more than welcome to put it up on that tower and use it as your command flag.",
  str_homestory_chat_28723012 = "Maybe you should just hold on to it...",
  str_homestory_chat_31499999 = "What are you doing, Navigator?",
  str_homestory_chat_31421001 = "Just thinking about taking a break...",
  str_homestory_chat_31421002 = "A break? Your face does look like it's missing some color.",
  str_homestory_chat_31421003 = "Are you feeling sick at all?",
  str_homestory_chat_31421004 = "Yes, a little...",
  str_homestory_chat_31421005 = "Here, why don't you let me give you a quick examination?",
  str_homestory_chat_31421006 = "No, not at all...",
  str_homestory_chat_31421007 = "It's okay, I promise. As a doctor, I can generally tell when someone isn't feeling well.",
  str_homestory_chat_31421008 = "Hmm... At first glance, nothing seems out of the ordinary.",
  str_homestory_chat_31421009 = "It's possible that you've been pushing yourself too hard lately. Remember to give your body plenty of time to rest.",
  str_homestory_chat_31421010 = "Do you need me to walk you to your room?",
  str_homestory_chat_31421011 = "No thanks, I can get there myself.",
  str_homestory_chat_31421012 = "Sure.",
  str_homestory_chat_31421013 = "If you're ever feeling under the weather... Don't hesitate to let me know.",
  str_homestory_chat_31422001 = "I was about to take a walk.",
  str_homestory_chat_31422002 = "A walk... That's good.",
  str_homestory_chat_31422003 = "By the way, do you usually go on walks by yourself?",
  str_homestory_chat_31422004 = "Want to come along?",
  str_homestory_chat_31422005 = "Would that be alright? I've been meaning to go for a walk with you for some time now.",
  str_homestory_chat_31422006 = "Sure!",
  str_homestory_chat_31422007 = "Yes, I prefer going alone.",
  str_homestory_chat_31422008 = "I agree, a little solitude can really help a person organize their thoughts.",
  str_homestory_chat_31422009 = "Unfortunately... I have a lot of work to do right now.",
  str_homestory_chat_31422010 = "Otherwise, I would have liked to go on a walk with you.",
  str_homestory_chat_31422011 = "I see, then don't let me keep you from your work!",
  str_homestory_chat_31422012 = "Until next time.",
  str_homestory_chat_31423001 = "Trying to finish my work.",
  str_homestory_chat_31423002 = "It must be hard for you sometimes. Just remember not to push yourself too much.",
  str_homestory_chat_31423003 = "Overdoing it can sometimes have the opposite effect.",
  str_homestory_chat_31423004 = "You can trust me on that.",
  str_homestory_chat_31423005 = "I'm sure you know, but I take in a lot of patients every day.",
  str_homestory_chat_31423006 = "At first, I didn't pay attention to my body's demands. I only wanted to treat as many people as possible...",
  str_homestory_chat_31423007 = "Thankfully, I was able to save them all in the end.",
  str_homestory_chat_31423008 = "But I ended up collapsing from exhaustion soon enough...",
  str_homestory_chat_31423009 = "I didn't realize it could get that bad.",
  str_homestory_chat_31423010 = "It can, which is why you need to know your own limits.",
  str_homestory_chat_31424001 = "I'm planning a dinner party!",
  str_homestory_chat_31424002 = "A... dinner party?",
  str_homestory_chat_31424003 = "Is there a problem?",
  str_homestory_chat_31424004 = "No, it just... Made me remember a few things.",
  str_homestory_chat_31424005 = "In the past, we used to have plenty of dinner parties within our family.",
  str_homestory_chat_31424006 = "Looking back, it feels like we had one almost every day.",
  str_homestory_chat_31424007 = "Your family must've been really big!",
  str_homestory_chat_31424008 = "I suppose that's true, at least from a numbers perspective...",
  str_homestory_chat_31424009 = "But now it's just my sister and myself...",
  str_homestory_chat_31424010 = "Do you want to join us?",
  str_homestory_chat_31424011 = "Huh? Me? No, I... I think I'll pass...",
  str_homestory_chat_31424012 = "I've more or less gotten used to eating alone.",
  str_homestory_chat_31424013 = "Rebecca...",
  str_homestory_chat_31424014 = "I'm sorry, I think I said too much...",
  str_homestory_chat_31424015 = "Please excuse me...",
  str_homestory_chat_31425001 = "Just looking to relax for a bit.",
  str_homestory_chat_31425002 = "\"Relax\"? I see...",
  str_homestory_chat_31425003 = "I don't think I've had a chance to relax in a very long time either.",
  str_homestory_chat_31425004 = "Could I ask what you usually do to relieve stress?",
  str_homestory_chat_31425005 = "Shopping for clothes!",
  str_homestory_chat_31425006 = "Clothes shopping, huh...",
  str_homestory_chat_31425007 = "Maybe it's time for me to update my wardrobe too?",
  str_homestory_chat_31425008 = "Eating tasty food!",
  str_homestory_chat_31425009 = "Eating, huh...",
  str_homestory_chat_31425010 = "I've thought about trying that too, but I'm not in the best shape to do it.",
  str_homestory_chat_31425011 = "Eating out... can have a very bad effect on me sometimes.",
  str_homestory_chat_31425012 = "That sounds really inconvenient...",
  str_homestory_chat_31425013 = "After chatting with you, I suddenly feel like going out to do some shopping.",
  str_homestory_chat_31425014 = "But I have to go back to the clinic soon...",
  str_homestory_chat_31425015 = "That's fine, there's always next time!",
  str_homestory_chat_31425016 = "Alright then. I'll be going now.",
  str_homestory_chat_31425017 = "I hope you feel better today too.",
  str_homestory_chat_31599999 = "What're you up to, Navigator?",
  str_homestory_chat_31521001 = "I was just about to do some training.",
  str_homestory_chat_31521002 = "Training, huh? Need a partner?",
  str_homestory_chat_31521003 = "I'll even cut you a deal! Twenty percent off for a top-notch training partner!",
  str_homestory_chat_31521004 = "I'll be fine on my own.",
  str_homestory_chat_31521005 = "No thanks...",
  str_homestory_chat_31521006 = "What? Even after I offered you such a generous discount?",
  str_homestory_chat_31521007 = "It's fine, I got plenty of other work to deal with anyway.",
  str_homestory_chat_31521008 = "I won't keep pressing you about it.",
  str_homestory_chat_31521009 = "Just call on me if you ever need a training partner! See ya!",
  str_homestory_chat_31522001 = "I was about to do some reading.",
  str_homestory_chat_31522002 = "Reading? That sounds like something you would do.",
  str_homestory_chat_31522003 = "I don't really care for books though.",
  str_homestory_chat_31522004 = "You mean you don't read often?",
  str_homestory_chat_31522005 = "I-It's not like I never read or anything!",
  str_homestory_chat_31522006 = "I just prefer thinking about stuff whenever I have downtime.",
  str_homestory_chat_31522007 = "But now that you mention it...",
  str_homestory_chat_31522008 = "I bought some comics from a street vendor the other day, and they're really something else!",
  str_homestory_chat_31522009 = "They're about two sisters who depend on each other to survive, but they get separated one day...",
  str_homestory_chat_31522010 = "And in the end, they... Whoops, that was close!",
  str_homestory_chat_31522011 = "Any more and I would've spoiled the whole story!",
  str_homestory_chat_31522012 = "Anyway, you should check them out when you have time.",
  str_homestory_chat_31522013 = "I forget the name of the comics, but they shouldn't be too hard to find.",
  str_homestory_chat_31523001 = "Nothing really.",
  str_homestory_chat_31523002 = "You bored?",
  str_homestory_chat_31523003 = "Wanna come to collect debts with me?",
  str_homestory_chat_31523004 = "It's lots of fun, you know!",
  str_homestory_chat_31523005 = "I think I'll pass.",
  str_homestory_chat_31523006 = "Don't worry, it's perfectly safe.",
  str_homestory_chat_31523007 = "And with me around, you won't have to do much either.",
  str_homestory_chat_31523008 = "What do you need me to do?",
  str_homestory_chat_31523009 = "Don't worry, you won't have to do much with me around.",
  str_homestory_chat_31523010 = "All you gotta do is puff out your chest and look extra menacing!",
  str_homestory_chat_31523011 = "You only need to act intimidating.",
  str_homestory_chat_31523012 = "Leave the rest to a professional like me, okay?",
  str_homestory_chat_31523013 = "That does sound kind of fun.",
  str_homestory_chat_31523014 = "Right? So now you just have to pay and we can get going!",
  str_homestory_chat_31523015 = "Wait, I have to pay for this?",
  str_homestory_chat_31523016 = "Well, of course! I'm providing you with first-hand experience, so of course you gotta pay!",
  str_homestory_chat_31523017 = "I think I still need to think about it.",
  str_homestory_chat_31523018 = "Huh? ?",
  str_homestory_chat_31524001 = "Just getting ready to take a break.",
  str_homestory_chat_31524002 = "Take a break?",
  str_homestory_chat_31524003 = "Then what the heck do you do on your days off?!",
  str_homestory_chat_31524004 = "Sleep all day.",
  str_homestory_chat_31524005 = "That's such a waste of time!",
  str_homestory_chat_31524006 = "Play games.",
  str_homestory_chat_31524007 = "I see. That's pretty normal, I guess.",
  str_homestory_chat_31524008 = "I like to keep myself nice and busy on my days off.",
  str_homestory_chat_31524009 = "I can't afford to waste even a second!",
  str_homestory_chat_31524010 = "So what do you usually do?",
  str_homestory_chat_31524011 = "Spend time with my precious family, of course!",
  str_homestory_chat_31524012 = "For me, even if I'm just watching Rebecca while she sleeps...",
  str_homestory_chat_31524013 = "It's a meaningful use of my time!",
  str_homestory_chat_31524014 = "And it counts as protecting her too!",
  str_homestory_chat_31524015 = "You sure are a hard worker, Isa.",
  str_homestory_chat_31699999 = "Hey, what are you busy doing?",
  str_homestory_chat_31621001 = "I'm going to clean my room.",
  str_homestory_chat_31621002 = "Room cleaning, eh...",
  str_homestory_chat_31621003 = "Why dirty your hands with that when you can use a clockwork puppet?",
  str_homestory_chat_31621004 = "So, wanna put one of my inventions to work?",
  str_homestory_chat_31621005 = "That's okay, I can do it myself.",
  str_homestory_chat_31621006 = "You sure? Guess you're the type that enjoys tidying things up and stuff.",
  str_homestory_chat_31621007 = "I'll leave you to your enjoyment then.",
  str_homestory_chat_31621008 = "The same still goes: Call me when you need me.",
  str_homestory_chat_31621009 = "Okay.",
  str_homestory_chat_31621010 = "I'll go back now and get it set up.",
  str_homestory_chat_31621011 = "Don't forget to take anything fragile with you, since I don't want to be held responsible.",
  str_homestory_chat_31621012 = "See you in a bit.",
  str_homestory_chat_31622001 = "I wanna go for a walk.",
  str_homestory_chat_31622002 = "A walk? It's hot out there and you'll get sunburn.",
  str_homestory_chat_31622003 = "I need my calcium from the sun.",
  str_homestory_chat_31622004 = "True that.",
  str_homestory_chat_31622005 = "But don't get too much of it.",
  str_homestory_chat_31622006 = "The sunburn streaks are rather embarrassing.",
  str_homestory_chat_31622007 = "That's what happened to me last time.",
  str_homestory_chat_31622008 = "Wanna borrow my parasol?",
  str_homestory_chat_31622009 = "Sure.",
  str_homestory_chat_31622010 = "But I don't think you're strong enough to carry it.",
  str_homestory_chat_31622011 = "So I gotta come with you.",
  str_homestory_chat_31623001 = "I'm pondering what to do later...",
  str_homestory_chat_31623002 = "Does that mean you have free time on your hands?",
  str_homestory_chat_31623003 = "Wanna be my assistant?",
  str_homestory_chat_31623004 = "I'm making a new gadget right now.",
  str_homestory_chat_31623005 = "Is that hard work?",
  str_homestory_chat_31623006 = "It sure isn't easy if I can't do it by myself.",
  str_homestory_chat_31623007 = "I wouldn't mess up the gadget, would I?",
  str_homestory_chat_31623008 = "Don't think so.",
  str_homestory_chat_31623009 = "But it's possible you could get hurt by it...",
  str_homestory_chat_31623010 = "What kind of gadget is it?",
  str_homestory_chat_31623011 = "It stores a lot of beads and self-destructs in an emergency—",
  str_homestory_chat_31623012 = "Wait, that's probably too dangerous for you.",
  str_homestory_chat_31623013 = "Now that I think about it, it's rash to ask for your help.",
  str_homestory_chat_31623014 = "Since it's tough to handle that thing.",
  str_homestory_chat_31623015 = "And if we get you involved...",
  str_homestory_chat_31623016 = "Sorry, I gotta do this alone.",
  str_homestory_chat_31624001 = "Let's go hang out in the Rec Room in a minute.",
  str_homestory_chat_31624002 = "The Rec Room? Too many things to do in there!",
  str_homestory_chat_31624003 = "Do you prefer something intense or something relaxing?",
  str_homestory_chat_31624004 = "Intense.",
  str_homestory_chat_31624005 = "I see. It's fun to go all out.",
  str_homestory_chat_31624006 = "Especially when you have a lot of stress built up inside you.",
  str_homestory_chat_31624007 = "I'd spar with my training bot sometimes too.",
  str_homestory_chat_31624008 = "Relaxing.",
  str_homestory_chat_31624009 = "Well, it's not bad to enjoy something quiet.",
  str_homestory_chat_31624010 = "Then you throw in the tune from the clockwork bird and massage from the clockwork puppet...",
  str_homestory_chat_31624011 = "It's relaxing just thinking about it.",
  str_homestory_chat_31624012 = "There are games that do both.",
  str_homestory_chat_31624013 = "Really? You gotta show me then!",
  str_homestory_chat_31625001 = "I wanna go grab something to eat.",
  str_homestory_chat_31625002 = "How about checking out the street food?",
  str_homestory_chat_31625003 = "Nobody knows street food more than me.",
  str_homestory_chat_31625004 = "Other than building gadgets, shopping and eating street food is what I do.",
  str_homestory_chat_31625005 = "You're into that?",
  str_homestory_chat_31625006 = "I have a surprisingly diverse taste.",
  str_homestory_chat_31625007 = "Not to mention finding something unexpected in the shops along the way.",
  str_homestory_chat_31625008 = "Any vendors you'd recommend?",
  str_homestory_chat_31625009 = "Yes, but I don't think you can track some of them down.",
  str_homestory_chat_31625010 = "Since they're really out of the way.",
  str_homestory_chat_31625011 = "How about this, I'll take you with me next time we get a chance?",
  str_homestory_chat_31625012 = "Gotta run now, but I promise!",
  str_homestory_chat_31799999 = "What are you up to, PlayerName?",
  str_homestory_chat_31721001 = "Thinking about going to the market.",
  str_homestory_chat_31721002 = "Market? That sounds great.",
  str_homestory_chat_31721003 = "Sometimes, there are old things you don't often see in the market.",
  str_homestory_chat_31721004 = "Can I tag along?",
  str_homestory_chat_31721005 = "Sure, but the place will be crowded.",
  str_homestory_chat_31721006 = "Crowded? Well, never mind then.",
  str_homestory_chat_31721007 = "Sure, but it's a little far...",
  str_homestory_chat_31721008 = "Far? Well, never mind then.",
  str_homestory_chat_31721009 = "I don't want to be too far away from my buddies in the warehouse.",
  str_homestory_chat_31721010 = "I'd better to the warehouse and familiarize myself with Ms. Sheol's new shipment.",
  str_homestory_chat_31721011 = "Send pictures to my terminal if you see anything interesting, PlayerName.",
  str_homestory_chat_31721012 = "I'll be going now.",
  str_homestory_chat_31722001 = "Thinking about grabbing something to eat.",
  str_homestory_chat_31722002 = "You're getting something to eat?",
  str_homestory_chat_31722003 = "I recommend you get sweets!",
  str_homestory_chat_31722004 = "There's nothing enough sugar won't solve!",
  str_homestory_chat_31722005 = "Sounds awesome!",
  str_homestory_chat_31722006 = "You got the point of sugar rather quickly.",
  str_homestory_chat_31722007 = "But I want meat.",
  str_homestory_chat_31722008 = "Meat? You can season it with sugar too.",
  str_homestory_chat_31722009 = "Anyway, making sure you have enough sugar is never a bad thing.",
  str_homestory_chat_31722010 = "Hmm, speaking of that, I'm getting hungry myself.",
  str_homestory_chat_31722011 = "I'll go look for some food. See you later.",
  str_homestory_chat_31723001 = "I'm thinking about going to the museum.",
  str_homestory_chat_31723002 = "The museum? I love going there!",
  str_homestory_chat_31723003 = "So many cool exhibits!",
  str_homestory_chat_31723004 = "Even though I could only watch from a distance, that's still enough for me!",
  str_homestory_chat_31723005 = "You just love antiques, don't you, Vergil?",
  str_homestory_chat_31723006 = "More precisely, I love anything vintage.",
  str_homestory_chat_31723007 = "It's just that most of the antiques preserved to the present day happen to be vintage.",
  str_homestory_chat_31723008 = "I know how you feel.",
  str_homestory_chat_31723009 = "Right, right?!",
  str_homestory_chat_31723010 = "I'd love to ask Ms. Sheol for a day off and go to the museum.",
  str_homestory_chat_31723011 = "Too bad I got a shipment to appraise today.",
  str_homestory_chat_31723012 = "Gotta go. See you later.",
  str_homestory_chat_31724001 = "Thinking about how to acquire some sudden wealth.",
  str_homestory_chat_31724002 = "Sudden wealth? Well, maybe it's better to not dwell on that.",
  str_homestory_chat_31724003 = "You'll only be consumed by money if you keep chasing after it.",
  str_homestory_chat_31724004 = "What do you mean?",
  str_homestory_chat_31724005 = "Let money consume me then!",
  str_homestory_chat_31724006 = "My parents got addicted to gambling because they were obsessed with getting rich overnight.",
  str_homestory_chat_31724007 = "Once you get addicted, you lose all concepts of wealth.",
  str_homestory_chat_31724008 = "Then you'll start doing irrational things...",
  str_homestory_chat_31724009 = "I don't want to see you like that.",
  str_homestory_chat_31724010 = "Vergil...",
  str_homestory_chat_31724011 = "Sorry, I think I just said something I'm not supposed to. Please don't take it personally.",
  str_homestory_chat_31724012 = "See you.",
  str_homestory_chat_31899999 = "Got any plans for the rare time off?",
  str_homestory_chat_31821001 = "I'm thinking about going out!",
  str_homestory_chat_31821002 = "A very conventional idea.",
  str_homestory_chat_31821003 = "But rumor has it bad luck always follows when you go out.",
  str_homestory_chat_31821004 = "It's only a rumor!",
  str_homestory_chat_31821005 = "I see. Perhaps I got the wrong report.",
  str_homestory_chat_31821006 = "Well, not totally, but it probably didn't give the whole picture either.",
  str_homestory_chat_31821007 = "No, just slightly less lucky.",
  str_homestory_chat_31821008 = "Maybe it has nothing to do with luck but with who you are.",
  str_homestory_chat_31821009 = "Well, after all that said, I hope you're still in the mood to go out.",
  str_homestory_chat_31821010 = "Oh man, now I don't feel like going out anymore.",
  str_homestory_chat_31821011 = "How about a game of chess with me?",
  str_homestory_chat_31821012 = "I can't promise you anything.",
  str_homestory_chat_31821013 = "Except for your safety.",
  str_homestory_chat_31821014 = "That sounds like a good idea.",
  str_homestory_chat_31821015 = "I'm on my way now!",
  str_homestory_chat_31821016 = "Pay attention to the road and, remember, haste makes waste.",
  str_homestory_chat_31821017 = "May the shadow watch over you.",
  str_homestory_chat_31822001 = "I prefer staying on the Colossus. Still got a lot of things to do.",
  str_homestory_chat_31822002 = "It's better to keep a balanced schedule between work and rest.",
  str_homestory_chat_31822003 = "Last time Vice said that, I went to see a game in Umbraton and...",
  str_homestory_chat_31822004 = "Do you still blame us for the poor hospitality?",
  str_homestory_chat_31822005 = "No, I had a very memorable time.",
  str_homestory_chat_31822006 = "Why do you say that?",
  str_homestory_chat_31822007 = "I made friends.",
  str_homestory_chat_31822008 = "You do value friendship a lot and are fearless when it comes to that...",
  str_homestory_chat_31822009 = "It was a marvelous experience.",
  str_homestory_chat_31822010 = "I didn't figure you'd like adventuring that much.",
  str_homestory_chat_31822011 = "Think I just figured out more about you.",
  str_homestory_chat_31822012 = "It's a nice day today. Hope you can enjoy your time off.",
  str_homestory_chat_31823001 = "Still haven't decided what to do yet.",
  str_homestory_chat_31823002 = "Not even planning your time off?",
  str_homestory_chat_31823003 = "I always make things up as I go along!",
  str_homestory_chat_31823004 = "And you take pride in such spontaneity?",
  str_homestory_chat_31823005 = "Interesting.",
  str_homestory_chat_31823006 = "But nothing wrong with forging full-steam ahead when you're young.",
  str_homestory_chat_31823007 = "As long as you know when to throttle back.",
  str_homestory_chat_31823008 = "Were you that way when you were young?",
  str_homestory_chat_31823009 = "I was passionate when I was young, taking everything seriously.",
  str_homestory_chat_31823010 = "Really?",
  str_homestory_chat_31823011 = "That's an encouragement. I hope you get that.",
  str_homestory_chat_31823012 = "Now that you said that, I'm more at ease.",
  str_homestory_chat_31823013 = "I think I have a reason to go by.",
  str_homestory_chat_31823014 = "Just don't use it as an excuse for everything.",
  str_homestory_chat_31824001 = "I want to use the opportunity to learn new things.",
  str_homestory_chat_31824002 = "Diligence is good. Glad to see you're disciplined.",
  str_homestory_chat_31824003 = "Come see me if you run into any problem.",
  str_homestory_chat_31824004 = "Well, I do have a question right now.",
  str_homestory_chat_31824005 = "Just ask. I won't let you down.",
  str_homestory_chat_31824006 = "About the entertainment industry in Umbraton.",
  str_homestory_chat_31824007 = "Are you curious why it's so big?",
  str_homestory_chat_31824008 = "Yes. I feel it gets more impressive every time I go to Umbraton.",
  str_homestory_chat_31824009 = "Oh, that's nothing.",
  str_homestory_chat_31824010 = "We have to work even harder to fill the void in Umbraton.",
  str_homestory_chat_31824011 = "Though I can't deny how good we are with commercial creations.",
  str_homestory_chat_31824012 = "About how the Umbraton Guild works.",
  str_homestory_chat_31824013 = "Well. That's Bethel's job now.",
  str_homestory_chat_31824014 = "What specifically do you want to know?",
  str_homestory_chat_31824015 = "How do you all manage to run such a complex guild?",
  str_homestory_chat_31824016 = "I get exhausted just running the Colossus.",
  str_homestory_chat_31824017 = "I truly admire you, Bethel, and others...",
  str_homestory_chat_31824018 = "You never had a chance to experience any complex society.",
  str_homestory_chat_31824019 = "So it's normal to feel overwhelmed when you're thrust into it.",
  str_homestory_chat_31824020 = "Keep hammering away like you have and you'll make it.",
  str_homestory_chat_31824021 = "But while it's good to be diligent, don't stretch yourself too thin.",
  str_homestory_chat_31824022 = "It's a very nice day today. Make sure to enjoy it when you take a break.",
  str_homestory_chat_31824023 = "I will!",
  str_homestory_chat_31825001 = "I want to visit friends.",
  str_homestory_chat_31825002 = "They've been helping me all the time.",
  str_homestory_chat_31825003 = "I'll also go see you... Oops, there goes the surprise.",
  str_homestory_chat_31825004 = "I'm glad to hear it.",
  str_homestory_chat_31825005 = "But an old man like me doesn't need surprises.",
  str_homestory_chat_31825006 = "It's depressing without any surprises.",
  str_homestory_chat_31825007 = "Shadow should always be calm.",
  str_homestory_chat_31825008 = "The unexpected is fun.",
  str_homestory_chat_31825009 = "Not everything unexpected is fun.",
  str_homestory_chat_31825010 = "I now prefer a stable life.",
  str_homestory_chat_31825011 = "My fault I slipped. Now it's not fun anymore.",
  str_homestory_chat_31825012 = "I haven't gotten that surprise yet.",
  str_homestory_chat_31825013 = "So you're still good.",
  str_homestory_chat_31825014 = "Okay, I'm on my way out the door then!",
  str_homestory_chat_31825015 = "Sure. I'll try not to peek ahead of time.",
  str_homestory_chat_31825016 = "Hope you'll make it a pleasant surprise.",
  str_homestory_chat_31825017 = "You won't be disappointed!",
  str_homestory_chat_31825018 = "After all, this is a hard-won time off.",
  str_homestory_chat_31825019 = "May the shadow watch over you. I'll be waiting.",
  str_homestory_chat_31999999 = "Do you have any request at this time, dear patron?",
  str_homestory_chat_31921001 = "Nothing in particular, no.",
  str_homestory_chat_31921002 = "I just got a new shipment in and I'm looking for a buyer.",
  str_homestory_chat_31921003 = "Would you be interested?",
  str_homestory_chat_31921004 = "Shipment? What kind of shipment?",
  str_homestory_chat_31921005 = "Jade ware from Longzhou.",
  str_homestory_chat_31921006 = "Jade ware?",
  str_homestory_chat_31921007 = "Yes. Have you heard of it before?",
  str_homestory_chat_31921008 = "Nope.",
  str_homestory_chat_31921009 = "That's more of a reason to check it out. I assure you won't be disappointed.",
  str_homestory_chat_31921019 = "Ahem... I don't think I can afford them.",
  str_homestory_chat_31921020 = "Impossible! But it's okay, I'll be here when you change your mind.",
  str_homestory_chat_31922001 = "I'm just twiddling my thumbs right now.",
  str_homestory_chat_31922002 = "You mean, you're bored out of your mind because you have nothing to do?",
  str_homestory_chat_31922003 = "You could say that.",
  str_homestory_chat_31922004 = "Then, how about playing a game with me?",
  str_homestory_chat_31922005 = "Game? What game?",
  str_homestory_chat_31922006 = "A very simple one.",
  str_homestory_chat_31922007 = "I got a Nightium here that I'll toss in the air.",
  str_homestory_chat_31922008 = "And then?",
  str_homestory_chat_31922009 = "Let's guess whether it will land face up or face down.",
  str_homestory_chat_31922010 = "If you're right, the coin is yours.",
  str_homestory_chat_31922011 = "What if I'm wrong?",
  str_homestory_chat_31922012 = "Then you're wrong.",
  str_homestory_chat_31922013 = "Huh?",
  str_homestory_chat_31922014 = "That means it's okay if you guessed wrong. No strings attached.",
  str_homestory_chat_31922015 = "Won't that work only in my favor?",
  str_homestory_chat_31922016 = "Yes, but it's just one Nightium.",
  str_homestory_chat_31922017 = "What we get out of this far exceeds the face value, and I might not lose, right?",
  str_homestory_chat_31923001 = "I'm going through the ledger.",
  str_homestory_chat_31923002 = "Is there a problem with it? I can help if necessary.",
  str_homestory_chat_31923003 = "Would you mind taking a look then?",
  str_homestory_chat_31923004 = "Sure, the pleasure is all mine.",
  str_homestory_chat_31923005 = "Let me take the load off your hand...",
  str_homestory_chat_31923006 = "I see. The ledger is rather badly kept and organized.",
  str_homestory_chat_31923007 = "I don't want to trouble you...",
  str_homestory_chat_31923008 = "It's okay, I understand. But to be honest, the ledger is vital to any institution.",
  str_homestory_chat_31923009 = "I do have enough experience with managing accounts, so may I make some suggestions?",
  str_homestory_chat_31923010 = "Really? Any suggestion from Lady Sheol would be a big help to me!",
  str_homestory_chat_31923011 = "Thank you!",
  str_homestory_chat_31923012 = "Heheh, you're welcome.",
  str_homestory_chat_31923013 = "It's just small tips and hints.",
  str_homestory_chat_31923014 = "It should be as detailed as possible with each entry, but concise as well.",
  str_homestory_chat_31923015 = "It goes without saying that dates and purposes should be listed in separate columns. Plus, recording amounts in two formats can reduce the chance of errors.",
  str_homestory_chat_31923016 = "This way, it's much easier to review.",
  str_homestory_chat_31923017 = "I see.",
  str_homestory_chat_31923018 = "Also...",
  str_homestory_chat_31923019 = "Hold on! I need to write this down!",
  str_homestory_chat_31924001 = "I'm thirsty and want something to drink.",
  str_homestory_chat_31924002 = "How about some coffee?",
  str_homestory_chat_31924003 = "Coffee?",
  str_homestory_chat_31924004 = "Yes, I just bought some nice coffee beans.",
  str_homestory_chat_31924005 = "It would be great to get a second opinion.",
  str_homestory_chat_31924006 = "But I don't know much about coffee...",
  str_homestory_chat_31924007 = "It's okay. Just give me your thoughts after drinking it.",
  str_homestory_chat_31924008 = "I don't mind trying it if that's all it takes.",
  str_homestory_chat_31924009 = "Do you like coffee, Lady Sheol?",
  str_homestory_chat_31924010 = "Not particularly, but don't hate it either.",
  str_homestory_chat_31924011 = "Then why did you buy the beans rather than ground coffee?",
  str_homestory_chat_31924012 = "No particular reason. Coffee beans are one of Cloudrover Guild's many business ventures, anyway.",
  str_homestory_chat_31924013 = "I just got the urge to taste it for myself.",
  str_homestory_chat_31925001 = "It's study time for me next.",
  str_homestory_chat_31925002 = "Study time?",
  str_homestory_chat_31925003 = "In other words, read books.",
  str_homestory_chat_31925004 = "I see. May I ask what kind of books are you planning to read?",
  str_homestory_chat_31925005 = "History and geography.",
  str_homestory_chat_31925006 = "I know a little about these subjects too. May I make recommendations to you?",
  str_homestory_chat_31925007 = "You're knowledgeable in such fields, Lady Sheol?",
  str_homestory_chat_31925008 = "As a merchant, the more I know, the better. Thus, I can converse with patrons from different trades.",
  str_homestory_chat_31925009 = "One has to work hard to be a great merchant, I see.",
  str_homestory_chat_31925010 = "Economics.",
  str_homestory_chat_31925011 = "Oh? You're interested in economics?",
  str_homestory_chat_31925012 = "Not so much as interested but curious.",
  str_homestory_chat_31925013 = "Not to mention it's always better to read more books.",
  str_homestory_chat_31925014 = "Exactly.",
  str_homestory_chat_31925015 = "I have a lot of good books from my personal collection I can recommend.",
  str_homestory_chat_31925016 = "Please do drop by sometime.",
  str_homestory_chat_32099999 = "I want to refurnish my office! Which style do you think works best?",
  str_homestory_chat_32021001 = "Northland style!",
  str_homestory_chat_32021002 = "Oh? Well, much of Northland does look like something out of a fairy tale, especially its decorations and architecture.",
  str_homestory_chat_32021003 = "I didn't realize you were such a romantic.",
  str_homestory_chat_32021004 = "You're a scientist.",
  str_homestory_chat_32021005 = "Romantic ideas like this probably bother you, right?",
  str_homestory_chat_32021006 = "You're from the Illumina Federation.",
  str_homestory_chat_32021007 = "Doesn't that mean you're opposed to impractical and romantic ideas like this?",
  str_homestory_chat_32021008 = "What a monumental misunderstanding!",
  str_homestory_chat_32021009 = "It's true that I'm a scientist of the Illumina Federation...",
  str_homestory_chat_32021010 = "So it's natural for everyone to believe that I want nothing to do with romanticism.",
  str_homestory_chat_32021011 = "But I believe that this is a very narrow-minded view of the notion.",
  str_homestory_chat_32021012 = "To make the unknown understandable, to turn wastelands into cities...",
  str_homestory_chat_32021013 = "Isn't that also romantic in its own way?",
  str_homestory_chat_32021014 = "I guess that makes sense.",
  str_homestory_chat_32021015 = "I didn't know you were also an eloquent debater.",
  str_homestory_chat_32021016 = "I'm also someone who's very good at taking suggestions.",
  str_homestory_chat_32021017 = "Which is why I've decided to redecorate my office in Northland's style!",
  str_homestory_chat_32022001 = "Lumopolis style!",
  str_homestory_chat_32022002 = "Lumopolis' style has a very classical and pious feeling to it.",
  str_homestory_chat_32022003 = "With all the cables and machinery running through my office, I'm not sure if such a decor style would be a good match...",
  str_homestory_chat_32022004 = "But your personality is full of contradictions.",
  str_homestory_chat_32022005 = "The sharp contrast is what makes it a perfect fit!",
  str_homestory_chat_32022006 = "Mismatched things have a certain charm to them too.",
  str_homestory_chat_32022007 = "Who says that things have to match in order to be beautiful?",
  str_homestory_chat_32022008 = "Hahahaha! You make a good point!",
  str_homestory_chat_32022009 = "Your knowledge and perceptiveness are extremely admirable qualities.",
  str_homestory_chat_32022010 = "Could they stem from your countless travels across the world?",
  str_homestory_chat_32022011 = "I'm sure it's also because we've known each other for so long...",
  str_homestory_chat_32022012 = "I'll take that as a compliment!",
  str_homestory_chat_32023001 = "Umbraton style!",
  str_homestory_chat_32023002 = "What a tricky suggestion to offer.",
  str_homestory_chat_32023003 = "So tell me, how exactly would you define Umbraton's style?",
  str_homestory_chat_32023004 = "From my experience, Umbraton tends to emphasize on diversity.",
  str_homestory_chat_32023005 = "That's the beauty of it. Don't you see...?",
  str_homestory_chat_32023006 = "It may just seem like a random suggestion, but when you really think about it...",
  str_homestory_chat_32023007 = "It's the perfect idea that encompasses all suggestions!",
  str_homestory_chat_32023008 = "In fact, you won't have to worry about redecorating your office ever again! Not in the next fifty years!",
  str_homestory_chat_32023009 = "Wow... Sometimes my ideas are so good that I even surprise myself!",
  str_homestory_chat_32023010 = "You're just making up excuses because you couldn't think of a better idea, aren't you?",
  str_homestory_chat_32023011 = "Heheh... Did I give myself away?",
  str_homestory_chat_32023012 = "Never mind. I suppose I'm partly to blame for you ending up like this, so I won't keep pushing the subject.",
  str_homestory_chat_32023013 = "So you knew all along!",
  str_homestory_chat_32023014 = "I'm a genius in every sense of the word. Never forget that.",
  str_homestory_chat_32024001 = "Longzhou style!",
  str_homestory_chat_32024002 = "Wow, I can't believe you suggested that...",
  str_homestory_chat_32024003 = "I've always been fascinated by the decor style of that faraway land...",
  str_homestory_chat_32024004 = "But do you have any idea what it would cost?",
  str_homestory_chat_32024005 = "Even something as simple as a wooden chair...",
  str_homestory_chat_32024006 = "Would cost the same as redecorating my entire office once over!",
  str_homestory_chat_32024007 = "That kind of luxury will always be out of reach for normal people like us, my Caelestite friend.",
  str_homestory_chat_32024008 = "\"Normal people\"?",
  str_homestory_chat_32024009 = "I never expected to hear you refer to yourself as a \"normal\" person in my lifetime...",
  str_homestory_chat_32024010 = "Or to put yourself on my level, for that matter...",
  str_homestory_chat_32024011 = "Thank you, Longzhou!",
  str_homestory_chat_32024012 = "Is it really that expensive?",
  str_homestory_chat_32024013 = "I didn't know Longzhou's furniture was so expensive...",
  str_homestory_chat_32024014 = "Forgive me, Longzhou!",
  str_homestory_chat_32024015 = "... Ugh, thanks for reminding me that I'll never achieve my dreams of a Longzhou-style office.",
  str_homestory_chat_32024016 = "Now compensate me for my mental anguish!",
  str_homestory_chat_32024017 = "B-But I don't have any money!",
  str_homestory_chat_32025001 = "Caelestite style!",
  str_homestory_chat_32025002 = "So your own style? What a truly unexpected answer.",
  str_homestory_chat_32025003 = "I meant the style of my people, not my own...",
  str_homestory_chat_32025004 = "Then are you willing to personally redecorate my office?",
  str_homestory_chat_32025005 = "How did you get that idea from my suggestion?!",
  str_homestory_chat_32025006 = "Well, in this world—",
  str_homestory_chat_32025007 = "The only one familiar with the style of the Caelestites is none other than yourself.",
  str_homestory_chat_32025008 = "Y-You didn't have to say it that way though!",
  str_homestory_chat_32025009 = "Besides, there are plenty of historians and archaeologists in Lumopolis and the Illumina Federation who can help you...",
  str_homestory_chat_32025010 = "I'm sure they know all about the style of the Caelestites.",
  str_homestory_chat_32025011 = "Yes, but why would I want their help rather than yours...",
  str_homestory_chat_32025012 = "Can you give me, say even one, reason?",
  str_homestory_chat_32025013 = "... I can't.",
  str_homestory_chat_32025014 = "But I can think of three good reasons why you want my help.",
  str_homestory_chat_32025015 = "One, I'm cheap. Two, I won't charge as much. And three, I'll save you money...",
  str_homestory_chat_32025016 = "Hahahaha! You shouldn't sell yourself so short, you know!",
  str_homestory_chat_32025017 = "I'm asking because I knew you would do a great job decorating my office.",
  str_homestory_chat_32025018 = "And also because I enjoy talking to you so much.",
  str_homestory_chat_32025019 = "That's all!",
  str_homestory_chat_32199999 = "What do you want to wish for?",
  str_homestory_chat_32121001 = "World peace.",
  str_homestory_chat_32121002 = "Wow, for someone to make a selfless wish like this—",
  str_homestory_chat_32121003 = "You're either not taking it seriously at all...",
  str_homestory_chat_32121004 = "Or you truly want something that grand.",
  str_homestory_chat_32121005 = "So which applies to you, PlayerName?",
  str_homestory_chat_32121006 = "Not taking it seriously.",
  str_homestory_chat_32121007 = "Haha, that does fit your style.",
  str_homestory_chat_32121008 = "You've never been one to leave the future up to hopes and wishes alone. When you really want something, you pursue it and make it reality...",
  str_homestory_chat_32121009 = "I want something that grand.",
  str_homestory_chat_32121010 = "In other words, world peace is your true goal in this life.",
  str_homestory_chat_32121011 = "You go to great lengths to ensure that every step you take brings you closer to that dream...",
  str_homestory_chat_32121012 = "In all my thousands of years, people like you always give me the biggest headaches.",
  str_homestory_chat_32121013 = "Huh? Why?",
  str_homestory_chat_32121014 = "Because people like you are also the ones who end up changing the world.",
  str_homestory_chat_32122001 = "Peace and safety for those dear to me.",
  str_homestory_chat_32122002 = "I hear that kind of wish in my temple all the time.",
  str_homestory_chat_32122003 = "It makes me wonder, are the people who make this kind of wish happy or just unfortunate?",
  str_homestory_chat_32122004 = "Happy, of course!",
  str_homestory_chat_32122005 = "It means they keep their friends and loved ones in their hearts, and want them to be happy too...",
  str_homestory_chat_32122006 = "How could they possibly be unfortunate?",
  str_homestory_chat_32122007 = "Because happiness is fleeting.",
  str_homestory_chat_32122008 = "...!",
  str_homestory_chat_32122009 = "The only reason people make this kind of wish is because they're aware of that, don't you think?",
  str_homestory_chat_32122010 = "... You have a point.",
  str_homestory_chat_32122011 = "In a world overrun by Eclipsites, we're always at risk of running into unexpected misfortune.",
  str_homestory_chat_32122012 = "That's why I want to do everything I can to make sure my friends are safe.",
  str_homestory_chat_32122013 = "Even if it's something as insignificant as making a wish for them.",
  str_homestory_chat_32122014 = "Heh. The universe is impermanent, and yet people often find strength and meaning because of it.",
  str_homestory_chat_32122015 = "Which is precisely the reason I have so much respect and admiration for mortals.",
  str_homestory_chat_32123001 = "To visit every corner of the world.",
  str_homestory_chat_32123002 = "Oh? That's not a wish I hear every day, PlayerName.",
  str_homestory_chat_32123003 = "You're already more than capable of doing that, so why make a wish out of it?",
  str_homestory_chat_32123004 = "Could it be that something is standing in the way?",
  str_homestory_chat_32123005 = "I have no money.",
  str_homestory_chat_32123006 = "\"There are those who live for leisure, yet life's circumstances deny their joy.\"",
  str_homestory_chat_32123007 = "But that's easy enough to solve! Just take some of my jewelry and pawn it for some cash!",
  str_homestory_chat_32123008 = "There are too many monsters.",
  str_homestory_chat_32123009 = "\"A bear blocks the path while tigers and leopards howl at our sides.\"",
  str_homestory_chat_32123010 = "But surely even the toughest Eclipsites are no match for you with me at your side, right?",
  str_homestory_chat_32123011 = "By the way, PlayerName, do you understand the meaning of my poems?",
  str_homestory_chat_32123012 = "Yeah, I heard lots of them while traveling through Longzhou.",
  str_homestory_chat_32123013 = "The more I saw and heard them, the more they started to make sense.",
  str_homestory_chat_32123014 = "You really know how to learn from your travels, PlayerName!",
  str_homestory_chat_32123015 = "Thanks!",
  str_homestory_chat_32123016 = "Anyway, you're a dear friend of mine now. I can't let you do all the heavy lifting, you know.",
  str_homestory_chat_32123017 = "That's why I'll keep traveling the world and improving myself as much as possible!",
  str_homestory_chat_32123018 = "Good, good! I'll be waiting for you.",
  str_homestory_chat_32124001 = "To hole up in the Colossus forever.",
  str_homestory_chat_32124002 = "I completely understand! There's nothing more comfortable than tucking yourself away in your own little nest.",
  str_homestory_chat_32124003 = "Right? Sometimes a staycation is exactly what we need!",
  str_homestory_chat_32124004 = "Especially when it's cold and snowing outside, like in the winter...",
  str_homestory_chat_32124005 = "There's nothing like curling up at home with a warm drink and a good book...",
  str_homestory_chat_32124006 = "Do you really do all that?",
  str_homestory_chat_32124007 = "Usually I just sleep the entire time.",
  str_homestory_chat_32124008 = "You should give it a try next time.",
  str_homestory_chat_32124009 = "Well, it does sound interesting!",
  str_homestory_chat_32124010 = "Hmm... First, I'll have to get myself a nice, big blanket!",
  str_homestory_chat_32124011 = "Maybe I'll do it your way next time.",
  str_homestory_chat_32124012 = "Okay! We can even do it together!",
  str_homestory_chat_32124013 = "That way, you can wake me up at a reasonable time!",
  str_homestory_chat_32124014 = "I never knew your heart's desires were so simple, PlayerName.",
  str_homestory_chat_32124015 = "At first I thought you would wish to bring back your people, or something like that...",
  str_homestory_chat_32124016 = "It's too late to change things like that...",
  str_homestory_chat_32124017 = "Besides, a wish should be used to improve our lives and the lives of our friends, right?",
  str_homestory_chat_32124018 = "Precisely. To accept that the past is done is to be courageous.",
  str_homestory_chat_32125001 = "For you to be happy forever!",
  str_homestory_chat_32125002 = "Hah? You'd really waste a once-in-a-lifetime wish on me like that?",
  str_homestory_chat_32125003 = "Why?",
  str_homestory_chat_32125004 = "Because wishes should be made for the sake of our friends and family!",
  str_homestory_chat_32125005 = "Besides, it's better to fight for the things you want rather than wish for them.",
  str_homestory_chat_32125006 = "... Hahaha, I've always wanted to say that! It sounded pretty cool, right?",
  str_homestory_chat_32125007 = "... It did.",
  str_homestory_chat_32125008 = "No need to laugh about it either. I'd never make fun of you for that.",
  str_homestory_chat_32125009 = "Maybe I should make a wish too?",
  str_homestory_chat_32125010 = "Oh? A goddess making a wish, huh? Guess there's a first time for everything!",
  str_homestory_chat_32125011 = "By the light of the sun and moon and the strength of the rivers and oceans.",
  str_homestory_chat_32125012 = "May my friend PlayerName enjoy the strength of body, restful respite, and joy in the days to come.",
  str_homestory_chat_32125013 = "D-Did I hear my name just now...?",
  str_homestory_chat_32125014 = "In other words, I wish you good health, good food, good sleep...",
  str_homestory_chat_32125015 = "And a very happy new year!",
  str_homestory_chat_32125016 = "Wow...",
  str_homestory_chat_32125017 = "Now we can have another happy year together.",
  str_homestory_chat_32125018 = "Trust me, a dragon's wish should never be taken lightly.",
  str_homestory_chat_32125019 = "G-Got it! Also...",
  str_homestory_chat_32125020 = "Thanks, Chen'ni.",
  str_homestory_chat_32299999 = "What are you up to, PlayerName?",
  str_homestory_chat_32221001a = "Hmm...",
  str_homestory_chat_32221001 = "Gonna spend the day in bed.",
  str_homestory_chat_32221002 = "All day? You remind me of one of my senior disciples.",
  str_homestory_chat_32221003 = "Your senior disciple?",
  str_homestory_chat_32221004 = "Yes. He used to take really good care of me, but...",
  str_homestory_chat_32221005 = "He never took things very seriously. In fact, some people would even say he's lazy.",
  str_homestory_chat_32221006 = "Talk about taking naps all the time.",
  str_homestory_chat_32221007 = "But his skills were top-notch, and our master regarded him as a genius.",
  str_homestory_chat_32221008 = "When I think about it, he was probably on a completely different level than us.",
  str_homestory_chat_32221009 = "Gonna do some reading.",
  str_homestory_chat_32221010 = "Reading, huh? I'm curious to know what kind of books you read?",
  str_homestory_chat_32221011 = "Back in my temple days, I just read all kinds of books.",
  str_homestory_chat_32221012 = "Aside from metaphysical studies, we also read about martial arts and all kinds of other things.",
  str_homestory_chat_32221013 = "Although I was a little more interested in martial arts training than books back then...",
  str_homestory_chat_32221014 = "Say, why not give our fiendling friends a quick lesson in literature?",
  str_homestory_chat_32221015 = "After all, just knowing how to fight is never enough.",
  str_homestory_chat_32221016 = "Alright, I'll go talk to Ah Ding and the others. See you later!",
  str_homestory_chat_32221017 = "Sure, see you in a bit.",
  str_homestory_chat_32222001 = "Might go finish up some work.",
  str_homestory_chat_32222002 = "Work, huh? Yeah, me too.",
  str_homestory_chat_32222003 = "I just accepted a new job today.",
  str_homestory_chat_32222004 = "Apparently something has been causing a ruckus in an old house, but they don't know if it's an Eclipsite or a wild animal.",
  str_homestory_chat_32222005 = "Makes no difference, really. I'll drag out whatever's in there and give it a good beating either way.",
  str_homestory_chat_32222006 = "Hope nothing goes wrong...",
  str_homestory_chat_32222007 = "Don't worry, Ah Ding and the others will be with me.",
  str_homestory_chat_32222008 = "If anything goes wrong, I can always rely on Ah Ding's iron headbutt technique.",
  str_homestory_chat_32222009 = "Good luck!",
  str_homestory_chat_32222010 = "Well, I should start getting ready to head out.",
  str_homestory_chat_32223001 = "Might go visit a friend.",
  str_homestory_chat_32223002 = "Visiting a friend? That's always good.",
  str_homestory_chat_32223003 = "I've been traveling in Longzhou for years and made many friends in the meantime.",
  str_homestory_chat_32223004 = "Speaking of which, do you ever make friends with people who have nothing in common with you?",
  str_homestory_chat_32223005 = "I do.",
  str_homestory_chat_32223006 = "I had a feeling you'd say that.",
  str_homestory_chat_32223007 = "After all, this Colossus is home to plenty of people with fiendling ancestry.",
  str_homestory_chat_32223008 = "The world is vast, and people's views should be just as broad.",
  str_homestory_chat_32223009 = "Not really.",
  str_homestory_chat_32223010 = "Really...? I suppose that's understandable too.",
  str_homestory_chat_32223011 = "After all, the world is full of problems that were born from people misunderstanding one another.",
  str_homestory_chat_32223012 = "But I think that people will become wiser someday...",
  str_homestory_chat_32223013 = "Wise enough to accept the things they don't understand.",
  str_homestory_chat_32223014 = "I hope so.",
  str_homestory_chat_32224001 = "I was about to do some exercise.",
  str_homestory_chat_32224002 = "Exercise, eh? Suddenly I don't feel tired anymore!",
  str_homestory_chat_32224003 = "Training is like making a castle out of sand: it all falls apart if you stop for even a day.",
  str_homestory_chat_32224004 = "So what do you say? Mind if I join you for today?",
  str_homestory_chat_32224005 = "You have a good foundation, and training will definitely bring out your incredible potential.",
  str_homestory_chat_32224006 = "N-Never mind...",
  str_homestory_chat_32224007 = "Really? That's too bad.",
  str_homestory_chat_32224008 = "Maybe I'll just go train with the fiendlings instead.",
  str_homestory_chat_32224009 = "Sure. You should be able to lift Ah Ding no problem!",
  str_homestory_chat_32224010 = "The elephant fiendlings from the Dian Kingdom, on the other hand...",
  str_homestory_chat_32224011 = "I wouldn't even try lifting one of those!",
  str_homestory_chat_146901001 = "Pierre",
  str_homestory_chat_124901001 = "Curo",
  str_homestory_chat_151901001 = "Sork",
  str_homestory_chat_173901001 = "Patsy",
  str_homestory_chat_104901001 = "Kuma",
  str_homestory_chat_115901001 = "Hachi",
  str_homestory_chat_247901001 = "Momo",
  str_homestory_chat_32399999 = "If you could be an animal, what would you be?",
  str_homestory_chat_32321001 = "Snow fox.",
  str_homestory_chat_32321002 = "I get you! Snow foxes are cool!",
  str_homestory_chat_32321003 = "Agile, mobile, outstanding hunters with the ability to blend into the snow for concealment!",
  str_homestory_chat_32321004 = "Incredibly high survivability! Great choice.",
  str_homestory_chat_32321005 = "Actually, I chose that only because...",
  str_homestory_chat_32321006 = "Snow foxes are cute.",
  str_homestory_chat_32321007 = "They're adorably fluffy.",
  str_homestory_chat_32321008 = "If every hunter were as deadly as you...",
  str_homestory_chat_32321009 = "It would be better if I became a soft animal and moved them with my cuteness!",
  str_homestory_chat_32321010 = "You love snow foxes, don't you?",
  str_homestory_chat_32321011 = "If I were one, maybe I'd live out the rest of my life in peace under your protection.",
  str_homestory_chat_32321012 = "What a logical, reasonable assumption!",
  str_homestory_chat_32321013 = "That is exactly how an Aurorian thinks!",
  str_homestory_chat_32321014 = "But animals out in the snow don't care about appeasing Aurorians.",
  str_homestory_chat_32321015 = "Ahem... Sorry, I'm neither an animal nor an Aurorian.",
  str_homestory_chat_32321016 = "I'm just a weak little Caelestite who puts survival above all else.",
  str_homestory_chat_32322001 = "Grizzly bear.",
  str_homestory_chat_32322002 = "...",
  str_homestory_chat_32322003 = "PlayerName...",
  str_homestory_chat_32322004 = "What's wrong? Why the pity in your eyes?",
  str_homestory_chat_32322005 = "What? No, no pity. I get it.",
  str_homestory_chat_32322006 = "You're a pushover without much physical strength, so...",
  str_homestory_chat_32322007 = "Naturally, you crave a powerful body like that of a grizzly.",
  str_homestory_chat_32322008 = "I understand. I really do!",
  str_homestory_chat_32322009 = "What are you saying?",
  str_homestory_chat_32322010 = "\"A pushover without much physical strength\"? That's going a little far!",
  str_homestory_chat_32322011 = "I just thought—",
  str_homestory_chat_32322012 = "Just thought what?",
  str_homestory_chat_32322013 = "The way a grizzly sleeps through the whole winter is what I would enjoy!",
  str_homestory_chat_32322014 = "PlayerName...",
  str_homestory_chat_32322015 = "Why is there more pity in your eyes now?",
  str_homestory_chat_32323001 = "Seagull.",
  str_homestory_chat_32323002 = "Oh, you mean those birds obsessed with fries?",
  str_homestory_chat_32323003 = "Wait, no...",
  str_homestory_chat_32323004 = "Fries aren't the only thing they eat.",
  str_homestory_chat_32323005 = "Rather, they're not picky at all when it comes to food.",
  str_homestory_chat_32323006 = "Berries, kelp, fish, insects... They eat all that—and fries too, of course.",
  str_homestory_chat_32323007 = "They're very open-minded and will try anything.",
  str_homestory_chat_32323008 = "That's very close to how I want to live!",
  str_homestory_chat_32323009 = "Now that you say that, you did mention it before...",
  str_homestory_chat_32323010 = "You want to visit every corner of the world and see everything.",
  str_homestory_chat_32323011 = "That is the perfect bird for you!",
  str_homestory_chat_32323012 = "You're a Caelestite and they're known to be associated with sky and flying.",
  str_homestory_chat_32323013 = "The Colossus is my wings.",
  str_homestory_chat_32323014 = "You're welcome to travel with me if you like!",
  str_homestory_chat_32323015 = "As long as we don't eat fries all the time.",
  str_homestory_chat_32323016 = "Stop talking about fries!",
  str_homestory_chat_32324001 = "Rabbit.",
  str_homestory_chat_32324002 = "Really? That's a unique choice.",
  str_homestory_chat_32324003 = "Rabbits can't fight and are at the bottom of the food chain out in the wild.",
  str_homestory_chat_32324004 = "Why would you want to be such a weak animal?",
  str_homestory_chat_32324005 = "Rabbits aren't weak.",
  str_homestory_chat_32324006 = "No one watches out for rabbits.",
  str_homestory_chat_32324007 = "The timid, harmless appearance is actually their best weapon.",
  str_homestory_chat_32324008 = "Why else would Novio pick a rabbit as his intel partner?",
  str_homestory_chat_32324009 = "Compared to preemptive strikes, I prefer reactive strikes better.",
  str_homestory_chat_32324010 = "Rabbits have keen hearing.",
  str_homestory_chat_32324011 = "They lurk in the dark and hear everything around them.",
  str_homestory_chat_32324012 = "Everything they sense helps their friends out.",
  str_homestory_chat_32324013 = "Don't you think that sounds a lot like a Caelestite with psychic abilities?",
  str_homestory_chat_32324014 = "True. Your Caelestite perspective is very different from an Aurorian's.",
  str_homestory_chat_32324015 = "Also, that gave me a new insight to improve my hunting.",
  str_homestory_chat_32324016 = "Oh no, I didn't just sell the rabbits down the river, did I?",
  str_homestory_chat_32324017 = "You'll see it at suppertime!",
  str_homestory_chat_32325001 = "Whale.",
  str_homestory_chat_32325002 = "Lord of the sea! A very reasonable choice.",
  str_homestory_chat_32325003 = "Is that because Caelestites desire power?",
  str_homestory_chat_32325004 = "Not exactly.",
  str_homestory_chat_32325005 = "There's a species of whale called orca. I heard they're big on family.",
  str_homestory_chat_32325006 = "They'd live with their family until death.",
  str_homestory_chat_32325007 = "I guess that's something I appreciate and gravitate to.",
  str_homestory_chat_32325008 = "PlayerName...",
  str_homestory_chat_32325009 = "Sorry, I didn't mean to remind you of your past.",
  str_homestory_chat_32325010 = "It's okay, no worries.",
  str_homestory_chat_32325011 = "I've got a family on the Colossus.",
  str_homestory_chat_32325012 = "So my wish already came true.",
  str_homestory_chat_32325013 = "Soroz is my family.",
  str_homestory_chat_32325014 = "We'd do anything for the other.",
  str_homestory_chat_32325015 = "Ah, I get it now.",
  str_homestory_chat_32325016 = "I'm just like you.",
  str_homestory_chat_32325017 = "I lost my family long ago, but I found a new family.",
  str_homestory_chat_32325018 = "In that sense, family goes beyond just a blood bond.",
  str_homestory_chat_32325019 = "I knew you'd get it.",
  str_homestory_chat_32325020 = "Thank you, Tiare.",
  str_homestory_chat_32499999 = "Ribbit!",
  str_homestory_chat_32421001 = "I see the little fellow likes it here too!",
  str_homestory_chat_32599999 = "If you had to choose a collecting hobby, which would you choose?",
  str_homestory_chat_32521001 = "Figurines.",
  str_homestory_chat_32521002 = "Like the ones used on sand tables to determine combat tactics?",
  str_homestory_chat_32521003 = "I had no idea you were such a military enthusiast.",
  str_homestory_chat_32521004 = "Yep, that's right.",
  str_homestory_chat_32521005 = "Everyone calls me the Navigator, which also makes me a kind of commander.",
  str_homestory_chat_32521006 = "Besides, there's nothing wrong with practicing combat strategies from time to time.",
  str_homestory_chat_32521007 = "PlayerName... I didn't realize you prepared for each battle so thoroughly.",
  str_homestory_chat_32521008 = "I'm seeing you in a new light yet again.",
  str_homestory_chat_32521009 = "I think you have the wrong idea...",
  str_homestory_chat_32521010 = "When I say figurines, I mean the colorful and expensive ones—",
  str_homestory_chat_32521011 = "So you'd buy the most advanced soldier models, complete with full weapon systems?",
  str_homestory_chat_32521012 = "PlayerName... I had no idea you took combat simulations so seriously.",
  str_homestory_chat_32521013 = "I rarely meet others who are just like me.",
  str_homestory_chat_32521014 = "Let's keep doing our best, okay?",
  str_homestory_chat_32521015 = "Uh... Sure!",
  str_homestory_chat_32522001 = "Furniture.",
  str_homestory_chat_32522002 = "Furniture? I suppose you do have a fair amount of rare furniture items in Cloud Gardens.",
  str_homestory_chat_32522003 = "So that's what you're into.",
  str_homestory_chat_32522004 = "Yep! Furniture doesn't just make our lives more comfortable...",
  str_homestory_chat_32522005 = "It also helps me get closer to my friends.",
  str_homestory_chat_32522006 = "Yes, I've seen you and your friends having passionate conversations around your furniture.",
  str_homestory_chat_32522007 = "I see now. You use furniture as a \"friend trap\" of sorts.",
  str_homestory_chat_32522008 = "After setting up the right piece of furniture, you wait for the perfect opportunity—",
  str_homestory_chat_32522009 = "To make unforgettable memories of our adventures.",
  str_homestory_chat_32522010 = "And those pieces of furniture serve as reminders of those adventures, right? That makes sense.",
  str_homestory_chat_32522011 = "Certain birds of prey have a similar habit.",
  str_homestory_chat_32522012 = "After tearing their prey apart and devouring the meat, they decorate their nests with the bones—",
  str_homestory_chat_32522013 = "W-W-W-Wait a second!",
  str_homestory_chat_32522014 = "Something about that doesn't seem right!",
  str_homestory_chat_32523001 = "Vice.",
  str_homestory_chat_32523002 = "You would collect... Lieutenant Vice? Sorry, but I don't follow.",
  str_homestory_chat_32523003 = "After all, she's an extremely one-of-a-kind person.",
  str_homestory_chat_32523004 = "You mean you don't understand? There are actually tons of different Vices!",
  str_homestory_chat_32523005 = "Like \"Yells at Me to Clean the Warehouse\" Vice, and \"Badgers Me to Take on More Jobs\" Vice...",
  str_homestory_chat_32523006 = "\"Reminds Me to Dust My Room\" Vice, and \"Forces Me to Eat Unspeakably Horrible Food\" Vice...",
  str_homestory_chat_32523007 = "... Even though all of those sound incredibly negative, I think I understand now.",
  str_homestory_chat_32523008 = "You just want to see every side of Lieutenant Vice, don't you?",
  str_homestory_chat_32523009 = "Ahem, I didn't say that!",
  str_homestory_chat_32524001 = "Colossi.",
  str_homestory_chat_32524002 = "Colossi... Can you really collect those?",
  str_homestory_chat_32524003 = "Well, obviously I wouldn't be putting them on a shelf or anything. I guess...",
  str_homestory_chat_32524004 = "What I really want is to see even more Colossi out there.",
  str_homestory_chat_32524005 = "PlayerName... From what I can tell, you must really miss your home.",
  str_homestory_chat_32524006 = "You're right.",
  str_homestory_chat_32524007 = "I think I can relate.",
  str_homestory_chat_32524008 = "When I was fighting to restore my family's honor...",
  str_homestory_chat_32524009 = "Anything that reminded me of home would strengthen my fighting spirit a hundred times over.",
  str_homestory_chat_32524010 = "It's not quite that.",
  str_homestory_chat_32524011 = "Colossi have much to teach me about themselves, as well as the Caelestites.",
  str_homestory_chat_32524012 = "With that knowledge, I can be ready for any problems that Soroz may have in the future!",
  str_homestory_chat_32524013 = "So rather than cling to the past, you fight to preserve what you cherish in the present...",
  str_homestory_chat_32524014 = "You really are determined, Caelestite One.",
  str_homestory_chat_32524015 = "Thanks for understanding, Rachel.",
  str_homestory_chat_32524016 = "In my eyes, you've been part of my family for a long time now.",
  str_homestory_chat_32525001 = "Aurorians.",
  str_homestory_chat_32525002 = "Is that what Aurorians mean to you? Collectibles?",
  str_homestory_chat_32525003 = "Well, yeah! After all, I'm a completionist at heart!",
  str_homestory_chat_32525004 = "And what exactly does that mean?",
  str_homestory_chat_32525005 = "Don't get the wrong idea. It's just a metaphor.",
  str_homestory_chat_32525006 = "I just want to fight alongside as many Aurorians as possible.",
  str_homestory_chat_32525007 = "That way, I can keep developing my collection... I mean, my ability to adapt...",
  str_homestory_chat_32525008 = "And then no problem will be too difficult for me to handle! Makes sense, right?",
  str_homestory_chat_32525009 = "I see... Sorry for doubting you just now.",
  str_homestory_chat_32525010 = "I admire your commendable intentions.",
  str_homestory_chat_32525011 = "Why don't we have a practice battle next time?",
  str_homestory_chat_32525012 = "Huh?",
  str_homestory_chat_32699999 = "Well, if it isn't the Last Caelestite! What are you up to?",
  str_homestory_chat_32621001 = "Uh...",
  str_homestory_chat_32621002 = "I was about to go do some exercise.",
  str_homestory_chat_32621003 = "I see! A little strength training, huh?",
  str_homestory_chat_32621004 = "Just as I thought, you don't take breaks even on normal days!",
  str_homestory_chat_32621005 = "Do you train pretty often too, Zeta?",
  str_homestory_chat_32621006 = "My wisdom and charisma are my best attributes. Even without physical training, I'm still plenty strong!",
  str_homestory_chat_32621007 = "For instance, have you ever seen a lion train itself before?",
  str_homestory_chat_32621008 = "Of course not! That's because it's completely unacceptable for a naturally powerful creature to train to become even more powerful!",
  str_homestory_chat_32621009 = "I was planning to take a break.",
  str_homestory_chat_32621010 = "I see. Getting some rest before the next brutal battle, huh?",
  str_homestory_chat_32621011 = "Just as I thought, you take your breaks as seriously as you do your work!",
  str_homestory_chat_32621012 = "You're just like me! Even though everyone says I eat way too many sweets...",
  str_homestory_chat_32621013 = "I always balance out my diet by eating vitamin-enriched candy too!",
  str_homestory_chat_32621014 = "Hmm? Uh-oh, it's almost time for me to meet up with those guys! Sorry, but I gotta go!",
  str_homestory_chat_32621015 = "That's fine, I'll see you later.",
  str_homestory_chat_32622001 = "I have some important stuff to do soon.",
  str_homestory_chat_32622002 = "Important stuff? Sounds awfully suspicious...",
  str_homestory_chat_32622003 = "Is it something so important that you can't tell your friends about it?",
  str_homestory_chat_32622004 = "In order to distance himself from his unsavory past, he leaves without saying goodbye and faces his grim fate alone...",
  str_homestory_chat_32622005 = "But don't worry, you'll never be alone again! I'll stand at your side wherever you go!",
  str_homestory_chat_32622006 = "Thanks, Zeta, but it's really just some maintenance work for the Colossus.",
  str_homestory_chat_32622007 = "Huh? Oh, that's boring.",
  str_homestory_chat_32622008 = "Wanna help me sort out some files?",
  str_homestory_chat_32622009 = "What? You mean that's all it is?",
  str_homestory_chat_32622010 = "Ahem... Sorry, but I just remembered I have something else to do right now.",
  str_homestory_chat_32622011 = "Warriors can be super busy too, you know! See you around!",
  str_homestory_chat_32623001 = "Nothing really.",
  str_homestory_chat_32623002 = "\"Nothing really,\" huh? I guess that means nothing bad has happened.",
  str_homestory_chat_32623003 = "But world-saving warriors like us can't afford to lose focus!",
  str_homestory_chat_32623004 = "Evil lurks around every corner, so we must always keep an eye out for it!",
  str_homestory_chat_32623005 = "Just don't get into any trouble.",
  str_homestory_chat_32623006 = "You're just waiting for mayhem to happen, aren't you?",
  str_homestory_chat_32623007 = "Relax! The great warrior Zeta would never do anything to cause trouble!",
  str_homestory_chat_32623008 = "Somehow your oath just makes me worry even more...",
  str_homestory_chat_32624001 = "I kind of want a snack right now.",
  str_homestory_chat_32624002 = "A snack? Then you ran into the right person!",
  str_homestory_chat_32624003 = "I've got all kinds of candy. Here, take your pick!",
  str_homestory_chat_32624004 = "But I want something salty.",
  str_homestory_chat_32624005 = "I've got salty candy too! Like this one, a ghost pepper lollipop!",
  str_homestory_chat_32624006 = "It's made with real ghost peppers. They say you won't be able to breathe after just a few licks!",
  str_homestory_chat_32624007 = "But I haven't tried it for myself yet, so I don't know if it's true or not.",
  str_homestory_chat_32624008 = "Then why would you give it to me?",
  str_homestory_chat_32624009 = "Don't mind if I do!",
  str_homestory_chat_32624010 = "Feel free to take whatever you want. Fair warning, though: there are a few bombs mixed in there, so be careful when you're eating them.",
  str_homestory_chat_32624011 = "B-Bombs? Which ones are bombs?",
  str_homestory_chat_32624012 = "You mean you can't tell them apart? It's totally obvious!",
  str_homestory_chat_32624013 = "Maybe to you, but I can't tell them apart at all.",
  str_homestory_chat_32624014 = "Eh, you're hopeless. Here, I'll pick one out just for you then.",
  str_homestory_chat_32624015 = "I've got some other stuff to do, so I'll see you later.",
  str_homestory_chat_32799999 = "Any games you would like to play lately?",
  str_homestory_chat_32721001 = "Role-playing games",
  str_homestory_chat_32721002 = "Ah, nice choice!",
  str_homestory_chat_32721003 = "What made you choose that?",
  str_homestory_chat_32721004 = "Are you more into the game setting or the story?",
  str_homestory_chat_32721005 = "The setting",
  str_homestory_chat_32721006 = "It's neat to feel like you're living somewhere else.",
  str_homestory_chat_32721007 = "The experience type... I get it.",
  str_homestory_chat_32721008 = "The story",
  str_homestory_chat_32721009 = "It's typically good-guys-slaying-the-dragon kind of stuff.",
  str_homestory_chat_32721010 = "But I don't mind it at all.",
  str_homestory_chat_32721011 = "The feel-good type... I can dig that.",
  str_homestory_chat_32721012 = "You don't like that kind of game, Batia?",
  str_homestory_chat_32721013 = "I do, it's just... I don't have a particular preference.",
  str_homestory_chat_32721014 = "I relish it more when there's a wide variety to choose from.",
  str_homestory_chat_32722001 = "Strategy games",
  str_homestory_chat_32722002 = "That's not surprising!",
  str_homestory_chat_32722003 = "I would like to improve my navigation ability as a Caelestite.",
  str_homestory_chat_32722004 = "So I'm better composed when facing Eclipsites.",
  str_homestory_chat_32722005 = "So you're telling me...",
  str_homestory_chat_32722006 = "You want to improve how you counter them through playing strategic games?",
  str_homestory_chat_32722007 = "It's impressive that you would think about that even when playing a game.",
  str_homestory_chat_32722008 = "Well, I've actually been training for that.",
  str_homestory_chat_32722009 = "It would be nice to play all sorts of simulations and scenarios out in a game.",
  str_homestory_chat_32723001 = "Casual games",
  str_homestory_chat_32723002 = "Tile-matching games are pretty easy, right?",
  str_homestory_chat_32723003 = "Uh, not necessarily.",
  str_homestory_chat_32723004 = "Even that kind of game can be tough and very challenging.",
  str_homestory_chat_32723005 = "How tough?",
  str_homestory_chat_32723006 = "You can't make a move at all.",
  str_homestory_chat_32723007 = "How challenging?",
  str_homestory_chat_32723008 = "Lots of weird requirements that demand time and effort.",
  str_homestory_chat_32723009 = "Perhaps I should reconsider.",
  str_homestory_chat_32724001 = "Tetrablox! Tetrablox!",
  str_homestory_chat_32724002 = "You like Tetrablox too?!",
  str_homestory_chat_32724003 = "You could say that, but I'm definitely not as good as you.",
  str_homestory_chat_32724004 = "I'm not fast enough to clear out that many blocks.",
  str_homestory_chat_32724005 = "It's part luck and part skill... I can show you.",
  str_homestory_chat_32724006 = "Why don't we aim to reach Level 30 for now?",
  str_homestory_chat_32725001 = "Not really",
  str_homestory_chat_32725002 = "We should go outside.",
  str_homestory_chat_32725003 = "Outside? You mean outside-outside or here-outside?",
  str_homestory_chat_32725004 = "Outside-outside",
  str_homestory_chat_32725005 = "Uh, I don't go on trips often...",
  str_homestory_chat_32725006 = "It's okay. We got the Colossus.",
  str_homestory_chat_32725007 = "Here-outside",
  str_homestory_chat_32725008 = "It's okay. It's comfortable here and we have an umbrella.",
  str_homestory_chat_32725009 = "I'm not being a nuisance to you, am I?",
  str_homestory_chat_32725010 = "If we fall down...",
  str_homestory_chat_32725011 = "We can stare at the sky on our backs!",
  str_homestory_chat_32899999 = "If you could get your hands on a magical item, what would you want?",
  str_homestory_chat_32821001 = "A money printer.",
  str_homestory_chat_32821002 = "Geez! That's certainly... a particular type of \"magic\", I guess.",
  str_homestory_chat_32821003 = "I'm kidding... but we're seriously low on funds for the Colossus' upkeep these days.",
  str_homestory_chat_32821004 = "I'm already juggling eight jobs a day!",
  str_homestory_chat_32821005 = "If that's the case, why not work for the True Order?",
  str_homestory_chat_32821006 = "The payment I offer will not disgrace the reputation of Varaki.",
  str_homestory_chat_32821007 = "Where should I send my resume?!",
  str_homestory_chat_32821008 = "No need for such mundane formalities. When the chance led by the Truth comes, we will naturally work together.",
  str_homestory_chat_32821009 = "Forcing it won't bring any good.",
  str_homestory_chat_32821010 = "That sounds kinda unstable...",
  str_homestory_chat_32821011 = "You're not just making empty promises, are you?",
  str_homestory_chat_32821012 = "I'm honestly surprised you'd think that.",
  str_homestory_chat_32821013 = "Do you really see us in the True Order as a shady group that cons its followers?",
  str_homestory_chat_32821014 = "Absolutely not! It's just that I've run into too many dodgy bosses lately...",
  str_homestory_chat_32822001 = "An invisibility cloak.",
  str_homestory_chat_32822002 = "Oh...?",
  str_homestory_chat_32822003 = "Why... are you giving me that look?",
  str_homestory_chat_32822004 = "Heh...",
  str_homestory_chat_32822005 = "What's so funny about it?!",
  str_homestory_chat_32822006 = "No need to be embarrassed, Navigator. It's natural to have these thoughts at your age.",
  str_homestory_chat_32822007 = "What thoughts are you talking about? I just think an invisibility cloak would be great for stealth missions!",
  str_homestory_chat_32822008 = "Yeah, of course. You wouldn't want it otherwise.",
  str_homestory_chat_32822009 = "What in the world do you think I want it for?",
  str_homestory_chat_32823001 = "A broom that sweeps by itself.",
  str_homestory_chat_32823002 = "Oh my, with all the magical items to choose from, you just want a broom? Your desires are quite modest.",
  str_homestory_chat_32823003 = "If you don't want to do the cleaning, why not just get a servant?",
  str_homestory_chat_32823004 = "Someone as high up as you might not get it...",
  str_homestory_chat_32823005 = "But commanding someone else, even if I'm paying them, makes me feel uncomfortable.",
  str_homestory_chat_32823006 = "But if it's a magic broom, I can give orders without feeling bad!",
  str_homestory_chat_32823007 = "I see. You're a really kind soul.",
  str_homestory_chat_32823008 = "But, if you suppress your \"self\" too much for others, you might stray from the Truth.",
  str_homestory_chat_32823009 = "Caring for others is part of the \"self\".",
  str_homestory_chat_32823010 = "Well argued. Your wisdom and insight are indeed extraordinary.",
  str_homestory_chat_32823011 = "Indeed, if you could fully express your gentle nature...",
  str_homestory_chat_32823012 = "You would surely become a self-sacrificing saint, just like Nails...",
  str_homestory_chat_32823013 = "N-n-no, that's not necessary. I'm all good being just ordinary!",
  str_homestory_chat_32823014 = "So, only egomaniacs can get close to the Truth?",
  str_homestory_chat_32823015 = "Heh... Your words are quite sharp; how adorable.",
  str_homestory_chat_32823016 = "But yes, as it turns out, those who grasp the Truth tend to be egomaniacs.",
  str_homestory_chat_32823017 = "Your sharp words are like a rose's thorns... Perhaps it's the Truth manifesting in you... who knows.",
  str_homestory_chat_32823018 = "Isn't this Lord of Truth a bit difficult to get along with...?",
  str_homestory_chat_32824001 = "An hourglass that rewinds time.",
  str_homestory_chat_32824002 = "Rewinding time? A classic choice.",
  str_homestory_chat_32824003 = "Excuse me for asking, but is it because you want to go back seventeen years to change what happened in Eraveil?",
  str_homestory_chat_32824004 = "Of course.",
  str_homestory_chat_32824005 = "It's only natural for you to want that.",
  str_homestory_chat_32824006 = "If you really get the chance to make it happen, maybe... I will stand by your side.",
  str_homestory_chat_32824007 = "What? I figured everyone would be against such a big shift in history...",
  str_homestory_chat_32824008 = "I'm afraid to change things that much.",
  str_homestory_chat_32824009 = "The whole of Astra would be impacted...",
  str_homestory_chat_32824010 = "At most, I'd just go back to the day before yesterday and find my lost money... haha.",
  str_homestory_chat_32824011 = "...The fabric of time is extremely mysterious.",
  str_homestory_chat_32824012 = "The way the \"past\" is formed is much more complex than what we think.",
  str_homestory_chat_32824013 = "Sometimes, it might be the \"future\" that shapes the \"past\".",
  str_homestory_chat_32824014 = "...",
  str_homestory_chat_32825001 = "A potion that lets you learn while you sleep.",
  str_homestory_chat_32825002 = "...",
  str_homestory_chat_32825003 = "Fr-from your eyes, I see deep disapproval...",
  str_homestory_chat_32825004 = "Heh... I appreciate how smart you are.",
  str_homestory_chat_32825005 = "There are tons of fantasy novels centered around magic...",
  str_homestory_chat_32825006 = "But even they rarely describe the potion you want. Do you know why?",
  str_homestory_chat_32825007 = "The authors aren't daring enough?",
  str_homestory_chat_32825008 = "Because knowledge is the only path to the Truth.",
  str_homestory_chat_32825009 = "And learning is one thing that allows no shortcuts.",
  str_homestory_chat_32825010 = "Do you get it now?",
  str_homestory_chat_32825011 = "...I totally get it, Teacher Victoria!",
  str_homestory_chat_32999999 = "Have you ever repented for anything?",
  str_homestory_chat_32921001 = "Stayed up for three days playing games.",
  str_homestory_chat_32921002 = "Games...? What are those?",
  str_homestory_chat_32921003 = "They're devils.",
  str_homestory_chat_32921004 = "Devils? You mean vile creatures like the Eclipsites or the Necroservants?",
  str_homestory_chat_32921005 = "I will protect you, PlayerName, because this is exactly why the Lord has granted me the power of the Sacred Blood.",
  str_homestory_chat_32921006 = "Sacred Blood can't do anything about this.",
  str_homestory_chat_32921007 = "Devils called games use joy as bait, wasting my youth and draining my money...",
  str_homestory_chat_32921008 = "Even the strongest warrior can't escape their clutches!",
  str_homestory_chat_32921009 = "But... But it sounds like you're simply giving in to the temptation without putting up a fight.",
  str_homestory_chat_32921010 = "You must protect me.",
  str_homestory_chat_32921011 = "Next time Gronru tempts me with games, you have to block her!",
  str_homestory_chat_32921012 = "Gronru?",
  str_homestory_chat_32921013 = "She's the demon queen of games in hell. If it weren't for her, I wouldn't end up like this...",
  str_homestory_chat_32921014 = "Isn't that just... blaming someone else for your fault?",
  str_homestory_chat_32921015 = "Perhaps this is what you really should be repenting for, don't you think?",
  str_homestory_chat_32921016 = "Ugh...! Let's drop this topic. Goodbye!",
  str_homestory_chat_32922001 = "Stacking a fruit tower in a restaurant.",
  str_homestory_chat_32922002 = "A fruit tower?",
  str_homestory_chat_32922003 = "Ahem, you know those restaurants where you can get a self-serve fruit salad if you order a main dish?",
  str_homestory_chat_32922004 = "You can take as much as you want, but only once.",
  str_homestory_chat_32922005 = "Hence, stacking as much salad as possible on one plate becomes an art form.",
  str_homestory_chat_32922006 = "So, you piled up a... tower of fruits on your plate?",
  str_homestory_chat_32922007 = "Don't, don't look at me like that...",
  str_homestory_chat_32922008 = "That requires real skill!",
  str_homestory_chat_32922009 = "...If you feel proud, why did you repent it?",
  str_homestory_chat_32922010 = "I ate the whole fruit tower and had diarrhea for three days...",
  str_homestory_chat_32922011 = "Then you have received the Lord's punishment; your sins have been cleansed, PlayerName.",
  str_homestory_chat_32922012 = "Your eyes have turned warm again, which makes me feel even weirder...",
  str_homestory_chat_32923001 = "Speeding.",
  str_homestory_chat_32923002 = "Speeding... I didn't know the Colossus had speed limits.",
  str_homestory_chat_32923003 = "The sky is now mine to roam freely...",
  str_homestory_chat_32923004 = "But in the days when many Colossi were in the sky, there were customary speed limits.",
  str_homestory_chat_32923005 = "They were to keep other Colossi and birds safe, and I followed them most of the time.",
  str_homestory_chat_32923006 = "So why did you speed?",
  str_homestory_chat_32923007 = "Vice's birthday.",
  str_homestory_chat_32923008 = "I sped to Umbraton to grab one of the fifty limited-edition ultra-luxury fruit cakes.",
  str_homestory_chat_32923009 = "Carleen's birthday.",
  str_homestory_chat_32923010 = "I sped to Lumopolis for the birthday banquet and had to pick up my evening gown from the dry cleaners on the way...",
  str_homestory_chat_32923011 = "I see...",
  str_homestory_chat_32923012 = "Since it was for her, I can't blame you.",
  str_homestory_chat_32923013 = "And you've already repented sincerely, right?",
  str_homestory_chat_32923014 = "O-Of course!",
  str_homestory_chat_32923015 = "Even without anyone enforcing it, you still adhere to your clan's customs and repent when you break them.",
  str_homestory_chat_32923016 = "Your noble character is admirable.",
  str_homestory_chat_32923017 = "The Lord of Truth will bless you, PlayerName.",
  str_homestory_chat_32923018 = "Thank you... I mean, thank Him!",
  str_homestory_chat_32924001 = "Lack perseverance.",
  str_homestory_chat_32924002 = "Is it difficult for you to stick to things?",
  str_homestory_chat_32924003 = "Yes... especially when I decide to work out, ahem...",
  str_homestory_chat_32924004 = "Training the body is a painful process. I've been through it, so I get it.",
  str_homestory_chat_32924005 = "Actually, you don't need to push yourself because your strength doesn't lie in your body.",
  str_homestory_chat_32924006 = "Exercise doesn't suit you, but there must be something you can stick with, right?",
  str_homestory_chat_32924007 = "Sort of... I guess...",
  str_homestory_chat_32924008 = "Like what?",
  str_homestory_chat_32924009 = "Eating... sleeping...",
  str_homestory_chat_32924010 = "...",
  str_homestory_chat_32924011 = "There's more! Like...",
  str_homestory_chat_32924012 = "...Like breathing!",
  str_homestory_chat_32924013 = "...",
  str_homestory_chat_33099999 = "What kind of books do you like to read?",
  str_homestory_chat_33021001 = "Novels.",
  str_homestory_chat_33021002 = "Interesting.",
  str_homestory_chat_33021003 = "You know what? What you call novels have a surprisingly short history.",
  str_homestory_chat_33021004 = "They were just starting out in my time.",
  str_homestory_chat_33021005 = "That's news for me!",
  str_homestory_chat_33021006 = "I thought novels... um, have always been there?",
  str_homestory_chat_33021007 = "It's a common cognitive bias to think that new concepts in culture and society have always existed.",
  str_homestory_chat_33021008 = "Not just novels, concepts like childhood, love, reason, and so on are also products of modern times.",
  str_homestory_chat_33021009 = "Once you're used to them, it's hard to imagine life any other way...",
  str_homestory_chat_33021010 = "Hence the misconception that \"they have always existed.\"",
  str_homestory_chat_33021011 = "It's kind of hard to believe.",
  str_homestory_chat_33021012 = "Didn't the Aurorians have stories to read in the past?",
  str_homestory_chat_33021013 = "Back then, we had epics, dramas, and fables, which have elements of storytelling but are quite different from novels.",
  str_homestory_chat_33021014 = "Lately, I've been reading some of the bestselling novels displayed in bookstores. Compared to epics and such...",
  str_homestory_chat_33021015 = "Their plots are more complex, the emotions more nuanced, undoubtedly a product of societal affluence.",
  str_homestory_chat_33021016 = "A hundred years ago, the Aurorians had no time to ponder over such \"useless\" things.",
  str_homestory_chat_33021017 = "I see... It's really enlightening talking to you!",
  str_homestory_chat_33022001 = "History book.",
  str_homestory_chat_33022002 = "It's rare for someone your age to be interested in history.",
  str_homestory_chat_33022003 = "It's good to read history, but be mindful not to think that everything written in a book is absolutely true.",
  str_homestory_chat_33022004 = "I get it, Mr. Wilhelm. You mean \"history is written by the victors,\" right?",
  str_homestory_chat_33022005 = "That statement merely reflects the deliberate distortion of history by those in power. The reality is much more complex.",
  str_homestory_chat_33022006 = "Even when historians write history with the noble intention to \"restore the truth\"...",
  str_homestory_chat_33022007 = "They are inevitably influenced by the spirit and ethos of their own times.",
  str_homestory_chat_33022008 = "What they write down is already \"history as seen by the contemporary,\" not \"history\" itself.",
  str_homestory_chat_33022009 = "Are you saying... history cannot be accurately restored?",
  str_homestory_chat_33022010 = "As expected from a young one who reads history, you've already noticed the irony of \"history and truth.\"",
  str_homestory_chat_33023001 = "Poetry.",
  str_homestory_chat_33023002 = "Hmph, sometimes I think you're too old-souled for your age, but then you surprise me with some youthful interests.",
  str_homestory_chat_33023003 = "There's a saying, \"Dying young while youth still lingers is a poet's blessing.\" What do you make of that?",
  str_homestory_chat_33023004 = "I agree.",
  str_homestory_chat_33023005 = "Your thoughts are dangerous.",
  str_homestory_chat_33023006 = "Writing poetry demands youthful fervor. It's better to die early than wait for that passion to fade.",
  str_homestory_chat_33023007 = "A life without passion isn't worth living—is that what you think?",
  str_homestory_chat_33023008 = "Definitely not, but how about those poets?",
  str_homestory_chat_33023009 = "There's always someone who sees something as the purpose of their entire life, right?",
  str_homestory_chat_33023010 = "Purpose of the entire life... For me, perhaps it's the path to get closer to the Lord.",
  str_homestory_chat_33023011 = "You have a keen insight, PlayerName.",
  str_homestory_chat_33023012 = "I disagree.",
  str_homestory_chat_33023013 = "Are you against the \"innate talent theory\"?",
  str_homestory_chat_33023014 = "What do you mean?",
  str_homestory_chat_33023015 = "Of all literary forms, poetry is the most talent-demanding.",
  str_homestory_chat_33023016 = "Many great poets rise to fame in their teens and twenties, burn out their talents, and then reduce to mediocre.",
  str_homestory_chat_33023017 = "But you don't agree with this kind of fate.",
  str_homestory_chat_33023018 = "As long as one lives, one can pursue the poetry granted by the divine with a soul enriched by worldly experiences.",
  str_homestory_chat_33023019 = "Is that what you think?",
  str_homestory_chat_33023020 = "I... maybe. I hate the idea of tying life's possibilities down to \"youth\".",
  str_homestory_chat_33023021 = "On second thought, that's just what you meant.",
  str_homestory_chat_33023022 = "But I could never express it as well as you! You're incredible, Mr. Wilhelm!",
  str_homestory_chat_33024001 = "Popular science books.",
  str_homestory_chat_33024002 = "Science, huh... It has undoubtedly made great contributions to society.",
  str_homestory_chat_33024003 = "But with the current scientific framework, Aurorians are surely drifting away from the Truth.",
  str_homestory_chat_33024004 = "Eh, how so?",
  str_homestory_chat_33024005 = "Has Victoria ever said to you, \"Truth has many dimensions\"?",
  str_homestory_chat_33024006 = "She says that a lot!",
  str_homestory_chat_33024007 = "This is where the mystery lies.",
  str_homestory_chat_33024008 = "Science is built on predictability.",
  str_homestory_chat_33024009 = "Doing something ten thousand times and getting the same result each time is what makes it a \"scientific conclusion.\"",
  str_homestory_chat_33024010 = "But the Truth lies in the one-in-a-million spark.",
  str_homestory_chat_33024011 = "You catch it in one glance, and that glance, no matter how many times you take it, is always different.",
  str_homestory_chat_33024012 = "Do you get it?",
  str_homestory_chat_33024013 = "I get it.",
  str_homestory_chat_33024014 = "Nonsense. If you can really get it from my offhand words, what do we need the True Order for?",
  str_homestory_chat_33024015 = "...",
  str_homestory_chat_33024016 = "I don't get it.",
  str_homestory_chat_33024017 = "That's fine. You like science, so keep studying it.",
  str_homestory_chat_33024018 = "When science reaches its peak, it might become another gateway to the Truth.",
  str_homestory_chat_33025001 = "Theological texts.",
  str_homestory_chat_33025002 = "???",
  str_homestory_chat_33025003 = "...Oh, I see.",
  str_homestory_chat_33025004 = "Have you been reading... what is it called? \"Fantasy novels\"? The ones based on myths.",
  str_homestory_chat_33025005 = "And that's why you're intrigued by the concepts and settings in them, right?",
  str_homestory_chat_33025006 = "Huh? No, Mr. Wilhelm.",
  str_homestory_chat_33025007 = "Hearing you mention \"the Truth\" and \"Lord\" a lot, I want to understand what you're talking about.",
  str_homestory_chat_33025008 = "?!",
  str_homestory_chat_33025009 = "For... me?",
  str_homestory_chat_33025010 = "Yes. I find your talks intriguing and want to be able to respond to you sometimes.",
  str_homestory_chat_33025011 = "...Ugh, is it too flippant to read theological texts with such a mindset?",
  str_homestory_chat_33025012 = "...No, it isn't.",
  str_homestory_chat_33025013 = "What's the matter?",
  str_homestory_chat_33025014 = "Nothing! Go read now.",
  str_homestory_chat_33025015 = "If there's anything you don't understand... feel free to ask me.",
  str_homestory_chat_33199999 = "Any interesting dreams lately?",
  str_homestory_chat_33121001 = "Interesting dreams?",
  str_homestory_chat_33121002 = "Can't think of any...",
  str_homestory_chat_33121003 = "Hmm... Are you under a lot of pressure?",
  str_homestory_chat_33121004 = "Isn't it exhausting to sleep without sweet dreams?",
  str_homestory_chat_33121005 = "Huh? I wouldn't say so...",
  str_homestory_chat_33121006 = "A lot of stress is gone after a good night's sleep.",
  str_homestory_chat_33121007 = "Is that so? But...",
  str_homestory_chat_33121008 = "Sure.",
  str_homestory_chat_33121009 = "Ah. PlayerName, you are an optimistic man!",
  str_homestory_chat_33121010 = "Huh? My dreams led you to this conclusion?",
  str_homestory_chat_33121011 = "Yes! Those who live a happy life and treat others with optimism...",
  str_homestory_chat_33121012 = "They will have many beautiful things with their loved ones in their dreams!",
  str_homestory_chat_33121013 = "Hehe. There's an even simpler way though.",
  str_homestory_chat_33121014 = "Come to see me whenever you feel like a sweet dream!",
  str_homestory_chat_33121015 = "I will!",
  str_homestory_chat_33122001 = "A world without Eclipsites.",
  str_homestory_chat_33122002 = "Wow. Please give me a minute to process this...",
  str_homestory_chat_33122003 = "That would be a bubble without any mottles!",
  str_homestory_chat_33122004 = "The most beautiful, perfect bubble!",
  str_homestory_chat_33122005 = "What did you do there?",
  str_homestory_chat_33122006 = "I traveled around with everyone.",
  str_homestory_chat_33122007 = "Wow. I wish I were there with you!",
  str_homestory_chat_33122008 = "We embraced the wind and watched the birth of a new world together atop the Colossus...",
  str_homestory_chat_33122009 = "We worked together to restore our homeland.",
  str_homestory_chat_33122010 = "How kind and selfless you are even in your dreams!",
  str_homestory_chat_33122011 = "It's very important to restore the colors of the bubble indeed.",
  str_homestory_chat_33122012 = "Would you take me with you next time to experience such a beautiful dream together?",
  str_homestory_chat_33122013 = "Sure, I just don't know when that would be...",
  str_homestory_chat_33123001 = "Longzhou.",
  str_homestory_chat_33123002 = "Longzhou. I read about it in a fairy tale book...",
  str_homestory_chat_33123003 = "Fairy tales over there are quite profound.",
  str_homestory_chat_33123004 = "They like to use big words and weird phrases. Hard for me to understand...",
  str_homestory_chat_33123005 = "The culture of Longzhou is indeed profound and extensive.",
  str_homestory_chat_33123006 = "Their gadgets, calendar, and Aurorians are truly intriguing.",
  str_homestory_chat_33123007 = "Really? I've never seen an Aurorian from Longzhou.",
  str_homestory_chat_33123008 = "I'll ask my ancestor to give me a glimpse tonight in my dream.",
  str_homestory_chat_33123009 = "Are you serious?",
  str_homestory_chat_33123010 = "How about I introduce you to some of their Aurorians next time?",
  str_homestory_chat_33123011 = "Hooray! You are so nice to me, just like my ancestor!",
  str_homestory_chat_33124001 = "A circus show.",
  str_homestory_chat_33124002 = "Hmm... A show?",
  str_homestory_chat_33124003 = "I watched many when I was in the circus...",
  str_homestory_chat_33124004 = "Although I can't remember much...",
  str_homestory_chat_33124005 = "I know for sure they were incredible performers!",
  str_homestory_chat_33124006 = "What's your favorite part of the show?",
  str_homestory_chat_33124007 = "I guess the knife-throwing?",
  str_homestory_chat_33124008 = "The knife-throwing? Didn't know you were into the thrill.",
  str_homestory_chat_33124009 = "It's exciting and always ends well!",
  str_homestory_chat_33124010 = "That's why I'm also a fan.",
  str_homestory_chat_33124011 = "I guess the magic show?",
  str_homestory_chat_33124012 = "The magic show? Jeno is a fabulous magician!",
  str_homestory_chat_33124013 = "I remember how mysterious it felt! He could tell a lot by simply drawing a few cards!",
  str_homestory_chat_33124014 = "Hmm... I miss everyone from the circus...",
  str_homestory_chat_33124015 = "Let's watch a circus show together if we get the chance!",
  str_homestory_chat_33124016 = "Deal!",
  str_homestory_chat_33125001 = "Eraveil.",
  str_homestory_chat_33125002 = "Eraveil... That's your hometown, isn't it?",
  str_homestory_chat_33125003 = "I was born on a ship. Home is a strange concept for me.",
  str_homestory_chat_33125004 = "Do you like Eraveil?",
  str_homestory_chat_33125005 = "Yeah, my people had been living there for generations after all.",
  str_homestory_chat_33125006 = "But I spent seventeen years underground.",
  str_homestory_chat_33125007 = "There's still a lot I don't know about my ancestors.",
  str_homestory_chat_33125008 = "That's one of the reasons why I'm traveling.",
  str_homestory_chat_33125009 = "Wow. The Caelestite is also trying to learn about his ancestors?",
  str_homestory_chat_33125010 = "We are quite similar, aren't we?",
  str_homestory_chat_33125011 = "Perhaps my ancestor knows yours?",
  str_homestory_chat_33125012 = "Perhaps they used to be good friends!",
  str_homestory_chat_33125013 = "Haha. That's a very interesting thought.",
  str_homestory_chat_33125014 = "Hehe. Our ancestors must be very happy to see us continue their friendship!",
  str_homestory_chat_33299999 = "Do you have something you want to protect?",
  str_homestory_chat_33221001 = "The things I want to protect...",
  str_homestory_chat_33221002 = "There are so many, you know.",
  str_homestory_chat_33221003 = "Can you be more specific?",
  str_homestory_chat_33221004 = "Hmm... It's hard to describe.",
  str_homestory_chat_33221005 = "What kind of things are you asking?",
  str_homestory_chat_33221006 = "From grand concepts like ideals and beliefs.",
  str_homestory_chat_33221007 = "Down to the small and intricate details.",
  str_homestory_chat_33221008 = "Maybe you can give me some examples.",
  str_homestory_chat_33221009 = "How about...",
  str_homestory_chat_33221010 = "The knives I treasure, my crow, and seniors like Tweety.",
  str_homestory_chat_33221011 = "In that case... There's something I must protect right now!",
  str_homestory_chat_33221012 = "To protect tonight's dinner, I must stop Vice from developing a new dish!!!",
  str_homestory_chat_33222001 = "The Colossus.",
  str_homestory_chat_33222002 = "I see.",
  str_homestory_chat_33222003 = "Your companion left behind the battlefield to spend eons with you.",
  str_homestory_chat_33222004 = "And your spirits entwined in a miraculous harmony.",
  str_homestory_chat_33222005 = "I, too, was shocked when I opened the family heirloom... I understand now.",
  str_homestory_chat_33222006 = "Now that you mention it, we do share a similar destiny.",
  str_homestory_chat_33222007 = "Indeed, even our ancestors met a long time ago.",
  str_homestory_chat_33222008 = "You helped me fulfill my mission, so now, I'll help you protect the Colossus.",
  str_homestory_chat_33222009 = "Thank you, with your help...",
  str_homestory_chat_33222010 = "We can do it for sure!",
  str_homestory_chat_33223001 = "The glory of the ancestors.",
  str_homestory_chat_33223002 = "I understand how she feels.",
  str_homestory_chat_33223003 = "After all, I've made it this far by following the will of my ancestors.",
  str_homestory_chat_33223004 = "It hasn't been an easy journey, filled as it was with doubt...",
  str_homestory_chat_33223005 = "But I've fulfilled my destiny. And you, where has your path taken you?",
  str_homestory_chat_33223006 = "There are some achievements...",
  str_homestory_chat_33223007 = "Congratulations to you then.",
  str_homestory_chat_33223008 = "I'm still working on it...",
  str_homestory_chat_33223009 = "Then I will be watching over you.",
  str_homestory_chat_33223010 = "If you need any help, feel free to tell me.",
  str_homestory_chat_33223011 = "I'm not just thanking you for your help. I'm genuinely fascinated by the history of Caelestites.",
  str_homestory_chat_33223012 = "Thank you.",
  str_homestory_chat_33224001 = "Justice!",
  str_homestory_chat_33224002 = "Oh?",
  str_homestory_chat_33224003 = "Do you also want to become a comrade of justice?",
  str_homestory_chat_33224004 = "I already am!",
  str_homestory_chat_33224005 = "I've come to truly appreciate your sense of justice through our time together.",
  str_homestory_chat_33224006 = "I believe you must be the most suitable candidate.",
  str_homestory_chat_33224007 = "Of course I want to!",
  str_homestory_chat_33224008 = "Really? Having such determination and belief is quite impressive.",
  str_homestory_chat_33224009 = "But this is not an easy job.",
  str_homestory_chat_33224010 = "Would you like to be my assistant?",
  str_homestory_chat_33224011 = "Our actions against evil at night will surely be more effective with you around.",
  str_homestory_chat_33224012 = "Uh, if it's about this, please allow me to think it over a bit more!",
  str_homestory_chat_33225001 = "Friendship.",
  str_homestory_chat_33225002 = "Friendship is indeed beautiful.",
  str_homestory_chat_33225003 = "I was always on the move, changing jobs and never really settling down.",
  str_homestory_chat_33225004 = "But now, I've found some amazing people to call friends, like my senior in the Courier Union and that special friend at night.",
  str_homestory_chat_33225005 = "They are the friends I wish to protect.",
  str_homestory_chat_33225006 = "What kind of friendship do you want to protect?",
  str_homestory_chat_33225007 = "The friendship with everyone on the Colossus!",
  str_homestory_chat_33225008 = "Right, everyone on the Colossus is very nice.",
  str_homestory_chat_33225009 = "It's just that I'm used to a life of keeping a distance from people.",
  str_homestory_chat_33225010 = "Seems like I'm not ready yet, to make friends with everyone.",
  str_homestory_chat_33225011 = "So if we're talking about the present...",
  str_homestory_chat_33225012 = "My friendship with you!",
  str_homestory_chat_33225013 = "Sorry, I just... I don't think I mentioned you.",
  str_homestory_chat_33225014 = "After all, you being by my side has become something I'm used to.",
  str_homestory_chat_33225015 = "Allow me to rectify.",
  str_homestory_chat_33225016 = "Guarding our friendship is extremely important.",
  str_homestory_chat_33225017 = "It's my honor! I'll cherish this friendship!",
  str_homestory_chat_33399999 = "If one day you wake up and you're the only person left in the world, what would you do?",
  str_homestory_chat_33321001 = "Continue to sleep.",
  str_homestory_chat_33321002 = "I must be dreaming.",
  str_homestory_chat_33321003 = "Why is it so? Normally, people would immediately go explore and do things they can't usually do, right?",
  str_homestory_chat_33321004 = "But I'm the star!",
  str_homestory_chat_33321005 = "Normally, a lot of unusual things happen.",
  str_homestory_chat_33321006 = "Hahaha, you, of all people, are even more arrogant than me.",
  str_homestory_chat_33321007 = "Have you ever thought about it? If everyone disappeared, your psychic abilities would be useless, right?",
  str_homestory_chat_33321008 = "Well... Since there's nothing to do, I should really just go to sleep.",
  str_homestory_chat_33321009 = "What is it that you want to do but can't?",
  str_homestory_chat_33321010 = "Humph. At first, it seems like there's a lot, but upon closer thought, there doesn't seem to be much.",
  str_homestory_chat_33321011 = "I'll do whatever I want to do, rules can't stop me.",
  str_homestory_chat_33321012 = "There's no such thing as \"something you can't usually do\"!",
  str_homestory_chat_33321013 = "What a dangerous guy...",
  str_homestory_chat_33322001 = "First, rush to the amusement park in Umbraton or Harbor City.",
  str_homestory_chat_33322002 = "Then, let's enjoy the activities that usually require lining up!",
  str_homestory_chat_33322003 = "Should I call you... honest, or uptight?",
  str_homestory_chat_33322004 = "Your dream can be realized just by sneaking into the amusement park at midnight.",
  str_homestory_chat_33322005 = "... Who would think of doing such a thing!?",
  str_homestory_chat_33322006 = "You're the radiant and unrestrained Lady Pepita.",
  str_homestory_chat_33322007 = "Come on, I'll take you there tonight.",
  str_homestory_chat_33322008 = "(Oh, no. I'm actually a bit smitten...)",
  str_homestory_chat_33323001 = "Go to the bookstore to read free books",
  str_homestory_chat_33323002 = "I can watch all day, sit wherever I want, and not worry about the shop clerk glaring at me... Ah, heaven!",
  str_homestory_chat_33323003 = "...",
  str_homestory_chat_33323004 = "I know my wish is humble, but you don't have to look at me so speechlessly...",
  str_homestory_chat_33323005 = "You misunderstood, I didn't think your wish was humble at all.",
  str_homestory_chat_33323006 = "But if you want to read books for free, all you need to do is put on a fancy outfit... and you can walk into the bookstore and pick whatever you want.",
  str_homestory_chat_33323007 = "Once you've selected, just mention any noble's name. The bookstore can collect the payment at the end of the Tsuki.",
  str_homestory_chat_33323008 = "Those nobles treat their monthly bills like snowflakes, they never bother to check them one by one.",
  str_homestory_chat_33323009 = "Y-You... Th-This is a crime, isn't it?",
  str_homestory_chat_33323010 = "Ha! Those ignorant nobles, it's me who's spreading knowledge to the common folk... And you call this a crime?",
  str_homestory_chat_33323011 = "I'd say it's my blessing.",
  str_homestory_chat_33323012 = "...",
  str_homestory_chat_33324001 = "Bathing in the river",
  str_homestory_chat_33324002 = "Ptui!",
  str_homestory_chat_33324003 = "*cough*... To be honest with you, I've wanted to do this for a long time.",
  str_homestory_chat_33324004 = "But you're still worried... right?",
  str_homestory_chat_33324005 = "No, I go all the time.",
  str_homestory_chat_33324006 = "What?! You're not worried—",
  str_homestory_chat_33324007 = "Is someone coming?",
  str_homestory_chat_33324008 = "Petey is here. Besides, what kind of person would stare at others while they're bathing?",
  str_homestory_chat_33324009 = "Besides, everyone's the same, what's there to be shy about?",
  str_homestory_chat_33324010 = "... No, no, wait! Don't even think about tricking me into bathing in the river right now!",
  str_homestory_chat_33324011 = "Attacked by piranhas?",
  str_homestory_chat_33324012 = "When I go to bathe in the river, I'm usually covered in mud.",
  str_homestory_chat_33324013 = "Sharks would be poisoned and faint.",
  str_homestory_chat_33324014 = "So grand... no, that's not what I meant to look at!",
  str_homestory_chat_33325001 = "Sitting on the throne of Lumopolis",
  str_homestory_chat_33325002 = "You're still going to cross your legs!",
  str_homestory_chat_33325003 = "Sigh, I'm out of ideas, I've been sitting for a while now.",
  str_homestory_chat_33325004 = "What?! Let me ask first, you're unauthorized, right...?",
  str_homestory_chat_33325005 = "Could it be that Carleen's father will also graciously invite me?",
  str_homestory_chat_33325006 = "Is the chair comfortable to sit in?",
  str_homestory_chat_33325007 = "Tsk, not comfortable at all, it's too hard!",
  str_homestory_chat_33325008 = "For Carleen's sake, I left a cushion there.",
  str_homestory_chat_33325009 = "I really hope the City Lord will thank me... Hahaha!",
  str_homestory_chat_33325010 = "How did you get over there?",
  str_homestory_chat_33325011 = "That night, I was graffitiing on a beautiful white wall, then the guards came...",
  str_homestory_chat_33325012 = "I just found out that it's the Lumopolis Hall of Justice.",
  str_homestory_chat_33325013 = "...",
  str_homestory_chat_33325014 = "And then I ran into the place where the City Lord's throne is!",
  str_homestory_chat_33325015 = "For the sake of safety, I have to keep a certain distance from you...",
  str_homestory_chat_33429999 = "Would you mind sharing some interesting things about this time?",
  str_homestory_chat_33421001 = "Of course, but you don't have to be so polite.",
  str_homestory_chat_33421002 = "It's been so long. I only know very little about the world now.",
  str_homestory_chat_33421003 = "And I could become more of a burden than a help if I don't adapt to the modern world.",
  str_homestory_chat_33421004 = "Please tell me more about the world.",
  str_homestory_chat_33421005 = "Oh, don't worry about it. You see, I've spent the last seventeen years underground.",
  str_homestory_chat_33421006 = "I'm still very much in the process of exploring this world!",
  str_homestory_chat_33421007 = "So, we can share our experiences with each other.",
  str_homestory_chat_33421008 = "Let's enjoy the world together!",
  str_homestory_chat_33421009 = "It is a great world indeed.",
  str_homestory_chat_33421010 = "It's my pleasure to share my thoughts with you.",
  str_homestory_chat_33421011 = "In the name of Achilles, I will also share with you all that I know.",
  str_homestory_chat_33421012 = "If you wish to know about your fellow Caelestites, I'm happy to share their stories with you.",
  str_homestory_chat_33421013 = "I'm very interested! Tell me about them someday.",
  str_homestory_chat_33422001 = "Are you interested in the Rediesel car rally?",
  str_homestory_chat_33422002 = "Car... I've only just been introduced to the term.",
  str_homestory_chat_33422003 = "We used to have carriages for transportation in my time.",
  str_homestory_chat_33422004 = "It is said that cars are not only faster than carriages but also more stable.",
  str_homestory_chat_33422005 = "The technology now is breathtaking.",
  str_homestory_chat_33422006 = "Wanna try driving?",
  str_homestory_chat_33422007 = "I haven't mastered the skill yet.",
  str_homestory_chat_33422008 = "Attempting it rashly would likely lead to numerous risks and unnecessary troubles.",
  str_homestory_chat_33422009 = "Do you want me to take you for a ride?",
  str_homestory_chat_33422010 = "Sounds like a perfect activity for leisure time.",
  str_homestory_chat_33422011 = "However, as a warrior, I really want to learn how to control my own car.",
  str_homestory_chat_33422012 = "Perhaps you could practice driving in the future using the simulator on the Colossus. I'd be happy to teach you.",
  str_homestory_chat_33422013 = "Is there such a convenient tool?",
  str_homestory_chat_33422014 = "Please let me give it a try. I indeed want to learn some new-age techniques.",
  str_homestory_chat_33422015 = "No problem!",
  str_homestory_chat_33423001 = "For instance, the aquarium in Harbor City? That place is pretty good.",
  str_homestory_chat_33423002 = "Such a novel term. What kind of place is that?",
  str_homestory_chat_33423003 = "A very dreamy place.",
  str_homestory_chat_33423004 = "As if immersed in a dream of the deep sea.",
  str_homestory_chat_33423005 = "You can see many sights that can't be seen on land.",
  str_homestory_chat_33423006 = "A marvelous place.",
  str_homestory_chat_33423007 = "They have all kinds of marine life.",
  str_homestory_chat_33423008 = "Just one visit is enough to learn a lot about the ocean.",
  str_homestory_chat_33423009 = "That sounds fascinating, I'm looking forward to it.",
  str_homestory_chat_33423010 = "The more people you have with you, the richer the experience becomes at a place like that.",
  str_homestory_chat_33423011 = "You can invite the Star Warriors to join you next time.",
  str_homestory_chat_33423012 = "That's very considerate of you.",
  str_homestory_chat_33423013 = "If possible, I hope you can be our guide and accompany us.",
  str_homestory_chat_33423014 = "You're our partner as well.",
  str_homestory_chat_33423015 = "Alright! Anytime you need me, I'm there!",
  str_homestory_chat_33424001 = "You'd be interested in the Illumina's Joint Military Exercise, wouldn't you?",
  str_homestory_chat_33424002 = "Joint Military Exercise...",
  str_homestory_chat_33424003 = "Sounds like a military exercise where the Aurorians are banding together?",
  str_homestory_chat_33424004 = "Yes, Aurorians from all factions will be there.",
  str_homestory_chat_33424005 = "They'll be sharpening their skills.",
  str_homestory_chat_33424006 = "And they'll fight for honor.",
  str_homestory_chat_33424007 = "Such a grand event. I'd love to be there.",
  str_homestory_chat_33424008 = "Have you participated in the Joint Military Exercise? How did you perform?",
  str_homestory_chat_33424009 = "N-Not really good.",
  str_homestory_chat_33424010 = "After all, we didn't manage to secure the final victory...",
  str_homestory_chat_33424011 = "It was good!",
  str_homestory_chat_33424012 = "It's already great to be able to hold on till the end!",
  str_homestory_chat_33424013 = "I see. Got it.",
  str_homestory_chat_33424014 = "If given the chance, I'd really love to go and see for myself. Aurorians seem to be living the good life these days.",
  str_homestory_chat_33424015 = "That being said... if all Star Warriors were to participate... things could get a bit too intense.",
  str_homestory_chat_33425001 = "We can't miss the exotic charm of Longzhou!",
  str_homestory_chat_33425002 = "That's a truly enchanting land across the sea.",
  str_homestory_chat_33425003 = "An ancient empire rules over numerous vassal kingdoms.",
  str_homestory_chat_33425004 = "Not only are there Aurorians who are somewhat different from us, but there are also creatures known as Fiendlings.",
  str_homestory_chat_33425005 = "An ancient empire, huh...",
  str_homestory_chat_33425006 = "Having weathered centuries, even millennia, of trials and tribulations.",
  str_homestory_chat_33425007 = "Did they all survive?",
  str_homestory_chat_33425008 = "Right! It's amazing, isn't it?",
  str_homestory_chat_33425009 = "I'm still learning about Longzhou.",
  str_homestory_chat_33425010 = "But if you're interested, I can tell you the story of my adventure in Longzhou.",
  str_homestory_chat_33425011 = "There are also some ancient books from Longzhou that I can share with you.",
  str_homestory_chat_33425012 = "It's very nice of you, I'll make sure to read and study thoroughly.",
  str_homestory_chat_33425013 = "And... an adventure?",
  str_homestory_chat_33425014 = "It seems that Longzhou has many stories and legends of heroes.",
  str_homestory_chat_33425015 = "I'm looking forward to it.",
  str_homestory_chat_33425016 = "Okay, I'll have the Fireflies bring you some books tonight."
}
return config
